_BOUND_LANE_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]*\Z")


def _normalized_key(value: Any) -> str:
    return str(value).casefold().replace("-", "_")


def _contains_secret_key(value: Any) -> Optional[str]:
    """Return the first credential/inherited-environment key found."""
    if isinstance(value, Mapping):
        for key, item in value.items():
            normalized = _normalized_key(key)
            if normalized in _SECRET_KEY_PARTS or any(
                part in normalized
                for part in (
                    "api_key",
                    "auth_token",
                    "oauth_token",
                    "access_token",
                    "refresh_token",
                    "client_secret",
                    "base_url",
                    "bedrock",
                    "vertex",
                    "credential",
                    "extra_args",
                    "provider",
                )
            ):
                return str(key)
            found = _contains_secret_key(item)
            if found is not None:
                return found
    elif isinstance(value, (list, tuple, set, frozenset)):
        for item in value:
            found = _contains_secret_key(item)
            if found is not None:
                return found
    return None


def _typed_runner_spec_projection(
        value: Any, label: str,
) -> Optional[Dict[str, Any]]:
    """Project only the exact SDK ``RunnerSpec`` at the adapter boundary.

    The SDK wire serializer includes transport-only defaults.  They are not
    durable controller settings, but an exact default may be omitted after it
    has been checked against the SDK's own default instance.  In particular,
    this helper is deliberately not an ``isinstance`` or dataclass escape
    hatch: subclasses and lookalike dataclasses remain on the strict path.
    """
    try:
        from lane_managed_sdk import RunnerSpec
    except (ImportError, AttributeError):
        return None
    if type(value) is not RunnerSpec:
        return None
    try:
        raw = value.to_dict()
        default_instance = RunnerSpec()
        defaults = default_instance.to_dict()
    except Exception as exc:
        raise _error("invalid", "%s is malformed" % label) from exc
    if not isinstance(raw, Mapping) or not isinstance(defaults, Mapping):
        raise _error("invalid", "%s is malformed" % label)
    if any(not isinstance(key, str) for key in raw):
        raise _error("invalid", "%s contains a non-string field" % label)
    unknown = set(raw).difference(_RUNNER_SPEC_TYPED_FIELDS)
    if unknown:
        raise _error(
            "unsupported",
            "%s contains unknown SDK field %s" % (label, sorted(unknown)[0]),
        )

    for field_name in _RUNNER_SPEC_NON_DURABLE_DEFAULT_FIELDS:
        try:
            actual = getattr(value, field_name)
            default = getattr(default_instance, field_name)
        except AttributeError as exc:
            raise _error(
                "unsupported",
                "%s has an unknown SDK default field %s" % (label, field_name),
            ) from exc
        if _canonical_json(actual, "%s.%s" % (label, field_name)) != _canonical_json(
                default, "%s.%s default" % (label, field_name)):
            raise _error(
                "unsupported",
                "%s contains non-default non-durable setting %s" %
                (label, field_name),
            )

    supported_models = raw.get("supported_models", [])
    if not isinstance(supported_models, (list, tuple)) or any(
        not isinstance(model, str) or not model
        for model in supported_models
    ):
        raise _error("invalid", "%s supported_models is invalid" % label)

    # Only fields already admitted by the durable runner allowlist survive.
    # ``supported_models`` is retained when meaningful because it is requested
    # configuration, not runtime capability evidence.
    projected = {
        key: raw[key]
        for key in raw
        if key in _SAFE_RUNNER_KEYS and
        (key != "supported_models" or bool(supported_models))
    }
    return projected


def _safe_runner_projection(value: Any, label: str = "runner specification") -> Dict[str, Any]:
    """Return the only runner data allowed to become durable state.

    This boundary intentionally rejects unknown settings rather than trying to
    guess whether an SDK option is harmless.  Environment inheritance,
    authentication material, raw settings, and arbitrary argv are all
    reconstructed by the adapter from its own trusted configuration and never
    copied into controller state.
    """
    typed_projection = _typed_runner_spec_projection(value, label)
    if typed_projection is not None:
        value = typed_projection
    elif dataclasses.is_dataclass(value) and not isinstance(value, type):
        raise _error("invalid", "%s is malformed" % label)
    if not isinstance(value, Mapping):
        raise _error("invalid", "%s is malformed" % label)
    secret_key = _contains_secret_key(value)
    if secret_key is not None:
        raise _error("unsupported", "%s contains credential or environment key %s" % (label, secret_key))
    projected: Dict[str, Any] = {}
    for raw_key, raw_value in value.items():
        key = str(raw_key)
        normalized = _normalized_key(key)
        if normalized in _SECRET_KEY_PARTS or normalized not in _SAFE_RUNNER_KEYS:
            raise _error("unsupported", "%s contains non-durable setting %s" % (label, key))
        if normalized == "supported_models":
            if not isinstance(raw_value, (list, tuple)) or any(
                not isinstance(model, str) or not model
                for model in raw_value
            ):
                raise _error("invalid", "%s supported_models is invalid" % label)
        if isinstance(raw_value, Mapping):
            # Fingerprints and permission maps are structured, but must still
            # be recursively JSON-shaped and credential-free.
            projected_value = _safe_json_projection(raw_value, "%s.%s" % (label, key))
        elif isinstance(raw_value, (list, tuple, set, frozenset)):
            projected_value = _safe_json_projection(raw_value, "%s.%s" % (label, key))
        elif raw_value is None or isinstance(raw_value, (str, int, float, bool)):
            projected_value = raw_value
        else:
            raise _error("invalid", "%s.%s is not JSON-shaped" % (label, key))
        projected[key] = projected_value
    _digest(projected)
    return projected


def _safe_json_projection(value: Any, label: str) -> Any:
    """Validate nested durable values without accepting arbitrary settings."""
    secret_key = _contains_secret_key(value)
    if secret_key is not None:
        raise _error("unsupported", "%s contains credential or environment key %s" % (label, secret_key))
    if isinstance(value, Mapping):
        result: Dict[str, Any] = {}
        for key, item in value.items():
            if not isinstance(key, str) or not key:
                raise _error("invalid", "%s has an invalid key" % label)
            result[key] = _safe_json_projection(item, "%s.%s" % (label, key))
        return result
    if isinstance(value, (list, tuple, set, frozenset)):
        return [_safe_json_projection(item, label) for item in value]
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    raise _error("invalid", "%s is not JSON-shaped" % label)


def _opaque_payload_reference(value: Any, label: str = "payload_ref") -> str:
    """Accept only a bounded opaque reference, never a prompt/body object."""
    if not isinstance(value, str):
        raise _error("invalid", "%s must be an opaque string reference" % label)
    if not value or len(value.encode("utf-8")) > MAX_PAYLOAD_REFERENCE_BYTES:
        raise _error("invalid", "%s is empty or exceeds one MiB" % label)
    if len(value) > MAX_ID_LENGTH or "\x00" in value:
        raise _error("invalid", "%s is empty or too long" % label)
    return value


class ControllerError(RuntimeError):
    """Stable refusal raised by the managed controller boundary."""

    def __init__(self, code: str, message: str) -> None:
        self.code = str(code)
        self.message = str(message)
        super().__init__(self.message)


def _error(code: str, message: str) -> ControllerError:
    return ControllerError(code, message)


def _native_validate(
        record: Any, *, record_kind: Optional[str] = None,
        required: Optional[Sequence[str]] = None,
        label: str = "managed controller record") -> Dict[str, Any]:
    """Use the state layer's one strict schema-v2 marker in this module."""

    try:
        return validate_native_lineage_record(
            record, record_kind=record_kind, required=required, label=label,
        )
    except ManagedStateError as exc:
        raise _error(exc.code, exc.message)


def _id(value: Any, label: str, *, required: bool = True) -> Optional[str]:
    if value is None:
        if required:
            raise _error("invalid", "%s is required" % label)
        return None
    if isinstance(value, bool):
        raise _error("invalid", "%s must be a string" % label)
    if not isinstance(value, str):
        raise _error("invalid", "%s must be a string" % label)
    if not value or len(value) > MAX_ID_LENGTH or "\x00" in value:
        raise _error("invalid", "%s is empty or too long" % label)
    return value


def _optional_text(value: Any, label: str) -> Optional[str]:
    return _id(value, label, required=False)


def _mapping(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise _error("invalid", "%s must be an object" % label)
    return value


def _native_exact_fields(
        value: Any, fields: Sequence[str], label: str) -> Dict[str, Any]:
    """Copy one bounded internal object only when its wire fields are exact."""

    if not isinstance(value, Mapping):
        raise _error("invalid", "%s must be an object" % label)
    keys = list(value.keys())
    if any(not isinstance(key, str) for key in keys):
        raise _error("invalid", "%s contains a non-string key" % label)
    expected = set(fields)
    actual = set(keys)
    if actual != expected:
        missing = expected - actual
        extra = actual - expected
        if missing:
            raise _error(
                "invalid", "%s is missing required fields: %s" %
                (label, ", ".join(sorted(missing))),
            )
        raise _error(
            "invalid", "%s contains unsupported fields: %s" %
            (label, ", ".join(sorted(extra))),
        )
    return dict(value)


def _json_value(value: Any) -> Any:
    """Convert dataclasses and paths into bounded JSON-shaped values."""
    if isinstance(value, Path):
        return str(value)
    if dataclasses.is_dataclass(value):
        if hasattr(value, "to_dict"):
            return _json_value(value.to_dict())
        return _json_value(dataclasses.asdict(value))
    if isinstance(value, Mapping):
        return {str(key): _json_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set, frozenset)):
        return [_json_value(item) for item in value]
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    return str(value)


def _canonical_json(value: Any, label: str = "request content") -> str:
    try:
        return json.dumps(
            _json_value(value),
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        )
    except (TypeError, ValueError) as exc:
        raise _error("invalid", "%s is not JSON: %s" % (label, exc))


def _digest(value: Any) -> str:
    encoded = _canonical_json(value).encode("utf-8")
    if len(encoded) > MAX_PAYLOAD_REFERENCE_BYTES:
        raise _error("invalid", "request content exceeds one MiB")
    return hashlib.sha256(encoded).hexdigest()


def _get(value: Any, *names: str, default: Any = None) -> Any:
    if isinstance(value, Mapping):
        for name in names:
            if name in value:
                return value[name]
    else:
        for name in names:
            if hasattr(value, name):
                return getattr(value, name)
    return default


_NATIVE_CHILD_FORBIDDEN_FIELDS = frozenset(
    {
        "participant_id", "session_id", "session_uuid", "uuid", "mailbox",
        "mailbox_id", "process_group_id", "pgid", "runner_id",
        "runner_instance_id", "child_id", "agentId", "taskId", "sessionId",
        "mailboxId", "processGroupId",
    }
)
_NATIVE_LINEAGE_STATES = frozenset(
    {"starting", "held", "active", "stopping", "completed", "failed",
     "indeterminate", "released"}
)
_NATIVE_CHILD_STATES = frozenset(
    {"discovered", "admitted", "active", "stopping", "held", "completed",
     "resume-pending", "restart-pending", "restarting", "exact-resumed",
     "restarted", "unresolved", "unsupported"}
)
_NATIVE_CLAIM_STATES = frozenset({"held", "active", "released", "uncertain"})
_NATIVE_STOP_INTENT_TYPE = "native-stop-intent"
_NATIVE_STOP_EVIDENCE_TYPE = "native-stop-evidence"
_NATIVE_STOP_EVIDENCE_KINDS = frozenset({"runtime-ack", "terminal"})
_COORDINATOR_INTERRUPT_INTENT_TYPE = "coordinator-interrupt-intent"
_COORDINATOR_INTERRUPT_EVIDENCE_TYPE = "coordinator-interrupt-evidence"
_COORDINATOR_INTERRUPT_EVIDENCE_KINDS = frozenset(
    {
        "runtime-ack",
        "member-terminal",
        "tool-terminal",
        "effect-outcome",
        "admission-closed",
        "parent-drained",
        "request-observation",
        "process-excluded",
    }
)
_COORDINATOR_INTERRUPT_FACT_FIELDS = {
    "runtime-ack": frozenset({"accepted", "ack_kind"}),
    "member-terminal": frozenset({
        "agent_id", "task_id", "lineage_incarnation", "tool_use_id",
        "event_kind", "event_uuid", "status",
    }),
    "tool-terminal": frozenset({
        "tool_use_id", "agent_id", "lineage_incarnation", "status",
    }),
    "effect-outcome": frozenset({"effect_id", "status"}),
    "admission-closed": frozenset({"admission_id", "closed"}),
    "parent-drained": frozenset({"invocation_id", "state"}),
    "request-observation": frozenset({
        "epoch_id", "entry_watermark", "through_watermark",
        "new_requests", "observable",
    }),
    "process-excluded": frozenset({"process_identity_digest", "status"}),
}


def _native_canonical_path(value: Any, label: str) -> str:
    """Validate one absolute realpath spelling without repairing it."""

    if not isinstance(value, str) or not value:
        raise _error("invalid", "%s must be an absolute canonical path" % label)
    path = Path(value)
    if not path.is_absolute():
        raise _error("invalid", "%s must be an absolute canonical path" % label)
    try:
        canonical = path.resolve(strict=False)
    except (OSError, RuntimeError) as exc:
        raise _error("invalid", "%s cannot be resolved: %s" % (label, exc))
    if str(canonical) != value:
        raise _error("invalid", "%s is not a canonical path" % label)
    return value


def _native_positive_generation(value: Any, label: str) -> int:
    if (isinstance(value, bool) or not isinstance(value, int) or value <= 0):
        raise _error("invalid", "%s must be positive" % label)
    return value


def _native_claim_ref(
        value: Any, *, lineage_id: str, label: str = "native claim_ref",
        expected_agent_id: Optional[str] = None,
        expected_task_id: Optional[str] = None,
        expected_owner_generation: Optional[int] = None,
        expected_lineage_generation: Optional[int] = None,
        expected_workspace: Optional[str] = None,
        expected_common_dir: Optional[str] = None,
        expected_lane: Optional[str] = None,
        expected_lane_key: Optional[str] = None,
        expected_host: Optional[str] = None,
        expected_coordinator_session_uuid: Optional[str] = None,
        expected_parent_read_only: Optional[bool] = None) -> Dict[str, Any]:
    """Validate an inherited or isolated claim descriptor.

    A claim reference embedded in a child/lineage record is a descriptor, not
    a second top-level owner.  It therefore deliberately has no coordinator
    session, mailbox, process, or participant aliases.  The mapping is
    returned byte-for-byte in meaning (only shallow-copied), so nested child
    records can inherit the exact workspace claim.
    """

    claim = dict(_mapping(value, label))
    if _NATIVE_CHILD_FORBIDDEN_FIELDS.intersection(claim):
        raise _error("schema-mismatch", "%s contains a superseded identity alias" % label)
    if "schema" in claim or "version" in claim:
        raise _error("schema-mismatch", "%s uses a superseded schema field" % label)
    if "schema_version" in claim or "architecture" in claim:
        _native_validate(claim, label=label)
    claim_kind = claim.get("claim_kind")
    if claim_kind not in {"workspace", "child-worktree"}:
        raise _error("unsupported", "%s kind is unknown" % label)
    if claim_kind == "workspace":
        required = {
            "claim_kind", "lineage_id", "owner_generation", "lineage_generation",
            "workspace", "common_dir", "state",
        }
    else:
        required = {
            "claim_kind", "lineage_id", "owner_generation", "lineage_generation",
            "agent_id", "task_id", "worktree", "common_dir", "state",
        }
    optional = {
        "schema_version", "architecture", "record_kind", "repository",
        "parent_read_only", "claimed_at", "definition_digest",
        "capability_digest", "lane", "lane_key", "host",
        "coordinator_session_uuid", "workspace",
    }
    if not required.issubset(claim) or set(claim) - required - optional:
        raise _error("invalid", "%s is malformed" % label)
    # There are two intentional forms: the compact inherited descriptor used
    # inside a controller graph, and the complete state-store claim returned by
    # the native claim API.  A partially copied store row is not a third form;
    # it is refused so callers cannot silently lose owner scope.
    scope_fields = {
        "schema_version", "architecture", "record_kind", "lane", "lane_key",
        "host", "repository", "claimed_at",
    }
    full_store_row = bool(scope_fields.intersection(claim))
    if full_store_row and not scope_fields.issubset(claim):
        raise _error("schema-mismatch", "%s has an incomplete owner scope" % label)
    if full_store_row and claim_kind == "child-worktree" and "workspace" not in claim:
        raise _error("schema-mismatch", "%s child row has no owning workspace" % label)
    if claim.get("record_kind") is not None:
        expected_record_kind = (
            "workspace-claim" if claim_kind == "workspace"
            else "child-worktree-claim"
        )
        if claim["record_kind"] != expected_record_kind:
            raise _error("schema-mismatch", "%s kind marker is unsupported" % label)
    if "lane" in claim:
        lane = claim["lane"]
        if (not isinstance(lane, str) or not lane or
                not _BOUND_LANE_RE.fullmatch(lane)):
            raise _error("invalid", "%s lane is invalid" % label)
        if "lane_key" in claim and claim["lane_key"] != lane.casefold():
            raise _error("ownership-conflict", "%s lane scope changed" % label)
    elif "lane_key" in claim:
        raise _error("invalid", "%s lane_key has no lane" % label)
    if "lane_key" in claim and (
            not isinstance(claim["lane_key"], str) or not claim["lane_key"]):
        raise _error("invalid", "%s lane_key is invalid" % label)
    if "host" in claim:
        _id(claim["host"], "%s host" % label)
    if "coordinator_session_uuid" in claim:
        _id(claim["coordinator_session_uuid"],
            "%s coordinator_session_uuid" % label)
        if (expected_coordinator_session_uuid is not None and
                claim["coordinator_session_uuid"] !=
                expected_coordinator_session_uuid):
            raise _error(
                "ownership-conflict",
                "%s coordinator session identity changed" % label,
            )
    if "repository" in claim:
        _native_canonical_path(claim["repository"], "%s repository" % label)
    if "claimed_at" in claim:
        claimed_at = claim["claimed_at"]
        if (isinstance(claimed_at, bool) or
                not isinstance(claimed_at, (int, float))):
            raise _error("invalid", "%s claimed_at is invalid" % label)
    if "schema_version" in claim or "architecture" in claim:
        if claim.get("schema_version") != NATIVE_SCHEMA_VERSION:
            raise _error("schema-mismatch", "%s schema marker is unsupported" % label)
    if claim.get("lineage_id") != lineage_id:
        raise _error("ownership-conflict", "%s belongs to another lineage" % label)
    _id(claim.get("lineage_id"), "%s lineage_id" % label)
    _native_positive_generation(claim.get("owner_generation"),
                                "%s owner_generation" % label)
    _native_positive_generation(claim.get("lineage_generation"),
                                "%s lineage_generation" % label)
    if (expected_owner_generation is not None and
            claim.get("owner_generation") != expected_owner_generation):
        raise _error("ownership-conflict", "%s owner generation changed" % label)
    if (expected_lineage_generation is not None and
            claim.get("lineage_generation") != expected_lineage_generation):
        raise _error("ownership-conflict", "%s lineage generation changed" % label)
    _native_canonical_path(claim["workspace"] if claim_kind == "workspace"
                           else claim.get("workspace", claim.get("worktree")),
                           "%s workspace" % label)
    if claim_kind == "child-worktree" and "workspace" in claim:
        _native_canonical_path(claim["workspace"], "%s workspace" % label)
    _native_canonical_path(claim["common_dir"], "%s common_dir" % label)
    if expected_workspace is not None and claim.get("workspace") != expected_workspace:
        raise _error("ownership-conflict", "%s workspace changed" % label)
    if expected_common_dir is not None and claim.get("common_dir") != expected_common_dir:
        raise _error("ownership-conflict", "%s common directory changed" % label)
    if (expected_lane is not None and "lane" in claim and
            claim.get("lane") != expected_lane):
        raise _error("ownership-conflict", "%s lane changed" % label)
    if (expected_lane_key is not None and "lane_key" in claim and
            claim.get("lane_key") != expected_lane_key):
        raise _error("ownership-conflict", "%s lane key changed" % label)
    if (expected_host is not None and "host" in claim and
            claim.get("host") != expected_host):
        raise _error("ownership-conflict", "%s host changed" % label)
    if claim.get("state") not in _NATIVE_CLAIM_STATES:
        raise _error("invalid", "%s state is invalid" % label)
    if claim_kind == "workspace":
        if "parent_read_only" in claim and not isinstance(
                claim["parent_read_only"], bool):
            raise _error("invalid", "%s parent_read_only is invalid" % label)
        if expected_parent_read_only is not None:
            if ("parent_read_only" not in claim or
                    claim["parent_read_only"] != expected_parent_read_only):
                raise _error(
                    "ownership-conflict",
                    "%s parent read-only scope changed" % label,
                )
        if "worktree" in claim or "agent_id" in claim or "task_id" in claim:
            raise _error("invalid", "%s has child-only fields" % label)
    else:
        agent_id = _id(claim.get("agent_id"), "%s agent_id" % label)
        task_id = _id(claim.get("task_id"), "%s task_id" % label)
        if expected_agent_id is not None and agent_id != expected_agent_id:
            raise _error("ownership-conflict", "%s agent identity changed" % label)
        if expected_task_id is not None and task_id != expected_task_id:
            raise _error("ownership-conflict", "%s task identity changed" % label)
        _native_canonical_path(claim["worktree"], "%s worktree" % label)
    for digest_name in ("definition_digest", "capability_digest"):
        if digest_name in claim and (
                not isinstance(claim[digest_name], str) or
                not re.fullmatch(r"[0-9a-f]{64}", claim[digest_name])):
            raise _error("invalid", "%s %s is invalid" % (label, digest_name))
    return claim


@dataclass(frozen=True)
class LineageRecord:
    """Strict schema-v2 record for one native coordinator execution lineage."""

    lineage_id: str
    lane: str
    owner_generation: int
    lineage_generation: int
    session_uuid: str
    transcript: Dict[str, Any]
    workspace: str
    common_dir: str
    state: str
    workspace_claim: Dict[str, Any]
    read_only: bool = False

    @classmethod
    def from_dict(cls, raw: Mapping[str, Any]) -> "LineageRecord":
        value = _native_validate(raw, label="native lineage record")
        required = {
            "schema_version", "architecture", "lineage_id", "lane",
            "owner_generation", "lineage_generation", "session_uuid",
            "transcript", "workspace", "common_dir", "state",
            "workspace_claim",
        }
        optional = {"record_kind", "read_only"}
        if not required.issubset(value) or set(value) - required - optional:
            raise _error("invalid", "native lineage record is malformed")
        if value.get("record_kind") is not None and value["record_kind"] != "lineage":
            raise _error("schema-mismatch", "native lineage record kind is unsupported")
        lineage_id = _id(value.get("lineage_id"), "lineage_id") or ""
        lane = value.get("lane")
        if (not isinstance(lane, str) or not lane or len(lane) > MAX_ID_LENGTH or
                not _BOUND_LANE_RE.fullmatch(lane)):
            raise _error("invalid", "native lineage lane is invalid")
        owner_generation = _native_positive_generation(
            value.get("owner_generation"), "lineage owner_generation")
        lineage_generation = _native_positive_generation(
            value.get("lineage_generation"), "lineage lineage_generation")
        session_uuid = _id(value.get("session_uuid"), "coordinator session_uuid") or ""
        transcript = dict(_mapping(value.get("transcript"), "lineage transcript"))
        _safe_json_projection(transcript, "lineage transcript")
        workspace = _native_canonical_path(value.get("workspace"), "lineage workspace")
        common_dir = _native_canonical_path(value.get("common_dir"), "lineage common_dir")
        state = value.get("state")
        if state not in _NATIVE_LINEAGE_STATES:
            raise _error("invalid", "native lineage state is invalid")
        read_only = value.get("read_only", False)
        if not isinstance(read_only, bool):
            raise _error("invalid", "native lineage read_only is invalid")
        workspace_claim = _native_claim_ref(
            value.get("workspace_claim"), lineage_id=lineage_id,
            label="native lineage workspace_claim",
            expected_owner_generation=owner_generation,
            expected_lineage_generation=lineage_generation,
            expected_workspace=workspace,
            expected_common_dir=common_dir,
            expected_lane=lane,
            expected_lane_key=lane.casefold(),
            expected_coordinator_session_uuid=session_uuid,
            expected_parent_read_only=read_only,
        )
        if workspace_claim.get("claim_kind") != "workspace":
            raise _error("ownership-conflict", "native lineage workspace claim is not a workspace claim")
        if (workspace_claim.get("owner_generation") != owner_generation or
                workspace_claim.get("lineage_generation") != lineage_generation or
                workspace_claim.get("workspace") != workspace or
                workspace_claim.get("common_dir") != common_dir):
            raise _error("ownership-conflict", "native lineage workspace claim changed")
        return cls(
            lineage_id=lineage_id,
            lane=lane,
            owner_generation=owner_generation,
            lineage_generation=lineage_generation,
            session_uuid=session_uuid,
            transcript=transcript,
            workspace=workspace,
            common_dir=common_dir,
            state=state,
            workspace_claim=workspace_claim,
            read_only=read_only,
        )

    @classmethod
    def from_store_claim(
            cls, claim: Mapping[str, Any], *, session_uuid: Any,
            transcript: Mapping[str, Any], read_only: bool = False,
            state: Optional[str] = None) -> "LineageRecord":
        """Construct a lineage record from the store's actual claim row.

        The claim is validated and copied as returned.  This bridge exists so
        controller callers cannot manufacture a reduced descriptor and lose
        lane/host/common-directory ownership scope on the way back to the
        durable record.
        """

        claim_value = dict(_mapping(claim, "managed workspace claim"))
        lineage_id = _id(claim_value.get("lineage_id"), "claim lineage_id") or ""
        _native_claim_ref(claim_value, lineage_id=lineage_id,
                          label="managed workspace claim",
                          expected_coordinator_session_uuid=session_uuid)
        if claim_value.get("claim_kind") != "workspace":
            raise _error("ownership-conflict", "managed store claim is not a workspace claim")
        return cls.from_dict({
            **native_record_marker("lineage"),
            "lineage_id": lineage_id,
            "lane": claim_value.get("lane"),
            "owner_generation": claim_value.get("owner_generation"),
            "lineage_generation": claim_value.get("lineage_generation"),
            "session_uuid": session_uuid,
            "transcript": transcript,
            "workspace": claim_value.get("workspace"),
            "common_dir": claim_value.get("common_dir"),
            "state": claim_value.get("state") if state is None else state,
            "workspace_claim": claim_value,
            "read_only": read_only,
        })

    from_state_claim = from_store_claim

    def to_dict(self) -> Dict[str, Any]:
        return {
            **native_record_marker("lineage"),
            "lineage_id": self.lineage_id,
            "lane": self.lane,
            "owner_generation": self.owner_generation,
            "lineage_generation": self.lineage_generation,
            "session_uuid": self.session_uuid,
            "transcript": _json_value(self.transcript),
            "workspace": self.workspace,
            "common_dir": self.common_dir,
            "state": self.state,
            "workspace_claim": _json_value(self.workspace_claim),
            "read_only": self.read_only,
        }


@dataclass(frozen=True)
class ChildTaskRecord:
    """Strict schema-v2 record for an actual native Agent/Task child."""

    lineage_id: str
    agent_id: str
    task_id: str
    type: str
    tool_use_id: str
    parent_links: Dict[str, Any]
    transcript: Dict[str, Any]
    status: str
    model: str
    effort: str
    custom_definition: Dict[str, Any]
    execution_mode: str
    claim_ref: Dict[str, Any]
    extras: Dict[str, Any] = field(default_factory=dict)

    @classmethod
    def from_dict(
        cls,
        raw: Mapping[str, Any],
        *,
        expected_claim: Optional[Mapping[str, Any]] = None,
    ) -> "ChildTaskRecord":
        value = _native_validate(raw, label="native child task record")
        if _NATIVE_CHILD_FORBIDDEN_FIELDS.intersection(value):
            raise _error(
                "schema-mismatch",
                "native child task record contains a superseded identity alias",
            )
        required = {
            "schema_version", "architecture", "lineage_id", "agent_id", "task_id",
            "type", "tool_use_id", "parent_links", "transcript", "status", "model",
            "effort", "custom_definition", "execution_mode", "claim_ref",
        }
        optional = {
            "record_kind", "stop_provenance", "restart_correlation",
            "admission_context", "tool_events", "effective_tools", "permissions",
            "read_only", "writable",
        }
        if not required.issubset(value) or set(value) - required - optional:
            raise _error("invalid", "native child task record is malformed")
        if value.get("record_kind") is not None and value["record_kind"] != "child-task":
            raise _error("schema-mismatch", "native child task record kind is unsupported")
        lineage_id = _id(value.get("lineage_id"), "child lineage_id") or ""
        agent_id = _id(value.get("agent_id"), "child agent_id") or ""
        task_id = _id(value.get("task_id"), "child task_id") or ""
        child_type = _id(value.get("type"), "child type") or ""
        tool_use_id = _id(value.get("tool_use_id"), "child tool_use_id") or ""
        parent_links = dict(_mapping(value.get("parent_links"), "child parent_links"))
        if any(alias in parent_links for alias in
               {"session_id", "uuid", "parent_session_id", "sessionId"}):
            raise _error("schema-mismatch", "child parent linkage contains a superseded alias")
        parent_session = _id(parent_links.get("session_uuid"),
                             "child parent session_uuid")
        if parent_session is None:
            raise _error("unsupported", "child coordinator parent linkage is unavailable")
        for link_name in ("parent_agent_id", "parent_task_id", "parent_tool_use_id"):
            if link_name in parent_links and parent_links[link_name] is not None:
                _id(parent_links[link_name], "child %s" % link_name)
        if "event_watermark" in parent_links:
            _native_positive_generation(parent_links["event_watermark"],
                                        "child event_watermark")
        transcript = dict(_mapping(value.get("transcript"), "child transcript"))
        _safe_json_projection(transcript, "child transcript")
        status = value.get("status")
        if status not in _NATIVE_CHILD_STATES:
            raise _error("invalid", "native child status is invalid")
        model = _id(value.get("model"), "child model") or ""
        effort = _id(value.get("effort"), "child effort") or ""
        definition = dict(_mapping(value.get("custom_definition"),
                                   "child custom_definition"))
        if _NATIVE_CHILD_FORBIDDEN_FIELDS.intersection(definition):
            raise _error("schema-mismatch", "child definition contains a superseded alias")
        if not isinstance(definition.get("name"), str) or not definition["name"]:
            raise _error("unsupported", "child custom definition identity is unavailable")
        tools = definition.get("tools")
        if not isinstance(tools, (list, tuple, set, frozenset)) or not tools:
            raise _error("unsupported", "child custom definition has no effective tools")
        for tool in tools:
            if not isinstance(tool, str) or not tool.strip():
                raise _error("unsupported", "child custom definition has unknown tools")
        if "permission_mode" not in definition or not isinstance(
                definition["permission_mode"], str) or not definition["permission_mode"]:
            raise _error("unsupported", "child permission capability is unavailable")
        _safe_json_projection(definition, "child custom_definition")
        execution_mode = value.get("execution_mode")
        if execution_mode not in {"foreground", "background"}:
            raise _error("invalid", "child execution_mode is invalid")
        claim_expectations: Dict[str, Any] = {}
        if expected_claim is not None:
            # Validate the durable baseline against its own lineage before
            # validating the candidate record.  A changed child lineage must
            # be reported from the candidate claim, rather than making the
            # unchanged expected claim fail against the candidate's ID.
            expected_lineage_id = _id(
                _get(expected_claim, "lineage_id"),
                "expected native child claim lineage_id",
            ) or ""
            expected = _native_claim_ref(
                expected_claim,
                lineage_id=expected_lineage_id,
                label="expected native child claim",
                expected_coordinator_session_uuid=parent_session,
            )
            for key in (
                "owner_generation", "lineage_generation", "workspace",
                "common_dir", "lane", "lane_key", "host",
                "coordinator_session_uuid",
            ):
                if key in expected:
                    claim_expectations["expected_" + key] = expected[key]
        claim_kwargs = {
            "expected_agent_id": agent_id if _get(value.get("claim_ref"),
                                                   "claim_kind") == "child-worktree" else None,
            "expected_task_id": task_id if _get(value.get("claim_ref"),
                                                 "claim_kind") == "child-worktree" else None,
            "expected_coordinator_session_uuid": parent_session,
        }
        claim_kwargs.update(claim_expectations)
        claim_ref = _native_claim_ref(
            value.get("claim_ref"), lineage_id=lineage_id,
            **claim_kwargs,
        )
        extras = {key: _json_value(value[key]) for key in optional if key in value}
        return cls(
            lineage_id=lineage_id,
            agent_id=agent_id,
            task_id=task_id,
            type=child_type,
            tool_use_id=tool_use_id,
            parent_links=parent_links,
            transcript=transcript,
            status=status,
            model=model,
            effort=effort,
            custom_definition=definition,
            execution_mode=execution_mode,
            claim_ref=claim_ref,
            extras=extras,
        )

    @classmethod
    def from_store_claim(
            cls, raw: Mapping[str, Any], claim: Mapping[str, Any],
            ) -> "ChildTaskRecord":
        """Build a child record while retaining the exact store claim row."""

        value = dict(_mapping(raw, "native child task record"))
        value["claim_ref"] = dict(_mapping(claim, "managed child claim"))
        return cls.from_dict(value)

    from_state_claim = from_store_claim

    def to_dict(self) -> Dict[str, Any]:
        result: Dict[str, Any] = {
            **native_record_marker("child-task"),
            "lineage_id": self.lineage_id,
            "agent_id": self.agent_id,
            "task_id": self.task_id,
            "type": self.type,
            "tool_use_id": self.tool_use_id,
            "parent_links": _json_value(self.parent_links),
            "transcript": _json_value(self.transcript),
            "status": self.status,
            "model": self.model,
            "effort": self.effort,
            "custom_definition": _json_value(self.custom_definition),
            "execution_mode": self.execution_mode,
            "claim_ref": _json_value(self.claim_ref),
        }
        result.update(_json_value(self.extras))
        return result


@dataclass(init=False)
class WriterClaim:
    """One exclusive writer worktree delegated to the state store."""

    participant_id: str
    worktree: Path
    repository: Optional[Path]
    state: str
    lane: Optional[str]
    metadata: Dict[str, Any]

    def __init__(
        self,
        participant_id: Optional[str] = None,
        worktree: Any = None,
        repository: Any = None,
        state: str = "active",
        lane: Optional[str] = None,
        metadata: Optional[Mapping[str, Any]] = None,
        **aliases: Any,
    ) -> None:
        if participant_id is None:
            participant_id = aliases.pop("owner", aliases.pop("participant", None))
        if worktree is None:
            worktree = aliases.pop("path", aliases.pop("worktree_path", None))
        if repository is None:
            repository = aliases.pop("repository_path", None)
        if aliases:
            merged = dict(metadata or {})
            merged.update(aliases)
            metadata = merged
        self.participant_id = _id(participant_id, "writer claim participant_id") or ""
        if isinstance(worktree, Path):
            path = worktree
        elif isinstance(worktree, str):
            path = Path(worktree)
        else:
            raise _error("invalid", "writer claim worktree is required")
        if not path.is_absolute():
            raise _error("invalid", "writer claim worktree must be absolute")
        self.worktree = path
        if repository is None:
            self.repository = None
        elif isinstance(repository, Path):
            self.repository = repository
        elif isinstance(repository, str):
            self.repository = Path(repository)
        else:
            raise _error("invalid", "writer claim repository must be a path")
        if self.repository is not None and not self.repository.is_absolute():
            raise _error("invalid", "writer claim repository must be absolute")
        if not isinstance(state, str) or not state:
            raise _error("invalid", "writer claim state is invalid")
        if state not in {"active", "released"}:
            raise _error("invalid", "writer claim state is invalid")
        self.state = state
        self.lane = _optional_text(lane, "writer claim lane")
        self.metadata = dict(metadata or {})

    @property
    def path(self) -> Path:
        return self.worktree

    def to_dict(self) -> Dict[str, Any]:
        result: Dict[str, Any] = {
            "participant_id": self.participant_id,
            "worktree": str(self.worktree),
            "repository": str(self.repository) if self.repository is not None else None,
            "state": self.state,
        }
        if self.lane is not None:
            result["lane"] = self.lane
        if self.metadata:
            result["metadata"] = _json_value(self.metadata)
        return result

    @classmethod
    def from_dict(cls, raw: Mapping[str, Any]) -> "WriterClaim":
        if not isinstance(raw, Mapping):
            raise _error("invalid", "writer claim record is invalid")
        required = {"participant_id", "worktree", "repository", "state"}
        if not required.issubset(raw):
            raise _error("invalid", "writer claim record is incomplete")
        if "metadata" in raw and not isinstance(raw["metadata"], Mapping):
            raise _error("invalid", "writer claim metadata is invalid")
        return cls(
            participant_id=raw.get("participant_id"),
            worktree=raw.get("worktree"),
            repository=raw.get("repository"),
            state=raw.get("state"),
            lane=raw.get("lane"),
            metadata=raw.get("metadata"),
        )


@dataclass(init=False)
class Participant:
    """Explicit top-level coordinator or worker in the managed roster."""

    participant_id: str
    session_id: str
    session_name: Optional[str]
    bound_lane: Optional[str]
    role: str
    parent_id: Optional[str]
    task_id: Optional[str]
    mailbox_id: str
    kind: str
    state: str
    writer_claim: Optional[WriterClaim]
    read_only: bool
    background: bool
    detached: bool
    model: Optional[str]
    permission_mode: Optional[str]
    fingerprint: Any
    metadata: Dict[str, Any]

    def __init__(
        self,
        participant_id: Optional[str] = None,
        session_id: Optional[str] = None,
        session_name: Optional[str] = None,
        bound_lane: Optional[str] = None,
        role: str = "worker",
        parent_id: Optional[str] = None,
        task_id: Optional[str] = None,
        mailbox_id: Optional[str] = None,
        kind: str = "independent",
        state: str = "reserved",
        writer_claim: Any = None,
        read_only: bool = False,
        background: bool = False,
        detached: bool = False,
        model: Optional[str] = None,
        permission_mode: Optional[str] = None,
        fingerprint: Any = None,
        metadata: Optional[Mapping[str, Any]] = None,
        **aliases: Any,
    ) -> None:
        if participant_id is None:
            participant_id = aliases.pop("id", aliases.pop("participant", None))
        if session_id is None:
            session_id = aliases.pop(
                "session_uuid", aliases.pop("native_session_id", aliases.pop("uuid", None))
            )
        if session_name is None:
            session_name = aliases.pop("name", aliases.pop("runner_name", None))
        if bound_lane is None:
            bound_lane = aliases.pop("lane", aliases.pop("lane_name", None))
        if parent_id is None and "parent" in aliases:
            parent_id = aliases.pop("parent")
        if task_id is None and "task" in aliases:
            task_id = aliases.pop("task")
        if mailbox_id is None:
            mailbox_id = aliases.pop("mailbox", aliases.pop("mailbox_identity", None))
        if writer_claim is None:
            writer_claim = aliases.pop("claim", None)
        if writer_claim is None and "worktree" in aliases:
            worktree = aliases.pop("worktree")
            writer_claim = WriterClaim(participant_id=participant_id, worktree=worktree)
        if "native_kind" in aliases and kind == "independent":
            kind = str(aliases["native_kind"])
        merged = dict(metadata or {})
        merged.update(aliases)
        self.participant_id = _id(participant_id, "participant_id") or ""
        self.session_id = _id(session_id, "session_id") or ""
        self.session_name = _optional_text(session_name, "session_name")
        self.bound_lane = _optional_text(bound_lane, "bound_lane")
        if not isinstance(role, str) or not role:
            raise _error("invalid", "participant role is required")
        self.role = role
        self.parent_id = _optional_text(parent_id, "parent_id")
        self.task_id = _optional_text(task_id, "task_id")
        self.mailbox_id = _id(mailbox_id, "mailbox_id") or ""
        if not isinstance(kind, str) or not kind:
            raise _error("invalid", "participant kind is required")
        self.kind = kind
        if not isinstance(state, str) or not state:
            raise _error("invalid", "participant state is invalid")
        if state not in _PARTICIPANT_STATES:
            raise _error("invalid", "participant state is invalid")
        self.state = state
        if writer_claim is None:
            self.writer_claim = None
        elif isinstance(writer_claim, WriterClaim):
            self.writer_claim = writer_claim
        elif isinstance(writer_claim, Mapping):
            self.writer_claim = WriterClaim.from_dict(writer_claim)
        else:
            raise _error("invalid", "writer claim is invalid")
        for flag, label in (
            (read_only, "read_only"),
            (background, "background"),
            (detached, "detached"),
        ):
            if not isinstance(flag, bool):
                raise _error("invalid", "%s must be boolean" % label)
        self.read_only = read_only
        self.background = background
        self.detached = detached
        self.model = _optional_text(model, "participant model")
        self.permission_mode = _optional_text(permission_mode, "participant permission_mode")
        self.fingerprint = fingerprint
        self.metadata = merged

    @property
    def id(self) -> str:
        return self.participant_id

    @property
    def session_uuid(self) -> str:
        return self.session_id

    @property
    def mailbox(self) -> str:
        return self.mailbox_id

    def to_dict(self) -> Dict[str, Any]:
        return {
            "participant_id": self.participant_id,
            "session_id": self.session_id,
            "session_uuid": self.session_id,
            "session_name": self.session_name,
            "bound_lane": self.bound_lane,
            "role": self.role,
            "parent_id": self.parent_id,
            "task_id": self.task_id,
            "mailbox_id": self.mailbox_id,
            "kind": self.kind,
            "state": self.state,
            "writer_claim": self.writer_claim.to_dict() if self.writer_claim else None,
            "read_only": self.read_only,
            "background": self.background,
            "detached": self.detached,
            "model": self.model,
            "permission_mode": self.permission_mode,
            "fingerprint": _json_value(self.fingerprint),
            "metadata": _json_value(self.metadata),
        }

    @classmethod
    def from_dict(cls, raw: Mapping[str, Any]) -> "Participant":
        if not isinstance(raw, Mapping):
            raise _error("invalid", "participant record is invalid")
        required = {
            "participant_id", "session_id", "session_name", "bound_lane",
            "role", "parent_id", "task_id",
            "mailbox_id", "kind", "state", "writer_claim", "read_only",
            "background", "detached", "model", "permission_mode", "fingerprint",
            "metadata",
        }
        if not required.issubset(raw):
            raise _error("invalid", "participant record is incomplete")
        if not isinstance(raw["metadata"], Mapping):
            raise _error("invalid", "participant metadata is invalid")
        return cls(
            participant_id=raw.get("participant_id"),
            session_id=raw.get("session_id"),
            session_name=raw.get("session_name"),
            bound_lane=raw.get("bound_lane"),
            role=raw.get("role"),
            parent_id=raw.get("parent_id"),
            task_id=raw.get("task_id"),
            mailbox_id=raw.get("mailbox_id"),
            kind=raw.get("kind"),
            state=raw.get("state"),
            writer_claim=raw.get("writer_claim"),
            read_only=raw.get("read_only"),
            background=raw.get("background"),
            detached=raw.get("detached"),
            model=raw.get("model"),
            permission_mode=raw.get("permission_mode"),
            fingerprint=raw.get("fingerprint"),
            metadata=raw.get("metadata"),
        )


@dataclass(init=False)
class MailboxEntry:
    """One explicit payload reference and its at-most-once dispatch state."""

    message_id: str
    request_id: str
    sender_id: str
    recipient_id: str
    task_id: Optional[str]
    payload_ref: Any
    state: str
    generation: Any
    operation_id: Optional[str]
    dispatch_attempt: int
    runtime_ack: Any
    metadata: Dict[str, Any]

    def __init__(
        self,
        message_id: Optional[str] = None,
        request_id: Optional[str] = None,
        sender_id: str = "user",
        recipient_id: Optional[str] = None,
        task_id: Optional[str] = None,
        payload_ref: Any = None,
        state: str = "queued",
        generation: Any = None,
        operation_id: Optional[str] = None,
        dispatch_attempt: int = 0,
        runtime_ack: Any = None,
        metadata: Optional[Mapping[str, Any]] = None,
        **aliases: Any,
    ) -> None:
        if message_id is None:
            message_id = aliases.pop("id", None)
        if request_id is None:
            request_id = aliases.pop("request", None)
        if recipient_id is None:
            recipient_id = aliases.pop("recipient", aliases.pop("to", None))
        if payload_ref is None and "payload" in aliases:
            payload_ref = aliases.pop("payload")
        merged = dict(metadata or {})
        merged.update(aliases)
        self.message_id = _id(message_id, "message_id") or ""
        self.request_id = _id(request_id, "request_id") or ""
        self.sender_id = _id(sender_id, "sender_id") or ""
        self.recipient_id = _id(recipient_id, "recipient_id") or ""
        self.task_id = _optional_text(task_id, "task_id")
        if payload_ref is None:
            raise _error("invalid", "payload_ref is required")
        # The mailbox carries an opaque lookup key only.  The resolver turns
        # it into ephemeral text after dispatch intent is durable; a body or
        # arbitrary JSON object must never enter the durable snapshot.
        self.payload_ref = _opaque_payload_reference(payload_ref)
        if not isinstance(state, str) or not state:
            raise _error("invalid", "mailbox state is invalid")
        if state not in _MAILBOX_STATES:
            raise _error("invalid", "mailbox state is invalid")
        self.state = state
        self.generation = generation
        self.operation_id = _optional_text(operation_id, "operation_id")
        if isinstance(dispatch_attempt, bool) or not isinstance(dispatch_attempt, int) or dispatch_attempt < 0:
            raise _error("invalid", "dispatch_attempt is invalid")
        self.dispatch_attempt = dispatch_attempt
        self.runtime_ack = runtime_ack
        self.metadata = merged

    def to_dict(self) -> Dict[str, Any]:
        return {
            "message_id": self.message_id,
            "request_id": self.request_id,
            "sender_id": self.sender_id,
            "recipient_id": self.recipient_id,
            "task_id": self.task_id,
            "payload_ref": _json_value(self.payload_ref),
            "state": self.state,
            "generation": _json_value(self.generation),
            "operation_id": self.operation_id,
            "dispatch_attempt": self.dispatch_attempt,
            "runtime_ack": _json_value(self.runtime_ack),
            "metadata": _json_value(self.metadata),
        }

    @classmethod
    def from_dict(cls, raw: Mapping[str, Any]) -> "MailboxEntry":
        if not isinstance(raw, Mapping):
            raise _error("invalid", "mailbox record is invalid")
        required = {
            "message_id", "request_id", "sender_id", "recipient_id", "task_id",
            "payload_ref", "state", "generation", "operation_id", "dispatch_attempt",
            "runtime_ack", "metadata",
        }
        if not required.issubset(raw):
            raise _error("invalid", "mailbox record is incomplete")
        if not isinstance(raw["metadata"], Mapping):
            raise _error("invalid", "mailbox metadata is invalid")
        return cls(
            message_id=raw.get("message_id"),
            request_id=raw.get("request_id"),
            sender_id=raw.get("sender_id"),
            recipient_id=raw.get("recipient_id"),
            task_id=raw.get("task_id"),
            payload_ref=raw.get("payload_ref"),
            state=raw.get("state"),
            generation=raw.get("generation"),
            operation_id=raw.get("operation_id"),
            dispatch_attempt=raw.get("dispatch_attempt"),
            runtime_ack=raw.get("runtime_ack"),
            metadata=raw.get("metadata"),
        )


@dataclass(init=False)
class Operation:
    """One serialized operation and its sealed roster/release evidence."""

    operation_id: str
    request_id: str
    mode: str
    generation: Any
    phase: str
    sealed_participants: Tuple[str, ...]
    release_count: int
    readiness: Dict[str, Any]
    uncertainty: list[Any]
    metadata: Dict[str, Any]

    def __init__(
        self,
        operation_id: Optional[str] = None,
        request_id: Optional[str] = None,
        mode: str = "",
        generation: Any = None,
        phase: str = "preflight",
        sealed_participants: Iterable[str] = (),
        release_count: int = 0,
        readiness: Optional[Mapping[str, Any]] = None,
        uncertainty: Optional[Iterable[Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
        **aliases: Any,
    ) -> None:
        if operation_id is None:
            operation_id = aliases.pop("id", None)
        merged = dict(metadata or {})
        merged.update(aliases)
        self.operation_id = _id(operation_id, "operation_id") or ""
        self.request_id = _id(request_id, "request_id") or ""
        if not isinstance(mode, str) or not mode:
            raise _error("invalid", "operation mode is required")
        self.mode = mode
        self.generation = generation
        if not isinstance(phase, str) or not phase:
            raise _error("invalid", "operation phase is invalid")
        if phase not in _OPERATION_PHASES:
            raise _error("invalid", "operation phase is invalid")
        self.phase = phase
        if isinstance(sealed_participants, (str, bytes)):
            raise _error("invalid", "operation sealed participants are invalid")
        self.sealed_participants = tuple(_id(item, "sealed participant") or "" for item in sealed_participants)
        if isinstance(release_count, bool) or not isinstance(release_count, int) or release_count < 0:
            raise _error("invalid", "operation release_count is invalid")
        self.release_count = release_count
        if readiness is not None and not isinstance(readiness, Mapping):
            raise _error("invalid", "operation readiness is invalid")
        self.readiness = dict(readiness or {})
        if isinstance(uncertainty, (str, bytes, Mapping)):
            raise _error("invalid", "operation uncertainty is invalid")
        self.uncertainty = list(uncertainty or ())
        self.metadata = merged

    @property
    def id(self) -> str:
        return self.operation_id

    def to_dict(self) -> Dict[str, Any]:
        return {
            "operation_id": self.operation_id,
            "request_id": self.request_id,
            "mode": self.mode,
            "generation": _json_value(self.generation),
            "phase": self.phase,
            "sealed_participants": list(self.sealed_participants),
            "release_count": self.release_count,
            "readiness": _json_value(self.readiness),
            "uncertainty": _json_value(self.uncertainty),
            "metadata": _json_value(self.metadata),
        }

    @classmethod
    def from_dict(cls, raw: Mapping[str, Any]) -> "Operation":
        if not isinstance(raw, Mapping):
            raise _error("invalid", "operation record is invalid")
        required = {
            "operation_id", "request_id", "mode", "generation", "phase",
            "sealed_participants", "release_count", "readiness", "uncertainty",
            "metadata",
        }
        if not required.issubset(raw):
            raise _error("invalid", "operation record is incomplete")
        if not isinstance(raw["sealed_participants"], list):
            raise _error("invalid", "operation sealed participants are invalid")
        if not isinstance(raw["readiness"], Mapping):
            raise _error("invalid", "operation readiness is invalid")
        if not isinstance(raw["uncertainty"], list):
            raise _error("invalid", "operation uncertainty is invalid")
        if not isinstance(raw["metadata"], Mapping):
            raise _error("invalid", "operation metadata is invalid")
        return cls(
            operation_id=raw.get("operation_id"),
            request_id=raw.get("request_id"),
            mode=raw.get("mode"),
            generation=raw.get("generation"),
            phase=raw.get("phase"),
            sealed_participants=raw.get("sealed_participants"),
            release_count=raw.get("release_count"),
            readiness=raw.get("readiness"),
            uncertainty=raw.get("uncertainty"),
            metadata=raw.get("metadata"),
        )


_BANNED_KIND_WORDS = frozenset(
    {
        "agent",
        "task",
        "team",
        "teams",
        "background",
        "run_in_background",
        "detached",
        "native-agent",
        "native-task",
        "native-team",
    }
)
_ALLOWED_KIND_WORDS = frozenset(
    {
        "",
        "independent",
        "top-level",
        "top_level",
        "top-level-session",
        "top_level_session",
        "managed",
        "session",
        "coordinator",
        "worker",
    }
)
# A failed/indeterminate operation is deliberately still active.  It may
# carry unresolved writers/effects and cannot be replaced until an explicit
# recovery owner advances it; treating either phase as terminal would reopen
# admission and permit a second operation to race it.
_TERMINAL_OPERATION_PHASES = frozenset({"released", "complete"})
_FENCED_PHASES = frozenset({"quiescing", "paused", "starting", "ready-held", "held"})
_PARTICIPANT_STATES = frozenset({"reserved", "held", "active", "completed", "stopped"})
_MAILBOX_STATES = frozenset(
    {"queued", "fenced", "dispatch-intent", "acknowledged", "uncertain"}
)
_OPERATION_PHASES = frozenset(
    {
        "preflight",
        "quiescing",
        "paused",
        "starting",
        "ready-held",
        "released",
        "failed",
        "indeterminate",
        "complete",
    }
)

# Permission-mode names are deliberately absent from the claimless admission
# gate.  ``dontAsk`` (and the other SDK permission modes) controls prompting;
# it does not constrain the tool surface.  A claimless participant is admitted
# only when the state record carries the same explicit, bounded tool boundary
# that the runner will enforce before every tool call.
_READ_ONLY_BUILTIN_TOOLS = frozenset(
    {"read", "glob", "grep", "ls", "list", "search", "todoread", "webfetch", "websearch"}
)
_READ_ONLY_REQUIRED_DENIALS = frozenset(
    {"write", "edit", "bash", "execute", "shell", "agent", "task", "team"}
)
_READ_ONLY_DENIAL_GROUPS = (
    frozenset({"write", "edit"}),
    frozenset({"bash", "execute", "shell"}),
    frozenset({"agent", "task", "team"}),
)


def _transactional(method):
    """Run one controller mutation/read against the latest durable record."""

    def wrapped(self, *args, **kwargs):
        with self._transaction():
            return method(self, *args, **kwargs)

    wrapped.__name__ = getattr(method, "__name__", "controller_method")
    wrapped.__doc__ = getattr(method, "__doc__", None)
    return wrapped


class ManagedController:
    """Roster, mailbox, operation serialization, and writer claim authority."""

    def __init__(
        self,
        store: Any,
        runtime: Any = None,
        clock: Any = None,
        payload_resolver: Any = None,
        transcript_verifier: Any = None,
        _capability_evidence_provider: Any = None,
        _native_stop_daemon_id: Optional[str] = None,
        _coordinator_interrupt_daemon_id: Optional[str] = None,
        _native_adoption_evidence_provider: Any = None,
        _native_swap_evidence_provider: Any = None,
    ) -> None:
        if store is None:
            raise _error("unsupported", "managed controller requires a durable state store")
        if not isinstance(store, Mapping) and not any(
            callable(getattr(store, name, None))
            for name in ("read_json", "read", "load", "get")
        ):
            raise _error("unsupported", "managed controller state store cannot read records")
        if not isinstance(store, Mapping) and not any(
            callable(getattr(store, name, None))
            for name in ("write_json", "write", "save", "put")
        ):
            raise _error("unsupported", "managed controller state store cannot persist records")
        self.store = store
        self.runtime = runtime
        self.clock = clock if clock is not None else time.time
        # This resolver is intentionally ephemeral and injected by the
        # production daemon.  Controller state stores only the opaque ref.
        self.payload_resolver = payload_resolver
        # Exact transcript-preflight seam from transcript-preflight.md.  It is
        # deliberately separate from the durable state store: profile and OS
        # facts come from the resolver, while this controller owns policy.
        self.transcript_verifier = transcript_verifier
        # Gate 0 evidence is an internal runtime/provider seam.  It is never
        # read from a public request or durable runner specification.
        self._capability_evidence_provider = _capability_evidence_provider
        self._native_stop_daemon_id = (
            None if _native_stop_daemon_id is None else
            (_id(_native_stop_daemon_id, "native stop daemon ID") or "")
        )
        self._coordinator_interrupt_daemon_id = (
            None if _coordinator_interrupt_daemon_id is None else
            (_id(_coordinator_interrupt_daemon_id, "coordinator interrupt daemon ID") or "")
        )
        # Adoption evidence is an internal, synchronous gate only.  It is
        # deliberately absent by default and is never sourced from a public
        # request, runner specification, or durable boolean.
        self._native_adoption_evidence_provider = (
            _native_adoption_evidence_provider
        )
        # Native swap evidence is a separate, constructor-only observation
        # authority.  It never comes from a public request, stored boolean,
        # or the static capability gate.
        self._native_swap_evidence_provider = _native_swap_evidence_provider
        self._local_lock = threading.RLock()
        self._transaction_local = threading.local()
        self._participants: Dict[str, Participant] = {}
        self._archived_participants: Dict[str, Participant] = {}
        self._session_history: set[str] = set()
        self._mailboxes: Dict[str, MailboxEntry] = {}
        self._operations: Dict[str, Operation] = {}
        self._requests: Dict[str, Dict[str, Any]] = {}
        self._checkpoints: Dict[str, Dict[str, Any]] = {}
        self._generation: Any = None
        self._coordinator_id: Optional[str] = None
        self._active_operation_id: Optional[str] = None
        self._native_context: Optional[Dict[str, Any]] = None
        self._native_admissions: Dict[str, Dict[str, Any]] = {}
        self._native_child_observations: Dict[str, Dict[str, Any]] = {}
        # Preserve the optional child-observation field exactly for older
        # snapshots.  An absent ledger is not rewritten as an empty one until
        # a real observation (or an explicit pre-existing field) exists.
        self._native_child_observations_present = False
        self._native_stops: Dict[str, Dict[str, Any]] = {}
        self._coordinator_interrupts: Dict[str, Dict[str, Any]] = {}
        self._native_invocation_history: Dict[str, Dict[str, Any]] = {}
        self._native_invocation_rollovers: Dict[str, Dict[str, Any]] = {}
        self._native_source_archives: Dict[str, Dict[str, Any]] = {}
        # Source archives are immutable once published.  Cache only a fully
        # validated normalized archive, keyed by the digest of its complete
        # durable bytes; every reload still hashes the incoming value first,
        # so a changed/tampered snapshot can never reuse the cache.
        self._native_source_archive_validation_cache: Dict[
            Tuple[str, str], Dict[str, Any]
        ] = {}
        # Runtime awaits are intentionally tracked only in memory.  A fresh
        # controller must never infer a no-send result from this marker; the
        # adapter-owned receipt is the durable authority after a reload.
        self._native_dispatch_inflight: Dict[str, str] = {}
        self._load()

    # ---- storage seam -------------------------------------------------

    def _read_record(self) -> Any:
        if self.store is None:
            return None
        if isinstance(self.store, Mapping):
            return self.store.get("controller.json", self.store.get("controller"))
        for name in ("read_json", "read", "load", "get"):
            method = getattr(self.store, name, None)
            if not callable(method):
                continue
            try:
                return method("controller.json")
            except ManagedStateError as exc:
                raise _error(exc.code, exc.message)
            except (KeyError, FileNotFoundError):
                return None
            except TypeError:
                try:
                    return method("controller")
                except ManagedStateError as exc:
                    raise _error(exc.code, exc.message)
                except (KeyError, FileNotFoundError):
                    return None
        return None

    def _write_record(self, record: Mapping[str, Any]) -> None:
        if self.store is None:
            return
        payload = _json_value(record)
        required = {
            "schema_version", "architecture", "record_kind", "generation",
            "coordinator_id", "active_operation_id", "participants",
            "mailboxes", "operations", "requests",
        }
        _native_validate(
            payload, record_kind="controller", required=required,
            label="managed controller record",
        )
        # A controller object may have been created before another process
        # published an obsolete snapshot.  Re-read that snapshot under the
        # store's own write boundary and refuse before calling its writer;
        # no migration or deletion is implicit in this path.
        current = self._read_record()
        if current is not None:
            _native_validate(
                current, record_kind="controller",
                label="managed controller record",
            )
        if isinstance(self.store, MutableMapping):
            self.store["controller.json"] = payload
            return
        for name in ("write_json", "write", "save", "put"):
            method = getattr(self.store, name, None)
            if not callable(method):
                continue
            try:
                method("controller.json", payload)
            except ManagedStateError as exc:
                raise _error(exc.code, exc.message)
            except TypeError:
                try:
                    method("controller", payload)
                except ManagedStateError as exc:
                    raise _error(exc.code, exc.message)
            return
        raise _error("unsupported", "managed controller state store cannot persist records")

    def _append_journal(self, event: Mapping[str, Any]) -> None:
        if self.store is None:
            return
        method = getattr(self.store, "append_journal", None)
        if callable(method):
            try:
                method("controller.jsonl", _json_value(event))
            except TypeError:
                method("controller", _json_value(event))
            return
        method = getattr(self.store, "journal", None)
        if callable(method):
            try:
                method(_json_value(event))
            except TypeError:
                method("controller", _json_value(event))

    def _validate_native_swap_record_links(
            self, operation: Operation, native_swap: Mapping[str, Any]
    ) -> None:
        """Join provider evidence to the controller-owned swap facts."""
        evidence = native_swap.get("native_swap_evidence")
        if not isinstance(evidence, Mapping):
            raise _error("invalid", "durable native swap evidence is malformed")
        for stage, record in evidence.items():
            if not isinstance(stage, str) or not isinstance(record, Mapping):
                raise _error("invalid", "durable native swap evidence record is malformed")
            observation = record.get("observation")
            if not isinstance(observation, Mapping):
                raise _error("invalid", "durable native swap evidence observation is malformed")
            expected_binding = self._native_swap_binding_locked(operation, stage)
            if observation.get("binding") != expected_binding:
                raise _error(
                    "ownership-conflict",
                    "native swap evidence binding is not joined to its operation",
                )

        interrupt_digest = native_swap.get("interrupt_intent_digest")
        if interrupt_digest is not None:
            selection = operation.metadata.get("coordinator_interrupt_selection")
            if (not isinstance(selection, Mapping)
                    or _digest(selection) != interrupt_digest):
                raise _error(
                    "stale-generation",
                    "native swap interrupt evidence is not joined to its selection",
                )
        if "graph-drained" in evidence and interrupt_digest is None:
            raise _error(
                "stale-generation",
                "native swap graph evidence has no committed interrupt selection",
            )

        source_operation_id = native_swap.get("source_operation_id")
        source_operation = self._operations.get(source_operation_id)
        if source_operation is None:
            raise _error("stale-generation", "native swap source operation is unavailable")
        source_startup = native_swap.get("source_startup")
        source_participant_id = (
            source_startup.get("participant_id")
            if isinstance(source_startup, Mapping) else None
        )
        if (not isinstance(source_startup, Mapping)
                or source_operation.metadata.get("native_startup") != source_startup):
            raise _error(
                "ownership-conflict",
                "native swap source startup is not joined to its source operation",
            )
        source_gates = source_operation.metadata.get("capability_gates")
        source_gate = (
            source_gates.get(source_participant_id)
            if isinstance(source_gates, Mapping)
            and isinstance(source_participant_id, str)
            else None
        )
        source_digest = native_swap.get("source_runtime_identity_digest")
        if (not isinstance(source_gate, Mapping)
                or source_gate.get("verdict") != "verified"
                or source_gate.get("identity_digest") != source_digest):
            raise _error(
                "ownership-conflict",
                "native swap source capability is not joined to its source operation",
            )
        target_digest = native_swap.get("runtime_identity_digest")
        if target_digest is not None:
            target_gates = operation.metadata.get("capability_gates")
            target_gate = (
                target_gates.get(source_participant_id)
                if isinstance(target_gates, Mapping)
                and isinstance(source_participant_id, str)
                else None
            )
            if (not isinstance(target_gate, Mapping)
                    or target_gate.get("verdict") != "verified"
                    or target_gate.get("identity_digest") != target_digest):
                raise _error(
                    "ownership-conflict",
                    "native swap target capability is not joined to its operation",
                )

        release_binding = native_swap.get("release_binding")
        if release_binding is not None:
            expected_release_binding = self._native_swap_release_binding_locked(operation)
            if release_binding != expected_release_binding:
                raise _error(
                    "stale-generation",
                    "native swap release binding is not joined to its operation",
                )

        archive_digest = native_swap.get("source_archive_digest")
        if archive_digest is None:
            return
        archive = self._native_source_archives.get(native_swap.get("source_archive_id"))
        if not isinstance(archive, Mapping):
            raise _error("stale-generation", "native swap source archive is unavailable")
        snapshot = archive.get("snapshot")
        if not isinstance(snapshot, Mapping):
            raise _error("invalid", "native swap source archive snapshot is malformed")
        archived_context = snapshot.get("native_context")
        captured_context = native_swap.get("source_context")
        if (not isinstance(archived_context, Mapping)
                or not isinstance(captured_context, Mapping)):
            raise _error("invalid", "native swap source archive context is malformed")
        if archived_context.get("fenced") is not True:
            raise _error("ownership-conflict", "native swap source archive is not fenced")
        # The archive is taken after the durable fence.  ``fenced`` is the
        # one lifecycle bit that legitimately changes after source capture;
        # all identity, lineage, definition, and watermark facts remain
        # joined to the immutable captured context.
        archived_context_projection = dict(archived_context)
        captured_context_projection = dict(captured_context)
        archived_context_projection.pop("fenced", None)
        captured_context_projection.pop("fenced", None)
        if archived_context_projection != captured_context_projection:
            raise _error(
                "ownership-conflict",
                "native swap source archive context changed",
            )
        archived_operations = snapshot.get("operations")
        archived_source = None
        if isinstance(archived_operations, list):
            archived_source = next(
                (
                    item for item in archived_operations
                    if isinstance(item, Mapping)
                    and item.get("operation_id") == source_operation_id
                ),
                None,
            )
        archived_metadata = (
            archived_source.get("metadata")
            if isinstance(archived_source, Mapping) else None
        )
        if (not isinstance(archived_metadata, Mapping)
                or archived_metadata.get("native_startup") != source_startup):
            raise _error(
                "ownership-conflict",
                "native swap source archive startup changed",
            )

    def _record(self) -> Dict[str, Any]:
        for participant in list(self._participants.values()) + list(self._archived_participants.values()):
            self._validate_durable_participant(participant)
        for operation in self._operations.values():
            self._validate_durable_operation(operation)
            native_swap = operation.metadata.get("native_swap")
            if isinstance(native_swap, Mapping):
                self._validate_native_swap_record_links(operation, native_swap)
                archive_id = native_swap.get("source_archive_id")
                archive_digest = native_swap.get("source_archive_digest")
                if archive_digest is not None:
                    archive = self._native_source_archives.get(archive_id)
                    if (not isinstance(archive, Mapping)
                            or archive.get("operation_id") != operation.operation_id
                            or archive.get("snapshot_digest") != archive_digest
                            or archive.get("source_identity") != native_swap.get("source_identity")):
                        raise _error(
                            "stale-generation",
                            "native swap source archive is not joined to its operation",
                        )
        # Re-run the two-pass child validator before every durable write.  A
        # caller may have mutated a detached observation or admission after a
        # prior load; integrity of the enclosing controller record is not a
        # substitute for the causal context/identity joins.
        if self._native_child_observations_present:
            self._load_native_child_observations({
                "native_child_observations": self._native_child_observations,
            })
        self._validate_native_admission_parent_links()
        history_ids = set(self._native_invocation_history)
        if len(history_ids) > _NATIVE_INVOCATION_HISTORY_LIMIT:
            raise _error("invalid", "native invocation history exceeds capacity")
        if len(self._native_invocation_rollovers) > _NATIVE_ROLLOVER_LIMIT:
            raise _error("invalid", "native invocation rollover exceeds capacity")
        for history_id, history in self._native_invocation_history.items():
            self._validate_native_invocation_history_entry(
                history, expected_history_id=history_id,
            )
        for rollover_id, rollover in self._native_invocation_rollovers.items():
            self._validate_native_invocation_rollover_entry(
                rollover, expected_rollover_id=rollover_id,
                expected_generation=self._generation, history_ids=history_ids,
            )
        self._validate_native_invocation_cross_links(
            self._native_invocation_history,
            self._native_invocation_rollovers,
            current_context=self._native_context,
        )
        self._validate_native_child_identity_joins()
        ledger = {
            "native_invocation_history": self._native_invocation_history,
            "native_invocation_rollovers": self._native_invocation_rollovers,
        }
        if len(_canonical_json(ledger).encode("utf-8")) > _NATIVE_INVOCATION_LEDGER_BYTES:
            raise _error("invalid", "native invocation ledger exceeds capacity")
        requests = {
            request_id: {
                "digest": value.get("digest"),
                "kind": value.get("kind"),
                "result": _json_value(value.get("result")),
            }
            for request_id, value in self._requests.items()
        }
        record = {
            **native_record_marker("controller"),
            "generation": _json_value(self._generation),
            "coordinator_id": self._coordinator_id,
            "active_operation_id": self._active_operation_id,
            "participants": [item.to_dict() for item in self._participants.values()],
            "archived_participants": [
                item.to_dict() for item in self._archived_participants.values()
            ],
            "session_history": sorted(self._session_history),
            "mailboxes": [item.to_dict() for item in self._mailboxes.values()],
            "operations": [item.to_dict() for item in self._operations.values()],
            "requests": requests,
            "checkpoints": [
                _json_value(value) for value in self._checkpoints.values()
            ],
            "native_context": _json_value(self._native_context),
            "native_admissions": _json_value(self._native_admissions),
            "native_stops": _json_value(self._native_stops),
            "coordinator_interrupts": _json_value(self._coordinator_interrupts),
            "native_invocation_history": _json_value(self._native_invocation_history),
            "native_invocation_rollovers": _json_value(self._native_invocation_rollovers),
            "native_source_archives": _json_value(self._native_source_archives),
        }
        if self._native_child_observations_present:
            record["native_child_observations"] = _json_value(
                self._native_child_observations
            )
        return record

    def _persist(self, event: Optional[Mapping[str, Any]] = None) -> None:
        self._write_record(self._record())
        if event is not None:
            self._append_journal({"at": self.clock(), **dict(event)})

    def _load(self) -> None:
        # Every transaction starts from the latest durable snapshot.  Clearing
        # first also makes malformed/partial records fail closed instead of
        # accidentally retaining objects from a prior in-memory generation.
        self._participants.clear()
        self._archived_participants.clear()
        self._session_history.clear()
        self._mailboxes.clear()
        self._operations.clear()
        self._requests.clear()
        self._checkpoints.clear()
        self._generation = None
        self._coordinator_id = None
        self._active_operation_id = None
        self._native_context = None
        self._native_admissions.clear()
        self._native_child_observations.clear()
        self._native_child_observations_present = False
        self._native_stops.clear()
        self._coordinator_interrupts.clear()
        self._native_invocation_history.clear()
        self._native_invocation_rollovers.clear()
        self._native_source_archives.clear()
        raw = self._read_record()
        if raw is None:
            return
        if not isinstance(raw, Mapping):
            raise _error("invalid", "managed controller record is not an object")
        # Validate the shared envelope before looking at any prototype fields.
        # In particular, ``schema``/schema-1 snapshots are read-only refusal
        # cases and must not be interpreted as a partial native roster.
        _native_validate(
            raw, record_kind="controller",
            label="managed controller record",
        )
        required = {
            "schema_version",
            "architecture",
            "record_kind",
            "generation",
            "coordinator_id",
            "active_operation_id",
            "participants",
            "mailboxes",
            "operations",
            "requests",
        }
        if not required.issubset(raw):
            raise _error("invalid", "managed controller record is incomplete")
        generation = raw.get("generation")
        if generation is not None:
            self._generation_valid(generation)
        coordinator_id = raw.get("coordinator_id")
        active_operation_id = raw.get("active_operation_id")
        if coordinator_id is not None:
            coordinator_id = _id(coordinator_id, "coordinator_id")
        if active_operation_id is not None:
            active_operation_id = _id(active_operation_id, "active_operation_id")
        participants = raw.get("participants")
        archived_participants = raw.get("archived_participants", [])
        session_history = raw.get("session_history")
        mailboxes = raw.get("mailboxes")
        operations = raw.get("operations")
        checkpoints = raw.get("checkpoints", [])
        if not isinstance(participants, list):
            raise _error("invalid", "managed controller participants are invalid")
        if not isinstance(archived_participants, list):
            raise _error("invalid", "managed controller archived participants are invalid")
        if session_history is not None and not isinstance(session_history, list):
            raise _error("invalid", "managed controller session history is invalid")
        if not isinstance(mailboxes, list):
            raise _error("invalid", "managed controller mailboxes are invalid")
        if not isinstance(operations, list):
            raise _error("invalid", "managed controller operations are invalid")
        if not isinstance(checkpoints, (list, Mapping)):
            raise _error("invalid", "managed controller checkpoints are invalid")
        participant_ids = set()
        session_ids = set()
        session_names = set()
        bound_lanes = set()
        mailbox_identities = set()
        for item in participants:
            if not isinstance(item, Mapping):
                raise _error("invalid", "managed controller participant entry is invalid")
            participant = Participant.from_dict(item)
            self._validate_durable_participant(participant)
            if participant.participant_id in participant_ids:
                raise _error("invalid", "managed controller has duplicate participant IDs")
            if participant.session_id in session_ids:
                raise _error("invalid", "managed controller has duplicate session UUIDs")
            if participant.session_name in session_names:
                raise _error("invalid", "managed controller has duplicate session names")
            if participant.mailbox_id in mailbox_identities:
                raise _error("invalid", "managed controller has duplicate mailbox identities")
            participant_ids.add(participant.participant_id)
            session_ids.add(participant.session_id)
            session_names.add(participant.session_name)
            bound_lanes.add(participant.bound_lane)
            mailbox_identities.add(participant.mailbox_id)
            self._participants[participant.participant_id] = participant
        for item in archived_participants:
            if not isinstance(item, Mapping):
                raise _error("invalid", "managed controller archived participant entry is invalid")
            participant = Participant.from_dict(item)
            self._validate_durable_participant(participant)
            if participant.participant_id in participant_ids:
                raise _error("invalid", "managed controller repeats a participant ID")
            if participant.session_id in session_ids:
                raise _error("invalid", "managed controller repeats a session UUID")
            if participant.session_name in session_names:
                raise _error("invalid", "managed controller repeats a session name")
            if participant.mailbox_id in mailbox_identities:
                raise _error("invalid", "managed controller repeats a mailbox identity")
            participant_ids.add(participant.participant_id)
            session_ids.add(participant.session_id)
            session_names.add(participant.session_name)
            bound_lanes.add(participant.bound_lane)
            mailbox_identities.add(participant.mailbox_id)
            self._archived_participants[participant.participant_id] = participant
        if session_history is None:
            self._session_history = set(session_ids)
        else:
            history: set[str] = set()
            for value in session_history:
                if not isinstance(value, str) or not value or value in history:
                    raise _error("invalid", "managed controller session history is malformed")
                history.add(value)
            if not session_ids.issubset(history):
                raise _error("invalid", "managed controller session history omits a participant")
            self._session_history = history
        if sum(item.role.casefold() == "coordinator" for item in self._participants.values()) > 1:
            raise _error("invalid", "managed controller has more than one coordinator")
        if len(bound_lanes) > 1:
            raise _error("invalid", "managed controller participants are bound to different lanes")
        for participant in list(self._participants.values()) + list(self._archived_participants.values()):
            self._validate_bound_lane(participant)
        if coordinator_id is not None and coordinator_id not in self._participants:
            raise _error("invalid", "managed controller coordinator ID is unknown")
        mailbox_ids = set()
        for item in mailboxes:
            if not isinstance(item, Mapping):
                raise _error("invalid", "managed controller mailbox entry is invalid")
            mailbox = MailboxEntry.from_dict(item)
            if mailbox.message_id in mailbox_ids:
                raise _error("invalid", "managed controller has duplicate message IDs")
            mailbox_ids.add(mailbox.message_id)
            self._mailboxes[mailbox.message_id] = mailbox
        operation_ids = set()
        for item in operations:
            if not isinstance(item, Mapping):
                raise _error("invalid", "managed controller operation entry is invalid")
            operation = Operation.from_dict(item)
            self._validate_durable_operation(operation)
            if operation.phase not in _OPERATION_PHASES:
                raise _error("invalid", "managed controller operation phase is invalid")
            if operation.operation_id in operation_ids:
                raise _error("invalid", "managed controller has duplicate operation IDs")
            operation_ids.add(operation.operation_id)
            self._operations[operation.operation_id] = operation
        if active_operation_id is not None and active_operation_id not in self._operations:
            raise _error("invalid", "managed controller active operation ID is unknown")
        requests = raw.get("requests", {})
        if not isinstance(requests, Mapping):
            raise _error("invalid", "managed controller request ledger is invalid")
        self._requests = {}
        for key, value in requests.items():
            if not isinstance(key, str) or not key or not isinstance(value, Mapping):
                raise _error("invalid", "managed controller request ledger entry is invalid")
            digest = value.get("digest")
            if (not isinstance(digest, str) or len(digest) != 64 or
                    any(char not in "0123456789abcdef" for char in digest)):
                raise _error("invalid", "managed controller request digest is invalid")
            kind = value.get("kind")
            if kind not in {"submit", "operation"}:
                raise _error("invalid", "managed controller request kind is invalid")
            if "result" not in value:
                raise _error("invalid", "managed controller request result is missing")
            if _contains_secret_key(value.get("result")) is not None:
                raise _error("unsupported", "managed request result contains credential or environment data")
            self._requests[key] = dict(value)
        if isinstance(checkpoints, Mapping):
            checkpoint_items = list(checkpoints.items())
        else:
            checkpoint_items = []
            for item in checkpoints:
                if not isinstance(item, Mapping):
                    raise _error("invalid", "managed controller checkpoint entry is invalid")
                checkpoint_items.append((item.get("request_id"), item))
        checkpoint_ids = set()
        for key, value in checkpoint_items:
            if not isinstance(key, str) or not key or not isinstance(value, Mapping):
                raise _error("invalid", "managed controller checkpoint entry is invalid")
            checkpoint_id = _id(value.get("request_id", key), "checkpoint request_id") or ""
            if checkpoint_id != key and isinstance(checkpoints, Mapping):
                raise _error("invalid", "managed controller checkpoint key is inconsistent")
            if checkpoint_id in checkpoint_ids:
                raise _error("invalid", "managed controller has duplicate checkpoints")
            if value.get("generation") is None:
                raise _error("invalid", "managed controller checkpoint generation is missing")
            if "checkpoint" not in value:
                raise _error("invalid", "managed controller checkpoint reference is missing")
            normalized_checkpoint = self._checkpoint_reference(value.get("checkpoint"))
            if _json_value(normalized_checkpoint) != _json_value(value.get("checkpoint")):
                raise _error("invalid", "managed controller checkpoint reference is not canonical")
            checkpoint_ids.add(checkpoint_id)
            self._checkpoints[checkpoint_id] = dict(value)
        self._generation = generation
        self._coordinator_id = coordinator_id
        self._active_operation_id = active_operation_id
        if self._coordinator_id is None:
            coordinators = [
                participant.participant_id
                for participant in self._participants.values()
                if participant.role.casefold() == "coordinator"
            ]
            self._coordinator_id = coordinators[0] if coordinators else None
        elif self._participants[self._coordinator_id].role.casefold() != "coordinator":
            raise _error("invalid", "managed controller coordinator ID is not a coordinator")
        if self._participants and self._generation is None:
            raise _error("invalid", "managed controller roster has no generation")
        active_operations = [
            operation for operation in self._operations.values()
            if operation.phase not in _TERMINAL_OPERATION_PHASES
        ]
        if len(active_operations) > 1:
            raise _error("invalid", "managed controller has more than one active operation")
        if active_operations:
            if self._active_operation_id != active_operations[0].operation_id:
                raise _error("invalid", "managed controller active operation is inconsistent")
        elif self._active_operation_id is not None:
            active = self._operations[self._active_operation_id]
            # A released operation remains the current generation's dispatch
            # gate until the next operation supersedes it.  ``complete`` is
            # terminal history and must not remain the active pointer.
            if active.phase == "complete":
                raise _error("invalid", "managed controller points at a terminal operation")
        for participant in self._participants.values():
            if participant.role.casefold() == "worker":
                parent = self._participants.get(participant.parent_id)
                if parent is None:
                    parent = self._archived_participants.get(participant.parent_id)
                if parent is None:
                    raise _error("invalid", "managed controller worker parent is unknown")
                if parent.role.casefold() != "coordinator":
                    raise _error("invalid", "managed controller worker parent is not a coordinator")
            if participant.writer_claim is not None:
                self._claim_for(participant)
        for mailbox in self._mailboxes.values():
            if mailbox.state not in _MAILBOX_STATES:
                raise _error("invalid", "managed controller mailbox state is invalid")
            if (mailbox.recipient_id not in self._participants
                    and mailbox.recipient_id not in self._archived_participants):
                raise _error("invalid", "managed controller mailbox recipient is unknown")
            if mailbox.generation != self._generation:
                historical_operation = self._operations.get(mailbox.operation_id or "")
                if (
                    historical_operation is None
                    or historical_operation.generation != mailbox.generation
                    or historical_operation.phase not in _TERMINAL_OPERATION_PHASES
                ):
                    raise _error("invalid", "managed controller mailbox generation is stale")
            if mailbox.operation_id is not None:
                operation = self._operations.get(mailbox.operation_id)
                if operation is None or operation.generation != mailbox.generation:
                    raise _error("invalid", "managed controller mailbox operation is invalid")
            if mailbox.state == "acknowledged":
                if self._ack_id(mailbox.runtime_ack) != mailbox.message_id:
                    raise _error("invalid", "managed controller mailbox acknowledgement is invalid")
        for operation in self._operations.values():
            if operation.generation != self._generation:
                if operation.phase not in _TERMINAL_OPERATION_PHASES:
                    raise _error("invalid", "managed controller operation generation is stale")
                # Completed/released operations remain durable historical
                # records across an authoritative owner-generation rollover.
                # They cannot become the active dispatch gate for the new
                # generation, but retaining them preserves stale-request and
                # session-reservation evidence after re-enrollment.
                continue
            if len(set(operation.sealed_participants)) != len(operation.sealed_participants):
                raise _error("invalid", "managed controller operation seals a participant twice")
            if any(
                item not in self._participants and item not in self._archived_participants
                for item in operation.sealed_participants
            ):
                raise _error("invalid", "managed controller operation seals an unknown participant")
        self._load_native_admissions(raw)
        self._load_native_child_observations(raw)
        self._validate_native_admission_parent_links()
        self._load_native_stops(raw)
        self._load_coordinator_interrupts(raw)
        self._load_native_invocation_history(raw)
        self._load_native_source_archives(raw)
        self._validate_native_child_identity_joins()
        # Source archives are loaded last because the operation-side join
        # needs their immutable snapshots.  Re-run the controller-owned
        # native-swap joins after every complete reload; validating provider
        # hashes alone is insufficient when a snapshot forges a different
        # but independently well-formed binding.
        for operation in self._operations.values():
            native_swap = operation.metadata.get("native_swap")
            if isinstance(native_swap, Mapping):
                self._validate_native_swap_record_links(operation, native_swap)

    # ---- durable native pre-allow authority ----------------------------

    @staticmethod
    def _native_definition_facts(definitions: Any) -> Dict[str, Any]:
        """Fingerprint trusted launch definitions without persisting prompts."""
        # The runtime and durable authority must compare the same body-free
        # facts while their digest still covers the complete private definition.
        from lane_managed_sdk import SdkAdapterError, native_definition_facts

        definitions = _mapping(definitions, "trusted native definitions")
        if not definitions or len(definitions) > 256:
            raise _error("invalid", "trusted native definition count is invalid")
        try:
            return native_definition_facts(definitions)
        except SdkAdapterError as exc:
            raise _error("invalid", "trusted native definition is invalid") from exc

    @staticmethod
    def _validate_native_context(value: Any) -> Dict[str, Any]:
        raw = _native_validate(value, record_kind="admission-context",
                               label="native admission context")
        expected = {"schema_version", "architecture", "record_kind", "lineage",
                    "runner_incarnation", "invocation_id", "invocation_watermark",
                    "prompt_id", "definitions", "fenced"}
        if set(raw) != expected:
            raise _error("invalid", "native admission context fields are malformed")
        lineage = LineageRecord.from_dict(raw["lineage"])
        for key in ("runner_incarnation", "invocation_id"):
            _id(raw[key], "native context " + key)
        _optional_text(raw["prompt_id"], "native context prompt_id")
        _native_positive_generation(raw["invocation_watermark"], "native invocation watermark")
        if type(raw["fenced"]) is not bool:
            raise _error("invalid", "native context fence is invalid")
        definitions = _mapping(raw["definitions"], "native definition facts")
        if not definitions or len(definitions) > 256:
            raise _error("invalid", "native definition facts count is invalid")
        keys = {"name", "digest", "tools", "model", "effort", "permissionMode",
                "permissions", "writable_paths"}
        for name, fact in definitions.items():
            _id(name, "native definition name")
            if not isinstance(fact, Mapping) or set(fact) != keys or fact["name"] != name:
                raise _error("invalid", "native definition facts are malformed")
            if not isinstance(fact["digest"], str) or not re.fullmatch(r"[0-9a-f]{64}", fact["digest"]):
                raise _error("invalid", "native definition digest is invalid")
            tools = fact["tools"]
            if (not isinstance(tools, list) or not tools or len(tools) > 128
                    or any(not isinstance(tool, str) or not tool or len(tool) > 128 for tool in tools)):
                raise _error("invalid", "native definition tools are invalid")
            for key in ("model", "effort", "permissionMode"):
                _optional_text(fact[key], "native definition " + key)
        projected = ManagedController._native_definition_facts(definitions)
        for name, fact in definitions.items():
            # The original full definition is intentionally not persisted;
            # retain its digest, but refuse unsanitized or coerced fact bodies.
            projected[name]["digest"] = fact["digest"]
            if projected[name] != fact:
                raise _error("invalid", "native definition facts are not body-free")
        raw = _safe_json_projection(raw, "native admission context")
        raw["lineage"] = lineage.to_dict()
        _digest(raw)
        return raw

    @staticmethod
    def _validate_native_admission(value: Any, context: Mapping[str, Any]) -> Dict[str, Any]:
        raw = _mapping(value, "native admission")
        expected = {"admission_id", "tool_use_id", "agent_type", "invocation_id", "parent",
                    "custom_definition", "definition_digest", "trusted_definition_digest",
                    "watermark", "owner_generation", "lineage_id", "runner_incarnation",
                    "launch_completed"}
        if set(raw) != expected:
            raise _error("invalid", "native admission fields are malformed")
        for key in ("admission_id", "tool_use_id", "agent_type", "invocation_id", "lineage_id", "runner_incarnation"):
            _id(raw[key], "native admission " + key)
        _native_positive_generation(raw["owner_generation"], "native admission generation")
        _native_positive_generation(raw["watermark"], "native admission watermark")
        if raw["launch_completed"] is not False:
            raise _error("unsupported", "native admission must precede child launch")
        lineage = context["lineage"]
        expected_identity = {
            "owner_generation": lineage["owner_generation"], "lineage_id": lineage["lineage_id"],
            "runner_incarnation": context["runner_incarnation"], "invocation_id": context["invocation_id"],
        }
        if any(type(raw[key]) is not type(expected) or raw[key] != expected
               for key, expected in expected_identity.items()):
            raise _error("stale-generation", "native admission context changed")
        if raw["watermark"] <= context["invocation_watermark"]:
            raise _error("stale-generation", "native admission predates current invocation")
        parent = _mapping(raw["parent"], "native admission parent")
        if (not {"session_id", "invocation_id"}.issubset(parent)
                or set(parent) - {"session_id", "invocation_id", "agent_id", "prompt_id"}):
            raise _error("invalid", "native admission parent fields are malformed")
        if (parent["session_id"] != lineage["session_uuid"]
                or parent["invocation_id"] != context["invocation_id"]
                or parent.get("prompt_id") != context["prompt_id"]):
            raise _error("ownership-conflict", "native admission parent does not match current context")
        fact = context["definitions"].get(raw["agent_type"])
        if (fact is None or _digest(raw["custom_definition"]) != _digest(fact)
                or raw["definition_digest"] != fact["digest"]
                or raw["trusted_definition_digest"] != fact["digest"]):
            raise _error("permission-mismatch", "native admission changed the trusted definition")
        raw = _safe_json_projection(raw, "native admission")
        _digest(raw)
        return raw

    def _load_native_admissions(self, raw: Mapping[str, Any]) -> None:
        if ("native_context" in raw) != ("native_admissions" in raw):
            raise _error("invalid", "native context and admission ledger must occur together")
        context = raw.get("native_context")
        admissions = raw.get("native_admissions", {})
        if not isinstance(admissions, Mapping) or len(admissions) > 256:
            raise _error("invalid", "native admission ledger is malformed")
        if context is None:
            if admissions:
                raise _error("invalid", "native admissions have no context")
            return
        context = self._validate_native_context(context)
        if context["lineage"]["owner_generation"] != self._generation:
            raise _error("stale-generation", "native context generation is stale")
        active = self._operations.get(self._active_operation_id or "")
        if active is not None and active.generation != self._generation:
            raise _error("stale-generation", "native active operation generation is stale")
        coordinator = self._participants.get(self._coordinator_id or "")
        if coordinator is None or coordinator.session_id != context["lineage"]["session_uuid"]:
            raise _error("ownership-conflict", "native context coordinator changed")
        admission_ids, tool_ids, watermarks = set(), set(), set()
        for request_id, record in admissions.items():
            _id(request_id, "native admission request ID")
            if request_id in self._requests:
                raise _error("invalid", "native admission request collides with another operation")
            record = _native_validate(record, record_kind="pending-admission",
                                      label="pending native admission")
            base_fields = {"schema_version", "architecture", "record_kind", "request_id",
                           "digest", "admission", "claim_ref", "ack"}
            record_fields = set(record)
            if (not base_fields.issubset(record_fields)
                    or record_fields - base_fields - {"parent_observation"}
                    or record["request_id"] != request_id):
                raise _error("invalid", "pending native admission fields are malformed")
            admission = self._validate_native_admission(record["admission"], context)
            if record["digest"] != _digest(admission):
                raise _error("invalid", "pending native admission digest changed")
            if record["claim_ref"] != context["lineage"]["workspace_claim"]:
                raise _error("ownership-conflict", "pending native admission claim changed")
            if record["ack"] != self._native_admission_ack(admission):
                raise _error("invalid", "pending native admission acknowledgement changed")
            parent_agent = admission["parent"].get("agent_id")
            if parent_agent is None and "parent_observation" in record:
                raise _error("invalid", "top-level native admission has a parent binding")
            if parent_agent is not None:
                binding = record.get("parent_observation")
                if binding is None:
                    raise _error("ownership-conflict", "nested native admission has no parent binding")
                _native_exact_fields(
                    binding,
                    ("child_run_id", "observation_id", "observation_digest"),
                    "native admission parent observation",
                )
            for seen, key in ((admission_ids, "admission_id"), (tool_ids, "tool_use_id"), (watermarks, "watermark")):
                if admission[key] in seen:
                    raise _error("invalid", "pending native admission identity is duplicated")
                seen.add(admission[key])
            self._native_admissions[request_id] = _json_value(record)
        self._native_context = context

    @staticmethod
    def _native_child_call(function: Any, *args: Any, **kwargs: Any) -> Any:
        """Translate the pure child contract's structured refusal."""
        try:
            return function(*args, **kwargs)
        except NativeChildContractError as exc:
            raise _error(exc.code, exc.message) from exc

    @staticmethod
    def _native_child_digest(value: Any, label: str = "native child value") -> str:
        try:
            return _native_child_digest(value)
        except NativeChildContractError as exc:
            raise _error(exc.code, "%s: %s" % (label, exc.message)) from exc

    @staticmethod
    def _native_child_digest_field(value: Any, label: str) -> str:
        if (not isinstance(value, str)
                or not re.fullmatch(r"[0-9a-f]{64}", value)):
            raise _error("invalid", "%s must be a sha256 digest" % label)
        return value

    def _native_child_source_operation_locked(
            self, context: Mapping[str, Any]
    ) -> Operation:
        """Resolve the operation that owns the exact observed invocation.

        A swap operation can be the active lifecycle operation while its
        source invocation is still the one publishing child observations.  A
        source operation is therefore selected only from its immutable startup
        or native-swap source binding.  Runner/release state alone is not an
        invocation binding and cannot identify source A after a reload.
        """
        context = self._validate_native_context(context)
        lineage = context["lineage"]
        coordinator_id = self._coordinator_id
        candidates: Dict[str, Operation] = {}

        def identity_matches(startup: Any) -> bool:
            if not isinstance(startup, Mapping):
                return False
            if startup.get("participant_id") != coordinator_id:
                return False
            if startup.get("session_id", startup.get("session_uuid")) != lineage["session_uuid"]:
                return False
            if startup.get("runner_incarnation") != context["runner_incarnation"]:
                return False
            return startup.get("invocation_id") == context["invocation_id"]

        def mailbox_matches(operation: Operation) -> bool:
            mailbox = self._mailboxes.get(context["invocation_id"])
            return bool(
                mailbox is not None
                and mailbox.message_id == context["invocation_id"]
                and mailbox.recipient_id == coordinator_id
                and mailbox.operation_id == operation.operation_id
                and mailbox.generation == operation.generation
            )

        for operation in self._operations.values():
            startup = operation.metadata.get("native_startup")
            if identity_matches(startup) and mailbox_matches(operation):
                candidates[operation.operation_id] = operation
            native_swap = operation.metadata.get("native_swap")
            if not isinstance(native_swap, Mapping):
                continue
            source_identity = native_swap.get("source_identity")
            if not isinstance(source_identity, Mapping):
                continue
            if any(source_identity.get(key) != expected for key, expected in {
                "owner_generation": lineage["owner_generation"],
                "lineage_id": lineage["lineage_id"],
                "lineage_generation": lineage["lineage_generation"],
                "session_uuid": lineage["session_uuid"],
                "runner_incarnation": context["runner_incarnation"],
                "invocation_id": context["invocation_id"],
            }.items()):
                continue
            source_operation_id = native_swap.get("source_operation_id")
            source_operation = self._operations.get(source_operation_id)
            source_startup = (
                source_operation.metadata.get("native_startup")
                if source_operation is not None else None
            )
            if (
                source_operation is not None
                and isinstance(native_swap.get("source_startup"), Mapping)
                and source_startup == native_swap["source_startup"]
                and identity_matches(source_startup)
                and mailbox_matches(source_operation)
            ):
                candidates[source_operation.operation_id] = source_operation
        if len(candidates) != 1:
            raise _error(
                "ownership-conflict" if candidates else "unsupported",
                "native child source operation is not uniquely bound",
            )
        return next(iter(candidates.values()))

    @staticmethod
    def _native_child_observation_entry_shape(
            value: Any, *, expected_observation_id: Optional[str] = None,
    ) -> Dict[str, Any]:
        raw = _native_validate(
            value, record_kind="native-child-observation",
            label="native child observation record",
        )
        if set(raw) != _NATIVE_CHILD_OBSERVATION_FIELDS:
            raise _error("invalid", "native child observation record fields are malformed")
        observation_id = _id(raw["observation_id"], "native child observation ID") or ""
        if expected_observation_id is not None and observation_id != expected_observation_id:
            raise _error("invalid", "native child observation key is inconsistent")
        observation = _mapping(raw["observation"], "native child observation")
        digest = ManagedController._native_child_digest_field(
            raw["observation_digest"], "native child observation digest"
        )
        if digest != ManagedController._native_child_digest(observation):
            raise _error("invalid", "native child observation digest changed")
        child_run_id = ManagedController._native_child_digest_field(
            raw["child_run_id"], "native child run ID"
        )
        source_operation_id = _id(
            raw["source_operation_id"], "native child source operation ID"
        ) or ""
        ack = _native_exact_fields(
            raw["ack"], tuple(_NATIVE_CHILD_ACK_FIELDS),
            "native child observation acknowledgement",
        )
        if (ack["recorded"] is not True
                or ack["observation_id"] != observation_id
                or ack["observation_digest"] != digest
                or ack["child_run_id"] != child_run_id):
            raise _error("invalid", "native child observation acknowledgement changed")
        watermark = observation.get("observation_watermark")
        if type(watermark) is not int or watermark <= 0 or ack["observation_watermark"] != watermark:
            raise _error("invalid", "native child observation acknowledgement watermark changed")
        return {
            **native_record_marker("native-child-observation"),
            "observation_id": observation_id,
            "observation": _json_value(observation),
            "observation_digest": digest,
            "child_run_id": child_run_id,
            "source_operation_id": source_operation_id,
            "ack": _json_value(ack),
        }

    def _native_child_admission_bodies(self) -> Dict[str, Any]:
        return {
            record["admission"]["admission_id"]: record["admission"]
            for record in self._native_admissions.values()
            if isinstance(record, Mapping)
            and isinstance(record.get("admission"), Mapping)
        }

    def _native_child_observation_bodies(self) -> Dict[str, Any]:
        return {
            observation_id: record["observation"]
            for observation_id, record in self._native_child_observations.items()
            if isinstance(record, Mapping)
            and isinstance(record.get("observation"), Mapping)
        }

    def _native_child_join_observation(
            self, observation: Any, *, context: Mapping[str, Any],
            admission: Mapping[str, Any], label: str = "native child observation",
    ) -> Dict[str, Any]:
        try:
            return self._native_child_call(
                _validate_native_child_observation,
                observation, context=context, admission=admission,
            )
        except ControllerError as exc:
            raise _error(exc.code, "%s: %s" % (label, exc.message)) from exc

    def _validate_native_child_identity_joins(self) -> None:
        """Reject child identity reuse across live and retained ledgers."""
        seen_observations: Dict[str, Tuple[str, str]] = {}
        seen_identities: Dict[Tuple[str, str], Tuple[str, str]] = {}

        def add_collection(
                scope: str, values: Any, *, logical_id: str
        ) -> None:
            if not isinstance(values, Mapping):
                return
            for observation_id, entry in values.items():
                if not isinstance(entry, Mapping):
                    continue
                observation = entry.get("observation")
                child = observation.get("child") if isinstance(observation, Mapping) else None
                if not isinstance(child, Mapping):
                    continue
                run_id = entry.get("child_run_id")
                if not isinstance(run_id, str) or not run_id:
                    continue
                observation_id = str(observation_id)
                prior_observation = seen_observations.get(observation_id)
                if prior_observation is not None and prior_observation != (scope, logical_id):
                    raise _error("invalid", "native child observation ID was reused")
                seen_observations[observation_id] = (scope, logical_id)
                for key in ("admission_id", "tool_use_id", "agent_id", "task_id"):
                    value = child.get(key)
                    if not isinstance(value, str) or not value:
                        continue
                    identity_key = (key, value)
                    prior_identity = seen_identities.get(identity_key)
                    if prior_identity is not None:
                        prior_scope, prior_run_id = prior_identity
                        if prior_scope != scope or prior_run_id != run_id:
                            raise _error("invalid", "native child identity was reused")
                    seen_identities[identity_key] = (scope, run_id)

        add_collection("current", self._native_child_observations, logical_id="current")
        for history_id, history in self._native_invocation_history.items():
            if isinstance(history, Mapping):
                add_collection(
                    "history", history.get("native_child_observations"),
                    logical_id=history_id,
                )
        for archive_id, archive in self._native_source_archives.items():
            snapshot = archive.get("snapshot") if isinstance(archive, Mapping) else None
            if isinstance(snapshot, Mapping):
                add_collection(
                    "archive", snapshot.get("native_child_observations"),
                    logical_id=archive_id,
                )

    def _validate_native_admission_parent_links(self) -> None:
        context = self._native_context
        if context is None:
            return
        admissions = self._native_child_admission_bodies()
        observations = self._native_child_observation_bodies()
        for record in self._native_admissions.values():
            admission = record["admission"]
            parent_agent = admission["parent"].get("agent_id")
            binding = record.get("parent_observation")
            if parent_agent is None:
                if binding is not None:
                    raise _error("invalid", "top-level native admission has a parent binding")
                continue
            if binding is None:
                raise _error("ownership-conflict", "nested native admission has no parent binding")
            self._native_child_call(
                _validate_native_parent_binding,
                admission, binding, context=context,
                admissions=admissions, observations=observations,
            )

    def _load_native_child_observations(self, raw: Mapping[str, Any]) -> None:
        if "native_child_observations" not in raw:
            return
        self._native_child_observations_present = True
        values = raw["native_child_observations"]
        if values is None or not isinstance(values, Mapping):
            raise _error("invalid", "native child observation collection is malformed")
        if len(values) > _NATIVE_CHILD_OBSERVATION_LIMIT * _NATIVE_CHILD_OBSERVATIONS_PER_RUN_LIMIT:
            raise _error("invalid", "native child observation collection exceeds capacity")
        if len(_canonical_json(values).encode("utf-8")) > MAX_PAYLOAD_REFERENCE_BYTES:
            raise _error("invalid", "native child observation collection exceeds one MiB")
        context = self._native_context
        if context is None:
            if values:
                raise _error("invalid", "native child observations have no context")
            return
        shape: Dict[str, Dict[str, Any]] = {}
        for observation_id, value in values.items():
            observation_id = _id(observation_id, "native child observation key") or ""
            shape[observation_id] = self._native_child_observation_entry_shape(
                value, expected_observation_id=observation_id,
            )
        admissions = self._native_child_admission_bodies()
        normalized: Dict[str, Dict[str, Any]] = {}
        groups: Dict[str, List[Dict[str, Any]]] = {}
        for observation_id, entry in shape.items():
            observation = entry["observation"]
            child = observation.get("child") if isinstance(observation, Mapping) else None
            admission_id = child.get("admission_id") if isinstance(child, Mapping) else None
            admission = admissions.get(admission_id)
            if admission is None:
                raise _error("ownership-conflict", "native child observation admission is unknown")
            observation = self._native_child_join_observation(
                observation, context=context, admission=admission,
            )
            entry["observation"] = observation
            try:
                run_id = _native_child_run_id(observation)
            except NativeChildContractError as exc:
                raise _error(exc.code, exc.message) from exc
            if entry["child_run_id"] != run_id:
                raise _error("invalid", "native child observation run identity changed")
            source_operation = self._native_child_source_operation_locked(context)
            if entry["source_operation_id"] != source_operation.operation_id:
                raise _error("ownership-conflict", "native child source operation changed")
            child = observation.get("child")
            if not isinstance(child, Mapping):
                raise _error("invalid", "native child observation child identity is malformed")
            if self._native_historical_identity_conflict(
                    observation_id=observation_id,
                    admission_id=child.get("admission_id"),
                    tool_use_id=child.get("tool_use_id"),
                    agent_id=child.get("agent_id"),
                    task_id=child.get("task_id"),
            ):
                raise _error("invalid", "native child identity was reused by retained history")
            normalized[observation_id] = entry
            groups.setdefault(run_id, []).append(observation)
        if len(groups) > _NATIVE_CHILD_OBSERVATION_LIMIT:
            raise _error("busy", "native child observation run capacity is exhausted")
        for history in groups.values():
            history.sort(key=lambda item: item["observation_watermark"])
            if len(history) > _NATIVE_CHILD_OBSERVATIONS_PER_RUN_LIMIT:
                raise _error("busy", "native child observation run capacity is exhausted")
            for prior, candidate in zip(history, history[1:]):
                self._native_child_call(_validate_native_child_progress, prior, candidate)
        identities: Dict[Tuple[str, str], str] = {}
        for entry in normalized.values():
            child = entry["observation"]["child"]
            run_id = entry["child_run_id"]
            for key in ("admission_id", "tool_use_id", "agent_id", "task_id"):
                value = child[key]
                identity_key = (key, value)
                prior_run = identities.get(identity_key)
                if prior_run is not None and prior_run != run_id:
                    raise _error("invalid", "native child identity was reused across runs")
                identities[identity_key] = run_id
        self._native_child_observations = normalized

    @staticmethod
    def _native_interrupt_digest(value: Any, label: str) -> str:
        if (not isinstance(value, str) or
                not re.fullmatch(r"[0-9a-f]{64}", value)):
            raise _error("invalid", "%s must be a sha256 digest" % label)
        return value

    @staticmethod
    def _native_interrupt_id_list(value: Any, label: str) -> List[str]:
        if not isinstance(value, list) or len(value) > 256:
            raise _error("invalid", "%s must be a bounded list" % label)
        result: List[str] = []
        seen = set()
        for item in value:
            item = _id(item, label + " item") or ""
            if item in seen:
                raise _error("invalid", "%s contains a duplicate ID" % label)
            seen.add(item)
            result.append(item)
        return result

    @staticmethod
    def _native_interrupt_task_start_event(
            value: Any, label: str
    ) -> Dict[str, Any]:
        event = _native_exact_fields(
            value, ("event_uuid", "watermark", "task_type"), label
        )
        if event["event_uuid"] is not None:
            event["event_uuid"] = _id(
                event["event_uuid"], label + " event_uuid"
            )
        event["watermark"] = _native_positive_generation(
            event["watermark"], label + " watermark"
        )
        event["task_type"] = _id(
            event["task_type"], label + " task_type"
        ) or ""
        return event

    @staticmethod
    def _native_interrupt_child(
            value: Any, *, seal_watermark: int, label: str
    ) -> Dict[str, Any]:
        child = _native_exact_fields(
            value,
            (
                "admission_id", "tool_use_id", "agent_id", "task_id",
                "parent_agent_id", "invocation_id", "lineage_incarnation",
                "trusted_definition_digest", "start_watermark", "task_start_event",
                "status", "terminal_watermark", "active_tool_ids",
                "uncertain_tool_ids", "unresolved_effect_ids",
            ),
            label,
        )
        for key in (
            "admission_id", "tool_use_id", "agent_id", "task_id", "invocation_id",
        ):
            child[key] = _id(child[key], label + " " + key) or ""
        if child["parent_agent_id"] is not None:
            child["parent_agent_id"] = _id(
                child["parent_agent_id"], label + " parent_agent_id"
            )
        child["lineage_incarnation"] = _native_positive_generation(
            child["lineage_incarnation"], label + " lineage_incarnation"
        )
        child["trusted_definition_digest"] = ManagedController._native_interrupt_digest(
            child["trusted_definition_digest"], label + " trusted_definition_digest"
        )
        child["start_watermark"] = _native_positive_generation(
            child["start_watermark"], label + " start_watermark"
        )
        child["task_start_event"] = ManagedController._native_interrupt_task_start_event(
            child["task_start_event"], label + " task_start_event"
        )
        if (not isinstance(child["status"], str) or
                child["status"] not in {"active", "completed", "stopped"}):
            raise _error("invalid", "%s status is invalid" % label)
        terminal_watermark = child["terminal_watermark"]
        if child["status"] == "active":
            if terminal_watermark is not None:
                raise _error("invalid", "%s active child has terminal watermark" % label)
        else:
            terminal_watermark = _native_positive_generation(
                terminal_watermark, label + " terminal_watermark"
            )
            if terminal_watermark > seal_watermark:
                raise _error("stale-generation", "%s terminal watermark is after roster seal" % label)
        child["terminal_watermark"] = terminal_watermark
        for key in ("active_tool_ids", "uncertain_tool_ids", "unresolved_effect_ids"):
            child[key] = ManagedController._native_interrupt_id_list(
                child[key], label + " " + key
            )
        return child

    @staticmethod
    def _native_interrupt_roster_projection(
            roster: Mapping[str, Any]
    ) -> Dict[str, Any]:
        """Return the stable identity/inventory projection used for its digest."""
        children = []
        for child in roster["children"]:
            children.append({
                "admission_id": child["admission_id"],
                "tool_use_id": child["tool_use_id"],
                "agent_id": child["agent_id"],
                "task_id": child["task_id"],
                "parent_agent_id": child["parent_agent_id"],
                "invocation_id": child["invocation_id"],
                "lineage_incarnation": child["lineage_incarnation"],
                "trusted_definition_digest": child["trusted_definition_digest"],
                "active_tool_ids": sorted(child["active_tool_ids"]),
                "uncertain_tool_ids": sorted(child["uncertain_tool_ids"]),
                "unresolved_effect_ids": sorted(child["unresolved_effect_ids"]),
            })
        children.sort(key=lambda item: item["admission_id"])
        return {
            "children": children,
            "pending_admission_ids": sorted(roster["pending_admission_ids"]),
            "pending_task_ids": sorted(roster["pending_task_ids"]),
            "parent_active_tool_ids": sorted(roster["parent_active_tool_ids"]),
            "parent_uncertain_tool_ids": sorted(roster["parent_uncertain_tool_ids"]),
            "parent_unresolved_effect_ids": sorted(roster["parent_unresolved_effect_ids"]),
            "descendant_ids": sorted(roster["descendant_ids"]),
        }

    @staticmethod
    def _native_interrupt_source_key(
            *, owner_generation: int, lineage_id: str,
            lineage_generation: int, session_id: str,
            runner_instance_id: str,
    ) -> str:
        return _digest({
            "owner_generation": owner_generation,
            "lineage_id": lineage_id,
            "lineage_generation": lineage_generation,
            "session_id": session_id,
            "runner_instance_id": runner_instance_id,
        })

    def _native_interrupt_admissions(self) -> Dict[str, Dict[str, Any]]:
        """Index the exact durable admission records available to a fence."""
        result: Dict[str, Dict[str, Any]] = {}
        for request_id, record in self._native_admissions.items():
            admission = record.get("admission")
            if not isinstance(admission, Mapping):
                raise _error("invalid", "native interrupt admission is malformed")
            admission_id = _id(
                admission.get("admission_id"), "native interrupt admission_id"
            ) or ""
            if admission_id in result:
                raise _error("invalid", "native interrupt admission identity is duplicated")
            result[admission_id] = {
                "request_id": request_id,
                "admission": admission,
                "record": record,
            }
        return result

    def _native_interrupt_roster(
            self, interrupt: Mapping[str, Any], *, live: bool
    ) -> Dict[str, Any]:
        roster = _native_exact_fields(
            interrupt["roster"],
            (
                "parent_state", "children", "pending_admission_ids",
                "pending_task_ids", "parent_active_tool_ids",
                "parent_uncertain_tool_ids", "parent_unresolved_effect_ids",
                "descendant_ids",
            ),
            "coordinator interrupt roster",
        )
        if (not isinstance(roster["parent_state"], str) or
                roster["parent_state"] not in {"active", "idle"}):
            raise _error("invalid", "coordinator interrupt parent_state is invalid")
        if not isinstance(roster["children"], list) or len(roster["children"]) > 256:
            raise _error("invalid", "coordinator interrupt children are invalid")
        for key in (
            "pending_admission_ids", "pending_task_ids", "parent_active_tool_ids",
            "parent_uncertain_tool_ids", "parent_unresolved_effect_ids", "descendant_ids",
        ):
            roster[key] = self._native_interrupt_id_list(
                roster[key], "coordinator interrupt " + key
            )
        if roster["pending_admission_ids"] or roster["pending_task_ids"]:
            raise _error(
                "unsupported",
                "coordinator interrupt has unresolved pending admissions or tasks",
            )
        seal_watermark = _native_positive_generation(
            interrupt["roster_seal_watermark"],
            "coordinator interrupt roster_seal_watermark",
        )
        children = [
            self._native_interrupt_child(
                child, seal_watermark=seal_watermark,
                label="coordinator interrupt child",
            )
            for child in roster["children"]
        ]
        child_admissions = [child["admission_id"] for child in children]
        if len(set(child_admissions)) != len(child_admissions):
            raise _error("invalid", "coordinator interrupt child admission is duplicated")
        child_agents = [child["agent_id"] for child in children]
        child_tasks = [child["task_id"] for child in children]
        child_tools = [child["tool_use_id"] for child in children]
        for values, label in (
            (child_agents, "agent"), (child_tasks, "task"), (child_tools, "tool"),
        ):
            if len(set(values)) != len(values):
                raise _error("invalid", "coordinator interrupt child %s identity is duplicated" % label)
        agent_set = set(child_agents)
        for child in children:
            parent_agent_id = child["parent_agent_id"]
            if parent_agent_id is not None:
                if parent_agent_id == child["agent_id"] or parent_agent_id not in agent_set:
                    raise _error("invalid", "coordinator interrupt child parent is not a roster member")
        # A nested parent graph must terminate at the coordinator and may not
        # contain a cycle.  The current admission authority only emits
        # top-level children, but keeping this check here prevents a future
        # nested producer from bypassing the sealed-roster boundary.
        child_by_agent = {child["agent_id"]: child for child in children}
        for child in children:
            seen = set()
            parent = child["parent_agent_id"]
            while parent is not None:
                if parent in seen:
                    raise _error("invalid", "coordinator interrupt child parent graph cycles")
                seen.add(parent)
                parent = child_by_agent[parent]["parent_agent_id"]
        parent_tools = set(roster["parent_active_tool_ids"]) | set(roster["parent_uncertain_tool_ids"])
        if (len(parent_tools) != len(roster["parent_active_tool_ids"]) +
                len(roster["parent_uncertain_tool_ids"])):
            raise _error("invalid", "coordinator interrupt parent tool inventory overlaps")
        child_tools = []
        for child in children:
            if set(child["active_tool_ids"]) & set(child["uncertain_tool_ids"]):
                raise _error("invalid", "coordinator interrupt child tool inventory overlaps")
            child_tools.extend(child["active_tool_ids"])
            child_tools.extend(child["uncertain_tool_ids"])
        if len(set(child_tools)) != len(child_tools) or parent_tools.intersection(child_tools):
            raise _error("invalid", "coordinator interrupt tool ownership is ambiguous")
        launch_tools = {child["tool_use_id"] for child in children}
        # A launch tool belongs to the parent and may therefore also appear in
        # the parent's active inventory.  It must never be shadowed by a
        # child's own active/uncertain tool inventory.
        if launch_tools.intersection(child_tools):
            raise _error("invalid", "coordinator interrupt launch tool ownership is ambiguous")
        effect_owners = {}
        for effect_id in roster["parent_unresolved_effect_ids"]:
            effect_owners[effect_id] = "parent"
        for child in children:
            for effect_id in child["unresolved_effect_ids"]:
                if effect_id in effect_owners:
                    raise _error("invalid", "coordinator interrupt effect ownership is ambiguous")
                effect_owners[effect_id] = child["agent_id"]
        roster["children"] = children
        admissions = self._native_interrupt_admissions()
        operation = self._operations.get(interrupt["operation_id"])
        if operation is None:
            raise _error("ownership-conflict" if live else "invalid",
                         "coordinator interrupt operation is unknown")
        sealed = []
        sealed = operation.metadata.get("sealed_native_admissions", [])
        if (not isinstance(sealed, list) or
                any(not isinstance(value, str) or not value for value in sealed) or
                len(set(sealed)) != len(sealed)):
            raise _error("invalid", "coordinator interrupt sealed admissions are malformed")
        if not sealed:
            raise _error(
                "unsupported" if live else "invalid",
                "coordinator interrupt cannot authorize an empty native roster",
            )
        if set(child_admissions) != set(sealed):
            raise _error(
                "ownership-conflict" if live else "invalid",
                "coordinator interrupt roster does not match fenced admissions",
            )
        if set(admissions) != set(sealed):
            raise _error(
                "ownership-conflict" if live else "invalid",
                "coordinator interrupt roster does not cover durable fenced admissions",
            )
        for child in children:
            entry = admissions.get(child["admission_id"])
            if entry is None:
                raise _error("ownership-conflict", "coordinator interrupt child admission is unknown")
            admission = entry["admission"]
            expected = {
                "tool_use_id": admission["tool_use_id"],
                "invocation_id": admission["invocation_id"],
                "trusted_definition_digest": admission["trusted_definition_digest"],
            }
            if any(child[key] != value for key, value in expected.items()):
                raise _error("ownership-conflict", "coordinator interrupt child identity changed")
            expected_parent = admission.get("parent", {}).get("agent_id")
            if child["parent_agent_id"] != expected_parent:
                raise _error("ownership-conflict", "coordinator interrupt child parent changed")
            if child["start_watermark"] <= admission["watermark"]:
                raise _error("stale-generation", "coordinator interrupt child start predates admission")
            if child["start_watermark"] > seal_watermark:
                raise _error("stale-generation", "coordinator interrupt child start is after roster seal")
            if child["task_start_event"]["watermark"] <= admission["watermark"]:
                raise _error("stale-generation", "coordinator interrupt task event predates admission")
            if child["task_start_event"]["watermark"] > seal_watermark:
                raise _error("stale-generation", "coordinator interrupt task event is after roster seal")
            if (child["terminal_watermark"] is not None and
                    child["terminal_watermark"] < max(
                        child["start_watermark"], child["task_start_event"]["watermark"]
                    )):
                raise _error("stale-generation", "coordinator interrupt terminal predates child start")
        projection = self._native_interrupt_roster_projection(roster)
        digest = _digest(projection)
        if self._native_interrupt_digest(
                interrupt["roster_identity_digest"],
                "coordinator interrupt roster_identity_digest",
        ) != digest:
            raise _error("invalid", "coordinator interrupt roster digest changed")
        if live and not admissions and children:
            raise _error("unsupported", "coordinator interrupt has no durable admission roster")
        return roster

    def _validate_coordinator_interrupt_intent(
            self, value: Any, context: Mapping[str, Any], *, live: bool
    ) -> Dict[str, Any]:
        raw = _native_exact_fields(
            value,
            ("type", "participant_id", "session_id", "runner_instance_id", "interrupt"),
            "coordinator interrupt intent",
        )
        if raw["type"] != _COORDINATOR_INTERRUPT_INTENT_TYPE:
            raise _error("invalid", "coordinator interrupt intent type is invalid")
        participant_id = _id(raw["participant_id"], "coordinator interrupt participant_id") or ""
        session_id = _id(raw["session_id"], "coordinator interrupt session_id") or ""
        runner_id = _id(
            raw["runner_instance_id"], "coordinator interrupt runner_instance_id"
        ) or ""
        coordinator = self._participants.get(self._coordinator_id or "")
        lineage = context["lineage"]
        if (coordinator is None or participant_id != coordinator.participant_id or
                session_id != lineage["session_uuid"] or
                runner_id != context["runner_incarnation"]):
            raise _error("ownership-conflict", "coordinator interrupt runner identity changed")
        interrupt = _native_exact_fields(
            raw["interrupt"],
            (
                "interrupt_id", "operation_id", "owner_generation", "lineage_id",
                "lineage_generation", "invocation_id", "fence_epoch",
                "roster_identity_digest", "roster_seal_watermark", "capability_digest",
                "request_epoch_id", "request_entry_watermark", "roster",
            ),
            "coordinator interrupt intent body",
        )
        for key in ("interrupt_id", "operation_id", "lineage_id", "invocation_id", "request_epoch_id"):
            interrupt[key] = _id(interrupt[key], "coordinator interrupt " + key) or ""
        for key in (
            "owner_generation", "lineage_generation", "fence_epoch",
            "roster_seal_watermark", "request_entry_watermark",
        ):
            interrupt[key] = _native_positive_generation(
                interrupt[key], "coordinator interrupt " + key
            )
        interrupt["capability_digest"] = self._native_interrupt_digest(
            interrupt["capability_digest"], "coordinator interrupt capability_digest"
        )
        interrupt["roster_identity_digest"] = self._native_interrupt_digest(
            interrupt["roster_identity_digest"],
            "coordinator interrupt roster_identity_digest",
        )
        if interrupt["request_entry_watermark"] > interrupt["roster_seal_watermark"]:
            raise _error("stale-generation", "coordinator interrupt request epoch starts after seal")
        if (interrupt["owner_generation"] != lineage["owner_generation"] or
                interrupt["lineage_id"] != lineage["lineage_id"] or
                interrupt["lineage_generation"] != lineage["lineage_generation"] or
                interrupt["invocation_id"] != context["invocation_id"]):
            raise _error("stale-generation", "coordinator interrupt lineage changed")
        roster = self._native_interrupt_roster(interrupt, live=live)
        interrupt["roster"] = roster
        raw["participant_id"] = participant_id
        raw["session_id"] = session_id
        raw["runner_instance_id"] = runner_id
        raw["interrupt"] = interrupt
        return _safe_json_projection(raw, "coordinator interrupt intent")

    def _validate_coordinator_interrupt_evidence(
            self, value: Any, context: Mapping[str, Any],
            intent: Mapping[str, Any], *, live: bool = False
    ) -> Dict[str, Any]:
        raw = _native_exact_fields(
            value,
            ("type", "participant_id", "session_id", "runner_instance_id", "evidence"),
            "coordinator interrupt evidence",
        )
        if raw["type"] != _COORDINATOR_INTERRUPT_EVIDENCE_TYPE:
            raise _error("invalid", "coordinator interrupt evidence type is invalid")
        for key in ("participant_id", "session_id", "runner_instance_id"):
            raw[key] = _id(raw[key], "coordinator interrupt evidence " + key) or ""
        expected_outer = {
            "participant_id": intent["participant_id"],
            "session_id": intent["session_id"],
            "runner_instance_id": intent["runner_instance_id"],
        }
        if any(raw[key] != expected_outer[key] for key in expected_outer):
            raise _error("ownership-conflict", "coordinator interrupt evidence runner changed")
        evidence = _native_exact_fields(
            raw["evidence"],
            ("evidence_id", "interrupt_id", "kind", "observed_watermark", "data"),
            "coordinator interrupt evidence body",
        )
        evidence["evidence_id"] = _id(
            evidence["evidence_id"], "coordinator interrupt evidence evidence_id"
        ) or ""
        evidence["interrupt_id"] = _id(
            evidence["interrupt_id"], "coordinator interrupt evidence interrupt_id"
        ) or ""
        if evidence["interrupt_id"] != intent["interrupt"]["interrupt_id"]:
            raise _error("ownership-conflict", "coordinator interrupt evidence intent changed")
        if (not isinstance(evidence["kind"], str) or
                evidence["kind"] not in _COORDINATOR_INTERRUPT_EVIDENCE_KINDS):
            raise _error("invalid", "coordinator interrupt evidence kind is invalid")
        observed = _native_positive_generation(
            evidence["observed_watermark"],
            "coordinator interrupt evidence observed_watermark",
        )
        data = _native_exact_fields(
            evidence["data"],
            _COORDINATOR_INTERRUPT_FACT_FIELDS[evidence["kind"]],
            "coordinator interrupt %s data" % evidence["kind"],
        )
        roster = intent["interrupt"]["roster"]
        children = roster["children"]
        child_by_admission = {child["admission_id"]: child for child in children}
        if evidence["kind"] == "runtime-ack":
            if data["accepted"] is not True or data["ack_kind"] != "accepted-interrupt":
                raise _error("invalid", "coordinator interrupt runtime acknowledgement is invalid")
        elif evidence["kind"] == "member-terminal":
            data["agent_id"] = _id(data["agent_id"], "coordinator member terminal agent_id") or ""
            data["task_id"] = _id(data["task_id"], "coordinator member terminal task_id") or ""
            data["tool_use_id"] = _id(data["tool_use_id"], "coordinator member terminal tool_use_id") or ""
            data["lineage_incarnation"] = _native_positive_generation(
                data["lineage_incarnation"], "coordinator member terminal lineage_incarnation"
            )
            if (not isinstance(data["event_kind"], str) or
                    data["event_kind"] not in {"task_notification", "SubagentStop"}):
                raise _error("invalid", "coordinator member terminal event kind is invalid")
            if data["event_uuid"] is not None:
                data["event_uuid"] = _id(
                    data["event_uuid"], "coordinator member terminal event_uuid"
                )
            if (not isinstance(data["status"], str) or
                    data["status"] not in {"completed", "stopped", "failed"}):
                raise _error("invalid", "coordinator member terminal status is invalid")
            matching = [
                child for child in children
                if child["agent_id"] == data["agent_id"]
                and child["task_id"] == data["task_id"]
                and child["tool_use_id"] == data["tool_use_id"]
                and child["lineage_incarnation"] == data["lineage_incarnation"]
            ]
            if len(matching) != 1:
                raise _error("ownership-conflict", "coordinator member terminal is not in the sealed roster")
            child = matching[0]
            if observed <= intent["interrupt"]["roster_seal_watermark"]:
                if (child["status"] not in {"completed", "stopped"} or
                        child["terminal_watermark"] != observed or
                        data["status"] != child["status"]):
                    raise _error("stale-generation", "pre-seal member terminal is not authoritative")
            elif (child["status"] in {"completed", "stopped"} and
                  data["status"] != child["status"]):
                raise _error("uncertain-effect", "coordinator member terminal conflicts with sealed status")
        elif evidence["kind"] == "tool-terminal":
            data["tool_use_id"] = _id(data["tool_use_id"], "coordinator tool terminal tool_use_id") or ""
            if data["agent_id"] is not None:
                data["agent_id"] = _id(data["agent_id"], "coordinator tool terminal agent_id")
            if data["lineage_incarnation"] is not None:
                data["lineage_incarnation"] = _native_positive_generation(
                    data["lineage_incarnation"], "coordinator tool terminal lineage_incarnation"
                )
            if (not isinstance(data["status"], str) or
                    data["status"] not in {"completed", "cancelled", "failed"}):
                raise _error("invalid", "coordinator tool terminal status is invalid")
            parent_tool = data["tool_use_id"] in roster["parent_active_tool_ids"] or data["tool_use_id"] in roster["parent_uncertain_tool_ids"]
            child_matches = [
                child for child in children
                if data["tool_use_id"] in child["active_tool_ids"] or
                data["tool_use_id"] in child["uncertain_tool_ids"]
            ]
            if parent_tool:
                if data["agent_id"] is not None or data["lineage_incarnation"] is not None:
                    raise _error("ownership-conflict", "coordinator parent tool owner is not null")
            else:
                if len(child_matches) != 1:
                    raise _error("ownership-conflict", "coordinator tool terminal is not in one sealed child inventory")
                child = child_matches[0]
                if (data["agent_id"] != child["agent_id"] or
                        data["lineage_incarnation"] != child["lineage_incarnation"]):
                    raise _error("ownership-conflict", "coordinator tool terminal owner changed")
        elif evidence["kind"] == "effect-outcome":
            data["effect_id"] = _id(data["effect_id"], "coordinator effect outcome effect_id") or ""
            known_effect = data["effect_id"] in roster["parent_unresolved_effect_ids"]
            known_effect = known_effect or any(
                data["effect_id"] in child["unresolved_effect_ids"] for child in children
            )
            if not known_effect:
                raise _error("ownership-conflict", "coordinator effect is not in the sealed inventory")
            if (not isinstance(data["status"], str) or
                    data["status"] not in {"resolved", "unknown"}):
                raise _error("invalid", "coordinator effect outcome status is invalid")
        elif evidence["kind"] == "admission-closed":
            data["admission_id"] = _id(
                data["admission_id"], "coordinator admission closed admission_id"
            ) or ""
            if data["admission_id"] not in child_by_admission or data["closed"] is not True:
                raise _error("ownership-conflict", "coordinator admission closure is not in the sealed roster")
        elif evidence["kind"] == "parent-drained":
            data["invocation_id"] = _id(
                data["invocation_id"], "coordinator parent drained invocation_id"
            ) or ""
            if data["invocation_id"] != intent["interrupt"]["invocation_id"]:
                raise _error("ownership-conflict", "coordinator parent drain invocation changed")
            if (not isinstance(data["state"], str) or
                    data["state"] not in {"drained", "idle"}):
                raise _error("invalid", "coordinator parent drain state is invalid")
        elif evidence["kind"] == "request-observation":
            data["epoch_id"] = _id(data["epoch_id"], "coordinator request observation epoch_id") or ""
            if data["epoch_id"] != intent["interrupt"]["request_epoch_id"]:
                raise _error("ownership-conflict", "coordinator request epoch changed")
            data["entry_watermark"] = _native_positive_generation(
                data["entry_watermark"], "coordinator request observation entry_watermark"
            )
            data["through_watermark"] = _native_positive_generation(
                data["through_watermark"], "coordinator request observation through_watermark"
            )
            if data["entry_watermark"] != intent["interrupt"]["request_entry_watermark"]:
                raise _error("stale-generation", "coordinator request observation entry watermark changed")
            if data["through_watermark"] < data["entry_watermark"]:
                raise _error("stale-generation", "coordinator request observation watermark moved backwards")
            if data["through_watermark"] > observed:
                raise _error("stale-generation", "coordinator request observation exceeds observed watermark")
            if data["new_requests"] is not None:
                if (type(data["new_requests"]) is not int or
                        data["new_requests"] < 0):
                    raise _error("invalid", "coordinator request observation count is invalid")
            if not isinstance(data["observable"], bool):
                raise _error("invalid", "coordinator request observation observability is invalid")
        elif evidence["kind"] == "process-excluded":
            if data["process_identity_digest"] is not None:
                data["process_identity_digest"] = self._native_interrupt_digest(
                    data["process_identity_digest"],
                    "coordinator process exclusion digest",
                )
            if (not isinstance(data["status"], str) or
                    data["status"] not in {"excluded", "unknown"}):
                raise _error("invalid", "coordinator process exclusion status is invalid")
            if data["status"] == "excluded" and data["process_identity_digest"] is None:
                raise _error("invalid", "coordinator process exclusion digest is required")
        if (evidence["kind"] != "member-terminal" and
                observed < intent["interrupt"]["roster_seal_watermark"]):
            raise _error("stale-generation", "coordinator evidence predates roster seal")
        evidence["observed_watermark"] = observed
        evidence["data"] = data
        raw["evidence"] = evidence
        return _safe_json_projection(raw, "coordinator interrupt evidence")

    def _coordinator_interrupt_live_operation(
            self, interrupt: Mapping[str, Any], context: Mapping[str, Any]
    ) -> Operation:
        if not context.get("fenced"):
            raise _error("busy", "coordinator interrupt requires a durable native fence")
        operation_id = interrupt["operation_id"]
        operation = self._operations.get(operation_id)
        if (operation is None or self._active_operation_id != operation_id or
                operation.generation != self._generation or
                operation.phase != "paused"):
            raise _error("stale-generation", "coordinator interrupt operation is not active")
        selection = operation.metadata.get("coordinator_interrupt_selection")
        if isinstance(selection, Mapping):
            expected = {
                "operation_id": interrupt.get("operation_id"),
                "interrupt_id": interrupt.get("interrupt_id"),
                "fence_epoch": interrupt.get("fence_epoch"),
                "request_epoch_id": interrupt.get("request_epoch_id"),
                "capability_digest": interrupt.get("capability_digest"),
            }
            if dict(selection) != expected:
                raise _error("stale-generation", "coordinator interrupt selection changed")
        sealed = operation.metadata.get("sealed_native_admissions")
        if (not isinstance(sealed, list) or not sealed or
                any(not isinstance(value, str) or not value for value in sealed)):
            raise _error("unsupported", "coordinator interrupt has no complete sealed native roster")
        return operation

    @staticmethod
    def _coordinator_interrupt_intent_ack(
            interrupt_id: str, *, authorize_send: bool
    ) -> Dict[str, Any]:
        return {
            "recorded": True,
            "authorize_send": authorize_send,
            "interrupt_id": interrupt_id,
        }

    @staticmethod
    def _coordinator_interrupt_evidence_ack(
            frame: Mapping[str, Any]
    ) -> Dict[str, Any]:
        evidence = frame["evidence"]
        return {
            "recorded": True,
            "evidence_id": evidence["evidence_id"],
            "interrupt_id": evidence["interrupt_id"],
        }

    @staticmethod
    def _native_stop_id_list(value: Any, label: str) -> List[str]:
        if not isinstance(value, list) or len(value) > 256:
            raise _error("invalid", "%s must be a bounded list" % label)
        result: List[str] = []
        seen = set()
        for item in value:
            item = _id(item, label + " item") or ""
            if item in seen:
                raise _error("invalid", "%s contains a duplicate ID" % label)
            seen.add(item)
            result.append(item)
        return result

    @staticmethod
    def _native_stop_task_key(frame: Mapping[str, Any]) -> Tuple[Any, ...]:
        stop = frame["stop"]
        return (
            stop["owner_generation"],
            stop["lineage_id"],
            frame["runner_instance_id"],
            stop["invocation_id"],
            stop["agent_id"],
            stop["task_id"],
            stop["admission_id"],
            stop["tool_use_id"],
            stop["lineage_incarnation"],
        )

    def _native_stop_admission(
            self, stop: Mapping[str, Any], context: Mapping[str, Any]
    ) -> Mapping[str, Any]:
        """Join a stop to the controller's durable pre-launch admission."""

        matches = []
        for record in self._native_admissions.values():
            admission = record.get("admission")
            if (isinstance(admission, Mapping) and
                    admission.get("admission_id") == stop["admission_id"]):
                matches.append(admission)
        if len(matches) != 1:
            raise _error(
                "ownership-conflict",
                "native stop has no unique durable admission",
            )
        admission = matches[0]
        expected = {
            "tool_use_id": stop["tool_use_id"],
            "invocation_id": stop["invocation_id"],
            "owner_generation": stop["owner_generation"],
            "lineage_id": stop["lineage_id"],
            "runner_incarnation": context["runner_incarnation"],
        }
        if any(admission.get(key) != value for key, value in expected.items()):
            raise _error(
                "ownership-conflict",
                "native stop admission correlation changed",
            )
        if (stop["trusted_definition_digest"] !=
                admission.get("trusted_definition_digest")):
            raise _error(
                "permission-mismatch",
                "native stop trusted definition changed",
            )
        return admission

    def _validate_native_stop_intent(
            self, value: Any, context: Mapping[str, Any]
    ) -> Dict[str, Any]:
        raw = _native_exact_fields(
            value,
            ("type", "participant_id", "session_id", "runner_instance_id", "stop"),
            "native stop intent",
        )
        if raw["type"] != _NATIVE_STOP_INTENT_TYPE:
            raise _error("invalid", "native stop intent type is invalid")
        participant_id = _id(raw["participant_id"], "native stop participant_id") or ""
        session_id = _id(raw["session_id"], "native stop session_id") or ""
        runner_instance_id = _id(
            raw["runner_instance_id"], "native stop runner_instance_id"
        ) or ""
        coordinator = self._participants.get(self._coordinator_id or "")
        lineage = context["lineage"]
        if (coordinator is None or participant_id != coordinator.participant_id or
                session_id != lineage["session_uuid"] or
                runner_instance_id != context["runner_incarnation"]):
            raise _error("ownership-conflict", "native stop runner identity changed")

        stop = _native_exact_fields(
            raw["stop"],
            (
                "stop_id", "owner_generation", "lineage_id", "invocation_id",
                "admission_id", "tool_use_id", "agent_id", "task_id",
                "lineage_incarnation", "trusted_definition_digest",
                "observed_watermark", "observation",
            ),
            "native stop intent stop",
        )
        stop_id = _id(stop["stop_id"], "native stop stop_id") or ""
        for key in (
            "invocation_id", "admission_id", "tool_use_id", "agent_id", "task_id",
        ):
            stop[key] = _id(stop[key], "native stop " + key) or ""
        owner_generation = _native_positive_generation(
            stop["owner_generation"], "native stop owner_generation"
        )
        lineage_id = _id(stop["lineage_id"], "native stop lineage_id") or ""
        incarnation = _native_positive_generation(
            stop["lineage_incarnation"], "native stop lineage_incarnation"
        )
        observed_watermark = _native_positive_generation(
            stop["observed_watermark"], "native stop observed_watermark"
        )
        digest = stop["trusted_definition_digest"]
        if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise _error("invalid", "native stop trusted_definition_digest is invalid")
        if (owner_generation != lineage["owner_generation"] or
                lineage_id != lineage["lineage_id"] or
                stop["invocation_id"] != context["invocation_id"]):
            raise _error("stale-generation", "native stop invocation identity changed")
        # The pinned local_agent runtime may legitimately use the same string
        # for its agent and task IDs.  The task_start_event and its watermark
        # are the independent task-ledger observation; equality alone is not
        # evidence of fabrication and is therefore preserved.
        admission = self._native_stop_admission(stop, context)

        observation = _native_exact_fields(
            stop["observation"],
            (
                "status", "task_terminal", "start_watermark", "task_start_event",
                "active_tool_ids", "uncertain_tool_ids", "unresolved_effect_ids",
            ),
            "native stop observation",
        )
        if observation["status"] != "active" or observation["task_terminal"] is not False:
            raise _error("invalid", "native stop observation is not an active task")
        start_watermark = _native_positive_generation(
            observation["start_watermark"], "native stop start_watermark"
        )
        task_start_event = _native_exact_fields(
            observation["task_start_event"],
            ("event_uuid", "watermark", "task_type"),
            "native stop task_start_event",
        )
        event_uuid = task_start_event["event_uuid"]
        if event_uuid is not None:
            event_uuid = _id(event_uuid, "native stop task_start_event event_uuid")
        task_start_event["event_uuid"] = event_uuid
        event_watermark = _native_positive_generation(
            task_start_event["watermark"], "native stop task_start_event watermark"
        )
        task_start_event["task_type"] = _id(
            task_start_event["task_type"], "native stop task_start_event task_type"
        ) or ""
        if (start_watermark <= admission["watermark"] or
                event_watermark <= admission["watermark"] or
                event_watermark > observed_watermark):
            raise _error(
                "stale-generation",
                "native stop task watermarks are not after admission and bounded",
            )
        observation["start_watermark"] = start_watermark
        observation["task_start_event"] = task_start_event
        for key in ("active_tool_ids", "uncertain_tool_ids", "unresolved_effect_ids"):
            observation[key] = self._native_stop_id_list(observation[key],
                                                         "native stop " + key)
        stop["owner_generation"] = owner_generation
        stop["lineage_id"] = lineage_id
        stop["lineage_incarnation"] = incarnation
        stop["trusted_definition_digest"] = digest
        stop["observed_watermark"] = observed_watermark
        stop["observation"] = observation
        raw["participant_id"] = participant_id
        raw["session_id"] = session_id
        raw["runner_instance_id"] = runner_instance_id
        raw["stop"] = stop
        return _safe_json_projection(raw, "native stop intent")

    def _validate_native_stop_evidence(
            self, value: Any, context: Mapping[str, Any],
            intent: Mapping[str, Any]
    ) -> Dict[str, Any]:
        raw = _native_exact_fields(
            value,
            ("type", "participant_id", "session_id", "runner_instance_id", "evidence"),
            "native stop evidence",
        )
        if raw["type"] != _NATIVE_STOP_EVIDENCE_TYPE:
            raise _error("invalid", "native stop evidence type is invalid")
        for key in ("participant_id", "session_id", "runner_instance_id"):
            raw[key] = _id(raw[key], "native stop evidence " + key) or ""
        if any(raw[key] != intent[key] for key in
               ("participant_id", "session_id", "runner_instance_id")):
            raise _error("ownership-conflict", "native stop evidence runner identity changed")
        evidence = _native_exact_fields(
            raw["evidence"],
            (
                "evidence_id", "stop_id", "kind", "agent_id", "task_id",
                "lineage_incarnation", "observed_watermark",
                "accepted", "ack_kind",
            ) if isinstance(raw["evidence"], Mapping) and
            raw["evidence"].get("kind") == "runtime-ack" else (
                "evidence_id", "stop_id", "kind", "agent_id", "task_id",
                "lineage_incarnation", "observed_watermark", "event_kind",
                "event_uuid", "status", "tool_use_id", "observation",
            ),
            "native stop evidence body",
        )
        evidence["evidence_id"] = _id(
            evidence["evidence_id"], "native stop evidence evidence_id"
        ) or ""
        evidence["stop_id"] = _id(
            evidence["stop_id"], "native stop evidence stop_id"
        ) or ""
        if (not isinstance(evidence["kind"], str) or
                evidence["kind"] not in _NATIVE_STOP_EVIDENCE_KINDS):
            raise _error("invalid", "native stop evidence kind is invalid")
        evidence["agent_id"] = _id(
            evidence["agent_id"], "native stop evidence agent_id"
        ) or ""
        evidence["task_id"] = _id(
            evidence["task_id"], "native stop evidence task_id"
        ) or ""
        evidence["lineage_incarnation"] = _native_positive_generation(
            evidence["lineage_incarnation"],
            "native stop evidence lineage_incarnation",
        )
        evidence["observed_watermark"] = _native_positive_generation(
            evidence["observed_watermark"],
            "native stop evidence observed_watermark",
        )
        stop = intent["stop"]
        if (evidence["stop_id"] != stop["stop_id"] or
                evidence["agent_id"] != stop["agent_id"] or
                evidence["task_id"] != stop["task_id"] or
                evidence["lineage_incarnation"] != stop["lineage_incarnation"]):
            raise _error("ownership-conflict", "native stop evidence task identity changed")
        if evidence["observed_watermark"] < stop["observed_watermark"]:
            raise _error("stale-generation", "native stop evidence watermark moved backwards")
        admission = self._native_stop_admission(stop, context)
        if evidence["kind"] == "runtime-ack":
            if evidence["accepted"] is not True or evidence["ack_kind"] != "accepted-stop":
                raise _error("invalid", "native stop runtime acknowledgement is invalid")
        else:
            if (evidence["observed_watermark"] <= stop["observed_watermark"] or
                    evidence["event_kind"] != "task_notification" or
                    evidence["status"] != "stopped" or
                    evidence["tool_use_id"] != admission["tool_use_id"]):
                raise _error("stale-generation", "native stop terminal evidence is not current")
            event_uuid = evidence["event_uuid"]
            if event_uuid is not None:
                event_uuid = _id(
                    event_uuid, "native stop terminal event_uuid"
                )
            evidence["event_uuid"] = event_uuid
            terminal_observation = _native_exact_fields(
                evidence["observation"],
                (
                    "task_terminal", "active_tool_ids", "uncertain_tool_ids",
                    "unresolved_effect_ids",
                ),
                "native stop terminal observation",
            )
            if terminal_observation["task_terminal"] is not True:
                raise _error("invalid", "native stop terminal task fact is missing")
            for key in ("active_tool_ids", "uncertain_tool_ids", "unresolved_effect_ids"):
                terminal_observation[key] = self._native_stop_id_list(
                    terminal_observation[key], "native stop terminal " + key
                )
            evidence["observation"] = terminal_observation
        raw["evidence"] = evidence
        return _safe_json_projection(raw, "native stop evidence")

    def _load_native_stops(self, raw: Mapping[str, Any]) -> None:
        if self._native_context is not None and "native_stops" not in raw:
            raise _error("invalid", "native context has no durable native stop ledger")
        stops = raw.get("native_stops", {})
        if not isinstance(stops, Mapping) or len(stops) > 256:
            raise _error("invalid", "native stop ledger is malformed")
        if not stops:
            return
        context = self._native_context
        if context is None:
            raise _error("invalid", "native stops have no admission context")
        task_keys = set()
        for stop_id, record in stops.items():
            _id(stop_id, "native stop ID")
            record = _native_validate(
                record, record_kind="native-stop", label="native stop record"
            )
            expected = {
                "schema_version", "architecture", "record_kind", "stop_id",
                "digest", "frame", "may_have_been_sent", "authorization_count",
                "runtime_ack", "terminal_evidence", "evidence",
            }
            if set(record) != expected or record["stop_id"] != stop_id:
                raise _error("invalid", "native stop record fields are malformed")
            if (record["may_have_been_sent"] is not True or
                    type(record["authorization_count"]) is not int or
                    record["authorization_count"] != 1):
                raise _error("invalid", "native stop authorization state is malformed")
            digest = record["digest"]
            if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest):
                raise _error("invalid", "native stop digest is invalid")
            frame = self._validate_native_stop_intent(record["frame"], context)
            if frame["stop"]["stop_id"] != stop_id or digest != _digest(frame):
                raise _error("invalid", "native stop frame digest changed")
            task_key = self._native_stop_task_key(frame)
            if task_key in task_keys:
                raise _error("invalid", "native stop task incarnation was duplicated")
            task_keys.add(task_key)
            evidence_records = record["evidence"]
            if not isinstance(evidence_records, Mapping) or len(evidence_records) > 512:
                raise _error("invalid", "native stop evidence ledger is malformed")
            runtime_ack = None
            terminal_evidence = None
            for evidence_id, evidence_record in evidence_records.items():
                _id(evidence_id, "native stop evidence ID")
                evidence_record = _mapping(
                    evidence_record, "native stop evidence record"
                )
                if set(evidence_record) != {"digest", "frame", "result"}:
                    raise _error("invalid", "native stop evidence record fields are malformed")
                evidence_frame = self._validate_native_stop_evidence(
                    evidence_record["frame"], context, frame
                )
                if (evidence_frame["evidence"]["evidence_id"] != evidence_id or
                        evidence_record["digest"] != _digest(evidence_frame) or
                        evidence_record["result"] != self._native_stop_evidence_ack(evidence_frame)):
                    raise _error("invalid", "native stop evidence digest or result changed")
                if evidence_frame["evidence"]["kind"] == "runtime-ack":
                    if runtime_ack is not None:
                        raise _error("invalid", "native stop runtime acknowledgement was duplicated")
                    runtime_ack = evidence_frame
                else:
                    if terminal_evidence is not None:
                        raise _error("invalid", "native stop terminal evidence was duplicated")
                    terminal_evidence = evidence_frame
            if _json_value(record["runtime_ack"]) != _json_value(runtime_ack):
                raise _error("invalid", "native stop runtime acknowledgement is inconsistent")
            if _json_value(record["terminal_evidence"]) != _json_value(terminal_evidence):
                raise _error("invalid", "native stop terminal evidence is inconsistent")
            self._native_stops[stop_id] = _json_value(record)

    def _load_coordinator_interrupts(self, raw: Mapping[str, Any]) -> None:
        """Load coordinator interrupt facts without re-authorizing a send."""

        if self._native_context is not None and "coordinator_interrupts" not in raw:
            raise _error("invalid", "native context has no coordinator interrupt ledger")
        interrupts = raw.get("coordinator_interrupts", {})
        if not isinstance(interrupts, Mapping) or len(interrupts) > 256:
            raise _error("invalid", "coordinator interrupt ledger is malformed")
        if not interrupts:
            return
        context = self._native_context
        if context is None:
            raise _error("invalid", "coordinator interrupts have no admission context")
        source_keys = set()
        for interrupt_id, record in interrupts.items():
            _id(interrupt_id, "coordinator interrupt ID")
            record = _native_validate(
                record, record_kind="coordinator-interrupt",
                label="coordinator interrupt record",
            )
            expected = {
                "schema_version", "architecture", "record_kind", "interrupt_id",
                "source_exclusion_key", "digest", "frame", "created_at", "may_have_been_sent",
                "authorization_count", "runtime_ack", "evidence", "progress_watermark",
            }
            if set(record) != expected or record["interrupt_id"] != interrupt_id:
                raise _error("invalid", "coordinator interrupt record fields are malformed")
            if (record["may_have_been_sent"] is not True or
                    type(record["authorization_count"]) is not int or
                    record["authorization_count"] != 1):
                raise _error("invalid", "coordinator interrupt authorization state is malformed")
            if (isinstance(record["created_at"], bool) or
                    not isinstance(record["created_at"], (int, float)) or
                    not math.isfinite(record["created_at"])):
                raise _error("invalid", "coordinator interrupt creation timestamp is invalid")
            frame = self._validate_coordinator_interrupt_intent(
                record["frame"], context, live=False
            )
            interrupt = frame["interrupt"]
            if interrupt["interrupt_id"] != interrupt_id or record["digest"] != _digest(frame):
                raise _error("invalid", "coordinator interrupt frame digest changed")
            source_key = self._native_interrupt_source_key(
                owner_generation=interrupt["owner_generation"],
                lineage_id=interrupt["lineage_id"],
                lineage_generation=interrupt["lineage_generation"],
                session_id=frame["session_id"],
                runner_instance_id=frame["runner_instance_id"],
            )
            if record["source_exclusion_key"] != source_key:
                raise _error("invalid", "coordinator interrupt source exclusion key changed")
            self._native_interrupt_digest(
                record["source_exclusion_key"], "coordinator interrupt source exclusion key"
            )
            if source_key in source_keys:
                raise _error("invalid", "coordinator interrupt source was authorized twice")
            source_keys.add(source_key)
            evidence_records = record["evidence"]
            if not isinstance(evidence_records, Mapping) or len(evidence_records) > 512:
                raise _error("invalid", "coordinator interrupt evidence ledger is malformed")
            progress = interrupt["roster_seal_watermark"]
            observations = []
            terminal_facts = {}
            tool_terminal_facts = {}
            runtime_ack = None
            for evidence_id, evidence_record in evidence_records.items():
                _id(evidence_id, "coordinator interrupt evidence ID")
                evidence_record = _mapping(
                    evidence_record, "coordinator interrupt evidence record"
                )
                if set(evidence_record) != {"digest", "frame", "result"}:
                    raise _error("invalid", "coordinator interrupt evidence record fields are malformed")
                evidence_frame = self._validate_coordinator_interrupt_evidence(
                    evidence_record["frame"], context, frame
                )
                evidence = evidence_frame["evidence"]
                if (evidence["evidence_id"] != evidence_id or
                        evidence_record["digest"] != _digest(evidence_frame) or
                        evidence_record["result"] != self._coordinator_interrupt_evidence_ack(evidence_frame)):
                    raise _error("invalid", "coordinator interrupt evidence digest or result changed")
                progress = max(progress, evidence["observed_watermark"])
                if evidence["kind"] == "runtime-ack":
                    if runtime_ack is not None:
                        raise _error("invalid", "coordinator interrupt runtime acknowledgement was duplicated")
                    runtime_ack = evidence_frame
                if evidence["kind"] == "member-terminal":
                    data = evidence["data"]
                    terminal_key = (
                        data["agent_id"], data["task_id"], data["tool_use_id"],
                        data["lineage_incarnation"],
                    )
                    prior_status = terminal_facts.get(terminal_key)
                    if prior_status is not None and prior_status != data["status"]:
                        raise _error("uncertain-effect", "coordinator member terminal facts conflict")
                    terminal_facts[terminal_key] = data["status"]
                if evidence["kind"] == "tool-terminal":
                    data = evidence["data"]
                    tool_key = (
                        data["tool_use_id"], data["agent_id"],
                        data["lineage_incarnation"],
                    )
                    prior_status = tool_terminal_facts.get(tool_key)
                    if prior_status is not None and prior_status != data["status"]:
                        raise _error("uncertain-effect", "coordinator tool terminal facts conflict")
                    tool_terminal_facts[tool_key] = data["status"]
                if evidence["kind"] == "request-observation":
                    data = evidence["data"]
                    observations.append((
                        data["through_watermark"],
                        data["new_requests"],
                        data["observable"],
                        evidence_id,
                    ))
            prior_through = None
            prior_count = None
            same_through_count = None
            for through, count, _, _ in sorted(observations, key=lambda item: (item[0], item[3])):
                if prior_through is not None and through < prior_through:
                    raise _error("stale-generation", "coordinator request observation count moved backwards")
                if through == prior_through:
                    if (count is not None and same_through_count is not None and
                            count != same_through_count):
                        raise _error("stale-generation", "coordinator request observations conflict at one watermark")
                else:
                    same_through_count = None
                if count is not None:
                    if prior_count is not None and count < prior_count:
                        raise _error("stale-generation", "coordinator request observation count moved backwards")
                    prior_count = count
                    same_through_count = count
                prior_through = through
            if (type(record["progress_watermark"]) is not int or
                    record["progress_watermark"] != progress):
                raise _error("invalid", "coordinator interrupt progress watermark changed")
            if _json_value(record["runtime_ack"]) != _json_value(runtime_ack):
                raise _error("invalid", "coordinator interrupt runtime acknowledgement is inconsistent")
            self._coordinator_interrupts[interrupt_id] = _json_value(record)

    @staticmethod
    def _native_source_identity(
            generation: Any, context: Mapping[str, Any]
    ) -> Dict[str, Any]:
        context = _mapping(context, "native source context")
        lineage = _mapping(context.get("lineage"), "native source lineage")
        owner_generation = _native_positive_generation(
            lineage.get("owner_generation"),
            "native source owner_generation",
        )
        expected_generation = _native_positive_generation(
            generation, "native source generation"
        )
        if owner_generation != expected_generation:
            raise _error("stale-generation", "native source context generation changed")
        return {
            "owner_generation": owner_generation,
            "lineage_id": _id(
                lineage.get("lineage_id"), "native source lineage_id"
            ) or "",
            "lineage_generation": _native_positive_generation(
                lineage.get("lineage_generation"),
                "native source lineage_generation",
            ),
            "session_uuid": _id(
                lineage.get("session_uuid"), "native source session_uuid"
            ) or "",
            "runner_incarnation": _id(
                context.get("runner_incarnation"),
                "native source runner_incarnation",
            ) or "",
            "invocation_id": _id(
                context.get("invocation_id"), "native source invocation_id"
            ) or "",
        }

    @classmethod
    def _validate_native_source_archive_entry(
            cls, value: Any, *, expected_archive_id: Optional[str] = None
    ) -> Dict[str, Any]:
        """Validate one archive without consulting the live controller state."""

        raw = _native_validate(
            value,
            record_kind="native-source-archive",
            label="native source archive",
        )
        if set(raw) != _NATIVE_SOURCE_ARCHIVE_FIELDS:
            raise _error("invalid", "native source archive fields are malformed")
        archive_id = _id(raw["archive_id"], "native source archive ID") or ""
        if expected_archive_id is not None and archive_id != expected_archive_id:
            raise _error("invalid", "native source archive key is inconsistent")
        operation_id = _id(
            raw["operation_id"], "native source archive operation ID"
        ) or ""
        source_identity = _native_exact_fields(
            raw["source_identity"],
            tuple(sorted(_NATIVE_SOURCE_IDENTITY_FIELDS)),
            "native source archive source_identity",
        )
        source_identity["owner_generation"] = _native_positive_generation(
            source_identity["owner_generation"],
            "native source archive owner_generation",
        )
        source_identity["lineage_generation"] = _native_positive_generation(
            source_identity["lineage_generation"],
            "native source archive lineage_generation",
        )
        for key in (
                "lineage_id", "session_uuid", "runner_incarnation", "invocation_id"
        ):
            source_identity[key] = _id(
                source_identity[key], "native source archive " + key
            ) or ""
        snapshot = _mapping(raw["snapshot"], "native source archive snapshot")
        # This check deliberately precedes construction of the isolated
        # controller.  Even an empty nested collection would make historical
        # validation recursive and would no longer be an independent archive.
        if "native_source_archives" in snapshot:
            raise _error(
                "invalid",
                "native source archive snapshot contains native_source_archives",
            )
        if any(not isinstance(key, str) for key in snapshot):
            raise _error("invalid", "native source archive snapshot has invalid fields")
        snapshot_fields = set(snapshot)
        original_snapshot = _json_value(snapshot)
        optional_ledger_fields = {
            "native_invocation_history",
            "native_invocation_rollovers",
            "native_child_observations",
        }
        missing_optional = _CONTROLLER_SNAPSHOT_FIELDS - snapshot_fields
        if missing_optional and missing_optional.issubset(optional_ledger_fields):
            # Older schema-v2 source archives predate one or more optional
            # native ledgers. Keep their bytes/read semantics intact while
            # presenting explicit empty collections to the isolated reader.
            snapshot = dict(snapshot)
            for field in missing_optional:
                snapshot[field] = {}
        elif snapshot_fields != _CONTROLLER_SNAPSHOT_FIELDS:
            raise _error("invalid", "native source archive snapshot fields are malformed")
        snapshot = _json_value(snapshot)
        snapshot_digest = cls._native_interrupt_digest(
            raw["snapshot_digest"], "native source archive snapshot digest"
        )
        if snapshot_digest != _digest(original_snapshot):
            raise _error("invalid", "native source archive snapshot digest changed")

        # The historical validator has only the copied record.  In particular,
        # it receives no live store, runtime, trusted daemon, or current
        # controller object that could turn an old snapshot into a new claim.
        isolated = cls(
            {"controller.json": _json_value(snapshot)},
            runtime=None,
            clock=lambda: 0.0,
            _native_stop_daemon_id=None,
            _coordinator_interrupt_daemon_id=None,
        )
        canonical_snapshot = isolated._record()
        canonical_snapshot.pop("native_source_archives", None)
        if _canonical_json(snapshot, "native source archive snapshot") != _canonical_json(
                canonical_snapshot, "validated native source archive snapshot"):
            raise _error(
                "invalid",
                "native source archive snapshot is not canonical",
            )

        if isolated._active_operation_id != operation_id:
            raise _error("stale-generation", "native source archive operation linkage changed")
        operation = isolated._operations.get(operation_id)
        if (operation is None or operation.phase not in {"paused", "indeterminate"}):
            raise _error(
                "stale-generation",
                "native source archive operation is not paused or indeterminate",
            )
        if operation.generation != snapshot.get("generation"):
            raise _error("stale-generation", "native source archive operation generation changed")
        context = isolated._native_context
        if not isinstance(context, Mapping) or context.get("fenced") is not True:
            raise _error(
                "unsupported",
                "native source archive snapshot is not fenced",
            )
        expected_identity = cls._native_source_identity(
            snapshot.get("generation"), context
        )
        if source_identity != expected_identity:
            raise _error("ownership-conflict", "native source archive identity changed")
        if source_identity["owner_generation"] != operation.generation:
            raise _error("stale-generation", "native source archive operation owner changed")

        raw["archive_id"] = archive_id
        raw["operation_id"] = operation_id
        raw["source_identity"] = source_identity
        raw["snapshot_digest"] = snapshot_digest
        # Optional ledger defaults belong only to the isolated validator.
        # Returning that expanded view would silently rewrite immutable
        # history while retaining the digest of the original snapshot.
        raw["snapshot"] = original_snapshot
        return _json_value(raw)

    # ---- same-runner invocation history ------------------------------

    @staticmethod
    def _native_record_integrity(value: Mapping[str, Any], field: str) -> str:
        candidate = {
            key: _json_value(item)
            for key, item in value.items()
            if key != field
        }
        return _digest(candidate)

    @staticmethod
    def _native_coordinator_identity(value: Any, label: str) -> Dict[str, str]:
        identity = _native_exact_fields(
            value, ("participant_id", "session_uuid"), label
        )
        identity["participant_id"] = _id(
            identity["participant_id"], label + " participant_id"
        ) or ""
        identity["session_uuid"] = _id(
            identity["session_uuid"], label + " session_uuid"
        ) or ""
        return identity

    @classmethod
    def _validate_native_prepare_request(
            cls, value: Any, label: str = "native rollover preparation request",
    ) -> Dict[str, Any]:
        """Validate the immutable prepare-invocation binding independently.

        The request is not a durable native record and therefore does not use
        the record envelope validator.  It still has a closed field set and a
        self-authenticating binding digest; retaining only a mapping projection
        here would allow a recomputed rollover digest to hide a changed
        reservation or identity.
        """
        request = _native_exact_fields(value, tuple(_NATIVE_PREPARE_REQUEST_FIELDS), label)
        if type(request["schema_version"]) is not int or request["schema_version"] != 2:
            raise _error("invalid", "%s schema_version is unsupported" % label)
        if request["architecture"] != NATIVE_ARCHITECTURE:
            raise _error("invalid", "%s architecture is unsupported" % label)
        if type(request["reservation_version"]) is not int or request["reservation_version"] != 1:
            raise _error("invalid", "%s reservation_version is unsupported" % label)
        for key in (
            "reservation_id", "operation_id", "daemon_id", "participant_id",
            "session_id", "runner_incarnation", "lineage_id", "prior_invocation_id",
            "next_invocation_id", "prior_mailbox_id", "next_mailbox_id",
        ):
            request[key] = _id(request[key], "%s %s" % (label, key)) or ""
        for key in ("owner_generation", "lineage_generation", "prior_watermark"):
            request[key] = _native_positive_generation(
                request[key], "%s %s" % (label, key)
            )
        if request["prior_invocation_id"] != request["prior_mailbox_id"]:
            raise _error("ownership-conflict", "%s prior invocation/mailbox changed" % label)
        if request["next_invocation_id"] != request["next_mailbox_id"]:
            raise _error("ownership-conflict", "%s next invocation/mailbox changed" % label)
        if request["prior_invocation_id"] == request["next_invocation_id"]:
            raise _error("invalid", "%s reuses invocation identity" % label)
        for key in (
            "definitions_digest", "permissions_digest", "claim_digest", "binding_digest",
        ):
            digest = request[key]
            if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest):
                raise _error("invalid", "%s %s is invalid" % (label, key))
        expected_binding = _digest({
            key: request[key]
            for key in _NATIVE_PREPARE_REQUEST_FIELDS
            if key != "binding_digest"
        })
        if request["binding_digest"] != expected_binding:
            raise _error("invalid", "%s binding digest changed" % label)
        return _json_value(request)

    @staticmethod
    def _native_history_roster(value: Any, label: str) -> Dict[str, Any]:
        roster = _native_exact_fields(
            value,
            (
                "parent_state", "children", "pending_admission_ids",
                "pending_task_ids", "parent_active_tool_ids",
                "parent_uncertain_tool_ids", "parent_unresolved_effect_ids",
                "descendant_ids",
            ),
            label,
        )
        if roster["parent_state"] != "idle":
            raise _error("busy", "%s parent is not terminal" % label)
        if not isinstance(roster["children"], list) or len(roster["children"]) > 256:
            raise _error("invalid", "%s children are malformed" % label)
        for key in (
            "pending_admission_ids", "pending_task_ids", "parent_active_tool_ids",
            "parent_uncertain_tool_ids", "parent_unresolved_effect_ids",
            "descendant_ids",
        ):
            values = roster[key]
            if not isinstance(values, list) or any(
                not isinstance(item, str) or not item for item in values
            ) or len(set(values)) != len(values):
                raise _error("invalid", "%s %s are malformed" % (label, key))
            if values:
                raise _error("busy", "%s has unresolved %s" % (label, key))
        for index, child in enumerate(roster["children"]):
            child = _native_exact_fields(
                child,
                (
                    "admission_id", "tool_use_id", "agent_id", "task_id",
                    "parent_agent_id", "invocation_id", "lineage_incarnation",
                    "trusted_definition_digest", "start_watermark", "task_start_event",
                    "status", "terminal_watermark", "active_tool_ids",
                    "uncertain_tool_ids", "unresolved_effect_ids",
                ),
                "%s child %s" % (label, index),
            )
            for key in ("admission_id", "tool_use_id", "agent_id", "task_id", "invocation_id"):
                child[key] = _id(child[key], "%s child %s %s" % (label, index, key)) or ""
            if child["parent_agent_id"] is not None:
                child["parent_agent_id"] = _id(
                    child["parent_agent_id"], "%s child %s parent_agent_id" % (label, index)
                )
            child["lineage_incarnation"] = _native_positive_generation(
                child["lineage_incarnation"], "%s child %s lineage_incarnation" % (label, index)
            )
            if (
                not isinstance(child["trusted_definition_digest"], str)
                or not re.fullmatch(r"[0-9a-f]{64}", child["trusted_definition_digest"])
            ):
                raise _error("invalid", "%s child %s definition digest is invalid" % (label, index))
            child["start_watermark"] = _native_positive_generation(
                child["start_watermark"], "%s child %s start watermark" % (label, index)
            )
            event = _native_exact_fields(
                child["task_start_event"], ("event_uuid", "watermark", "task_type"),
                "%s child %s task-start event" % (label, index),
            )
            if event["event_uuid"] is not None:
                event["event_uuid"] = _id(
                    event["event_uuid"], "%s child %s event UUID" % (label, index)
                )
            event["watermark"] = _native_positive_generation(
                event["watermark"], "%s child %s event watermark" % (label, index)
            )
            event["task_type"] = _id(
                event["task_type"], "%s child %s task type" % (label, index)
            ) or ""
            child["task_start_event"] = event
            if event["watermark"] <= child["start_watermark"]:
                raise _error("stale-generation", "%s child %s task event predates start" % (label, index))
            if child["status"] not in {"completed", "stopped"}:
                raise _error("busy", "%s child %s is not terminal" % (label, index))
            child["terminal_watermark"] = _native_positive_generation(
                child["terminal_watermark"],
                "%s child %s terminal watermark" % (label, index),
            )
            if child["terminal_watermark"] < max(
                    child["start_watermark"], event["watermark"]
            ):
                raise _error("stale-generation", "%s child %s terminal predates task" % (label, index))
            for key in ("active_tool_ids", "uncertain_tool_ids", "unresolved_effect_ids"):
                values = child[key]
                if not isinstance(values, list) or any(
                    not isinstance(item, str) or not item for item in values
                ) or len(set(values)) != len(values) or values:
                    raise _error("busy", "%s child %s has unresolved %s" % (label, index, key))
            roster["children"][index] = child
        for key in ("admission_id", "tool_use_id", "agent_id", "task_id"):
            values = [child[key] for child in roster["children"]]
            if len(values) != len(set(values)):
                raise _error("invalid", "%s child %s identity is duplicated" % (label, key))
        return _safe_json_projection(roster, label)

    @classmethod
    def _validate_native_history_admissions(
            cls, value: Any, context: Mapping[str, Any],
    ) -> Dict[str, Any]:
        admissions = _mapping(value, "native history admissions")
        if len(admissions) > 256:
            raise _error("invalid", "native history admissions exceed capacity")
        normalized: Dict[str, Any] = {}
        admission_ids: set[str] = set()
        tool_use_ids: set[str] = set()
        watermarks: set[int] = set()
        for request_id, value in admissions.items():
            request_id = _id(request_id, "native history admission request ID") or ""
            record = _native_validate(
                value, record_kind="pending-admission",
                label="native history admission record",
            )
            expected = {
                "schema_version", "architecture", "record_kind", "request_id",
                "digest", "admission", "claim_ref", "ack",
            }
            record_fields = set(record)
            if (not expected.issubset(record_fields)
                    or record_fields - expected - {"parent_observation"}
                    or record["request_id"] != request_id):
                raise _error("invalid", "native history admission fields are malformed")
            admission = cls._validate_native_admission(record["admission"], context)
            if record["digest"] != _digest(admission):
                raise _error("invalid", "native history admission digest changed")
            claim_ref = _safe_json_projection(
                record["claim_ref"], "native history admission claim"
            )
            if claim_ref != context["lineage"]["workspace_claim"]:
                raise _error("ownership-conflict", "native history admission claim changed")
            if _json_value(record["ack"]) != _json_value(cls._native_admission_ack(admission)):
                raise _error("invalid", "native history admission acknowledgement changed")
            parent_agent = admission["parent"].get("agent_id")
            if parent_agent is None and "parent_observation" in record:
                raise _error("invalid", "top-level native history admission has a parent binding")
            if parent_agent is not None:
                binding = record.get("parent_observation")
                if binding is None:
                    raise _error("ownership-conflict", "native history nested admission has no parent binding")
                _native_exact_fields(
                    binding,
                    ("child_run_id", "observation_id", "observation_digest"),
                    "native history parent observation",
                )
            admission_id = admission["admission_id"]
            tool_use_id = admission["tool_use_id"]
            watermark = admission["watermark"]
            if admission_id in admission_ids or tool_use_id in tool_use_ids:
                raise _error("invalid", "native history admission identity is duplicated")
            if watermark in watermarks:
                raise _error("invalid", "native history admission watermark is duplicated")
            admission_ids.add(admission_id)
            tool_use_ids.add(tool_use_id)
            watermarks.add(watermark)
            normalized_record = {
                **native_record_marker("pending-admission"),
                "request_id": request_id,
                "digest": record["digest"],
                "admission": _json_value(admission),
                "claim_ref": claim_ref,
                "ack": _json_value(record["ack"]),
            }
            if parent_agent is not None:
                normalized_record["parent_observation"] = _json_value(record["parent_observation"])
            normalized[request_id] = normalized_record
        return normalized

    @classmethod
    def _validate_native_history_child_observations(
            cls, value: Any, *, context: Mapping[str, Any],
            admissions: Mapping[str, Any], operation_id: str,
    ) -> Dict[str, Any]:
        """Validate source-A child observations retained by an immutable history."""
        if value is None or not isinstance(value, Mapping):
            raise _error("invalid", "native history child observations are malformed")
        if len(value) > _NATIVE_CHILD_OBSERVATION_LIMIT * _NATIVE_CHILD_OBSERVATIONS_PER_RUN_LIMIT:
            raise _error("invalid", "native history child observations exceed capacity")
        if len(_canonical_json(value).encode("utf-8")) > MAX_PAYLOAD_REFERENCE_BYTES:
            raise _error("invalid", "native history child observations exceed one MiB")
        admission_bodies = {
            record["admission"]["admission_id"]: record["admission"]
            for record in admissions.values()
            if isinstance(record, Mapping)
            and isinstance(record.get("admission"), Mapping)
        }
        normalized: Dict[str, Any] = {}
        groups: Dict[str, List[Dict[str, Any]]] = {}
        for observation_id, value_entry in value.items():
            observation_id = _id(observation_id, "native history child observation key") or ""
            entry = cls._native_child_observation_entry_shape(
                value_entry, expected_observation_id=observation_id,
            )
            observation = entry["observation"]
            child = observation.get("child") if isinstance(observation, Mapping) else None
            admission_id = child.get("admission_id") if isinstance(child, Mapping) else None
            admission = admission_bodies.get(admission_id)
            if admission is None:
                raise _error("ownership-conflict", "native history child admission is unknown")
            try:
                observation = cls._native_child_call(
                    _validate_native_child_observation,
                    observation, context=context, admission=admission,
                )
            except ControllerError:
                raise
            entry["observation"] = observation
            try:
                run_id = _native_child_run_id(observation)
            except NativeChildContractError as exc:
                raise _error(exc.code, exc.message) from exc
            if entry["child_run_id"] != run_id:
                raise _error("invalid", "native history child run identity changed")
            if entry["source_operation_id"] != operation_id:
                raise _error("ownership-conflict", "native history child source operation changed")
            normalized[observation_id] = entry
            groups.setdefault(run_id, []).append(observation)
        if len(groups) > _NATIVE_CHILD_OBSERVATION_LIMIT:
            raise _error("busy", "native history child run capacity is exhausted")
        for history in groups.values():
            history.sort(key=lambda item: item["observation_watermark"])
            if len(history) > _NATIVE_CHILD_OBSERVATIONS_PER_RUN_LIMIT:
                raise _error("busy", "native history child observation run is full")
            for prior, candidate in zip(history, history[1:]):
                cls._native_child_call(_validate_native_child_progress, prior, candidate)
        identities: Dict[Tuple[str, str], str] = {}
        for entry in normalized.values():
            child = entry["observation"]["child"]
            run_id = entry["child_run_id"]
            for key in ("admission_id", "tool_use_id", "agent_id", "task_id"):
                identity_key = (key, child[key])
                prior_run = identities.get(identity_key)
                if prior_run is not None and prior_run != run_id:
                    raise _error("invalid", "native history child identity was reused across runs")
                identities[identity_key] = run_id
        for record in admissions.values():
            admission = record["admission"]
            parent_agent = admission["parent"].get("agent_id")
            binding = record.get("parent_observation")
            if parent_agent is None:
                if binding is not None:
                    raise _error("invalid", "native history top-level admission has a parent binding")
                continue
            if binding is None:
                raise _error("ownership-conflict", "native history nested admission has no parent binding")
            cls._native_child_call(
                _validate_native_parent_binding,
                admission, binding, context=context,
                admissions=admission_bodies,
                observations={key: item["observation"] for key, item in normalized.items()},
            )
        return normalized

    @classmethod
    def _validate_native_history_stop_record(
            cls, value: Any, context: Mapping[str, Any],
            admissions: Mapping[str, Any], invocation_id: str,
    ) -> Dict[str, Any]:
        record = _native_validate(
            value, record_kind="native-stop", label="native history stop record"
        )
        expected = {
            "schema_version", "architecture", "record_kind", "stop_id", "digest",
            "frame", "may_have_been_sent", "authorization_count", "runtime_ack",
            "terminal_evidence", "evidence",
        }
        if set(record) != expected:
            raise _error("invalid", "native history stop fields are malformed")
        stop_id = _id(record["stop_id"], "native history stop ID") or ""
        if record["may_have_been_sent"] is not True or record["authorization_count"] != 1:
            raise _error("invalid", "native history stop authorization is malformed")
        frame = _native_exact_fields(
            record["frame"],
            ("type", "participant_id", "session_id", "runner_instance_id", "stop"),
            "native history stop frame",
        )
        if frame["type"] != _NATIVE_STOP_INTENT_TYPE:
            raise _error("invalid", "native history stop frame type is invalid")
        participant_id = _id(frame["participant_id"], "native history stop participant") or ""
        session_id = _id(frame["session_id"], "native history stop session") or ""
        runner_id = _id(frame["runner_instance_id"], "native history stop runner") or ""
        if session_id != context["lineage"]["session_uuid"] or runner_id != context["runner_incarnation"]:
            raise _error("ownership-conflict", "native history stop runner identity changed")
        stop = _native_exact_fields(
            frame["stop"],
            (
                "stop_id", "owner_generation", "lineage_id", "invocation_id",
                "admission_id", "tool_use_id", "agent_id", "task_id",
                "lineage_incarnation", "trusted_definition_digest",
                "observed_watermark", "observation",
            ),
            "native history stop body",
        )
        for key in (
            "stop_id", "invocation_id", "admission_id", "tool_use_id", "agent_id", "task_id",
        ):
            stop[key] = _id(stop[key], "native history stop " + key) or ""
        if stop["stop_id"] != stop_id or stop["invocation_id"] != invocation_id:
            raise _error("ownership-conflict", "native history stop identity changed")
        if (
            stop["owner_generation"] != context["lineage"]["owner_generation"]
            or stop["lineage_id"] != context["lineage"]["lineage_id"]
            or stop["lineage_incarnation"] <= 0
        ):
            raise _error("stale-generation", "native history stop lineage changed")
        digest = stop["trusted_definition_digest"]
        if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise _error("invalid", "native history stop definition digest is invalid")
        request_id = None
        admission = None
        for candidate_request_id, candidate in admissions.items():
            candidate_admission = candidate.get("admission") if isinstance(candidate, Mapping) else None
            if isinstance(candidate_admission, Mapping) and candidate_admission.get(
                    "admission_id"
            ) == stop["admission_id"]:
                request_id = candidate_request_id
                admission = candidate_admission
                break
        if admission is None:
            raise _error("ownership-conflict", "native history stop admission is unknown")
        if (
            stop["tool_use_id"] != admission["tool_use_id"]
            or stop["trusted_definition_digest"] != admission["trusted_definition_digest"]
        ):
            raise _error("ownership-conflict", "native history stop admission changed")
        observation = _native_exact_fields(
            stop["observation"],
            (
                "status", "task_terminal", "start_watermark", "task_start_event",
                "active_tool_ids", "uncertain_tool_ids", "unresolved_effect_ids",
            ),
            "native history stop observation",
        )
        if observation["status"] != "active" or observation["task_terminal"] is not False:
            raise _error("invalid", "native history stop observation is not active")
        _native_positive_generation(
            observation["start_watermark"], "native history stop start watermark"
        )
        event = _native_exact_fields(
            observation["task_start_event"], ("event_uuid", "watermark", "task_type"),
            "native history stop task event",
        )
        if event["event_uuid"] is not None:
            _id(event["event_uuid"], "native history stop task event UUID")
        _native_positive_generation(event["watermark"], "native history stop task event watermark")
        _id(event["task_type"], "native history stop task type")
        for key in ("active_tool_ids", "uncertain_tool_ids", "unresolved_effect_ids"):
            cls._native_stop_id_list(observation[key], "native history stop " + key)
        _native_positive_generation(stop["observed_watermark"], "native history stop watermark")
        if record["digest"] != _digest(frame):
            raise _error("invalid", "native history stop digest changed")
        evidence_records = _mapping(record["evidence"], "native history stop evidence")
        runtime_ack = None
        terminal_evidence = None
        normalized_evidence: Dict[str, Any] = {}
        for evidence_id, evidence_record in evidence_records.items():
            evidence_id = _id(evidence_id, "native history stop evidence ID") or ""
            evidence_record = _native_exact_fields(
                evidence_record, ("digest", "frame", "result"),
                "native history stop evidence record",
            )
            evidence = _native_exact_fields(
                evidence_record["frame"],
                ("type", "participant_id", "session_id", "runner_instance_id", "evidence"),
                "native history stop evidence frame",
            )
            if evidence["type"] != _NATIVE_STOP_EVIDENCE_TYPE:
                raise _error("invalid", "native history stop evidence type is invalid")
            if (
                evidence["participant_id"] != participant_id
                or evidence["session_id"] != session_id
                or evidence["runner_instance_id"] != runner_id
            ):
                raise _error("ownership-conflict", "native history stop evidence runner changed")
            body = _mapping(evidence["evidence"], "native history stop evidence body")
            kind = body.get("kind")
            if kind not in _NATIVE_STOP_EVIDENCE_KINDS:
                raise _error("invalid", "native history stop evidence kind is invalid")
            fields = (
                "evidence_id", "stop_id", "kind", "agent_id", "task_id",
                "lineage_incarnation", "observed_watermark", "accepted", "ack_kind",
            ) if kind == "runtime-ack" else (
                "evidence_id", "stop_id", "kind", "agent_id", "task_id",
                "lineage_incarnation", "observed_watermark", "event_kind",
                "event_uuid", "status", "tool_use_id", "observation",
            )
            body = _native_exact_fields(body, fields, "native history stop evidence body")
            if body["evidence_id"] != evidence_id or body["stop_id"] != stop_id:
                raise _error("ownership-conflict", "native history stop evidence identity changed")
            if body["agent_id"] != stop["agent_id"] or body["task_id"] != stop["task_id"]:
                raise _error("ownership-conflict", "native history stop evidence task changed")
            if evidence_record["digest"] != _digest(evidence):
                raise _error("invalid", "native history stop evidence digest changed")
            expected_result = {
                "recorded": True, "evidence_id": evidence_id, "stop_id": stop_id,
            }
            if _json_value(evidence_record["result"]) != expected_result:
                raise _error("invalid", "native history stop evidence result changed")
            normalized_evidence[evidence_id] = {
                "digest": evidence_record["digest"],
                "frame": _json_value(evidence),
                "result": expected_result,
            }
            if kind == "runtime-ack":
                if runtime_ack is not None:
                    raise _error("invalid", "native history stop runtime acknowledgement duplicated")
                runtime_ack = evidence
            else:
                if terminal_evidence is not None:
                    raise _error("invalid", "native history stop terminal evidence duplicated")
                terminal_evidence = evidence
        if _json_value(record["runtime_ack"]) != _json_value(runtime_ack):
            raise _error("invalid", "native history stop runtime acknowledgement changed")
        if _json_value(record["terminal_evidence"]) != _json_value(terminal_evidence):
            raise _error("invalid", "native history stop terminal evidence changed")
        return {
            **native_record_marker("native-stop"),
            "stop_id": stop_id,
            "digest": record["digest"],
            "frame": _json_value(frame),
            "may_have_been_sent": True,
            "authorization_count": 1,
            "runtime_ack": _json_value(runtime_ack),
            "terminal_evidence": _json_value(terminal_evidence),
            "evidence": normalized_evidence,
        }

    @classmethod
    def _validate_native_history_interrupt_record(
            cls, value: Any, context: Mapping[str, Any],
            admissions: Mapping[str, Any], invocation_id: str,
            operation_id: str, coordinator_id: str,
    ) -> Dict[str, Any]:
        record = _native_validate(
            value, record_kind="coordinator-interrupt",
            label="native history coordinator interrupt record",
        )
        expected = {
            "schema_version", "architecture", "record_kind", "interrupt_id",
            "source_exclusion_key", "digest", "frame", "created_at",
            "may_have_been_sent", "authorization_count", "runtime_ack",
            "evidence", "progress_watermark",
        }
        if set(record) != expected:
            raise _error("invalid", "native history coordinator interrupt fields are malformed")
        interrupt_id = _id(record["interrupt_id"], "native history interrupt ID") or ""
        if record["may_have_been_sent"] is not True or record["authorization_count"] != 1:
            raise _error("invalid", "native history interrupt authorization is malformed")
        if (
            isinstance(record["created_at"], bool)
            or not isinstance(record["created_at"], (int, float))
            or not math.isfinite(record["created_at"])
        ):
            raise _error("invalid", "native history interrupt creation time is invalid")
        frame = _native_exact_fields(
            record["frame"],
            ("type", "participant_id", "session_id", "runner_instance_id", "interrupt"),
            "native history interrupt frame",
        )
        if frame["type"] != _COORDINATOR_INTERRUPT_INTENT_TYPE:
            raise _error("invalid", "native history interrupt frame type is invalid")
        if (
            frame["participant_id"] != coordinator_id
            or frame["session_id"] != context["lineage"]["session_uuid"]
            or frame["runner_instance_id"] != context["runner_incarnation"]
        ):
            raise _error("ownership-conflict", "native history interrupt runner identity changed")
        interrupt = _native_exact_fields(
            frame["interrupt"],
            (
                "interrupt_id", "operation_id", "owner_generation", "lineage_id",
                "lineage_generation", "invocation_id", "fence_epoch",
                "roster_identity_digest", "roster_seal_watermark", "capability_digest",
                "request_epoch_id", "request_entry_watermark", "roster",
            ),
            "native history interrupt body",
        )
        for key in ("interrupt_id", "operation_id", "lineage_id", "invocation_id", "request_epoch_id"):
            interrupt[key] = _id(interrupt[key], "native history interrupt " + key) or ""
        if interrupt["interrupt_id"] != interrupt_id or interrupt["operation_id"] != operation_id:
            raise _error("ownership-conflict", "native history interrupt operation changed")
        if interrupt["invocation_id"] != invocation_id:
            raise _error("ownership-conflict", "native history interrupt invocation changed")
        if (
            interrupt["owner_generation"] != context["lineage"]["owner_generation"]
            or interrupt["lineage_id"] != context["lineage"]["lineage_id"]
            or interrupt["lineage_generation"] != context["lineage"]["lineage_generation"]
        ):
            raise _error("stale-generation", "native history interrupt lineage changed")
        for key in (
            "fence_epoch", "roster_seal_watermark", "request_entry_watermark",
        ):
            _native_positive_generation(interrupt[key], "native history interrupt " + key)
        for key in ("roster_identity_digest", "capability_digest"):
            if not isinstance(interrupt[key], str) or not re.fullmatch(r"[0-9a-f]{64}", interrupt[key]):
                raise _error("invalid", "native history interrupt %s is invalid" % key)
        if interrupt["request_entry_watermark"] > interrupt["roster_seal_watermark"]:
            raise _error("stale-generation", "native history interrupt request watermark changed")
        roster = _native_exact_fields(
            interrupt["roster"],
            (
                "parent_state", "children", "pending_admission_ids", "pending_task_ids",
                "parent_active_tool_ids", "parent_uncertain_tool_ids",
                "parent_unresolved_effect_ids", "descendant_ids",
            ),
            "native history interrupt roster",
        )
        seal_watermark = interrupt["roster_seal_watermark"]
        children = roster["children"]
        if not isinstance(children, list) or len(children) > 256:
            raise _error("invalid", "native history interrupt roster children are malformed")
        normalized_children = []
        seen_admissions: set[str] = set()
        seen_agents: set[str] = set()
        seen_tasks: set[str] = set()
        seen_tools: set[str] = set()
        for index, child in enumerate(children):
            child = cls._native_interrupt_child(
                child, seal_watermark=seal_watermark,
                label="native history interrupt child %s" % index,
            )
            for key, seen in (
                ("admission_id", seen_admissions), ("agent_id", seen_agents),
                ("task_id", seen_tasks), ("tool_use_id", seen_tools),
            ):
                if child[key] in seen:
                    raise _error("invalid", "native history interrupt child identity is duplicated")
                seen.add(child[key])
            admission = None
            for candidate in admissions.values():
                candidate_admission = candidate.get("admission") if isinstance(candidate, Mapping) else None
                if isinstance(candidate_admission, Mapping) and candidate_admission.get(
                        "admission_id"
                ) == child["admission_id"]:
                    admission = candidate_admission
                    break
            if admission is None:
                raise _error("ownership-conflict", "native history interrupt child admission is unknown")
            if (
                child["tool_use_id"] != admission["tool_use_id"]
                or child["invocation_id"] != invocation_id
                or child["trusted_definition_digest"] != admission["trusted_definition_digest"]
                or child["start_watermark"] <= admission["watermark"]
                or child["task_start_event"]["watermark"] <= admission["watermark"]
            ):
                raise _error("ownership-conflict", "native history interrupt child binding changed")
            normalized_children.append(child)
        child_by_agent = {child["agent_id"]: child for child in normalized_children}
        for child in normalized_children:
            parent_agent = child["parent_agent_id"]
            if parent_agent is not None:
                if parent_agent == child["agent_id"] or parent_agent not in child_by_agent:
                    raise _error("invalid", "native history interrupt child parent changed")
                seen_parents: set[str] = set()
                while parent_agent is not None:
                    if parent_agent in seen_parents:
                        raise _error("invalid", "native history interrupt child graph cycles")
                    seen_parents.add(parent_agent)
                    parent_agent = child_by_agent[parent_agent]["parent_agent_id"]
        for key in (
            "pending_admission_ids", "pending_task_ids", "parent_active_tool_ids",
            "parent_uncertain_tool_ids", "parent_unresolved_effect_ids", "descendant_ids",
        ):
            values = cls._native_interrupt_id_list(
                roster[key], "native history interrupt " + key
            )
            if key in {"pending_admission_ids", "pending_task_ids"} and values:
                raise _error("busy", "native history interrupt has unresolved %s" % key)
            roster[key] = values
        roster["children"] = normalized_children
        projection = cls._native_interrupt_roster_projection(roster)
        if interrupt["roster_identity_digest"] != _digest(projection):
            raise _error("invalid", "native history interrupt roster digest changed")
        frame["interrupt"] = {
            **interrupt,
            "roster": _json_value(roster),
        }
        if record["digest"] != _digest(frame):
            raise _error("invalid", "native history interrupt digest changed")
        evidence_records = _mapping(record["evidence"], "native history interrupt evidence")
        runtime_ack = None
        normalized_evidence: Dict[str, Any] = {}
        progress = interrupt["roster_seal_watermark"]
        for evidence_id, evidence_record in evidence_records.items():
            evidence_id = _id(evidence_id, "native history interrupt evidence ID") or ""
            evidence_record = _native_exact_fields(
                evidence_record, ("digest", "frame", "result"),
                "native history interrupt evidence record",
            )
            evidence = _native_exact_fields(
                evidence_record["frame"],
                ("type", "participant_id", "session_id", "runner_instance_id", "evidence"),
                "native history interrupt evidence frame",
            )
            if evidence["type"] != _COORDINATOR_INTERRUPT_EVIDENCE_TYPE:
                raise _error("invalid", "native history interrupt evidence type is invalid")
            if (
                evidence["participant_id"] != coordinator_id
                or evidence["session_id"] != context["lineage"]["session_uuid"]
                or evidence["runner_instance_id"] != context["runner_incarnation"]
            ):
                raise _error("ownership-conflict", "native history interrupt evidence runner changed")
            body = _native_exact_fields(
                evidence["evidence"],
                ("evidence_id", "interrupt_id", "kind", "observed_watermark", "data"),
                "native history interrupt evidence body",
            )
            if body["evidence_id"] != evidence_id or body["interrupt_id"] != interrupt_id:
                raise _error("ownership-conflict", "native history interrupt evidence identity changed")
            kind = body["kind"]
            if kind not in _COORDINATOR_INTERRUPT_EVIDENCE_KINDS:
                raise _error("invalid", "native history interrupt evidence kind is invalid")
            data = _native_exact_fields(
                body["data"], _COORDINATOR_INTERRUPT_FACT_FIELDS[kind],
                "native history interrupt evidence data",
            )
            observed = _native_positive_generation(
                body["observed_watermark"], "native history interrupt evidence watermark"
            )
            progress = max(progress, observed)
            if evidence_record["digest"] != _digest(evidence):
                raise _error("invalid", "native history interrupt evidence digest changed")
            expected_result = {
                "recorded": True, "evidence_id": evidence_id,
                "interrupt_id": interrupt_id,
            }
            if _json_value(evidence_record["result"]) != expected_result:
                raise _error("invalid", "native history interrupt evidence result changed")
            normalized_evidence[evidence_id] = {
                "digest": evidence_record["digest"],
                "frame": _json_value(evidence),
                "result": expected_result,
            }
            if kind == "runtime-ack":
                if runtime_ack is not None:
                    raise _error("invalid", "native history interrupt runtime acknowledgement duplicated")
                runtime_ack = evidence
        if record["progress_watermark"] != progress:
            raise _error("invalid", "native history interrupt progress watermark changed")
        if _json_value(record["runtime_ack"]) != _json_value(runtime_ack):
            raise _error("invalid", "native history interrupt runtime acknowledgement changed")
        source_key = cls._native_interrupt_source_key(
            owner_generation=interrupt["owner_generation"],
            lineage_id=interrupt["lineage_id"],
            lineage_generation=interrupt["lineage_generation"],
            session_id=frame["session_id"],
            runner_instance_id=frame["runner_instance_id"],
        )
        if record["source_exclusion_key"] != source_key:
            raise _error("invalid", "native history interrupt source key changed")
        return {
            **native_record_marker("coordinator-interrupt"),
            "interrupt_id": interrupt_id,
            "source_exclusion_key": source_key,
            "digest": record["digest"],
            "frame": _json_value(frame),
            "created_at": record["created_at"],
            "may_have_been_sent": True,
            "authorization_count": 1,
            "runtime_ack": _json_value(runtime_ack),
            "evidence": normalized_evidence,
            "progress_watermark": progress,
        }

    @classmethod
    def _validate_native_invocation_history_entry(
            cls, value: Any, *, expected_history_id: Optional[str] = None,
            expected_generation: Any = None,
    ) -> Dict[str, Any]:
        raw = _native_validate(
            value, record_kind="native-invocation-history",
            label="native invocation history",
        )
        raw_fields = set(raw)
        if (not _NATIVE_INVOCATION_HISTORY_FIELDS.issubset(raw_fields)
                or raw_fields - _NATIVE_INVOCATION_HISTORY_FIELDS
                - _NATIVE_INVOCATION_HISTORY_OPTIONAL_FIELDS):
            raise _error("invalid", "native invocation history fields are malformed")
        if type(raw["history_schema"]) is not int or raw["history_schema"] != 1:
            raise _error("invalid", "native invocation history schema is unsupported")
        history_id = _id(raw["history_id"], "native history ID") or ""
        if expected_history_id is not None and history_id != expected_history_id:
            raise _error("invalid", "native history key is inconsistent")
        operation_id = _id(raw["operation_id"], "native history operation ID") or ""
        owner_generation = _native_positive_generation(
            raw["owner_generation"], "native history owner generation"
        )
        if expected_generation is not None and owner_generation != expected_generation:
            raise _error("stale-generation", "native history owner generation changed")
        lineage_id = _id(raw["lineage_id"], "native history lineage ID") or ""
        lineage_generation = _native_positive_generation(
            raw["lineage_generation"], "native history lineage generation"
        )
        daemon_id = _id(raw["daemon_id"], "native history daemon ID") or ""
        coordinator = cls._native_coordinator_identity(
            raw["coordinator"], "native history coordinator"
        )
        runner_incarnation = _id(
            raw["runner_incarnation"], "native history runner incarnation"
        ) or ""
        invocation_id = _id(raw["invocation_id"], "native history invocation ID") or ""
        mailbox_id = _id(raw["mailbox_id"], "native history mailbox ID") or ""
        if invocation_id != mailbox_id:
            raise _error("ownership-conflict", "native history invocation and mailbox differ")
        context = cls._validate_native_context(raw["context"])
        if context["fenced"] is not True:
            raise _error("ownership-conflict", "native history context is not fenced")
        lineage = context["lineage"]
        if (
            context["invocation_id"] != invocation_id
            or context["runner_incarnation"] != runner_incarnation
            or lineage["owner_generation"] != owner_generation
            or lineage["lineage_id"] != lineage_id
            or lineage["lineage_generation"] != lineage_generation
            or lineage["session_uuid"] != coordinator["session_uuid"]
        ):
            raise _error("ownership-conflict", "native history context identity changed")
        admissions = cls._validate_native_history_admissions(
            raw["admissions"], context
        )
        history_child_observations = None
        if "native_child_observations" in raw:
            history_child_observations = cls._validate_native_history_child_observations(
                raw["native_child_observations"],
                context=context,
                admissions=admissions,
                operation_id=operation_id,
            )
        controls = _native_exact_fields(
            raw["terminal_controls"],
            ("native_stops", "coordinator_interrupts", "release_receipts"),
            "native history terminal controls",
        )
        stop_values = _mapping(
            controls["native_stops"], "native history native stops"
        )
        interrupt_values = _mapping(
            controls["coordinator_interrupts"], "native history coordinator interrupts"
        )
        normalized_stops: Dict[str, Any] = {}
        for stop_id, stop_record in stop_values.items():
            stop_id = _id(stop_id, "native history stop key") or ""
            stop_record = cls._validate_native_history_stop_record(
                stop_record, context, admissions, invocation_id
            )
            if stop_record["stop_id"] != stop_id:
                raise _error("invalid", "native history stop key is inconsistent")
            if stop_record["frame"]["participant_id"] != coordinator["participant_id"]:
                raise _error("ownership-conflict", "native history stop coordinator changed")
            normalized_stops[stop_id] = stop_record
        normalized_interrupts: Dict[str, Any] = {}
        for interrupt_id, interrupt_record in interrupt_values.items():
            interrupt_id = _id(interrupt_id, "native history interrupt key") or ""
            interrupt_record = cls._validate_native_history_interrupt_record(
                interrupt_record, context, admissions, invocation_id,
                operation_id, coordinator["participant_id"],
            )
            if interrupt_record["interrupt_id"] != interrupt_id:
                raise _error("invalid", "native history interrupt key is inconsistent")
            normalized_interrupts[interrupt_id] = interrupt_record
        release_receipts = _mapping(
            controls["release_receipts"], "native history release receipts"
        )
        normalized_receipts: Dict[str, Any] = {}
        for participant_id, receipt in release_receipts.items():
            participant_id = _id(participant_id, "native history release participant") or ""
            if receipt is None:
                raise _error("invalid", "native history release receipt is null")
            receipt = _safe_json_projection(
                _mapping(receipt, "native history release receipt"),
                "native history release receipt",
            )
            if participant_id == coordinator["participant_id"]:
                for key, expected in (
                    ("participant_id", participant_id),
                    ("session_id", coordinator["session_uuid"]),
                    ("runner_instance_id", runner_incarnation),
                ):
                    if key in receipt and receipt[key] != expected:
                        raise _error("ownership-conflict", "native history release identity changed")
            normalized_receipts[participant_id] = receipt
        terminal_controls = {
            "native_stops": normalized_stops,
            "coordinator_interrupts": normalized_interrupts,
            "release_receipts": normalized_receipts,
        }
        terminal_result = _native_exact_fields(
            raw["terminal_result"],
            (
                "session_id", "invocation_id", "message_id",
                "result_watermark", "reader_drained_watermark",
            ),
            "native history terminal result",
        )
        if (
            terminal_result["session_id"] != coordinator["session_uuid"]
            or terminal_result["invocation_id"] != invocation_id
            or terminal_result["message_id"] != mailbox_id
        ):
            raise _error("ownership-conflict", "native history terminal result changed identity")
        result_watermark = _native_positive_generation(
            terminal_result["result_watermark"], "native history result watermark"
        )
        drained_watermark = _native_positive_generation(
            terminal_result["reader_drained_watermark"],
            "native history reader drained watermark",
        )
        if result_watermark > drained_watermark:
            raise _error("stale-generation", "native history terminal watermarks are not ordered")
        independent_drain = _native_exact_fields(
            raw["independent_drain"],
            ("observation_watermark", "uncertainty", "overflow"),
            "native history independent drain",
        )
        observation_watermark = _native_positive_generation(
            independent_drain["observation_watermark"],
            "native history observation watermark",
        )
        if independent_drain["uncertainty"] != [] or independent_drain["overflow"] is not False:
            raise _error("busy", "native history drain is uncertain")
        joined_roster = cls._native_history_roster(
            raw["joined_roster"], "native history roster"
        )
        definition_digests = {
            fact.get("digest")
            for fact in context["definitions"].values()
            if isinstance(fact, Mapping)
        }
        admission_records = {
            record["admission"]["admission_id"]
            for record in admissions.values()
        }
        child_admissions = {child["admission_id"] for child in joined_roster["children"]}
        if admission_records != child_admissions:
            raise _error("ownership-conflict", "native history roster does not cover admissions")
        for child in joined_roster["children"]:
            if child["invocation_id"] != invocation_id:
                raise _error("ownership-conflict", "native history child invocation changed")
            if child["trusted_definition_digest"] not in definition_digests:
                raise _error("permission-mismatch", "native history child definition changed")
            admission = next(
                record["admission"] for record in admissions.values()
                if record["admission"]["admission_id"] == child["admission_id"]
            )
            if (
                child["tool_use_id"] != admission["tool_use_id"]
                or child["start_watermark"] <= admission["watermark"]
            ):
                raise _error("ownership-conflict", "native history child admission is unknown")
            if child["terminal_watermark"] > observation_watermark:
                raise _error("stale-generation", "native history child terminal watermark is after observation")
        source_watermark = _native_positive_generation(
            raw["source_watermark"], "native history source watermark"
        )
        terminal_watermark = _native_positive_generation(
            raw["terminal_watermark"], "native history terminal watermark"
        )
        if not source_watermark < result_watermark <= drained_watermark <= observation_watermark == terminal_watermark:
            raise _error("stale-generation", "native history watermarks are not strictly ascending")
        terminal_proof_digest = raw["terminal_proof_digest"]
        if (
            not isinstance(terminal_proof_digest, str)
            or not re.fullmatch(r"[0-9a-f]{64}", terminal_proof_digest)
        ):
            raise _error("invalid", "native history terminal proof digest is invalid")
        terminal_proof = {
            "parent_result": _json_value(terminal_result),
            "roster": _json_value(joined_roster),
            "roster_digest": _digest(joined_roster),
            "observation_watermark": observation_watermark,
            "uncertainty": _json_value(independent_drain["uncertainty"]),
            "overflow": independent_drain["overflow"],
        }
        if terminal_proof_digest != _digest(terminal_proof):
            raise _error("invalid", "native history terminal proof digest changed")
        runtime_correlation = _native_exact_fields(
            raw["runtime_correlation"],
            ("reservation_id", "state"),
            "native history runtime correlation",
        )
        _id(runtime_correlation["reservation_id"], "native history reservation ID")
        if runtime_correlation["state"] != "reserved":
            raise _error("invalid", "native history runtime correlation is invalid")
        normalized = {
            **native_record_marker("native-invocation-history"),
            "history_schema": 1,
            "history_id": history_id,
            "integrity_digest": raw["integrity_digest"],
            "operation_id": operation_id,
            "owner_generation": owner_generation,
            "lineage_id": lineage_id,
            "lineage_generation": lineage_generation,
            "daemon_id": daemon_id,
            "coordinator": coordinator,
            "runner_incarnation": runner_incarnation,
            "invocation_id": invocation_id,
            "mailbox_id": mailbox_id,
            "context": _json_value(context),
            "admissions": admissions,
            "terminal_controls": _json_value(terminal_controls),
            "terminal_result": _json_value(terminal_result),
            "independent_drain": _json_value(independent_drain),
            "joined_roster": joined_roster,
            "terminal_watermark": terminal_watermark,
            "source_watermark": source_watermark,
            "terminal_proof_digest": terminal_proof_digest,
            "runtime_correlation": _json_value(runtime_correlation),
        }
        if history_child_observations is not None:
            normalized["native_child_observations"] = history_child_observations
        if (
            not isinstance(normalized["integrity_digest"], str)
            or not re.fullmatch(r"[0-9a-f]{64}", normalized["integrity_digest"])
        ):
            raise _error("invalid", "native invocation history integrity digest is invalid")
        if normalized["integrity_digest"] != cls._native_record_integrity(
                normalized, "integrity_digest"
        ):
            raise _error("invalid", "native invocation history integrity digest changed")
        if len(_canonical_json(normalized).encode("utf-8")) > _NATIVE_INVOCATION_HISTORY_ENTRY_BYTES:
            raise _error("invalid", "native invocation history entry exceeds capacity")
        return normalized

    @classmethod
    def _validate_native_invocation_rollover_entry(
            cls, value: Any, *, expected_rollover_id: Optional[str] = None,
            expected_generation: Any = None,
            history_ids: Optional[set[str]] = None,
    ) -> Dict[str, Any]:
        raw = _native_validate(
            value, record_kind="native-invocation-rollover",
            label="native invocation rollover",
        )
        raw_fields = set(raw)
        if (
            not _NATIVE_ROLLOVER_FIELDS.issubset(raw_fields)
            or raw_fields.difference(_NATIVE_ROLLOVER_FIELDS)
            - _NATIVE_ROLLOVER_OPTIONAL_FIELDS
        ):
            raise _error("invalid", "native invocation rollover fields are malformed")
        if type(raw["rollover_schema"]) is not int or raw["rollover_schema"] != 1:
            raise _error("invalid", "native invocation rollover schema is unsupported")
        rollover_id = _id(raw["rollover_id"], "native rollover ID") or ""
        if expected_rollover_id is not None and rollover_id != expected_rollover_id:
            raise _error("invalid", "native rollover key is inconsistent")
        operation_id = _id(raw["operation_id"], "native rollover operation ID") or ""
        owner_generation = _native_positive_generation(
            raw["owner_generation"], "native rollover owner generation"
        )
        if expected_generation is not None and owner_generation != expected_generation:
            raise _error("stale-generation", "native rollover owner generation changed")
        lineage_id = _id(raw["lineage_id"], "native rollover lineage ID") or ""
        lineage_generation = _native_positive_generation(
            raw["lineage_generation"], "native rollover lineage generation"
        )
        daemon_id = _id(raw["daemon_id"], "native rollover daemon ID") or ""
        daemon_incarnation = _id(
            raw["daemon_incarnation"], "native rollover daemon incarnation"
        ) or ""
        coordinator = cls._native_coordinator_identity(
            raw["coordinator"], "native rollover coordinator"
        )
        runner_incarnation = _id(
            raw["runner_incarnation"], "native rollover runner incarnation"
        ) or ""
        prior_invocation_id = _id(
            raw["prior_invocation_id"], "native rollover prior invocation ID"
        ) or ""
        next_invocation_id = _id(
            raw["next_invocation_id"], "native rollover next invocation ID"
        ) or ""
        prior_mailbox_id = _id(
            raw["prior_mailbox_id"], "native rollover prior mailbox ID"
        ) or ""
        next_mailbox_id = _id(
            raw["next_mailbox_id"], "native rollover next mailbox ID"
        ) or ""
        if prior_invocation_id != prior_mailbox_id or next_invocation_id != next_mailbox_id:
            raise _error("ownership-conflict", "native rollover invocation/mailbox binding changed")
        if prior_invocation_id == next_invocation_id:
            raise _error("invalid", "native rollover reuses invocation identity")
        reservation_version = raw["reservation_version"]
        if type(reservation_version) is not int or reservation_version != 1:
            raise _error("invalid", "native rollover reservation version is unsupported")
        reservation_id = _id(raw["reservation_id"], "native rollover reservation ID") or ""
        prior_watermark = _native_positive_generation(
            raw["prior_watermark"], "native rollover prior watermark"
        )
        next_watermark = _native_positive_generation(
            raw["next_watermark"], "native rollover next watermark"
        )
        state = raw["state"]
        if state not in _NATIVE_ROLLOVER_STATES:
            raise _error("invalid", "native rollover state is unsupported")
        request_fields = set(_NATIVE_PREPARE_REQUEST_FIELDS)
        preparation_intent = _native_exact_fields(
            raw["preparation_intent"],
            tuple(sorted(request_fields | {"request", "state"})),
            "native rollover preparation intent",
        )
        request = cls._validate_native_prepare_request(
            preparation_intent["request"], "native rollover preparation request"
        )
        if preparation_intent["state"] != "pending":
            raise _error("invalid", "native rollover preparation state is invalid")
        for key in request_fields:
            if preparation_intent[key] != request[key]:
                raise _error("ownership-conflict", "native rollover preparation binding changed")
        binding_identity = {
            "operation_id": operation_id,
            "owner_generation": owner_generation,
            "daemon_id": daemon_id,
            "participant_id": coordinator["participant_id"],
            "session_id": coordinator["session_uuid"],
            "runner_incarnation": runner_incarnation,
            "lineage_id": lineage_id,
            "lineage_generation": lineage_generation,
            "prior_invocation_id": prior_invocation_id,
            "next_invocation_id": next_invocation_id,
            "prior_mailbox_id": prior_mailbox_id,
            "next_mailbox_id": next_mailbox_id,
            "prior_watermark": prior_watermark,
            "reservation_version": reservation_version,
            "reservation_id": reservation_id,
        }
        for key, expected in binding_identity.items():
            if request[key] != expected:
                raise _error("ownership-conflict", "native rollover request %s changed" % key)
        if daemon_incarnation != daemon_id:
            raise _error("ownership-conflict", "native rollover daemon incarnation changed")
        uncertainty = raw["uncertainty"]
        if uncertainty is not None:
            uncertainty = _safe_json_projection(
                _mapping(uncertainty, "native rollover uncertainty"),
                "native rollover uncertainty",
            )
            if set(uncertainty) - {"stage", "code", "reason", "reservation_outcome"}:
                raise _error("invalid", "native rollover uncertainty fields are malformed")
            if uncertainty.get("stage") not in {"preparation", "send"}:
                raise _error("invalid", "native rollover uncertainty stage is invalid")
            if not isinstance(uncertainty.get("reason"), str) or not uncertainty["reason"]:
                raise _error("invalid", "native rollover uncertainty reason is invalid")
            if uncertainty["stage"] == "preparation":
                outcome = uncertainty.get("reservation_outcome")
                if outcome not in {"not-reserved", "unknown"}:
                    raise _error("invalid", "native rollover preparation outcome is invalid")
            elif uncertainty.get("reservation_outcome") is not None:
                raise _error("invalid", "native rollover send uncertainty has preparation outcome")
        preparation_state = state in {"preparation-pending", "runtime-reserved"}
        uncertain_preparation = (
            state == "uncertain"
            and isinstance(uncertainty, Mapping)
            and uncertainty.get("stage") == "preparation"
        )
        committed_state = state in {"bound", "send-pending", "delivered", "reconciled"}
        uncertain_send = (
            state == "uncertain"
            and isinstance(uncertainty, Mapping)
            and uncertainty.get("stage") == "send"
        )
        if not (preparation_state or uncertain_preparation or committed_state or uncertain_send):
            raise _error("invalid", "native rollover state and uncertainty disagree")
        if isinstance(uncertainty, Mapping):
            if uncertainty.get("stage") == "preparation" and not (
                    preparation_state or uncertain_preparation
            ):
                raise _error("invalid", "native rollover preparation uncertainty is out of stage")
            if uncertainty.get("stage") == "send" and not (
                    committed_state or uncertain_send
            ):
                raise _error("invalid", "native rollover send uncertainty is out of stage")
        if preparation_state or uncertain_preparation:
            if next_watermark != prior_watermark:
                raise _error("stale-generation", "native rollover preparation advanced its watermark")
            for key in ("history_id", "next_context", "startup_binding", "reservation_binding", "dispatch_intent"):
                if raw[key] is not None:
                    raise _error("invalid", "native rollover preparation has premature %s" % key)
        else:
            if next_watermark <= prior_watermark:
                raise _error("stale-generation", "native rollover watermark did not advance")
            for key in ("history_id", "next_context", "startup_binding", "reservation_binding", "dispatch_intent"):
                if raw[key] is None:
                    raise _error("invalid", "native rollover committed record lacks %s" % key)
        history_id = raw["history_id"]
        if history_id is not None:
            history_id = _id(history_id, "native rollover history ID") or ""
            if history_ids is not None and history_id not in history_ids:
                raise _error("ownership-conflict", "native rollover history is unknown")
        next_context = raw["next_context"]
        if next_context is not None:
            next_context = cls._validate_native_context(next_context)
            if next_context["fenced"] is not False:
                raise _error("ownership-conflict", "native rollover next context remains fenced")
            if next_context["invocation_id"] != next_invocation_id:
                raise _error("ownership-conflict", "native rollover next context changed")
            if next_context["runner_incarnation"] != runner_incarnation:
                raise _error("ownership-conflict", "native rollover next runner changed")
            if next_context["invocation_watermark"] != next_watermark:
                raise _error("stale-generation", "native rollover next context watermark changed")
            lineage = next_context["lineage"]
            if (
                lineage["owner_generation"] != owner_generation
                or lineage["lineage_id"] != lineage_id
                or lineage["lineage_generation"] != lineage_generation
                or lineage["session_uuid"] != coordinator["session_uuid"]
            ):
                raise _error("ownership-conflict", "native rollover next context lineage changed")
            if _digest(next_context["definitions"]) != request["definitions_digest"]:
                raise _error("permission-mismatch", "native rollover definitions changed")
            if _digest(cls._native_prepare_permissions(next_context["definitions"])) != request["permissions_digest"]:
                raise _error("permission-mismatch", "native rollover permissions changed")
            if _digest(lineage["workspace_claim"]) != request["claim_digest"]:
                raise _error("ownership-conflict", "native rollover claim changed")
        startup_binding = raw["startup_binding"]
        if startup_binding is not None:
            startup_binding = _native_validate(
                startup_binding, record_kind="coordinator-startup",
                label="native rollover startup binding",
            )
            expected_startup = {
                "schema_version", "architecture", "record_kind", "participant_id",
                "session_id", "runner_incarnation", "lineage_id", "lineage_generation",
                "lineage", "definitions", "invocation_id", "invocation_bound",
            }
            if set(startup_binding) != expected_startup:
                raise _error("invalid", "native rollover startup binding is malformed")
            if (
                startup_binding["participant_id"] != coordinator["participant_id"]
                or startup_binding["session_id"] != coordinator["session_uuid"]
                or startup_binding["runner_incarnation"] != runner_incarnation
                or startup_binding["lineage_id"] != lineage_id
                or startup_binding["lineage_generation"] != lineage_generation
                or startup_binding["invocation_id"] != next_invocation_id
                or startup_binding["invocation_bound"] is not True
            ):
                raise _error("ownership-conflict", "native rollover startup binding changed")
            startup_lineage = LineageRecord.from_dict(startup_binding["lineage"])
            if startup_lineage.to_dict() != next_context["lineage"]:
                raise _error("ownership-conflict", "native rollover startup lineage changed")
            startup_definitions = cls._validate_native_context({
                **native_record_marker("admission-context"),
                "lineage": startup_lineage.to_dict(),
                "runner_incarnation": runner_incarnation,
                "invocation_id": next_invocation_id,
                "invocation_watermark": next_watermark,
                "prompt_id": None,
                "definitions": startup_binding["definitions"],
                "fenced": False,
            })["definitions"]
            if startup_definitions != next_context["definitions"]:
                raise _error("permission-mismatch", "native rollover startup definitions changed")
        reservation_binding = raw["reservation_binding"]
        if reservation_binding is not None:
            reservation_binding = cls._validate_native_prepare_response(
                request, reservation_binding
            )
            if reservation_binding.get("state") != "reserved":
                raise _error("invalid", "native rollover reservation binding is not reserved")
            if reservation_binding["next_watermark"] != next_watermark:
                raise _error("stale-generation", "native rollover reservation watermark changed")
        no_send_receipt = None
        no_send_consumption = None
        has_no_send_receipt = "native_reservation_no_send" in raw
        has_no_send_consumption = "native_reservation_no_send_consumption" in raw
        if has_no_send_consumption and not has_no_send_receipt:
            raise _error(
                "invalid",
                "native reservation consumption has no no-send receipt",
            )
        if has_no_send_receipt:
            raw_receipt = raw["native_reservation_no_send"]
            if raw_receipt is None:
                # An explicit null receipt is the legacy-compatible
                # representation of "not observed".  It cannot be paired
                # with even an explicit null consumption record: partial
                # pairs are malformed rather than silently normalized.
                if has_no_send_consumption:
                    raise _error(
                        "invalid",
                        "native reservation consumption is not paired with a receipt",
                    )
                no_send_receipt = None
            else:
                no_send_receipt = cls._validate_native_no_send_receipt(
                    request, raw_receipt
                )
                if reservation_binding is not None and (
                    no_send_receipt["reservation_binding"] != reservation_binding
                ):
                    raise _error(
                        "ownership-conflict",
                        "native reservation no-send binding disagrees with rollover",
                    )
                if not has_no_send_consumption or raw["native_reservation_no_send_consumption"] is None:
                    raise _error(
                        "invalid",
                        "native reservation no-send receipt is not consumed",
                    )
                no_send_consumption = cls._validate_native_no_send_consumption(
                    raw["native_reservation_no_send_consumption"],
                    no_send_receipt,
                    next_mailbox_id,
                )
                if (
                    reservation_binding is None
                    or history_id is None
                    or next_context is None
                    or startup_binding is None
                    or raw["dispatch_intent"] is None
                    or not (
                        state in {"bound", "send-pending", "delivered", "reconciled"}
                        or (
                            state == "uncertain"
                            and isinstance(uncertainty, Mapping)
                            and uncertainty.get("stage") == "send"
                        )
                    )
                ):
                    raise _error(
                        "invalid",
                        "native reservation no-send pair is not bound to committed B",
                    )
        dispatch_intent = raw["dispatch_intent"]
        if dispatch_intent is not None:
            dispatch_intent = _native_exact_fields(
                dispatch_intent, ("message_id", "operation_id", "attempt"),
                "native rollover dispatch intent",
            )
            if dispatch_intent["message_id"] != next_mailbox_id or dispatch_intent["operation_id"] != operation_id:
                raise _error("ownership-conflict", "native rollover dispatch binding changed")
            if type(dispatch_intent["attempt"]) is not int or dispatch_intent["attempt"] < 1:
                raise _error("invalid", "native rollover dispatch attempt is invalid")
        normalized = {
            **native_record_marker("native-invocation-rollover"),
            "rollover_schema": 1,
            "rollover_id": rollover_id,
            "integrity_digest": raw["integrity_digest"],
            "operation_id": operation_id,
            "owner_generation": owner_generation,
            "lineage_id": lineage_id,
            "lineage_generation": lineage_generation,
            "daemon_id": daemon_id,
            "daemon_incarnation": daemon_incarnation,
            "coordinator": coordinator,
            "runner_incarnation": runner_incarnation,
            "prior_invocation_id": prior_invocation_id,
            "next_invocation_id": next_invocation_id,
            "prior_mailbox_id": prior_mailbox_id,
            "next_mailbox_id": next_mailbox_id,
            "preparation_intent": preparation_intent,
            "history_id": history_id,
            "next_context": _json_value(next_context),
            "startup_binding": _json_value(raw["startup_binding"]),
            "reservation_binding": _json_value(raw["reservation_binding"]),
            "dispatch_intent": _json_value(raw["dispatch_intent"]),
            "reservation_version": reservation_version,
            "reservation_id": reservation_id,
            "prior_watermark": prior_watermark,
            "next_watermark": next_watermark,
            "state": state,
            "uncertainty": _json_value(uncertainty),
        }
        if has_no_send_receipt:
            normalized["native_reservation_no_send"] = _json_value(no_send_receipt)
        if has_no_send_consumption:
            normalized["native_reservation_no_send_consumption"] = _json_value(
                no_send_consumption
            )
        if (
            not isinstance(normalized["integrity_digest"], str)
            or not re.fullmatch(r"[0-9a-f]{64}", normalized["integrity_digest"])
        ):
            raise _error("invalid", "native invocation rollover integrity digest is invalid")
        if normalized["integrity_digest"] != cls._native_record_integrity(
                normalized, "integrity_digest"
        ):
            raise _error("invalid", "native invocation rollover integrity digest changed")
        if len(_canonical_json(normalized).encode("utf-8")) > _NATIVE_ROLLOVER_RECORD_BYTES:
            raise _error("invalid", "native invocation rollover entry exceeds capacity")
        return normalized

    @classmethod
    def _validate_native_invocation_cross_links(
            cls, histories: Mapping[str, Mapping[str, Any]],
            rollovers: Mapping[str, Mapping[str, Any]],
            *, current_context: Optional[Mapping[str, Any]],
    ) -> None:
        """Validate the semantic join between immutable A and mutable rollover.

        Each record authenticates its own bytes, but that is not sufficient:
        two independently recomputed records could otherwise present different
        terminal observations for the same invocation.  The reservation proof
        and the archived proof must be one exact object, and the B context must
        be the context that is currently live or subsequently archived.
        """

        def _context_projection(value: Mapping[str, Any]) -> Dict[str, Any]:
            projected = _json_value(value)
            if not isinstance(projected, dict):
                raise _error("invalid", "native rollover context is malformed")
            projected["fenced"] = False
            return projected

        for rollover in rollovers.values():
            history_id = rollover.get("history_id")
            if history_id is None:
                continue
            history = histories.get(history_id)
            if not isinstance(history, Mapping):
                raise _error("ownership-conflict", "native rollover history is unknown")
            request = rollover.get("preparation_intent", {}).get("request")
            if not isinstance(request, Mapping):
                raise _error("invalid", "native rollover preparation request is missing")
            context = history.get("context")
            if not isinstance(context, Mapping):
                raise _error("invalid", "native rollover source context is missing")
            source_lineage = context.get("lineage")
            if not isinstance(source_lineage, Mapping):
                raise _error("invalid", "native rollover source lineage is missing")
            if context.get("invocation_id") != history.get("invocation_id"):
                raise _error("ownership-conflict", "native rollover source invocation changed")
            if context.get("invocation_watermark") != history.get("source_watermark"):
                raise _error("stale-generation", "native rollover source watermark changed")
            if request.get("prior_watermark") != history.get("source_watermark"):
                raise _error("stale-generation", "native rollover request source watermark changed")
            if _digest(context.get("definitions")) != request.get("definitions_digest"):
                raise _error("permission-mismatch", "native rollover source definitions changed")
            if _digest(cls._native_prepare_permissions(context.get("definitions", {}))) != request.get(
                    "permissions_digest"
            ):
                raise _error("permission-mismatch", "native rollover source permissions changed")
            if _digest(source_lineage.get("workspace_claim")) != request.get("claim_digest"):
                raise _error("ownership-conflict", "native rollover source claim changed")

            reservation = rollover.get("reservation_binding")
            if not isinstance(reservation, Mapping):
                raise _error("invalid", "native rollover reservation binding is missing")
            history_proof = {
                "parent_result": _json_value(history["terminal_result"]),
                "roster": _json_value(history["joined_roster"]),
                "roster_digest": _digest(history["joined_roster"]),
                "observation_watermark": history["independent_drain"][
                    "observation_watermark"
                ],
                "uncertainty": _json_value(history["independent_drain"]["uncertainty"]),
                "overflow": history["independent_drain"]["overflow"],
            }
            if reservation.get("terminal_proof") != history_proof:
                raise _error("ownership-conflict", "native rollover terminal proof disagrees with history")
            if reservation.get("terminal_proof_digest") != history.get("terminal_proof_digest"):
                raise _error("ownership-conflict", "native rollover terminal proof digest disagrees with history")
            if reservation.get("terminal_watermark") != history.get("terminal_watermark"):
                raise _error("stale-generation", "native rollover terminal watermark disagrees with history")
            if reservation.get("next_watermark") != rollover.get("next_watermark"):
                raise _error("stale-generation", "native rollover next watermark changed")

            next_context = rollover.get("next_context")
            if not isinstance(next_context, Mapping):
                raise _error("invalid", "native rollover next context is missing")
            next_matches = []
            if (
                    isinstance(current_context, Mapping)
                    and current_context.get("invocation_id") == rollover.get("next_invocation_id")
            ):
                next_matches.append(current_context)
            for candidate in histories.values():
                if candidate.get("invocation_id") == rollover.get("next_invocation_id"):
                    candidate_context = candidate.get("context")
                    if isinstance(candidate_context, Mapping):
                        next_matches.append(candidate_context)
            if not next_matches:
                raise _error("ownership-conflict", "native rollover next context has no durable successor")
            expected_next = _canonical_json(_context_projection(next_context))
            if any(_canonical_json(_context_projection(candidate)) != expected_next
                   for candidate in next_matches):
                raise _error("ownership-conflict", "native rollover next context disagrees with successor")

    def _load_native_invocation_history(self, raw: Mapping[str, Any]) -> None:
        has_history = "native_invocation_history" in raw
        has_rollovers = "native_invocation_rollovers" in raw
        if not has_history and not has_rollovers:
            return
        history_values = raw.get("native_invocation_history") if has_history else {}
        rollover_values = raw.get("native_invocation_rollovers") if has_rollovers else {}
        if history_values is None or rollover_values is None:
            raise _error("invalid", "native invocation history collections are malformed")
        if not isinstance(history_values, Mapping) or not isinstance(rollover_values, Mapping):
            raise _error("invalid", "native invocation history collections are malformed")
        if len(history_values) > _NATIVE_INVOCATION_HISTORY_LIMIT:
            raise _error("invalid", "native invocation history exceeds capacity")
        if len(rollover_values) > _NATIVE_ROLLOVER_LIMIT:
            raise _error("invalid", "native invocation rollover exceeds capacity")
        histories: Dict[str, Dict[str, Any]] = {}
        seen_invocations: set[str] = set()
        seen_mailboxes: set[str] = set()
        for history_id, value in history_values.items():
            history_id = _id(history_id, "native history key") or ""
            normalized = self._validate_native_invocation_history_entry(
                value, expected_history_id=history_id
            )
            if normalized["invocation_id"] in seen_invocations or normalized["mailbox_id"] in seen_mailboxes:
                raise _error("invalid", "native invocation history identity is duplicated")
            seen_invocations.add(normalized["invocation_id"])
            seen_mailboxes.add(normalized["mailbox_id"])
            histories[history_id] = normalized
        rollovers: Dict[str, Dict[str, Any]] = {}
        seen_reservations: set[str] = set()
        for rollover_id, value in rollover_values.items():
            rollover_id = _id(rollover_id, "native rollover key") or ""
            normalized = self._validate_native_invocation_rollover_entry(
                value,
                expected_rollover_id=rollover_id,
                expected_generation=self._generation,
                history_ids=set(histories),
            )
            if normalized["reservation_id"] in seen_reservations:
                raise _error("invalid", "native reservation identity is duplicated")
            seen_reservations.add(normalized["reservation_id"])
            rollovers[rollover_id] = normalized
        for rollover in rollovers.values():
            history_id = rollover.get("history_id")
            if history_id is None:
                continue
            history = histories.get(history_id)
            if history is None:
                raise _error("ownership-conflict", "native rollover history is unknown")
            pairs = (
                ("operation_id", "operation_id"),
                ("owner_generation", "owner_generation"),
                ("lineage_id", "lineage_id"),
                ("lineage_generation", "lineage_generation"),
                ("daemon_id", "daemon_id"),
                ("runner_incarnation", "runner_incarnation"),
                ("prior_invocation_id", "invocation_id"),
                ("prior_mailbox_id", "mailbox_id"),
            )
            if any(rollover[left] != history[right] for left, right in pairs):
                raise _error("ownership-conflict", "native rollover and history identity changed")
            if rollover["coordinator"] != history["coordinator"]:
                raise _error("ownership-conflict", "native rollover coordinator history changed")
            if rollover["prior_watermark"] != history["source_watermark"]:
                raise _error("stale-generation", "native rollover source watermark changed")
            if rollover["reservation_id"] != history["runtime_correlation"]["reservation_id"]:
                raise _error("ownership-conflict", "native rollover reservation correlation changed")
        self._validate_native_invocation_cross_links(
            histories,
            rollovers,
            current_context=self._native_context,
        )
        candidate = {
            "native_invocation_history": histories,
            "native_invocation_rollovers": rollovers,
        }
        if len(_canonical_json(candidate).encode("utf-8")) > _NATIVE_INVOCATION_LEDGER_BYTES:
            raise _error("invalid", "native invocation ledger exceeds capacity")
        self._native_invocation_history = histories
        self._native_invocation_rollovers = rollovers

    def _load_native_source_archives(self, raw: Mapping[str, Any]) -> None:
        if "native_source_archives" not in raw:
            return
        archives = raw["native_source_archives"]
        if (not isinstance(archives, Mapping) or
                len(archives) > _NATIVE_SOURCE_ARCHIVE_LIMIT):
            raise _error("invalid", "native source archive collection is malformed")
        for archive_id, value in archives.items():
            archive_id = _id(archive_id, "native source archive ID") or ""
            archive_bytes_digest = _digest(value)
            cache_key = (archive_id, archive_bytes_digest)
            cached = self._native_source_archive_validation_cache.get(cache_key)
            if cached is None:
                cached = self._validate_native_source_archive_entry(
                    value, expected_archive_id=archive_id
                )
                if len(self._native_source_archive_validation_cache) >= _NATIVE_SOURCE_ARCHIVE_LIMIT:
                    self._native_source_archive_validation_cache.pop(
                        next(iter(self._native_source_archive_validation_cache))
                    )
                self._native_source_archive_validation_cache[cache_key] = (
                    _json_value(cached)
                )
            self._native_source_archives[archive_id] = _json_value(cached)
        # Mapping-backed test stores do not necessarily enforce the common
        # record-size boundary, so validate the complete durable record while
        # it is still only being loaded.
        _digest(raw)

    @_transactional
    def archive_native_source(
            self, archive_id: str, operation_id: str, generation: Any,
    ) -> Dict[str, Any]:
        """Preserve a bounded, independently reloadable native source snapshot."""

        archive_id = _id(archive_id, "native source archive ID") or ""
        operation_id = _id(
            operation_id, "native source archive operation ID"
        ) or ""
        generation = _native_positive_generation(
            generation, "native source archive generation"
        )
        context = self._native_context
        operation = self._operations.get(operation_id)
        if context is None:
            raise _error("unsupported", "native source archive context is not registered")
        if context.get("fenced") is not True:
            raise _error("busy", "native source archive requires a durable native fence")
        self._check_coordinator_interrupt_authority(context)
        source_identity = self._native_source_identity(generation, context)
        self._check_generation(generation)
        if (operation is None or self._active_operation_id != operation_id or
                operation.generation != generation or
                operation.phase not in {"paused", "indeterminate"}):
            raise _error(
                "stale-generation",
                "native source archive operation is not active and paused or indeterminate",
            )

        snapshot = self._record()
        snapshot.pop("native_source_archives", None)
        archive = {
            **native_record_marker("native-source-archive"),
            "archive_id": archive_id,
            "operation_id": operation_id,
            "source_identity": source_identity,
            "snapshot_digest": _digest(snapshot),
            "snapshot": _json_value(snapshot),
        }
        archive = self._validate_native_source_archive_entry(
            archive, expected_archive_id=archive_id
        )
        existing = self._native_source_archives.get(archive_id)
        if existing is not None:
            if _canonical_json(existing, "native source archive") == _canonical_json(
                    archive, "native source archive"):
                return _json_value(existing)
            raise _error(
                "invalid",
                "native source archive ID was reused with different source content",
            )
        if len(self._native_source_archives) >= _NATIVE_SOURCE_ARCHIVE_LIMIT:
            raise _error("busy", "native source archive capacity requires reconciliation")

        candidate_archives = dict(self._native_source_archives)
        candidate_archives[archive_id] = archive
        candidate_record = self._record()
        candidate_record["native_source_archives"] = _json_value(candidate_archives)
        # _digest enforces the existing one-MiB canonical record bound even
        # when the injected store is a plain in-memory MutableMapping.
        _digest(candidate_record)
        self._native_source_archives[archive_id] = archive
        cache_key = (archive_id, _digest(archive))
        if cache_key not in self._native_source_archive_validation_cache:
            if len(self._native_source_archive_validation_cache) >= _NATIVE_SOURCE_ARCHIVE_LIMIT:
                self._native_source_archive_validation_cache.pop(
                    next(iter(self._native_source_archive_validation_cache))
                )
            self._native_source_archive_validation_cache[cache_key] = _json_value(archive)
        self._persist({
            "event": "native-source-archived",
            "archive_id": archive_id,
            "operation_id": operation_id,
        })
        return _json_value(archive)

    @_transactional
    def native_source_archive(self, archive_id: str) -> Dict[str, Any]:
        """Return one complete archive as a defensive read-only copy."""

        archive_id = _id(archive_id, "native source archive ID") or ""
        archive = self._native_source_archives.get(archive_id)
        if archive is None:
            raise _error("unknown", "native source archive %s is unknown" % archive_id)
        return _json_value(archive)

    # ---- held native ownership adoption --------------------------------

    @staticmethod
    def _native_adoption_digest(value: Any, label: str) -> str:
        if (not isinstance(value, str) or
                not re.fullmatch(r"[0-9a-f]{64}", value)):
            raise _error("invalid", "%s must be a sha256 digest" % label)
        return value

    @classmethod
    def _validate_native_adoption_claim(
            cls, value: Any, label: str
    ) -> Dict[str, Any]:
        """Validate one complete workspace claim without adopting it."""

        raw = _native_validate(
            value, record_kind="workspace-claim",
            label=label,
        )
        if set(raw) != _NATIVE_WORKSPACE_CLAIM_FIELDS:
            raise _error("invalid", "%s fields are malformed" % label)
        if raw.get("claim_kind") != "workspace" or raw.get("state") != "active":
            raise _error("invalid", "%s is not an active workspace claim" % label)
        for key in (
                "lineage_id", "coordinator_session_uuid", "lane", "lane_key",
                "host", "workspace", "common_dir", "repository",
        ):
            _id(raw.get(key), "%s %s" % (label, key))
        _native_positive_generation(raw.get("owner_generation"), label + " owner_generation")
        _native_positive_generation(
            raw.get("lineage_generation"), label + " lineage_generation"
        )
        if type(raw.get("parent_read_only")) is not bool:
            raise _error("invalid", "%s parent_read_only is invalid" % label)
        claimed_at = raw.get("claimed_at")
        if (isinstance(claimed_at, bool) or
                not isinstance(claimed_at, (int, float)) or
                not math.isfinite(claimed_at)):
            raise _error("invalid", "%s claimed_at is invalid" % label)
        _digest(raw)
        return _json_value(raw)

    @classmethod
    def _validate_native_adoption_claim_pair(
            cls, source_claim: Any, target_claim: Any, *,
            expected_generation: Optional[int] = None,
    ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        source = cls._validate_native_adoption_claim(
            source_claim, "native adoption source claim"
        )
        target = cls._validate_native_adoption_claim(
            target_claim, "native adoption target claim"
        )
        identity_fields = {
            "lineage_id", "coordinator_session_uuid", "lineage_generation",
        }
        source_immutable = {
            key: value for key, value in source.items()
            if key not in identity_fields
        }
        target_immutable = {
            key: value for key, value in target.items()
            if key not in identity_fields
        }
        if _canonical_json(source_immutable) != _canonical_json(target_immutable):
            raise _error(
                "ownership-conflict",
                "native adoption source and target claims change immutable fields",
            )
        if source["lineage_id"] == target["lineage_id"]:
            raise _error("ownership-conflict", "native adoption target lineage is not new")
        if source["coordinator_session_uuid"] == target["coordinator_session_uuid"]:
            raise _error(
                "ownership-conflict",
                "native adoption target coordinator is not new",
            )
        if target["lineage_generation"] != source["lineage_generation"] + 1:
            raise _error(
                "stale-generation",
                "native adoption target lineage generation is not next",
            )
        if source["owner_generation"] != target["owner_generation"]:
            raise _error(
                "stale-generation",
                "native adoption source and target owner generations differ",
            )
        if (expected_generation is not None and
                source["owner_generation"] != expected_generation):
            raise _error(
                "stale-generation",
                "native adoption claim owner generation is stale",
            )
        return source, target

    @staticmethod
    def _native_adoption_intent_digest(value: Mapping[str, Any]) -> str:
        immutable = dict(value)
        immutable.pop("intent_digest", None)
        immutable.pop("phase", None)
        immutable.pop("controller_commit_digest", None)
        return _digest(immutable)

    @classmethod
    def _validate_native_adoption_reference(
            cls, value: Any, *, expected_operation_id: Optional[str] = None
    ) -> Dict[str, Any]:
        raw = _native_exact_fields(
            value,
            tuple(sorted(_NATIVE_ADOPTION_REFERENCE_FIELDS)),
            "native adoption operation reference",
        )
        _id(raw["adoption_id"], "native adoption reference adoption_id")
        _id(raw["archive_id"], "native adoption reference archive_id")
        _id(raw["intent_digest"], "native adoption reference intent_digest")
        _id(raw["target_claim_digest"], "native adoption reference target_claim_digest")
        for key in ("intent_digest", "archive_digest", "target_claim_digest"):
            cls._native_adoption_digest(
                raw[key], "native adoption reference " + key
            )
        phase = raw["phase"]
        if phase not in {"prepared", "controller-committed"}:
            raise _error("invalid", "native adoption controller phase is invalid")
        if expected_operation_id is not None:
            _id(expected_operation_id, "native adoption operation ID")
        return _json_value(raw)

    @classmethod
    def _validate_native_adoption_intent(
            cls, value: Any, *, expected_adoption_id: Optional[str] = None,
            expected_operation_id: Optional[str] = None,
    ) -> Dict[str, Any]:
        raw = _native_validate(
            value, record_kind="native-adoption-intent",
            label="native adoption intent",
        )
        if set(raw) != _NATIVE_ADOPTION_INTENT_FIELDS:
            raise _error("invalid", "native adoption intent fields are malformed")
        adoption_id = _id(raw["adoption_id"], "native adoption adoption_id") or ""
        if expected_adoption_id is not None and adoption_id != expected_adoption_id:
            raise _error("ownership-conflict", "native adoption ID changed")
        operation_id = _id(raw["operation_id"], "native adoption operation_id") or ""
        if expected_operation_id is not None and operation_id != expected_operation_id:
            raise _error("stale-generation", "native adoption operation changed")
        _id(raw["archive_id"], "native adoption archive_id")
        _native_positive_generation(raw["owner_generation"], "native adoption owner_generation")
        _id(raw["expected_daemon_id"], "native adoption expected_daemon_id")
        source_identity = _native_exact_fields(
            raw["source_identity"],
            tuple(sorted(_NATIVE_SOURCE_IDENTITY_FIELDS)),
            "native adoption source_identity",
        )
        _native_positive_generation(
            source_identity["owner_generation"],
            "native adoption source identity owner_generation",
        )
        _native_positive_generation(
            source_identity["lineage_generation"],
            "native adoption source identity lineage_generation",
        )
        for key in (
                "lineage_id", "session_uuid", "runner_incarnation", "invocation_id"
        ):
            _id(source_identity[key], "native adoption source identity " + key)
        if source_identity["owner_generation"] != raw["owner_generation"]:
            raise _error("stale-generation", "native adoption source owner changed")
        source_claim, target_claim = cls._validate_native_adoption_claim_pair(
            raw["source_claim"], raw["target_claim"],
            expected_generation=raw["owner_generation"],
        )
        if (source_claim["lineage_id"] != source_identity["lineage_id"] or
                source_claim["lineage_generation"] != source_identity["lineage_generation"] or
                source_claim["coordinator_session_uuid"] != source_identity["session_uuid"]):
            raise _error("ownership-conflict", "native adoption source claim identity changed")
        for key in (
                "archive_digest", "source_claim_digest", "target_claim_digest",
                "evidence_digest", "runtime_identity_digest", "intent_digest",
        ):
            cls._native_adoption_digest(raw[key], "native adoption " + key)
        if raw["archive_digest"] != raw["archive_digest"].lower():
            raise _error("invalid", "native adoption archive digest is not canonical")
        if raw["source_claim_digest"] != _digest(source_claim):
            raise _error("invalid", "native adoption source claim digest changed")
        if raw["target_claim_digest"] != _digest(target_claim):
            raise _error("invalid", "native adoption target claim digest changed")
        _opaque_payload_reference(
            raw["evidence_reference"], "native adoption evidence_reference"
        )
        if raw["phase"] not in _NATIVE_ADOPTION_PHASES:
            raise _error("invalid", "native adoption phase is invalid")
        commit_digest = raw["controller_commit_digest"]
        if commit_digest is not None:
            cls._native_adoption_digest(
                commit_digest, "native adoption controller_commit_digest"
            )
        if raw["phase"] == "controller-committed":
            if commit_digest is None:
                raise _error(
                    "invalid",
                    "controller-committed native adoption has no controller digest",
                )
        elif commit_digest is not None:
            raise _error(
                "invalid",
                "native adoption controller digest precedes controller commit",
            )
        if raw["intent_digest"] != cls._native_adoption_intent_digest(raw):
            raise _error("invalid", "native adoption intent digest changed")
        raw["source_identity"] = _json_value(source_identity)
        raw["source_claim"] = source_claim
        raw["target_claim"] = target_claim
        return _json_value(raw)

    @classmethod
    def _validate_native_adoption_evidence(
            cls, value: Any, binding: Mapping[str, Any]
    ) -> Tuple[Dict[str, Any], str]:
        raw = _native_exact_fields(
            value,
            tuple(sorted(_NATIVE_ADOPTION_EVIDENCE_FIELDS)),
            "native adoption evidence",
        )
        expected_binding = _native_exact_fields(
            binding,
            tuple(sorted(_NATIVE_ADOPTION_BINDING_FIELDS)),
            "native adoption evidence binding",
        )
        for key in _NATIVE_ADOPTION_BINDING_FIELDS:
            if _canonical_json(raw[key]) != _canonical_json(expected_binding[key]):
                raise _error(
                    "ownership-conflict",
                    "native adoption evidence binding changed %s" % key,
                )
        for key in (
                "runtime_identity_digest",):
            cls._native_adoption_digest(raw[key], "native adoption " + key)
        _opaque_payload_reference(
            raw["evidence_reference"], "native adoption evidence_reference"
        )
        for key in (
                "source_writers_excluded", "source_effects_resolved",
                "native_worker_state_cleared", "control_epoch_request_free",
                "target_startup_hold_supported",
        ):
            if raw[key] is not True or type(raw[key]) is not bool:
                raise _error(
                    "unsupported",
                    "native adoption evidence does not prove %s" % key,
                )
        raw = _json_value(raw)
        return raw, _digest(raw)

    @classmethod
    def _native_adoption_binding(cls, intent: Mapping[str, Any]) -> Dict[str, Any]:
        return {
            key: _json_value(intent[key])
            for key in (
                "adoption_id", "archive_id", "archive_digest", "operation_id",
                "owner_generation", "expected_daemon_id", "source_identity",
                "source_claim_digest", "target_claim_digest",
            )
        }

    @classmethod
    def _native_adoption_intent(
            cls, *, adoption_id: str, archive_id: str, archive_digest: str,
            operation_id: str, owner_generation: int, expected_daemon_id: str,
            source_identity: Mapping[str, Any], source_claim: Mapping[str, Any],
            target_claim: Mapping[str, Any], evidence: Mapping[str, Any],
            evidence_digest: str,
    ) -> Dict[str, Any]:
        intent = {
            **native_record_marker("native-adoption-intent"),
            "adoption_id": adoption_id,
            "archive_id": archive_id,
            "archive_digest": archive_digest,
            "operation_id": operation_id,
            "owner_generation": owner_generation,
            "expected_daemon_id": expected_daemon_id,
            "source_identity": _json_value(source_identity),
            "source_claim": _json_value(source_claim),
            "target_claim": _json_value(target_claim),
            "source_claim_digest": _digest(source_claim),
            "target_claim_digest": _digest(target_claim),
            "evidence_digest": evidence_digest,
            "runtime_identity_digest": evidence["runtime_identity_digest"],
            "evidence_reference": evidence["evidence_reference"],
            "intent_digest": None,
            "phase": "prepared",
            "controller_commit_digest": None,
        }
        intent["intent_digest"] = cls._native_adoption_intent_digest(intent)
        return cls._validate_native_adoption_intent(intent)

    def _native_adoption_state_call(self, method_name: str, *args, **kwargs):
        method = getattr(self.store, method_name, None)
        if not callable(method):
            raise _error(
                "unsupported",
                "managed state store lacks %s" % method_name,
            )
        try:
            return method(*args, **kwargs)
        except ControllerError:
            raise
        except ManagedStateError as exc:
            raise _error(exc.code, exc.message)
        except Exception as exc:
            raise _error(
                "uncertain-effect",
                "%s failed without a trusted outcome: %s" % (method_name, exc),
            )

    def _native_adoption_read_state(
            self, adoption_id: str, *, required: bool = True
    ) -> Optional[Dict[str, Any]]:
        value = self._native_adoption_state_call(
            "read_lineage_adoption", adoption_id
        )
        if value is None:
            if required:
                raise _error(
                    "uncertain-effect",
                    "native adoption intent is missing",
                )
            return None
        return self._validate_native_adoption_intent(
            value, expected_adoption_id=adoption_id
        )

    def _native_adoption_authority(
            self, operation_id: str, generation: Any, archive_id: str
    ) -> Tuple[Operation, Dict[str, Any], Dict[str, Any]]:
        generation = _native_positive_generation(
            generation, "native adoption generation"
        )
        self._check_generation(generation)
        context = self._native_context
        if not isinstance(context, Mapping):
            raise _error("unsupported", "native adoption context is not registered")
        if context.get("fenced") is not True:
            raise _error("busy", "native adoption requires a durable native fence")
        # After the one-row CAS the archived source claim is intentionally
        # gone.  Reusing the interrupt helper here would therefore reject a
        # valid target-held recovery because that helper proves current source
        # claim membership.  Adoption authority is narrower: recheck the
        # current managed owner/daemon/generation and the still-fenced source
        # context identity, while the state assessment below proves either
        # source-held or target-held claims separately.
        daemon_id = self._coordinator_interrupt_daemon_id
        if daemon_id is None:
            raise _error(
                "unsupported",
                "native adoption requires the trusted coordinator daemon identity",
            )
        owner_reader = getattr(self.store, "read_owner", None)
        if not callable(owner_reader):
            raise _error(
                "unsupported",
                "native adoption requires durable owner authority",
            )
        owner = owner_reader()
        lineage = _mapping(context.get("lineage"), "native adoption source lineage")
        if (
                not isinstance(owner, Mapping)
                or owner.get("mode") != "managed"
                or type(owner.get("generation")) is not int
                or owner.get("generation") != generation
                or owner.get("lane") != lineage.get("lane")
                or owner.get("daemon_id") != daemon_id
                or ("lineage_id" in owner and
                    owner.get("lineage_id") != lineage.get("lineage_id"))
                or ("coordinator_session_uuid" in owner and
                    owner.get("coordinator_session_uuid") !=
                    lineage.get("session_uuid"))
        ):
            raise _error(
                "ownership-conflict",
                "native adoption owner daemon or generation changed",
            )
        coordinator = self._participants.get(self._coordinator_id or "")
        if (
                coordinator is None
                or coordinator.role != "coordinator"
                or coordinator.session_id != lineage.get("session_uuid")
                or coordinator.bound_lane != lineage.get("lane")
                or coordinator.read_only != lineage.get("read_only")
                or coordinator.metadata.get("runner_instance_id") !=
                context.get("runner_incarnation")
        ):
            raise _error(
                "ownership-conflict",
                "native adoption coordinator context identity changed",
            )
        if any(
                participant.role != "coordinator"
                for participant in self._participants.values()
        ):
            raise _error(
                "migration-required",
                "independent workers cannot join a native adoption",
            )
        operation = self._operations.get(operation_id)
        if (operation is None or self._active_operation_id != operation_id or
                operation.generation != generation or
                operation.phase not in {"paused", "indeterminate"}):
            raise _error(
                "stale-generation",
                "native adoption operation is not active and paused or indeterminate",
            )
        archive = self._native_source_archives.get(archive_id)
        if archive is None:
            raise _error("unknown", "native source archive %s is unknown" % archive_id)
        archive = self._validate_native_source_archive_entry(
            archive, expected_archive_id=archive_id
        )
        if archive["operation_id"] != operation_id:
            raise _error("stale-generation", "native adoption archive operation changed")
        source_identity = self._native_source_identity(generation, context)
        if source_identity != archive["source_identity"]:
            raise _error(
                "ownership-conflict",
                "native adoption source identity is not the archived identity",
            )
        return operation, archive, context

    def _native_adoption_bound_authority(
            self, intent: Mapping[str, Any]
    ) -> Tuple[Operation, Dict[str, Any], Dict[str, Any]]:
        """Recheck live owner authority and every archived binding."""

        operation, archive, context = self._native_adoption_authority(
            intent["operation_id"], intent["owner_generation"],
            intent["archive_id"],
        )
        if intent["expected_daemon_id"] != self._coordinator_interrupt_daemon_id:
            raise _error(
                "ownership-conflict",
                "native adoption daemon binding changed",
            )
        source_identity = self._native_source_identity(
            intent["owner_generation"], context
        )
        if (source_identity != intent["source_identity"] or
                source_identity != archive["source_identity"] or
                intent["archive_digest"] != archive["snapshot_digest"]):
            raise _error(
                "ownership-conflict",
                "native adoption archive binding changed",
            )
        if operation.operation_id != intent["operation_id"]:
            raise _error("stale-generation", "native adoption operation binding changed")
        if operation.generation != intent["owner_generation"]:
            raise _error("stale-generation", "native adoption generation binding changed")
        return operation, archive, context

    @classmethod
    def _native_adoption_bind_claims_to_archive(
            cls, source_claim: Mapping[str, Any], archive: Mapping[str, Any],
            source_identity: Mapping[str, Any]
    ) -> None:
        snapshot = _mapping(
            archive["snapshot"], "native adoption archive snapshot"
        )
        snapshot_context = _mapping(
            snapshot.get("native_context"),
            "native adoption archived native context",
        )
        snapshot_lineage = _mapping(
            snapshot_context.get("lineage"),
            "native adoption archived source lineage",
        )
        archived_claim = _mapping(
            snapshot_lineage.get("workspace_claim"),
            "native adoption archived workspace claim",
        )
        for key in (
                "workspace", "common_dir", "repository", "lane", "lane_key",
                "host", "parent_read_only",
        ):
            if source_claim.get(key) != archived_claim.get(key):
                raise _error(
                    "ownership-conflict",
                    "native adoption source claim is outside the archived workspace",
                )
        for key in ("owner_generation", "lineage_id", "lineage_generation"):
            if source_claim.get(key) != source_identity[key]:
                raise _error(
                    "ownership-conflict",
                    "native adoption source claim identity is not archived",
                )
        if source_claim.get("coordinator_session_uuid") != source_identity["session_uuid"]:
            raise _error(
                "ownership-conflict",
                "native adoption source claim coordinator is not archived",
            )

    def _native_adoption_assessment(
            self, intent: Mapping[str, Any], *, expected_status: str
    ) -> Dict[str, Any]:
        value = self._native_adoption_state_call(
            "assess_lineage_workspace_adoption",
            intent["source_claim"], intent["target_claim"],
            expected_daemon_id=intent["expected_daemon_id"],
        )
        if not isinstance(value, Mapping):
            raise _error("uncertain-effect", "native adoption claim assessment is malformed")
        expected = {"status", "blockers", "source_matches", "target_matches"}
        if set(value) != expected:
            raise _error("invalid", "native adoption claim assessment is malformed")
        status = value["status"]
        if status not in {"source-held", "target-held", "indeterminate"}:
            raise _error("invalid", "native adoption claim assessment status is invalid")
        blockers = value["blockers"]
        if (not isinstance(blockers, list) or
                any(not isinstance(item, str) or not item for item in blockers) or
                len(set(blockers)) != len(blockers)):
            raise _error("invalid", "native adoption claim assessment blockers are invalid")
        for key in ("source_matches", "target_matches"):
            if (type(value[key]) is not int or value[key] < 0):
                raise _error("invalid", "native adoption claim assessment counts are invalid")
        if status != expected_status or blockers:
            raise _error(
                "uncertain-effect",
                "native adoption claim assessment is %s%s" % (
                    status,
                    (": " + ",".join(blockers)) if blockers else "",
                ),
            )
        return _json_value(value)

    def _native_adoption_evidence(
            self, binding: Mapping[str, Any]
    ) -> Tuple[Dict[str, Any], str]:
        provider = self._native_adoption_evidence_provider
        if not callable(provider):
            raise _error(
                "unsupported",
                "native adoption requires an internal evidence provider",
            )
        binding = _native_exact_fields(
            binding,
            tuple(sorted(_NATIVE_ADOPTION_BINDING_FIELDS)),
            "native adoption evidence binding",
        )
        try:
            response = provider(_json_value(binding))
        except ControllerError:
            raise
        except Exception as exc:
            raise _error(
                "uncertain-effect",
                "native adoption evidence outcome is unknown: %s" % exc,
            )
        return self._validate_native_adoption_evidence(response, binding)

    def _native_adoption_evidence_for_intent(
            self, intent: Mapping[str, Any]
    ) -> Tuple[Dict[str, Any], str]:
        evidence, evidence_digest = self._native_adoption_evidence(
            self._native_adoption_binding(intent)
        )
        if evidence_digest != intent["evidence_digest"]:
            raise _error(
                "uncertain-effect",
                "native adoption evidence changed after preparation",
            )
        if (evidence["runtime_identity_digest"] != intent["runtime_identity_digest"] or
                evidence["evidence_reference"] != intent["evidence_reference"]):
            raise _error(
                "uncertain-effect",
                "native adoption evidence identity changed after preparation",
            )
        return evidence, evidence_digest

    def _native_adoption_operation_binding(
            self, adoption_id: str
    ) -> Tuple[Operation, Dict[str, Any]]:
        intent = self._native_adoption_read_state(adoption_id)
        if intent is None:  # pragma: no cover - required=True raises
            raise _error("uncertain-effect", "native adoption intent is missing")
        operation = self._operations.get(intent["operation_id"])
        if operation is None or self._active_operation_id != operation.operation_id:
            raise _error("stale-generation", "native adoption operation is not active")
        reference = operation.metadata.get("native_adoption")
        if reference is None:
            raise _error(
                "uncertain-effect",
                "native adoption controller reference is missing",
            )
        reference = self._validate_native_adoption_reference(
            reference, expected_operation_id=operation.operation_id
        )
        # Normally the controller reference stays ``prepared`` until state
        # finalization.  One crash window is intentionally durable and
        # recoverable: controller commit may be written while the state
        # intent is still ``claim-transferred``.  It is the only non-final
        # state phase that may carry a committed controller reference.
        if intent["phase"] == "controller-committed":
            allowed_reference_phases = {"controller-committed"}
        elif intent["phase"] == "claim-transferred":
            allowed_reference_phases = {"prepared", "controller-committed"}
        else:
            allowed_reference_phases = {"prepared"}
        if (reference["adoption_id"] != adoption_id or
                reference["intent_digest"] != intent["intent_digest"] or
                reference["archive_id"] != intent["archive_id"] or
                reference["archive_digest"] != intent["archive_digest"] or
                reference["target_claim_digest"] != intent["target_claim_digest"] or
                reference["phase"] not in allowed_reference_phases):
            raise _error(
                "uncertain-effect",
                "native adoption controller reference does not match state intent",
            )
        return operation, intent

    def _native_adoption_commit(
            self, operation: Operation, intent: Mapping[str, Any]
    ) -> Dict[str, Any]:
        reference = self._validate_native_adoption_reference(
            operation.metadata.get("native_adoption"),
            expected_operation_id=operation.operation_id,
        )
        if reference["phase"] == "prepared":
            operation.metadata["native_adoption"] = {
                "adoption_id": intent["adoption_id"],
                "intent_digest": intent["intent_digest"],
                "archive_id": intent["archive_id"],
                "archive_digest": intent["archive_digest"],
                "target_claim_digest": intent["target_claim_digest"],
                "phase": "controller-committed",
            }
            # This is the controller acknowledgement boundary.  The source
            # context, histories, and main operation phase remain unchanged.
            self._persist({
                "event": "native-adoption-controller-committed",
                "adoption_id": intent["adoption_id"],
                "operation_id": operation.operation_id,
            })
        elif reference["phase"] != "controller-committed":
            raise _error("invalid", "native adoption controller phase is invalid")
        controller_digest = _digest(self._record())
        finalized = self._native_adoption_state_call(
            "finalize_lineage_adoption",
            intent["adoption_id"],
            expected_daemon_id=intent["expected_daemon_id"],
            controller_digest=controller_digest,
        )
        finalized = self._validate_native_adoption_intent(
            finalized, expected_adoption_id=intent["adoption_id"],
            expected_operation_id=operation.operation_id,
        )
        if (finalized["phase"] != "controller-committed" or
                finalized["controller_commit_digest"] != controller_digest):
            raise _error(
                "uncertain-effect",
                "native adoption controller finalization is not authoritative",
            )
        return finalized

    @_transactional
    def prepare_native_adoption(
            self, adoption_id: str, archive_id: str, operation_id: str,
            generation: Any, source_claim: Mapping[str, Any],
            target_claim: Mapping[str, Any]
    ) -> Dict[str, Any]:
        """Prepare a held ownership descriptor without changing claims."""

        adoption_id = _id(adoption_id, "native adoption ID") or ""
        archive_id = _id(archive_id, "native adoption archive ID") or ""
        operation_id = _id(operation_id, "native adoption operation ID") or ""
        generation = _native_positive_generation(
            generation, "native adoption generation"
        )
        operation, archive, context = self._native_adoption_authority(
            operation_id, generation, archive_id
        )
        source, target = self._validate_native_adoption_claim_pair(
            source_claim, target_claim, expected_generation=generation
        )
        source_identity = archive["source_identity"]
        self._native_adoption_bind_claims_to_archive(
            source, archive, source_identity
        )
        if context["lineage"]["workspace"] != source["workspace"]:
            raise _error(
                "ownership-conflict",
                "native adoption source claim workspace changed",
            )
        binding = {
            "adoption_id": adoption_id,
            "archive_id": archive_id,
            "archive_digest": archive["snapshot_digest"],
            "operation_id": operation_id,
            "owner_generation": generation,
            "expected_daemon_id": self._coordinator_interrupt_daemon_id,
            "source_identity": source_identity,
            "source_claim_digest": _digest(source),
            "target_claim_digest": _digest(target),
        }
        evidence, evidence_digest = self._native_adoption_evidence(binding)
        intent = self._native_adoption_intent(
            adoption_id=adoption_id,
            archive_id=archive_id,
            archive_digest=archive["snapshot_digest"],
            operation_id=operation_id,
            owner_generation=generation,
            expected_daemon_id=self._coordinator_interrupt_daemon_id or "",
            source_identity=source_identity,
            source_claim=source,
            target_claim=target,
            evidence=evidence,
            evidence_digest=evidence_digest,
        )
        existing_reference = operation.metadata.get("native_adoption")
        existing_state = self._native_adoption_read_state(
            adoption_id, required=False
        )
        reference = {
            "adoption_id": adoption_id,
            "intent_digest": intent["intent_digest"],
            "archive_id": archive_id,
            "archive_digest": archive["snapshot_digest"],
            "target_claim_digest": intent["target_claim_digest"],
            "phase": "prepared",
        }
        if existing_reference is not None:
            existing_reference = self._validate_native_adoption_reference(
                existing_reference, expected_operation_id=operation_id
            )
            if any(
                    existing_reference[key] != reference[key]
                    for key in (
                        "adoption_id", "intent_digest", "archive_id",
                        "archive_digest", "target_claim_digest",
                    )
            ):
                raise _error(
                    "invalid",
                    "native adoption ID was reused with different content",
                )
            if existing_state is None:
                raise _error(
                    "uncertain-effect",
                    "native adoption controller reference has no state intent",
                )
            if (existing_state["intent_digest"] != intent["intent_digest"] or
                    self._native_adoption_intent_digest(existing_state) !=
                    self._native_adoption_intent_digest(intent) or
                    existing_state["intent_digest"] !=
                    existing_reference["intent_digest"]):
                raise _error(
                    "invalid",
                    "native adoption ID was reused with different immutable content",
                )
            if existing_state["phase"] == "controller-committed":
                allowed_reference_phases = {"controller-committed"}
            elif existing_state["phase"] == "claim-transferred":
                allowed_reference_phases = {"prepared", "controller-committed"}
            elif existing_state["phase"] == "prepared":
                allowed_reference_phases = {"prepared"}
            else:
                raise _error(
                    "uncertain-effect",
                    "native adoption retry has an unresolved state phase",
                )
            if existing_reference["phase"] not in allowed_reference_phases:
                raise _error(
                    "uncertain-effect",
                    "native adoption controller reference phase is inconsistent",
                )
            return existing_state
        if existing_state is not None:
            raise _error(
                "uncertain-effect",
                "native adoption state intent has no controller reference",
            )
        # The controller reference is deliberately durable before the state
        # store creates the prepared intent.  A crash between these writes is
        # recovered as an unbound/indeterminate transaction, never guessed.
        operation.metadata["native_adoption"] = reference
        self._persist({
            "event": "native-adoption-prepared",
            "adoption_id": adoption_id,
            "operation_id": operation_id,
        })
        prepared = self._native_adoption_state_call(
            "prepare_lineage_adoption", intent
        )
        prepared = self._validate_native_adoption_intent(
            prepared, expected_adoption_id=adoption_id,
            expected_operation_id=operation_id,
        )
        if prepared != intent:
            raise _error(
                "uncertain-effect",
                "native adoption state changed the prepared intent",
            )
        return prepared

    @_transactional
    def advance_native_adoption(self, adoption_id: str) -> Dict[str, Any]:
        """Transfer one exact claim only after fresh internal evidence."""

        adoption_id = _id(adoption_id, "native adoption ID") or ""
        operation, intent = self._native_adoption_operation_binding(adoption_id)
        if intent["phase"] == "controller-committed":
            operation, _archive, _context = self._native_adoption_bound_authority(intent)
            self._native_adoption_assessment(intent, expected_status="target-held")
            self._native_adoption_evidence_for_intent(intent)
            current_digest = _digest(self._record())
            if intent["controller_commit_digest"] != current_digest:
                raise _error(
                    "uncertain-effect",
                    "native adoption controller acknowledgement digest changed",
                )
            return intent
        if intent["phase"] == "claim-transferred":
            operation, _archive, _context = self._native_adoption_bound_authority(intent)
            self._native_adoption_assessment(intent, expected_status="target-held")
            self._native_adoption_evidence_for_intent(intent)
            return self._native_adoption_commit(operation, intent)
        if intent["phase"] != "prepared":
            raise _error(
                "uncertain-effect",
                "native adoption cannot advance from %s" % intent["phase"],
            )
        operation, _archive, _context = self._native_adoption_bound_authority(intent)
        self._native_adoption_assessment(intent, expected_status="source-held")
        self._native_adoption_evidence_for_intent(intent)
        applied = self._native_adoption_state_call(
            "apply_lineage_adoption",
            adoption_id,
            expected_daemon_id=intent["expected_daemon_id"],
            authoritative=True,
        )
        applied = self._validate_native_adoption_intent(
            applied, expected_adoption_id=adoption_id,
            expected_operation_id=operation.operation_id,
        )
        if applied["phase"] != "claim-transferred":
            raise _error(
                "uncertain-effect",
                "native adoption CAS did not produce a transferred intent",
            )
        self._native_adoption_assessment(applied, expected_status="target-held")
        return self._native_adoption_commit(operation, applied)

    @_transactional
    def recover_native_adoption(self, adoption_id: str) -> Dict[str, Any]:
        """Reconcile only durable adoption facts; never retry the CAS."""

        adoption_id = _id(adoption_id, "native adoption ID") or ""
        operation, intent = self._native_adoption_operation_binding(adoption_id)
        operation, _archive, _context = self._native_adoption_bound_authority(intent)
        if intent["phase"] == "claim-cas-pending":
            # Reprove the internal runtime/effect gate before the state store
            # is allowed to classify a possible-CAS window.  Reconciliation
            # may durably move the intent to transferred or indeterminate;
            # stale/missing evidence must refuse before that bookkeeping.
            self._native_adoption_evidence_for_intent(intent)
            reconciled = self._native_adoption_state_call(
                "reconcile_lineage_adoption",
                adoption_id,
                expected_daemon_id=intent["expected_daemon_id"],
            )
            intent = self._validate_native_adoption_intent(
                reconciled, expected_adoption_id=adoption_id,
                expected_operation_id=operation.operation_id,
            )
            if intent["phase"] != "claim-transferred":
                raise _error(
                    "uncertain-effect",
                    "native adoption recovery is indeterminate",
                )
        elif intent["phase"] == "prepared":
            raise _error(
                "uncertain-effect",
                "native adoption has not reached its claim boundary",
            )
        elif intent["phase"] == "indeterminate":
            raise _error(
                "uncertain-effect",
                "native adoption recovery is indeterminate",
            )
        elif intent["phase"] not in {"claim-transferred", "controller-committed"}:
            raise _error("invalid", "native adoption recovery phase is invalid")
        operation, _archive, _context = self._native_adoption_bound_authority(intent)
        self._native_adoption_assessment(intent, expected_status="target-held")
        self._native_adoption_evidence_for_intent(intent)
        if intent["phase"] == "controller-committed":
            reference = self._validate_native_adoption_reference(
                operation.metadata.get("native_adoption"),
                expected_operation_id=operation.operation_id,
            )
            if reference["phase"] != "controller-committed":
                raise _error(
                    "uncertain-effect",
                    "state adoption committed without a controller acknowledgement",
                )
        return self._native_adoption_commit(operation, intent)

    @_transactional
    def native_adoption(self, adoption_id: str) -> Dict[str, Any]:
        """Return one complete adoption intent as a defensive copy."""

        adoption_id = _id(adoption_id, "native adoption ID") or ""
        _operation, intent = self._native_adoption_operation_binding(adoption_id)
        return _json_value(intent)

    @staticmethod
    def _coordinator_interrupt_record(
            frame: Mapping[str, Any], digest: str, source_key: str,
            created_at: Any,
    ) -> Dict[str, Any]:
        interrupt_id = frame["interrupt"]["interrupt_id"]
        return {
            **native_record_marker("coordinator-interrupt"),
            "interrupt_id": interrupt_id,
            "source_exclusion_key": source_key,
            "digest": digest,
            "frame": _json_value(frame),
            "created_at": created_at,
            # This marker is the durable send-boundary authorization.  It is
            # intentionally written before any runtime bridge can call SDK
            # interrupt, and is never cleared by a later receipt.
            "may_have_been_sent": True,
            "authorization_count": 1,
            "runtime_ack": None,
            "evidence": {},
            "progress_watermark": frame["interrupt"]["roster_seal_watermark"],
        }

    @staticmethod
    def _native_stop_intent_ack(
            stop_id: str, *, authorize_send: bool
    ) -> Dict[str, Any]:
        return {
            "recorded": True,
            "authorize_send": authorize_send,
            "stop_id": stop_id,
        }

    @staticmethod
    def _native_stop_evidence_ack(frame: Mapping[str, Any]) -> Dict[str, Any]:
        evidence = frame["evidence"]
        return {
            "recorded": True,
            "evidence_id": evidence["evidence_id"],
            "stop_id": evidence["stop_id"],
        }

    @staticmethod
    def _native_stop_record(
            frame: Mapping[str, Any], digest: str
    ) -> Dict[str, Any]:
        stop_id = frame["stop"]["stop_id"]
        return {
            **native_record_marker("native-stop"),
            "stop_id": stop_id,
            "digest": digest,
            "frame": _json_value(frame),
            # This is deliberately set in the same durable snapshot as the
            # first authorization.  A process crash after this write is
            # indistinguishable from a sent SDK request and therefore cannot
            # authorize a retry.
            "may_have_been_sent": True,
            "authorization_count": 1,
            "runtime_ack": None,
            "terminal_evidence": None,
            "evidence": {},
        }

    @_transactional
    def persist_native_stop_intent(self, frame: Mapping[str, Any]) -> Dict[str, Any]:
        """Durably authorize one native task stop before the SDK call.

        The controller records the runner-derived task observation and closes
        native admission in the same snapshot.  It never calls the SDK and it
        never clears claims or infers quiescence from a stop acknowledgement.
        """

        context = self._native_context
        if context is None:
            raise _error("unsupported", "native stop context is not registered")
        self._check_native_stop_authority(context)
        value = self._validate_native_stop_intent(frame, context)
        stop_id = value["stop"]["stop_id"]
        digest = _digest(value)
        old = self._native_stops.get(stop_id)
        if old is not None:
            if (old.get("digest") != digest or
                    _json_value(old.get("frame")) != _json_value(value)):
                raise _error("invalid", "native stop ID was reused with different content")
            return self._native_stop_intent_ack(stop_id, authorize_send=False)

        stop = value["stop"]
        if self._native_historical_identity_conflict(
                admission_id=stop["admission_id"],
                tool_use_id=stop["tool_use_id"],
                agent_id=stop["agent_id"],
                task_id=stop["task_id"],
                stop_id=stop_id,
        ):
            raise _error("invalid", "native stop identity was used by a terminal invocation")

        task_key = self._native_stop_task_key(value)
        for existing in self._native_stops.values():
            if self._native_stop_task_key(existing["frame"]) == task_key:
                raise _error(
                    "busy",
                    "native task incarnation already has a durable stop intent",
                )
        if len(self._native_stops) >= 256:
            raise _error("busy", "native stop ledger requires reconciliation")

        # A stop closes native admission for the current context.  This is a
        # fence only: it does not release a claim or certify task/effect
        # exclusion.  The context is intentionally left fenced for reloads,
        # duplicate requests, and terminal evidence that arrives later.
        context["fenced"] = True
        self._native_stops[stop_id] = self._native_stop_record(value, digest)
        self._persist({
            "event": "native-stop-intent-persisted",
            "stop_id": stop_id,
            "admission_id": value["stop"]["admission_id"],
        })
        return self._native_stop_intent_ack(stop_id, authorize_send=True)

    @_transactional
    def persist_native_stop_evidence(self, frame: Mapping[str, Any]) -> Dict[str, Any]:
        """Persist runtime-stop and terminal facts independently and idempotently."""

        context = self._native_context
        if context is None:
            raise _error("unsupported", "native stop context is not registered")
        self._check_native_stop_authority(context)
        outer = _native_exact_fields(
            frame,
            ("type", "participant_id", "session_id", "runner_instance_id", "evidence"),
            "native stop evidence",
        )
        evidence_body = _mapping(outer["evidence"], "native stop evidence body")
        stop_id = _id(
            evidence_body.get("stop_id"), "native stop evidence stop_id"
        ) or ""
        record = self._native_stops.get(stop_id)
        if record is None:
            raise _error("unknown", "native stop intent is unknown")
        intent = record["frame"]
        value = self._validate_native_stop_evidence(frame, context, intent)
        evidence_id = value["evidence"]["evidence_id"]
        digest = _digest(value)
        evidence_records = record["evidence"]
        prior = evidence_records.get(evidence_id)
        if prior is not None:
            if (prior.get("digest") != digest or
                    _json_value(prior.get("frame")) != _json_value(value)):
                raise _error(
                    "invalid",
                    "native stop evidence ID was reused with different content",
                )
            return _json_value(prior["result"])

        kind = value["evidence"]["kind"]
        slot = "runtime_ack" if kind == "runtime-ack" else "terminal_evidence"
        if record[slot] is not None:
            raise _error(
                "invalid",
                "native stop %s evidence is already recorded" % kind,
            )
        result = self._native_stop_evidence_ack(value)
        evidence_records[evidence_id] = {
            "digest": digest,
            "frame": _json_value(value),
            "result": result,
        }
        record[slot] = _json_value(value)
        self._persist({
            "event": "native-stop-evidence-persisted",
            "stop_id": stop_id,
            "evidence_id": evidence_id,
            "kind": kind,
        })
        return _json_value(result)

    @_transactional
    def persist_coordinator_interrupt_intent(
            self, frame: Mapping[str, Any]
    ) -> Dict[str, Any]:
        """Record one coordinator-wide interrupt authorization.

        This persistence seam deliberately stops before the runtime bridge:
        the durable marker is an at-most-once authorization, while receipts,
        child terminals, tool/effect outcomes, request observations, and
        process exclusion arrive as independent evidence facts.
        """
        context = self._native_context
        if context is None:
            raise _error("unsupported", "coordinator interrupt context is not registered")
        self._check_coordinator_interrupt_authority(context)
        value = self._validate_coordinator_interrupt_intent(
            frame, context, live=False
        )
        interrupt_id = value["interrupt"]["interrupt_id"]
        digest = _digest(value)
        old = self._coordinator_interrupts.get(interrupt_id)
        if old is not None:
            if (old.get("digest") != digest or
                    _json_value(old.get("frame")) != _json_value(value)):
                raise _error(
                    "invalid",
                    "coordinator interrupt ID was reused with different content",
                )
            return self._coordinator_interrupt_intent_ack(
                interrupt_id, authorize_send=False
            )

        # New authorization is live-only.  Historical records are accepted by
        # the loader for correlation, but cannot authorize a later runtime send.
        self._coordinator_interrupt_live_operation(value["interrupt"], context)
        value = self._validate_coordinator_interrupt_intent(
            value, context, live=True
        )
        source_key = self._native_interrupt_source_key(
            owner_generation=value["interrupt"]["owner_generation"],
            lineage_id=value["interrupt"]["lineage_id"],
            lineage_generation=value["interrupt"]["lineage_generation"],
            session_id=value["session_id"],
            runner_instance_id=value["runner_instance_id"],
        )
        if self._native_historical_identity_conflict(
                interrupt_id=interrupt_id,
                source_exclusion_key=source_key,
        ):
            raise _error(
                "invalid",
                "coordinator interrupt identity was used by a terminal invocation",
            )
        for existing in self._coordinator_interrupts.values():
            if existing.get("source_exclusion_key") == source_key:
                raise _error(
                    "busy",
                    "coordinator interrupt source already has a durable authorization",
                )
        if len(self._coordinator_interrupts) >= 256:
            raise _error("busy", "coordinator interrupt ledger requires reconciliation")
        # Recompute after the live validation so no caller-controlled digest or
        # roster projection is carried into the durable record.
        digest = _digest(value)
        created_at = self.clock()
        if (isinstance(created_at, bool) or
                not isinstance(created_at, (int, float)) or
                not math.isfinite(created_at)):
            raise _error("invalid", "coordinator interrupt creation timestamp is invalid")
        self._coordinator_interrupts[interrupt_id] = self._coordinator_interrupt_record(
            value, digest, source_key, created_at
        )
        self._persist({
            "event": "coordinator-interrupt-intent-persisted",
            "interrupt_id": interrupt_id,
            "operation_id": value["interrupt"]["operation_id"],
        })
        return self._coordinator_interrupt_intent_ack(
            interrupt_id, authorize_send=True
        )

    @_transactional
    def persist_coordinator_interrupt_evidence(
            self, frame: Mapping[str, Any]
    ) -> Dict[str, Any]:
        """Persist one independently validated coordinator interrupt fact."""
        context = self._native_context
        if context is None:
            raise _error("unsupported", "coordinator interrupt context is not registered")
        self._check_coordinator_interrupt_authority(context)
        outer = _native_exact_fields(
            frame,
            ("type", "participant_id", "session_id", "runner_instance_id", "evidence"),
            "coordinator interrupt evidence",
        )
        evidence_body = _mapping(outer["evidence"], "coordinator interrupt evidence body")
        interrupt_id = _id(
            evidence_body.get("interrupt_id"),
            "coordinator interrupt evidence interrupt_id",
        ) or ""
        record = self._coordinator_interrupts.get(interrupt_id)
        if record is None:
            raise _error("unknown", "coordinator interrupt intent is unknown")
        intent = record["frame"]
        value = self._validate_coordinator_interrupt_evidence(
            frame, context, intent
        )
        evidence_id = value["evidence"]["evidence_id"]
        digest = _digest(value)
        evidence_records = record["evidence"]
        prior = evidence_records.get(evidence_id)
        if prior is not None:
            if (prior.get("digest") != digest or
                    _json_value(prior.get("frame")) != _json_value(value)):
                raise _error(
                    "invalid",
                    "coordinator interrupt evidence ID was reused with different content",
                )
            return _json_value(prior["result"])
        if len(evidence_records) >= 512:
            raise _error("busy", "coordinator interrupt evidence ledger requires reconciliation")
        if (value["evidence"]["kind"] == "runtime-ack" and
                record.get("runtime_ack") is not None):
            raise _error("invalid", "coordinator interrupt runtime acknowledgement was duplicated")
        if value["evidence"]["kind"] == "request-observation":
            data = value["evidence"]["data"]
            prior_observations = []
            for existing in evidence_records.values():
                existing_frame = existing.get("frame") if isinstance(existing, Mapping) else None
                if not isinstance(existing_frame, Mapping):
                    continue
                existing_evidence = existing_frame.get("evidence")
                if (isinstance(existing_evidence, Mapping) and
                        existing_evidence.get("kind") == "request-observation" and
                        isinstance(existing_evidence.get("data"), Mapping) and
                        existing_evidence["data"].get("epoch_id") == data["epoch_id"]):
                    prior_count = existing_evidence["data"].get("new_requests")
                    if isinstance(prior_count, int) and not isinstance(prior_count, bool):
                        prior_observations.append(prior_count)
            prior_throughs = []
            same_through_counts = []
            for existing in evidence_records.values():
                existing_frame = existing.get("frame") if isinstance(existing, Mapping) else None
                existing_evidence = existing_frame.get("evidence") if isinstance(existing_frame, Mapping) else None
                existing_data = existing_evidence.get("data") if isinstance(existing_evidence, Mapping) else None
                if (isinstance(existing_evidence, Mapping) and
                        existing_evidence.get("kind") == "request-observation" and
                        isinstance(existing_data, Mapping) and
                        existing_data.get("epoch_id") == data["epoch_id"]):
                    prior_throughs.append(existing_data.get("through_watermark"))
                    if existing_data.get("through_watermark") == data["through_watermark"]:
                        existing_count = existing_data.get("new_requests")
                        if isinstance(existing_count, int) and not isinstance(existing_count, bool):
                            same_through_counts.append(existing_count)
            if (prior_throughs and
                    data["through_watermark"] < max(prior_throughs)):
                raise _error("stale-generation", "coordinator request observation watermark moved backwards")
            if (same_through_counts and data["new_requests"] is not None and
                    data["new_requests"] not in same_through_counts):
                raise _error("stale-generation", "coordinator request observations conflict at one watermark")
            if (isinstance(data["new_requests"], int) and
                    not isinstance(data["new_requests"], bool) and
                    any(data["new_requests"] < count for count in prior_observations)):
                raise _error("stale-generation", "coordinator request observation count moved backwards")
        elif value["evidence"]["kind"] == "member-terminal":
            data = value["evidence"]["data"]
            terminal_key = (
                data["agent_id"], data["task_id"], data["tool_use_id"],
                data["lineage_incarnation"],
            )
            for existing in evidence_records.values():
                existing_frame = existing.get("frame") if isinstance(existing, Mapping) else None
                existing_evidence = existing_frame.get("evidence") if isinstance(existing_frame, Mapping) else None
                existing_data = existing_evidence.get("data") if isinstance(existing_evidence, Mapping) else None
                if not (isinstance(existing_evidence, Mapping) and
                        existing_evidence.get("kind") == "member-terminal" and
                        isinstance(existing_data, Mapping)):
                    continue
                existing_key = (
                    existing_data.get("agent_id"), existing_data.get("task_id"),
                    existing_data.get("tool_use_id"), existing_data.get("lineage_incarnation"),
                )
                if existing_key == terminal_key and existing_data.get("status") != data["status"]:
                    raise _error("uncertain-effect", "coordinator member terminal facts conflict")
        elif value["evidence"]["kind"] == "tool-terminal":
            data = value["evidence"]["data"]
            tool_key = (
                data["tool_use_id"], data["agent_id"], data["lineage_incarnation"]
            )
            for existing in evidence_records.values():
                existing_frame = existing.get("frame") if isinstance(existing, Mapping) else None
                existing_evidence = existing_frame.get("evidence") if isinstance(existing_frame, Mapping) else None
                existing_data = existing_evidence.get("data") if isinstance(existing_evidence, Mapping) else None
                if not (isinstance(existing_evidence, Mapping) and
                        existing_evidence.get("kind") == "tool-terminal" and
                        isinstance(existing_data, Mapping)):
                    continue
                existing_key = (
                    existing_data.get("tool_use_id"), existing_data.get("agent_id"),
                    existing_data.get("lineage_incarnation"),
                )
                if existing_key == tool_key and existing_data.get("status") != data["status"]:
                    raise _error("uncertain-effect", "coordinator tool terminal facts conflict")
        result = self._coordinator_interrupt_evidence_ack(value)
        evidence_records[evidence_id] = {
            "digest": digest,
            "frame": _json_value(value),
            "result": result,
        }
        if value["evidence"]["kind"] == "runtime-ack":
            record["runtime_ack"] = _json_value(value)
        record["progress_watermark"] = max(
            record["progress_watermark"], value["evidence"]["observed_watermark"]
        )
        self._persist({
            "event": "coordinator-interrupt-evidence-persisted",
            "interrupt_id": interrupt_id,
            "evidence_id": evidence_id,
            "kind": value["evidence"]["kind"],
        })
        return _json_value(result)

    @_transactional
    def validate_coordinator_interrupt_send(
            self, frame: Mapping[str, Any]
    ) -> Dict[str, Any]:
        """Revalidate one already-authorized interrupt immediately pre-send.

        This check is deliberately read/validate-only.  It does not create an
        authorization, increment a counter, or record a runtime receipt.  A
        caller must still consume the one positive intent acknowledgement and
        perform its own local connection/roster check before invoking the SDK.
        """

        context = self._native_context
        if context is None:
            raise _error("unsupported", "coordinator interrupt context is not registered")
        self._check_coordinator_interrupt_authority(context)
        value = _native_exact_fields(
            frame,
            (
                "type", "participant_id", "session_id", "runner_instance_id",
                "validation_id", "interrupt_id", "intent_digest",
            ),
            "coordinator interrupt validation",
        )
        if value["type"] != "coordinator-interrupt-validate":
            raise _error("invalid", "coordinator interrupt validation type is invalid")
        for key in ("participant_id", "session_id", "runner_instance_id", "validation_id", "interrupt_id"):
            value[key] = _id(value[key], "coordinator interrupt validation " + key) or ""
        value["intent_digest"] = self._native_interrupt_digest(
            value["intent_digest"], "coordinator interrupt validation intent_digest"
        )
        record = self._coordinator_interrupts.get(value["interrupt_id"])
        if not isinstance(record, Mapping):
            raise _error("unknown", "coordinator interrupt intent is unknown")
        intent = record.get("frame")
        if not isinstance(intent, Mapping):
            raise _error("invalid", "coordinator interrupt intent record is malformed")
        expected_outer = {
            "participant_id": intent.get("participant_id"),
            "session_id": intent.get("session_id"),
            "runner_instance_id": intent.get("runner_instance_id"),
        }
        if any(value[key] != expected_outer[key] for key in expected_outer):
            raise _error("ownership-conflict", "coordinator interrupt validation identity changed")
        if value["intent_digest"] != record.get("digest"):
            raise _error("invalid", "coordinator interrupt intent digest changed")
        if record.get("may_have_been_sent") is not True or record.get("authorization_count") != 1:
            raise _error("uncertain-effect", "coordinator interrupt authorization is not sendable")
        normalized = self._validate_coordinator_interrupt_intent(
            intent, context, live=True
        )
        if _digest(normalized) != record.get("digest"):
            raise _error("invalid", "coordinator interrupt stored intent changed")
        self._coordinator_interrupt_live_operation(normalized["interrupt"], context)
        return {
            "validated": True,
            "validation_id": value["validation_id"],
            "interrupt_id": value["interrupt_id"],
            "intent_digest": value["intent_digest"],
        }

    async def interrupt_native_coordinator(
            self, operation_id: str, generation: Any, *,
            interrupt_id: str, capability_digest: str,
            request_epoch_id: Optional[str] = None,
            deadline: Optional[float] = None,
            allow_empty_roster: bool = False,
    ) -> Dict[str, Any]:
        """Start one runner-owned coordinator interrupt attempt.

        The controller establishes only the stable operation/fence/request
        selection.  The adapter builds the complete native roster, persists
        the typed intent, consumes its one ephemeral authorization, validates
        again, and invokes the SDK connection.  This method never accepts a
        caller-built roster, calls raw ``interrupt``, or persists runtime
        evidence.
        """

        operation_id = _id(operation_id, "operation_id") or ""
        generation = self._generation_valid(generation)
        interrupt_id = _id(interrupt_id, "interrupt_id") or ""
        capability_digest = self._native_interrupt_digest(
            capability_digest, "coordinator interrupt capability_digest"
        )
        # Account-control entry is before fencing.  Persist one stable epoch
        # first; a missing epoch on an already-paused operation is historical
        # coverage we cannot reconstruct, so it refuses closed rather than
        # pretending the observation began earlier.
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            epoch = operation.metadata.get("coordinator_interrupt_epoch")
            if not isinstance(epoch, Mapping):
                if operation.phase not in {"preflight", "quiescing"}:
                    raise _error(
                        "unsupported",
                        "coordinator interrupt has no entry epoch before the existing fence",
                    )
                if request_epoch_id is None:
                    request_epoch_id = "request-epoch-" + uuid.uuid4().hex
                request_epoch_id = _id(request_epoch_id, "coordinator request_epoch_id") or ""
                created_at = self.clock()
                if (isinstance(created_at, bool) or
                        not isinstance(created_at, (int, float)) or
                        not math.isfinite(created_at)):
                    raise _error("invalid", "coordinator request epoch timestamp is invalid")
                # Fence epochs are source-wide monotonic identity.  A new
                # operation must not reset to one after a prior operation has
                # authorized native control for the same owner generation.
                # Snapshot validation has already rejected malformed prior
                # counters; retain the explicit guard here so a future
                # in-memory caller cannot silently reset the source fence.
                prior_epochs = []
                for prior_operation in self._operations.values():
                    if prior_operation.generation != operation.generation:
                        continue
                    prior_epoch = prior_operation.metadata.get("native_fence_epoch")
                    if prior_epoch is None:
                        continue
                    if type(prior_epoch) is not int or prior_epoch <= 0:
                        raise _error(
                            "invalid",
                            "prior native fence epoch is malformed",
                        )
                    prior_epochs.append(prior_epoch)
                fence_epoch = max(prior_epochs, default=0)
                epoch = {
                    **native_record_marker("coordinator-request-epoch"),
                    "request_epoch_id": request_epoch_id,
                    "entry_at": created_at,
                    "fence_epoch": fence_epoch + 1,
                }
                operation.metadata["coordinator_interrupt_epoch"] = epoch
                operation.metadata["native_fence_epoch"] = epoch["fence_epoch"]
                self._persist({
                    "event": "coordinator-interrupt-epoch-opened",
                    "operation_id": operation_id,
                    "request_epoch_id": request_epoch_id,
                })
            else:
                stored_epoch = epoch.get("request_epoch_id")
                if not isinstance(stored_epoch, str) or not stored_epoch:
                    raise _error("invalid", "coordinator request epoch is malformed")
                if request_epoch_id is not None and request_epoch_id != stored_epoch:
                    raise _error("stale-generation", "coordinator request epoch changed")
                request_epoch_id = stored_epoch
            fence_epoch = epoch.get("fence_epoch")
            if type(fence_epoch) is not int or fence_epoch <= 0:
                raise _error("invalid", "coordinator fence epoch is malformed")
            phase = operation.phase
        if phase in {"preflight", "quiescing"}:
            # Reuse the existing durable fence transition.  It seals the
            # native admission IDs and marks the context fenced atomically.
            self.fence(operation_id)
        with self._transaction():
            current = self._current_operation(operation_id, generation)
            if current.metadata.get("coordinator_interrupt_epoch") != epoch:
                raise _error("stale-generation", "coordinator interrupt epoch changed")
            context = self._native_context
            if context is None:
                raise _error("unsupported", "coordinator interrupt context is not registered")
            self._check_coordinator_interrupt_authority(context)
            if not context.get("fenced") or current.phase != "paused":
                raise _error("busy", "coordinator interrupt requires a durable native fence")
            sealed = current.metadata.get("sealed_native_admissions")
            if sealed is None and allow_empty_roster:
                sealed = []
                current.metadata["sealed_native_admissions"] = []
                self._persist({
                    "event": "coordinator-interrupt-empty-roster-sealed",
                    "operation_id": operation_id,
                })
            if (not isinstance(sealed, list) or (not sealed and not allow_empty_roster) or
                    any(not isinstance(item, str) or not item for item in sealed)):
                raise _error("unsupported", "coordinator interrupt has no complete sealed roster")
            selection = {
                "operation_id": operation_id,
                "interrupt_id": interrupt_id,
                "fence_epoch": fence_epoch,
                "request_epoch_id": request_epoch_id,
                "capability_digest": capability_digest,
            }
            prior_selection = current.metadata.get("coordinator_interrupt_selection")
            if isinstance(prior_selection, Mapping):
                if dict(prior_selection) != selection:
                    raise _error("busy", "coordinator interrupt selection is already fixed")
            else:
                current.metadata["coordinator_interrupt_selection"] = _json_value(selection)
                self._persist({
                    "event": "coordinator-interrupt-selection-sealed",
                    "operation_id": operation_id,
                    "interrupt_id": interrupt_id,
                })
            coordinator_id = self._coordinator_id
            if self._participants.get(coordinator_id or "") is None:
                raise _error("ownership-conflict", "native coordinator is unavailable")
        sender = getattr(self.runtime, "coordinator_interrupt", None) if self.runtime is not None else None
        if not callable(sender):
            raise _error("unsupported", "managed native coordinator interrupt is unavailable")
        try:
            result = sender(coordinator_id, copy.deepcopy(selection))
            if inspect.isawaitable(result):
                if deadline is None:
                    result = await result
                else:
                    timeout = float(deadline)
                    if not math.isfinite(timeout) or timeout <= 0:
                        raise _error("invalid", "coordinator interrupt deadline is invalid")
                    result = await asyncio.wait_for(result, timeout)
        except asyncio.CancelledError:
            raise
        except ControllerError:
            raise
        except asyncio.TimeoutError as exc:
            raise _error("uncertain-effect", "coordinator interrupt control outcome is unknown") from exc
        except Exception as exc:
            raise _error("uncertain-effect", "coordinator interrupt control outcome is unknown") from exc
        if not isinstance(result, Mapping):
            raise _error("uncertain-effect", "coordinator interrupt control receipt is malformed")
        accepted = result.get("accepted")
        if type(accepted) is not bool:
            raise _error(
                "uncertain-effect",
                "coordinator interrupt control receipt has no boolean outcome",
            )
        if result.get("interrupt_id") != interrupt_id:
            raise _error(
                "uncertain-effect",
                "coordinator interrupt control receipt has the wrong interrupt ID",
            )
        # These fields are optional for a small adapter receipt, but if the
        # adapter returns them they are transport correlation facts rather
        # than claims the controller may rewrite.
        for key in ("operation_id", "request_epoch_id", "fence_epoch"):
            if key in result and result[key] != selection[key]:
                raise _error(
                    "uncertain-effect",
                    "coordinator interrupt control receipt changed %s" % key,
                )
        # The adapter call is outside the state transaction.  Re-read the
        # immutable selection before returning its receipt so a concurrent
        # lifecycle change cannot make this result look like a receipt for a
        # different control request.
        with self._transaction():
            current = self._operations.get(operation_id)
            stored_selection = (
                current.metadata.get("coordinator_interrupt_selection")
                if current is not None else None
            )
            if not isinstance(stored_selection, Mapping) or dict(stored_selection) != selection:
                raise _error(
                    "uncertain-effect",
                    "coordinator interrupt selection changed during control",
                )
        # A receipt is adapter evidence only.  The runner's independent
        # runtime-ack/member/tool/effect facts remain in the durable ledger;
        # this boundary does not reinterpret arbitrary receipt fields.
        return {
            "accepted": accepted,
            "interrupt_id": interrupt_id,
            "operation_id": operation_id,
            "request_epoch_id": request_epoch_id,
            "fence_epoch": fence_epoch,
            "receipt": _json_value(result),
        }

    @staticmethod
    def _native_admission_ack(admission: Mapping[str, Any]) -> Dict[str, Any]:
        keys = ("admission_id", "owner_generation", "lineage_id", "runner_incarnation",
                "invocation_id", "tool_use_id", "trusted_definition_digest")
        return {"accepted": True, **{key: admission[key] for key in keys}}

    def _native_historical_identity_conflict(
            self, *, admission_id: Optional[str] = None,
            tool_use_id: Optional[str] = None,
            agent_id: Optional[str] = None,
            task_id: Optional[str] = None,
            observation_id: Optional[str] = None,
            stop_id: Optional[str] = None,
            interrupt_id: Optional[str] = None,
            source_exclusion_key: Optional[str] = None,
    ) -> bool:
        """Return whether a live ID would reuse immutable A-owned identity."""
        def child_conflict(child: Mapping[str, Any]) -> bool:
            return bool(
                (admission_id is not None and child.get("admission_id") == admission_id)
                or (tool_use_id is not None and child.get("tool_use_id") == tool_use_id)
                or (agent_id is not None and child.get("agent_id") == agent_id)
                or (task_id is not None and child.get("task_id") == task_id)
            )

        for archive in self._native_source_archives.values():
            snapshot = archive.get("snapshot") if isinstance(archive, Mapping) else None
            observations = (
                snapshot.get("native_child_observations")
                if isinstance(snapshot, Mapping) else None
            )
            if not isinstance(observations, Mapping):
                continue
            for key, entry in observations.items():
                if observation_id is not None and key == observation_id:
                    return True
                if (isinstance(entry, Mapping)
                        and observation_id is not None
                        and entry.get("observation_id") == observation_id):
                    return True
                observation = entry.get("observation") if isinstance(entry, Mapping) else None
                child = observation.get("child") if isinstance(observation, Mapping) else None
                if isinstance(child, Mapping) and child_conflict(child):
                    return True
        for history in self._native_invocation_history.values():
            history_observations = history.get("native_child_observations")
            if isinstance(history_observations, Mapping):
                for key, entry in history_observations.items():
                    if observation_id is not None and key == observation_id:
                        return True
                    if (isinstance(entry, Mapping)
                            and observation_id is not None
                            and entry.get("observation_id") == observation_id):
                        return True
                    observation = entry.get("observation") if isinstance(entry, Mapping) else None
                    child = observation.get("child") if isinstance(observation, Mapping) else None
                    if isinstance(child, Mapping) and child_conflict(child):
                        return True
            admissions = history.get("admissions", {})
            if isinstance(admissions, Mapping):
                for request_id, record in admissions.items():
                    if request_id == admission_id:
                        return True
                    admission = record.get("admission") if isinstance(record, Mapping) else None
                    if not isinstance(admission, Mapping):
                        continue
                    if admission_id is not None and admission.get("admission_id") == admission_id:
                        return True
                    if tool_use_id is not None and admission.get("tool_use_id") == tool_use_id:
                        return True
            roster = history.get("joined_roster", {})
            children = roster.get("children", []) if isinstance(roster, Mapping) else []
            child_values = children if isinstance(children, list) else []
            for child in child_values:
                if not isinstance(child, Mapping):
                    continue
                if child_conflict(child):
                    return True
            controls = history.get("terminal_controls", {})
            if not isinstance(controls, Mapping):
                continue
            stops = controls.get("native_stops", {})
            if isinstance(stops, Mapping):
                for key, record in stops.items():
                    if key == stop_id:
                        return True
                    if isinstance(record, Mapping):
                        if record.get("stop_id") == stop_id:
                            return True
                        frame = record.get("frame", {})
                        stop = frame.get("stop", {}) if isinstance(frame, Mapping) else {}
                        if (
                            admission_id is not None and stop.get("admission_id") == admission_id
                        ) or (
                            tool_use_id is not None and stop.get("tool_use_id") == tool_use_id
                        ) or (
                            agent_id is not None and stop.get("agent_id") == agent_id
                        ) or (
                            task_id is not None and stop.get("task_id") == task_id
                        ):
                            return True
            interrupts = controls.get("coordinator_interrupts", {})
            if isinstance(interrupts, Mapping):
                for key, record in interrupts.items():
                    if key == interrupt_id:
                        return True
                    if not isinstance(record, Mapping):
                        continue
                    if record.get("interrupt_id") == interrupt_id:
                        return True
                    if source_exclusion_key is not None and record.get(
                            "source_exclusion_key"
                    ) == source_exclusion_key:
                        return True
        return False

    def _check_native_authority(
            self, context: Mapping[str, Any], *,
            expected_daemon_id: Optional[str] = None) -> None:
        """Re-read owner and the exact global claim within the transaction."""
        lineage = context["lineage"]
        self._check_generation(lineage["owner_generation"])
        owner_reader = getattr(self.store, "read_owner", None)
        claim_reader = getattr(self.store, "read_lineage_claims", None)
        if not callable(owner_reader) or not callable(claim_reader):
            raise _error("unsupported", "native admission requires durable owner and lineage claims")
        owner = owner_reader()
        if (not isinstance(owner, Mapping) or owner.get("mode") != "managed"
                or type(owner.get("generation")) is not int
                or owner["generation"] != lineage["owner_generation"]
                or owner.get("lane") != lineage["lane"]
                or ("lineage_id" in owner and owner["lineage_id"] != lineage["lineage_id"])
                or ("coordinator_session_uuid" in owner
                    and owner["coordinator_session_uuid"] != lineage["session_uuid"])
                or (expected_daemon_id is not None
                    and owner.get("daemon_id") != expected_daemon_id)):
            raise _error("ownership-conflict", "native admission owner changed")
        claims = claim_reader()
        claim = lineage["workspace_claim"]
        if claim.get("state") not in {"held", "active"} or claim not in claims:
            raise _error("ownership-conflict", "native admission workspace claim is not current")
        coordinator = self._participants.get(self._coordinator_id or "")
        if (coordinator is None or coordinator.session_id != lineage["session_uuid"]
                or coordinator.bound_lane != lineage["lane"]
                or coordinator.read_only != lineage["read_only"]
                or coordinator.metadata.get("runner_instance_id") != context["runner_incarnation"]):
            raise _error("ownership-conflict", "native admission coordinator runner changed")
        if any(participant.role != "coordinator" for participant in self._participants.values()):
            raise _error("migration-required", "independent workers cannot join a native context")

    def _check_native_stop_authority(self, context: Mapping[str, Any]) -> None:
        """Recheck the trusted daemon owner before any stop record mutation."""

        daemon_id = self._native_stop_daemon_id
        if daemon_id is None:
            raise _error(
                "unsupported",
                "native stop requires the trusted daemon identity",
            )
        self._check_native_authority(context, expected_daemon_id=daemon_id)

    def _check_coordinator_interrupt_authority(
            self, context: Mapping[str, Any]
    ) -> None:
        """Recheck the distinct trusted owner for coordinator interrupts."""

        daemon_id = self._coordinator_interrupt_daemon_id
        if daemon_id is None:
            raise _error(
                "unsupported",
                "coordinator interrupt requires the trusted daemon identity",
            )
        self._check_native_authority(context, expected_daemon_id=daemon_id)

    def _register_native_context_locked(
            self, generation: Any, lineage: Any, runner_incarnation: str,
            invocation_id: str, trusted_definitions: Mapping[str, Any], *,
            invocation_watermark: int = 1, prompt_id: Optional[str] = None
    ) -> Dict[str, Any]:
        """Register a real native invocation inside an existing transaction.

        Startup preparation deliberately does not call this helper.  The
        invocation ID is the durable mailbox message ID and is unavailable
        until the controller has selected the first message immediately
        before the adapter send.  Keeping this helper separate also prevents a
        nested decorated transaction from reloading the controller while a
        dispatch transaction is binding that message.
        """
        _native_positive_generation(generation, "native context generation")
        self._check_generation(generation)
        record = LineageRecord.from_dict(lineage.to_dict() if isinstance(lineage, LineageRecord) else lineage)
        context = self._validate_native_context({
            **native_record_marker("admission-context"), "lineage": record.to_dict(),
            "runner_incarnation": runner_incarnation, "invocation_id": invocation_id,
            "invocation_watermark": invocation_watermark, "prompt_id": prompt_id,
            "definitions": self._native_definition_facts(trusted_definitions), "fenced": False,
        })
        self._check_native_authority(context)
        if self._native_context is not None:
            if self._native_context == context:
                return _json_value(context)
            raise _error("busy", "native context replacement requires lineage reconciliation")
        self._native_context = context
        self._persist({"event": "native-context-registered", "lineage_id": record.lineage_id,
                       "invocation_id": invocation_id})
        return _json_value(context)

    @_transactional
    def register_native_context(
            self, generation: Any, lineage: Any, runner_incarnation: str,
            invocation_id: str, trusted_definitions: Mapping[str, Any], *,
            invocation_watermark: int = 1, prompt_id: Optional[str] = None) -> Dict[str, Any]:
        """Internal configuration/event seam; never populated from an intent.

        The supervisor supplies the proven lineage and its trusted launch
        definitions before any Agent hook. Public admission requests cannot
        register or replace this authority. Pending records cannot be erased
        by replacing the invocation; lifecycle reconciliation owns that step.
        """
        return self._register_native_context_locked(
            generation, lineage, runner_incarnation, invocation_id,
            trusted_definitions, invocation_watermark=invocation_watermark,
            prompt_id=prompt_id,
        )

    @staticmethod
    def _native_startup_lineage_candidate(
            participant: Participant, runner_spec: Mapping[str, Any]
    ) -> tuple[Any, Any, Any, bool]:
        """Return the one supported native launch descriptor.

        Normal startup is selected only by ``fingerprint.native_config``.  A
        complete lineage record is also accepted when a recovery caller has
        already resolved the durable claim.  The values returned here are
        candidates; the store owner/claim and trusted definition checks below
        remain authoritative.
        """

        fingerprint = runner_spec.get("fingerprint")
        config: Any = None
        if isinstance(fingerprint, Mapping):
            config = fingerprint.get("native_config")
        if config is None and isinstance(participant.metadata, Mapping):
            # Participant metadata is retained for recovery of an already
            # prepared operation.  Fresh normal startup uses the fingerprint
            # channel above so arbitrary participant aliases cannot opt in.
            config = participant.metadata.get("native_config")
        if config is None:
            return None, None, None, False
        if not isinstance(config, Mapping):
            raise _error("invalid", "native_config must be an object")

        lineage: Any = config.get("lineage")
        if lineage is None:
            lineage = config.get("lineage_record")
        if lineage is None:
            # The normal form is identity-only.  The actual workspace claim
            # is looked up or created from the state store below.
            lineage = {
                key: config[key]
                for key in (
                    "lineage_id", "lineage_generation", "workspace",
                    "common_dir", "repository", "read_only",
                )
                if key in config
            }
        definitions = config.get("trusted_definitions")
        runner_incarnation = config.get(
            "runner_incarnation", config.get("runner_instance_id")
        )
        return lineage, definitions, runner_incarnation, True

    def _native_lineage_from_startup(
            self, participant: Participant, generation: int,
            candidate: Any,
    ) -> Optional[LineageRecord]:
        """Resolve startup lineage against the actual state-store claim."""

        claim_reader = getattr(self.store, "read_lineage_claims", None)
        claims: Any = None
        if callable(claim_reader):
            claims = claim_reader()
            if not isinstance(claims, list):
                raise _error("invalid", "native startup lineage claims are malformed")

        record: Optional[LineageRecord]
        if candidate is not None and not isinstance(candidate, Mapping):
            raise _error("invalid", "native startup lineage is malformed")

        # Recovery may supply the complete record.  A normal native_config is
        # deliberately smaller and is resolved against a real store claim.
        complete = isinstance(candidate, Mapping) and {
            "workspace", "common_dir", "workspace_claim", "lane",
            "session_uuid", "owner_generation", "lineage_generation",
        }.issubset(candidate)
        if complete:
            record = LineageRecord.from_dict(candidate)
            if (
                record.owner_generation != generation
                or record.session_uuid != participant.session_id
                or record.lane.casefold() != str(participant.bound_lane).casefold()
                or record.read_only != participant.read_only
            ):
                raise _error("ownership-conflict", "native startup lineage does not match the coordinator")
            if claims is not None and record.workspace_claim not in claims:
                raise _error("ownership-conflict", "native startup lineage claim is not current")
            return record

        if candidate is not None:
            lineage_id = _id(candidate.get("lineage_id"), "native startup lineage_id") or ""
            lineage_generation = _native_positive_generation(
                candidate.get("lineage_generation"),
                "native startup lineage_generation",
            )
        elif self._native_context is not None:
            return LineageRecord.from_dict(self._native_context["lineage"])
        else:
            raise _error("invalid", "native startup lineage identity is missing")

        if self._native_context is not None:
            existing = LineageRecord.from_dict(self._native_context["lineage"])
            if (existing.lineage_id != lineage_id or
                    existing.lineage_generation != lineage_generation):
                raise _error("busy", "native startup lineage changed")
            return existing

        transcript = participant.metadata.get("transcript", {})
        if not isinstance(transcript, Mapping):
            raise _error("invalid", "native startup transcript identity is malformed")

        matches = []
        if claims is not None:
            for claim in claims:
                if not isinstance(claim, Mapping):
                    raise _error("invalid", "native startup lineage claims are malformed")
                if (claim.get("claim_kind") != "workspace" or
                        claim.get("lineage_id") != lineage_id or
                        claim.get("owner_generation") != generation or
                        claim.get("lineage_generation") != lineage_generation):
                    continue
                claim_lane = claim.get("lane")
                if (not isinstance(claim_lane, str) or
                        claim_lane.casefold() != str(participant.bound_lane).casefold()):
                    continue
                claim_session = claim.get("coordinator_session_uuid")
                if claim_session is not None and claim_session != participant.session_id:
                    continue
                matches.append(claim)
        if len(matches) > 1:
            raise _error("ownership-conflict", "native startup has multiple lineage claims")
        if matches:
            return LineageRecord.from_store_claim(
                matches[0], session_uuid=participant.session_id,
                transcript=transcript, read_only=participant.read_only,
            )

        # A blank claim index is valid for the first native startup.  Claiming
        # is performed only after the caller's capability preflight (the
        # normal start path invokes this helper at that boundary).
        claimer = getattr(self.store, "claim_lineage", None)
        if not callable(claimer):
            raise _error("unsupported", "native startup requires durable lineage claims")
        claim_kwargs: Dict[str, Any] = {
            "coordinator_session_uuid": participant.session_id,
            "owner_generation": generation,
            "lineage_generation": lineage_generation,
            "parent_read_only": participant.read_only,
        }
        for key in ("workspace", "repository"):
            if isinstance(candidate, Mapping) and candidate.get(key) is not None:
                claim_kwargs[key] = candidate[key]
        try:
            claim = claimer(lineage_id, **claim_kwargs)
        except ControllerError:
            raise
        except Exception as exc:
            raise _error(
                str(getattr(exc, "code", "ownership-conflict")),
                "native startup lineage claim was refused",
            ) from exc
        if not isinstance(claim, Mapping):
            raise _error("uncertain-effect", "native startup lineage claim result is malformed")
        return LineageRecord.from_store_claim(
            claim, session_uuid=participant.session_id,
            transcript=transcript, read_only=participant.read_only,
        )

    @staticmethod
    def _native_startup_definitions(
            definitions: Any, runner_spec: Mapping[str, Any]
    ) -> Mapping[str, Any]:
        if definitions is None:
            fingerprint = runner_spec.get("fingerprint")
            if isinstance(fingerprint, Mapping):
                definitions = fingerprint.get("trusted_definitions")
        if not isinstance(definitions, Mapping) or not definitions:
            raise _error("unsupported", "native startup trusted definitions are unavailable")
        return definitions

    @staticmethod
    def _native_lineage_context_identity(
            context: Mapping[str, Any]
    ) -> Dict[str, Any]:
        lineage = context["lineage"]
        return {
            "owner_generation": lineage["owner_generation"],
            "lineage_id": lineage["lineage_id"],
            "lineage_generation": lineage["lineage_generation"],
            "runner_incarnation": context["runner_incarnation"],
        }

    def _prepare_native_coordinator_locked(
            self, operation: Operation, generation: int,
            coordinator: Participant, runner_spec: Mapping[str, Any],
            *, lineage: Optional[LineageRecord] = None,
            runner_incarnation: Optional[str] = None,
            trusted_definitions: Optional[Mapping[str, Any]] = None,
    ) -> Optional[Dict[str, Any]]:
        """Prepare one native coordinator before its runtime is opened.

        This method runs inside the existing start transaction.  It never
        contacts the runtime.  A runner incarnation is persisted before
        ``open`` and is placed in the exact SDK fingerprint used by the
        adapter.  The native context itself is intentionally left unset until
        the first real mailbox message is selected immediately before send.
        """

        if coordinator.participant_id != self._coordinator_id:
            raise _error("ownership-conflict", "native startup coordinator is not enrolled")
        if coordinator.role.casefold() != "coordinator":
            raise _error("invalid", "native startup requires a coordinator")
        if any(item.role.casefold() != "coordinator"
               for item in self._participants.values()):
            raise _error(
                "migration-required",
                "native coordinator startup cannot mix independent workers",
            )
        if lineage is None:
            descriptor, descriptor_definitions, descriptor_runner, explicit = (
                self._native_startup_lineage_candidate(coordinator, runner_spec)
            )
            if not explicit and self._native_context is None:
                return None
            lineage = self._native_lineage_from_startup(
                coordinator, generation, descriptor
            )
            if trusted_definitions is None:
                trusted_definitions = descriptor_definitions
            if runner_incarnation is None:
                runner_incarnation = descriptor_runner
        if not isinstance(lineage, LineageRecord):
            lineage = LineageRecord.from_dict(lineage)
        definitions = self._native_startup_definitions(
            trusted_definitions, runner_spec
        )

        fingerprint = runner_spec.get("fingerprint")
        if not isinstance(fingerprint, Mapping):
            raise _error("invalid", "native startup runner fingerprint is malformed")
        fingerprint = copy.deepcopy(dict(fingerprint))
        existing_identity = fingerprint.get("lineage_context")
        if existing_identity is not None and not isinstance(existing_identity, Mapping):
            raise _error("invalid", "native startup lineage context is malformed")

        startup = operation.metadata.get("native_startup")
        if isinstance(startup, Mapping):
            prior_runner = startup.get("runner_incarnation")
            if not isinstance(prior_runner, str) or not prior_runner:
                raise _error("invalid", "native startup runner identity is malformed")
            if runner_incarnation is not None and runner_incarnation != prior_runner:
                raise _error("stale-generation", "native startup runner identity changed")
            runner_incarnation = prior_runner
        if runner_incarnation is None:
            runner_incarnation = coordinator.metadata.get("runner_instance_id")
        if runner_incarnation is None:
            runner_incarnation = "native-runner-" + uuid.uuid4().hex
        runner_incarnation = _id(runner_incarnation, "native startup runner_incarnation") or ""

        current_runner = coordinator.metadata.get("runner_instance_id")
        if current_runner is not None and current_runner != runner_incarnation:
            raise _error("stale-generation", "native startup runner identity changed")
        coordinator.metadata["runner_instance_id"] = runner_incarnation
        # Preparation is still inside the capability-gated startup
        # transaction.  Re-read the authoritative managed owner and exact
        # workspace claim before any native identity or definition reaches
        # the durable runner fingerprint.  This deliberately uses the same
        # authority check as admission; a caller-supplied LineageRecord is
        # not a substitute for the current store row.
        self._check_native_authority({
            "lineage": lineage.to_dict(),
            "runner_incarnation": runner_incarnation,
        })
        fingerprint["lineage_context"] = {
            "owner_generation": lineage.owner_generation,
            "lineage_id": lineage.lineage_id,
            "lineage_generation": lineage.lineage_generation,
            "runner_incarnation": runner_incarnation,
        }
        # The adapter needs the exact fresh global claim to authorize a
        # writable native child under a read-only coordinator.  This is the
        # validated store row, never a caller-supplied reduced claim.
        fingerprint["lineage_claim"] = _json_value(lineage.workspace_claim)
        # The SDK needs complete definitions to construct custom agents; the
        # controller's durable context keeps only body-free facts.
        fingerprint["trusted_definitions"] = _json_value(definitions)
        runner_spec["fingerprint"] = fingerprint

        definition_facts = self._native_definition_facts(definitions)
        if self._native_context is not None:
            context = self._native_context
            if (
                context["lineage"] != lineage.to_dict()
                or context["runner_incarnation"] != runner_incarnation
                or context["definitions"] != definition_facts
            ):
                raise _error("busy", "native startup context does not match the enrolled coordinator")

        operation.metadata["native_startup"] = {
            **native_record_marker("coordinator-startup"),
            "participant_id": coordinator.participant_id,
            "session_id": coordinator.session_id,
            "runner_incarnation": runner_incarnation,
            "lineage_id": lineage.lineage_id,
            "lineage_generation": lineage.lineage_generation,
            "lineage": lineage.to_dict(),
            "definitions": definition_facts,
            "invocation_id": (
                self._native_context.get("invocation_id")
                if self._native_context is not None else None
            ),
            "invocation_bound": self._native_context is not None,
        }
        operation.metadata["target_specs"][coordinator.participant_id] = _json_value(runner_spec)
        self._persist({
            "event": "native-coordinator-prepared",
            "operation_id": operation.operation_id,
            "participant_id": coordinator.participant_id,
            "lineage_id": lineage.lineage_id,
        })
        return {
            **native_record_marker("coordinator-startup"),
            "lineage": lineage.to_dict(),
            "runner_incarnation": runner_incarnation,
            "invocation_id": (
                self._native_context.get("invocation_id")
                if self._native_context is not None else None
            ),
            "definitions": definition_facts,
            "fenced": False,
        }

    @_transactional
    def prepare_native_coordinator(
            self, generation: Any, lineage: Any, runner_incarnation: str,
            trusted_definitions: Mapping[str, Any], *,
            operation_id: Optional[str] = None,
            coordinator_id: Optional[str] = None,
    ) -> Optional[Dict[str, Any]]:
        """Prepare trusted native coordinator metadata before ``runtime.open``.

        This is the direct internal seam used by the normal start path and by
        the adapter integration tests.  It records no invocation: the caller
        must bind the actual durable mailbox message through
        :meth:`bind_native_invocation` before the first query.
        """

        generation = self._generation_valid(generation)
        if operation_id is None:
            operation = self._active_operation()
            if operation is None and self._active_operation_id is not None:
                # A released operation remains the current coordinator
                # connection for the direct internal preparation seam even
                # though it is terminal for the ordinary operation gate.
                candidate = self._operations.get(self._active_operation_id)
                if (candidate is not None and candidate.generation == generation
                        and candidate.phase == "released"):
                    operation = candidate
            if operation is None or operation.generation != generation:
                raise _error("unknown", "native startup has no current operation")
            operation_id = operation.operation_id
        else:
            operation_id = _id(operation_id, "operation_id") or ""
            operation = self._current_operation(operation_id, generation)
        if operation.phase not in {"starting", "preflight", "ready-held", "released"}:
            raise _error("busy", "native coordinator preparation is outside startup")
        if coordinator_id is None:
            coordinator_id = self._coordinator_id
        coordinator_id = _id(coordinator_id, "coordinator_id") or ""
        coordinator = self._participants.get(coordinator_id)
        if coordinator is None:
            raise _error("unknown", "native startup coordinator is not enrolled")
        if not isinstance(trusted_definitions, Mapping) or not trusted_definitions:
            raise _error("invalid", "native startup trusted definitions are malformed")
        if isinstance(lineage, LineageRecord):
            lineage_record = lineage
        else:
            lineage_record = LineageRecord.from_dict(lineage)
        if lineage_record.owner_generation != generation:
            raise _error("stale-generation", "native startup lineage generation is stale")
        if lineage_record.session_uuid != coordinator.session_id:
            raise _error("ownership-conflict", "native startup lineage session changed")
        if lineage_record.read_only != coordinator.read_only:
            raise _error("ownership-conflict", "native startup read-only policy changed")
        # Even this trusted internal seam must resolve a complete record back
        # to the current owner/claim index before it is copied into the
        # runner fingerprint.  The normal native_config path performs the
        # same resolution and may create the first claim.
        lineage_record = self._native_lineage_from_startup(
            coordinator, generation, lineage_record.to_dict()
        )
        if lineage_record is None:
            raise _error("unsupported", "native startup lineage is unavailable")
        runner_incarnation = _id(
            runner_incarnation, "native startup runner_incarnation"
        ) or ""
        target_specs = operation.metadata.get("target_specs", {})
        if not isinstance(target_specs, Mapping):
            raise _error("invalid", "native startup target specifications are malformed")
        target_specs = dict(target_specs)
        raw_spec = target_specs.get(coordinator_id)
        if not isinstance(raw_spec, Mapping):
            raw_spec = {"fingerprint": {}}
        runner_spec = copy.deepcopy(dict(raw_spec))
        fingerprint = runner_spec.get("fingerprint")
        if not isinstance(fingerprint, Mapping):
            fingerprint = {}
        fingerprint = copy.deepcopy(dict(fingerprint))
        fingerprint["native_config"] = {
            "lineage_id": lineage_record.lineage_id,
            "lineage_generation": lineage_record.lineage_generation,
            "runner_incarnation": runner_incarnation,
            "trusted_definitions": _json_value(trusted_definitions),
        }
        runner_spec["fingerprint"] = fingerprint
        operation.metadata["target_specs"] = target_specs
        return self._prepare_native_coordinator_locked(
            operation, generation, coordinator, runner_spec,
            lineage=lineage_record,
            runner_incarnation=runner_incarnation,
            trusted_definitions=trusted_definitions,
        )

    def _native_daemon_id_locked(self) -> str:
        owner_reader = getattr(self.store, "read_owner", None)
        if not callable(owner_reader):
            raise _error("unsupported", "native rollover requires durable daemon authority")
        owner = owner_reader()
        if not isinstance(owner, Mapping):
            raise _error("ownership-conflict", "native rollover owner evidence is malformed")
        daemon_id = _id(owner.get("daemon_id"), "native rollover daemon ID", required=False)
        if not daemon_id:
            raise _error("unsupported", "native rollover daemon authority is unavailable")
        return daemon_id

    @staticmethod
    def _native_prepare_permissions(definitions: Mapping[str, Any]) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        for name, facts in definitions.items():
            if not isinstance(facts, Mapping):
                raise _error("invalid", "native rollover definition facts are malformed")
            result[name] = {
                "tools": _json_value(facts.get("tools", [])),
                "permissionMode": facts.get("permissionMode"),
                "permissions": _json_value(facts.get("permissions", {})),
                "writable_paths": _json_value(facts.get("writable_paths", [])),
            }
        return result

    def _native_prepare_request_locked(
            self, operation: Operation, entry: MailboxEntry,
    ) -> Dict[str, Any]:
        context = self._native_context
        if not isinstance(context, Mapping):
            raise _error("unsupported", "native rollover has no prior invocation context")
        coordinator = self._participants.get(self._coordinator_id or "")
        if coordinator is None or coordinator.participant_id != entry.recipient_id:
            raise _error("ownership-conflict", "native rollover recipient is not the coordinator")
        if coordinator.session_id != context["lineage"]["session_uuid"]:
            raise _error("ownership-conflict", "native rollover coordinator session changed")
        runner_incarnation = _id(
            coordinator.metadata.get("runner_instance_id"),
            "native rollover runner incarnation",
        ) or ""
        if runner_incarnation != context["runner_incarnation"]:
            raise _error("stale-generation", "native rollover runner incarnation changed")
        daemon_id = self._native_daemon_id_locked()
        lineage = context["lineage"]
        reservation_id = "reservation-" + uuid.uuid4().hex
        request = {
            "schema_version": 2,
            "architecture": NATIVE_ARCHITECTURE,
            "reservation_version": 1,
            "reservation_id": reservation_id,
            "operation_id": operation.operation_id,
            "owner_generation": operation.generation,
            "daemon_id": daemon_id,
            "participant_id": coordinator.participant_id,
            "session_id": coordinator.session_id,
            "runner_incarnation": runner_incarnation,
            "lineage_id": lineage["lineage_id"],
            "lineage_generation": lineage["lineage_generation"],
            "prior_invocation_id": context["invocation_id"],
            "next_invocation_id": entry.message_id,
            "prior_mailbox_id": context["invocation_id"],
            "next_mailbox_id": entry.message_id,
            "prior_watermark": context["invocation_watermark"],
            "definitions_digest": _digest(context["definitions"]),
            "permissions_digest": _digest(
                self._native_prepare_permissions(context["definitions"])
            ),
            "claim_digest": _digest(lineage["workspace_claim"]),
        }
        # A deadline is transport-only; the immutable binding digest excludes
        # it and covers every exact request field except itself.
        request["binding_digest"] = _digest(request)
        return self._validate_native_prepare_request(request)

    @classmethod
    def _validate_native_prepare_response(
            cls, request: Mapping[str, Any], response: Any,
    ) -> Dict[str, Any]:
        request = cls._validate_native_prepare_request(request)
        if not isinstance(response, Mapping):
            raise _error("invalid", "native rollover reservation response is malformed")
        if len(_canonical_json(response).encode("utf-8")) > _NATIVE_ROLLOVER_RECORD_BYTES:
            raise _error("invalid", "native rollover reservation response exceeds capacity")
        expected = set(_NATIVE_PREPARE_REQUEST_FIELDS) | {
            "state", "terminal_watermark", "next_watermark",
            "terminal_proof", "terminal_proof_digest",
        }
        state = response.get("state")
        if state == "busy":
            if set(response) != set(_NATIVE_PREPARE_REQUEST_FIELDS) | {"state"}:
                raise _error("invalid", "native rollover busy response is malformed")
            for key in _NATIVE_PREPARE_REQUEST_FIELDS:
                if response.get(key) != request.get(key):
                    raise _error("ownership-conflict", "native rollover response binding changed")
            return _json_value(dict(response))
        if set(response) != expected:
            raise _error("invalid", "native rollover reservation response fields are malformed")
        for key in _NATIVE_PREPARE_REQUEST_FIELDS:
            if response.get(key) != request.get(key):
                raise _error("ownership-conflict", "native rollover response binding changed")
        if state != "reserved":
            raise _error("unsupported", "native rollover reservation was not accepted")
        proof = response.get("terminal_proof")
        if not isinstance(proof, Mapping):
            raise _error("invalid", "native rollover terminal proof is malformed")
        proof_fields = {
            "parent_result", "roster", "roster_digest", "observation_watermark",
            "uncertainty", "overflow",
        }
        if set(proof) != proof_fields:
            raise _error("invalid", "native rollover terminal proof fields are malformed")
        parent = _native_exact_fields(
            proof["parent_result"],
            (
                "session_id", "invocation_id", "message_id",
                "result_watermark", "reader_drained_watermark",
            ),
            "native rollover parent result",
        )
        if (
            parent["session_id"] != request["session_id"]
            or parent["invocation_id"] != request["prior_invocation_id"]
            or parent["message_id"] != request["prior_mailbox_id"]
        ):
            raise _error("ownership-conflict", "native rollover parent result changed identity")
        prior_watermark = _native_positive_generation(
            request["prior_watermark"], "native rollover prior watermark"
        )
        result_watermark = _native_positive_generation(
            parent["result_watermark"], "native rollover result watermark"
        )
        reader_watermark = _native_positive_generation(
            parent["reader_drained_watermark"],
            "native rollover reader drained watermark",
        )
        observation_watermark = _native_positive_generation(
            proof["observation_watermark"],
            "native rollover observation watermark",
        )
        terminal_watermark = _native_positive_generation(
            response["terminal_watermark"],
            "native rollover terminal watermark",
        )
        next_watermark = _native_positive_generation(
            response["next_watermark"], "native rollover next watermark"
        )
        if not (
            prior_watermark < result_watermark <= reader_watermark
            <= observation_watermark == terminal_watermark < next_watermark
        ):
            raise _error("stale-generation", "native rollover watermarks are not ordered")
        roster = cls._native_history_roster(
            proof["roster"], "native rollover roster"
        )
        if proof["roster_digest"] != _digest(roster):
            raise _error("invalid", "native rollover roster digest changed")
        if not isinstance(proof["uncertainty"], list) or proof["uncertainty"]:
            raise _error("busy", "native rollover proof is uncertain")
        if proof["overflow"] is not False:
            raise _error("busy", "native rollover proof overflowed")
        proof_digest = response["terminal_proof_digest"]
        if (
            not isinstance(proof_digest, str)
            or not re.fullmatch(r"[0-9a-f]{64}", proof_digest)
            or proof_digest != _digest(proof)
        ):
            raise _error("invalid", "native rollover terminal proof digest changed")
        if response["terminal_watermark"] != proof["observation_watermark"]:
            raise _error("stale-generation", "native rollover terminal watermark changed")
        if response["next_watermark"] <= response["terminal_watermark"]:
            raise _error("stale-generation", "native rollover next watermark did not advance")
        return _json_value(dict(response))

    @classmethod
    def _validate_native_no_send_receipt(
            cls, request: Mapping[str, Any], value: Any,
    ) -> Dict[str, Any]:
        """Validate the adapter's bounded proof that reservation B was unsent.

        This is intentionally narrower than the public ``recover_dispatch``
        transport-proof compatibility path.  Native rollover recovery may
        consume only a complete SDK reservation receipt whose binding is
        independently checked against the immutable A->B request.
        """
        receipt = _native_exact_fields(
            value,
            tuple(sorted(_NATIVE_NO_SEND_RECEIPT_FIELDS)),
            "native reservation no-send receipt",
        )
        _native_validate(
            receipt,
            record_kind="native-reservation-no-send",
            label="native reservation no-send receipt",
        )
        def _reject_body_or_secret(value: Any) -> None:
            if isinstance(value, Mapping):
                for key, child in value.items():
                    normalized = _normalized_key(key)
                    if normalized in _NATIVE_NO_SEND_FORBIDDEN_FIELDS:
                        raise _error(
                            "unsupported",
                            "native reservation no-send receipt contains sensitive data",
                        )
                    _reject_body_or_secret(child)
            elif isinstance(value, list):
                for child in value:
                    _reject_body_or_secret(child)
        _reject_body_or_secret(receipt)
        secret_key = _contains_secret_key(receipt)
        if secret_key is not None:
            raise _error(
                "unsupported",
                "native reservation no-send receipt contains credential data",
            )
        if type(receipt["schema_version"]) is not int or receipt["schema_version"] != 2:
            raise _error("invalid", "native reservation no-send schema is unsupported")
        if receipt["architecture"] != NATIVE_ARCHITECTURE:
            raise _error("invalid", "native reservation no-send architecture changed")
        _id(receipt["observation_id"], "native reservation observation ID")
        reservation = cls._validate_native_prepare_response(
            request, receipt["reservation_binding"]
        )
        if reservation.get("state") != "reserved":
            raise _error("invalid", "native no-send reservation is not committed")
        if receipt["reservation_digest"] != _digest(reservation):
            raise _error("invalid", "native reservation no-send binding digest changed")
        observation_watermark = _native_positive_generation(
            receipt["observation_watermark"],
            "native reservation observation watermark",
        )
        if observation_watermark < reservation["terminal_watermark"]:
            raise _error(
                "stale-generation",
                "native reservation no-send observation predates terminal proof",
            )
        if receipt["state"] != "reserved-unconsumed":
            raise _error("invalid", "native reservation no-send state is unsupported")
        if receipt["transport_attempted"] is not False:
            raise _error("uncertain-effect", "native reservation transport was attempted")
        digest = receipt["receipt_digest"]
        if (
            not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
            or digest != _digest({key: value for key, value in receipt.items()
                                  if key != "receipt_digest"})
        ):
            raise _error("invalid", "native reservation no-send receipt digest changed")
        if len(_canonical_json(receipt).encode("utf-8")) > _NATIVE_ROLLOVER_RECORD_BYTES:
            raise _error("invalid", "native reservation no-send receipt exceeds capacity")
        return _json_value(receipt)

    @staticmethod
    def _validate_native_no_send_consumption(
            value: Any, receipt: Mapping[str, Any], mailbox_id: str,
    ) -> Dict[str, Any]:
        consumption = _native_exact_fields(
            value,
            tuple(sorted(_NATIVE_NO_SEND_CONSUMPTION_FIELDS)),
            "native reservation no-send consumption",
        )
        _id(consumption["observation_id"], "native reservation consumption observation ID")
        _id(consumption["mailbox_id"], "native reservation consumption mailbox ID")
        if consumption["observation_id"] != receipt["observation_id"]:
            raise _error("ownership-conflict", "native reservation observation changed")
        if consumption["receipt_digest"] != receipt["receipt_digest"]:
            raise _error("ownership-conflict", "native reservation receipt changed")
        if consumption["mailbox_id"] != mailbox_id:
            raise _error("ownership-conflict", "native reservation mailbox changed")
        if consumption["consumed"] is not True:
            raise _error("invalid", "native reservation consumption is not committed")
        return _json_value(consumption)

    def _native_rollover_for_mailbox_locked(
            self, operation_id: str, mailbox_id: str,
    ) -> Optional[Dict[str, Any]]:
        for rollover in self._native_invocation_rollovers.values():
            if (
                rollover.get("operation_id") == operation_id
                and rollover.get("next_mailbox_id") == mailbox_id
            ):
                return rollover
        return None

    def _native_begin_rollover_locked(
            self, operation: Operation, entry: MailboxEntry,
    ) -> Tuple[str, Dict[str, Any], Dict[str, Any]]:
        existing = self._native_rollover_for_mailbox_locked(
            operation.operation_id, entry.message_id
        )
        if existing is not None:
            if existing["state"] in {"uncertain", "delivered"}:
                uncertainty = existing.get("uncertainty")
                if (
                    existing["state"] == "uncertain"
                    and isinstance(uncertainty, Mapping)
                    and uncertainty.get("stage") == "preparation"
                    and uncertainty.get("reservation_outcome") == "not-reserved"
                ):
                    request = self._validate_native_prepare_request(
                        existing["preparation_intent"].get("request")
                    )
                    return existing["rollover_id"], existing, request
                raise _error("uncertain-effect", "native rollover mailbox has an unresolved reservation")
            if (
                existing["state"] == "preparation-pending"
                and isinstance(existing.get("uncertainty"), Mapping)
                and existing["uncertainty"].get("code") == "busy"
                and existing["uncertainty"].get("reservation_outcome") == "not-reserved"
            ):
                request = self._validate_native_prepare_request(
                    existing["preparation_intent"].get("request")
                )
                return existing["rollover_id"], existing, request
            raise _error(
                "busy",
                "native rollover already has an unconsumed preparation reservation",
            )
        request = self._native_prepare_request_locked(operation, entry)
        rollover_id = "rollover-" + uuid.uuid4().hex
        context = self._native_context
        lineage = context["lineage"]
        rollover = {
            **native_record_marker("native-invocation-rollover"),
            "rollover_schema": 1,
            "rollover_id": rollover_id,
            "integrity_digest": "",
            "operation_id": operation.operation_id,
            "owner_generation": operation.generation,
            "lineage_id": lineage["lineage_id"],
            "lineage_generation": lineage["lineage_generation"],
            "daemon_id": request["daemon_id"],
            "daemon_incarnation": request["daemon_id"],
            "coordinator": {
                "participant_id": entry.recipient_id,
                "session_uuid": request["session_id"],
            },
            "runner_incarnation": request["runner_incarnation"],
            "prior_invocation_id": request["prior_invocation_id"],
            "next_invocation_id": request["next_invocation_id"],
            "prior_mailbox_id": request["prior_mailbox_id"],
            "next_mailbox_id": request["next_mailbox_id"],
            "preparation_intent": {
                **_json_value(request),
                "request": _json_value(request),
                "state": "pending",
            },
            "history_id": None,
            "next_context": None,
            "startup_binding": None,
            "reservation_binding": None,
            "dispatch_intent": None,
            "reservation_version": 1,
            "reservation_id": request["reservation_id"],
            "prior_watermark": request["prior_watermark"],
            "next_watermark": request["prior_watermark"],
            "state": "preparation-pending",
            "uncertainty": None,
        }
        rollover["integrity_digest"] = self._native_record_integrity(
            rollover, "integrity_digest"
        )
        self._native_invocation_rollovers[rollover_id] = rollover
        return rollover_id, rollover, request

    def _native_commit_rollover_locked(
            self, operation: Operation, rollover_id: str,
            response: Mapping[str, Any], *, persist: bool = True,
    ) -> Dict[str, Any]:
        rollover = self._native_invocation_rollovers.get(rollover_id)
        if rollover is None:
            raise _error("unknown", "native rollover reservation is unknown")
        request = rollover["preparation_intent"].get("request")
        if not isinstance(request, Mapping):
            raise _error("invalid", "native rollover preparation request is missing")
        response = self._validate_native_prepare_response(request, response)
        if response.get("state") == "busy":
            rollover["uncertainty"] = {
                "stage": "preparation",
                "code": "busy",
                "reason": "parent-not-terminal",
                "reservation_outcome": "not-reserved",
            }
            rollover["integrity_digest"] = self._native_record_integrity(
                rollover, "integrity_digest"
            )
            self._persist({
                "event": "native-rollover-busy",
                "operation_id": operation.operation_id,
                "rollover_id": rollover_id,
            })
            raise _error("busy", "native coordinator invocation remains busy")
        current = self._current_operation(operation.operation_id, operation.generation)
        if current.phase != "released":
            raise _error("busy", "native rollover operation is no longer released")
        daemon_id = self._native_daemon_id_locked()
        if daemon_id != request["daemon_id"]:
            raise _error("stale-generation", "native rollover daemon incarnation changed")
        context = self._native_context
        if not isinstance(context, Mapping) or context["invocation_id"] != request["prior_invocation_id"]:
            raise _error("stale-generation", "native rollover prior invocation changed")
        coordinator = self._participants.get(self._coordinator_id or "")
        if (
            coordinator is None
            or coordinator.participant_id != request["participant_id"]
            or coordinator.session_id != request["session_id"]
            or coordinator.metadata.get("runner_instance_id") != request["runner_incarnation"]
        ):
            raise _error("ownership-conflict", "native rollover coordinator identity changed")
        lineage = context["lineage"]
        if (
            _digest(context["definitions"]) != request["definitions_digest"]
            or _digest(self._native_prepare_permissions(context["definitions"]))
            != request["permissions_digest"]
            or _digest(lineage["workspace_claim"]) != request["claim_digest"]
        ):
            raise _error("ownership-conflict", "native rollover definitions or claim changed")
        history_id = "history-" + uuid.uuid4().hex
        if history_id in self._native_invocation_history:
            raise _error("invalid", "native invocation history identity was reused")
        proof = response["terminal_proof"]
        lineage = context["lineage"]
        history_context = copy.deepcopy(context)
        history_context["fenced"] = True
        history = {
            **native_record_marker("native-invocation-history"),
            "history_schema": 1,
            "history_id": history_id,
            "integrity_digest": "",
            "operation_id": operation.operation_id,
            "owner_generation": operation.generation,
            "lineage_id": lineage["lineage_id"],
            "lineage_generation": lineage["lineage_generation"],
            "daemon_id": request["daemon_id"],
            "coordinator": {
                "participant_id": request["participant_id"],
                "session_uuid": request["session_id"],
            },
            "runner_incarnation": request["runner_incarnation"],
            "invocation_id": request["prior_invocation_id"],
            "mailbox_id": request["prior_mailbox_id"],
            "context": _json_value(history_context),
            "admissions": _json_value(self._native_admissions),
            "terminal_controls": {
                "native_stops": _json_value(self._native_stops),
                "coordinator_interrupts": _json_value(self._coordinator_interrupts),
                "release_receipts": _json_value(
                    current.metadata.get("release_receipts", {})
                ),
            },
            "terminal_result": _json_value(proof["parent_result"]),
            "independent_drain": {
                "observation_watermark": response["terminal_watermark"],
                "uncertainty": _json_value(proof["uncertainty"]),
                "overflow": proof["overflow"],
            },
            "joined_roster": _json_value(proof["roster"]),
            "terminal_watermark": response["terminal_watermark"],
            "source_watermark": request["prior_watermark"],
            "terminal_proof_digest": response["terminal_proof_digest"],
            "runtime_correlation": {
                "reservation_id": request["reservation_id"],
                "state": response["state"],
            },
        }
        if self._native_child_observations_present:
            history["native_child_observations"] = _json_value(
                self._native_child_observations
            )
        history["integrity_digest"] = self._native_record_integrity(
            history, "integrity_digest"
        )
        next_context = copy.deepcopy(context)
        next_context["invocation_id"] = request["next_invocation_id"]
        next_context["invocation_watermark"] = response["next_watermark"]
        next_context["fenced"] = False
        next_context = self._validate_native_context(next_context)
        startup = current.metadata.get("native_startup")
        if not isinstance(startup, Mapping):
            raise _error("invalid", "native rollover startup binding is missing")
        startup_binding = _json_value(dict(startup))
        startup_binding["invocation_id"] = request["next_invocation_id"]
        startup_binding["invocation_bound"] = True
        dispatch_intent = {
            "message_id": request["next_mailbox_id"],
            "operation_id": operation.operation_id,
            "attempt": 1,
        }
        rollover.update({
            "history_id": history_id,
            "next_context": _json_value(next_context),
            "startup_binding": startup_binding,
            "reservation_binding": _json_value(response),
            "dispatch_intent": dispatch_intent,
            "next_watermark": response["next_watermark"],
            "state": "send-pending",
            "uncertainty": None,
        })
        entry = self._mailboxes.get(request["next_mailbox_id"])
        if entry is None or entry.state != "queued":
            raise _error("ownership-conflict", "native rollover mailbox changed before binding")
        entry.dispatch_attempt += 1
        entry.state = "dispatch-intent"
        entry.operation_id = operation.operation_id
        self._native_invocation_history[history_id] = history
        # A's admission/stop/interrupt ledgers are historical facts, not live
        # authority for B.  Retire them atomically with the context switch so
        # the next invocation starts with empty mutable ledgers and cannot
        # collide with or mutate A-owned IDs.
        self._native_admissions.clear()
        # Child observations are source-A facts.  Source archival captures
        # them before this retirement; they cannot remain in the live B map
        # where the A invocation/claim would be validated against B.
        self._native_child_observations.clear()
        self._native_stops.clear()
        self._coordinator_interrupts.clear()
        sealed = operation.metadata.get("sealed_native_admissions")
        if isinstance(sealed, list):
            operation.metadata["sealed_native_admissions"] = []
        operation.metadata.pop("coordinator_interrupt_selection", None)
        self._native_context = next_context
        current.metadata["native_startup"] = startup_binding
        rollover["integrity_digest"] = self._native_record_integrity(
            rollover, "integrity_digest"
        )
        if persist:
            self._persist({
                "event": "native-rollover-bound",
                "operation_id": operation.operation_id,
                "rollover_id": rollover_id,
                "history_id": history_id,
                "message_id": entry.message_id,
            })
        return _json_value(rollover)

    @_transactional
    def native_invocation_dispatch_binding(
            self, generation: Any, participant_id: str,
            runner_instance_id: str, message_id: str, *,
            session_id: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Return the exact committed context/reservation for one dispatch."""

        generation = self._generation_valid(generation)
        self._check_generation(generation)
        message_id = _id(message_id, "native dispatch message ID") or ""
        mailbox = self._mailboxes.get(message_id)
        operation = self._active_operation()
        if operation is None and self._active_operation_id is not None:
            candidate = self._operations.get(self._active_operation_id)
            if candidate is not None and candidate.phase == "released":
                operation = candidate
        if (
            mailbox is None
            or operation is None
            or operation.generation != generation
            or mailbox.recipient_id != participant_id
            or mailbox.operation_id != operation.operation_id
            or mailbox.generation != generation
            or mailbox.state not in {"dispatch-intent", "acknowledged", "uncertain"}
        ):
            raise _error("ownership-conflict", "native dispatch is not the committed mailbox")
        context = self._native_context
        if context is None:
            bound = self._bind_native_invocation_locked(
                generation, participant_id, runner_instance_id, message_id,
                session_id=session_id,
            )
            return {"context": _json_value(bound), "reservation_binding": None}
        if context["invocation_id"] != message_id:
            rollover = None
            for candidate in self._native_invocation_rollovers.values():
                if candidate.get("next_mailbox_id") == message_id:
                    rollover = candidate
                    break
            if rollover is None or rollover.get("reservation_binding") is None:
                raise _error("busy", "native dispatch has no committed rollover reservation")
            if rollover.get("state") not in {
                "send-pending", "delivered", "reconciled",
            }:
                raise _error("busy", "native dispatch reservation is not committed")
            if runner_instance_id != context["runner_incarnation"]:
                raise _error("stale-generation", "native dispatch runner changed")
            if session_id is not None and session_id != context["lineage"]["session_uuid"]:
                raise _error("ownership-conflict", "native dispatch coordinator session changed")
            return {
                "context": _json_value(context),
                "reservation_binding": _json_value(rollover["reservation_binding"]),
            }
        if runner_instance_id != context["runner_incarnation"]:
            raise _error("stale-generation", "native dispatch runner changed")
        if session_id is not None and session_id != context["lineage"]["session_uuid"]:
            raise _error("ownership-conflict", "native dispatch coordinator session changed")
        rollover = self._native_rollover_for_mailbox_locked(
            self._active_operation_id or "", message_id
        )
        return {
            "context": _json_value(context),
            "reservation_binding": (
                _json_value(rollover["reservation_binding"])
                if rollover is not None else None
            ),
        }

    def _bind_native_invocation_locked(

            self, generation: int, participant_id: str,
            runner_instance_id: str, invocation_id: str,
            session_id: Optional[str] = None,
    ) -> Optional[Dict[str, Any]]:
        context = self._native_context
        participant_id = _id(participant_id, "native invocation participant_id") or ""
        runner_instance_id = _id(runner_instance_id, "native invocation runner_instance_id") or ""
        invocation_id = _id(invocation_id, "native invocation_id") or ""
        coordinator = self._participants.get(self._coordinator_id or "")
        if coordinator is None or participant_id != coordinator.participant_id:
            raise _error("ownership-conflict", "native invocation is not for the coordinator")
        if session_id is not None and session_id != coordinator.session_id:
            raise _error("ownership-conflict", "native invocation coordinator session changed")
        operation = self._active_operation()
        if operation is None and self._active_operation_id is not None:
            candidate = self._operations.get(self._active_operation_id)
            if candidate is not None and candidate.phase == "released":
                operation = candidate
        if (
            operation is None or operation.generation != generation
            or operation.phase != "released"
        ):
            raise _error("busy", "native invocation requires a released coordinator")
        if coordinator.metadata.get("runner_instance_id") != runner_instance_id:
            raise _error("ownership-conflict", "native invocation coordinator runner changed")
        mailbox = self._mailboxes.get(invocation_id)
        if (mailbox is None or mailbox.message_id != invocation_id or
                mailbox.generation != generation or
                mailbox.recipient_id != participant_id or
                mailbox.operation_id != operation.operation_id or
                mailbox.state != "dispatch-intent" or
                mailbox.dispatch_attempt < 1):
            raise _error(
                "ownership-conflict",
                "native invocation is not the current durable coordinator mailbox",
            )
        startup = operation.metadata.get("native_startup")
        if context is None:
            if not isinstance(startup, Mapping):
                return None
            if (startup.get("participant_id") != participant_id or
                    startup.get("session_id") != coordinator.session_id):
                raise _error("stale-generation", "native startup identity changed")
            if startup.get("runner_incarnation") != runner_instance_id:
                # Startup preparation records the requested incarnation before
                # open.  The first durable mailbox bind may reconcile that
                # hint to the exact runner identity from the trusted open
                # evidence, but never to a caller-supplied transport ID.
                open_evidence = operation.metadata.get("open_evidence", {})
                evidence = (
                    open_evidence.get(participant_id)
                    if isinstance(open_evidence, Mapping) else None
                )
                evidence_runner = self._runtime_runner_instance(evidence)
                if evidence_runner != runner_instance_id:
                    raise _error("stale-generation", "native startup runner identity changed")
                startup = dict(startup)
                startup["runner_incarnation"] = runner_instance_id
                operation.metadata["native_startup"] = startup
            lineage = startup.get("lineage")
            definition_facts = startup.get("definitions")
            if not isinstance(lineage, Mapping) or not isinstance(definition_facts, Mapping):
                raise _error("invalid", "native startup metadata is incomplete")
            target_specs = operation.metadata.get("target_specs")
            if not isinstance(target_specs, Mapping):
                raise _error("invalid", "native startup target specifications are missing")
            target_spec = target_specs.get(participant_id)
            fingerprint = target_spec.get("fingerprint") if isinstance(target_spec, Mapping) else None
            definitions = fingerprint.get("trusted_definitions") if isinstance(fingerprint, Mapping) else None
            if not isinstance(definitions, Mapping) or not definitions:
                raise _error("unsupported", "native startup trusted definitions are unavailable")
            if self._native_definition_facts(definitions) != dict(definition_facts):
                raise _error("permission-mismatch", "native startup definitions changed")
            # This is the actual bind point: the mailbox ID is now durable and
            # no runtime send has happened yet.  Do not mutate a prepared
            # context or accept a transport request ID as a substitute.
            bound = self._register_native_context_locked(
                generation, lineage, runner_instance_id, invocation_id,
                definitions, invocation_watermark=1,
            )
            startup_value = dict(startup)
            startup_value["invocation_id"] = invocation_id
            startup_value["invocation_bound"] = True
            operation.metadata["native_startup"] = startup_value
            self._persist({
                "event": "native-coordinator-invocation-bound",
                "participant_id": participant_id,
                "invocation_id": invocation_id,
            })
            return bound
        if runner_instance_id != context["runner_incarnation"]:
            raise _error("stale-generation", "native invocation runner changed")
        current = context["invocation_id"]
        if current == invocation_id:
            return _json_value(context)
        raise _error("busy", "native coordinator invocation is already bound")

    @_transactional
    def bind_native_invocation(
            self, generation: Any, participant_id: str,
            runner_instance_id: str, invocation_id: str,
            session_id: Optional[str] = None,
    ) -> Optional[Dict[str, Any]]:
        """Bind the real durable mailbox ID before the first SDK query."""

        generation = self._generation_valid(generation)
        self._check_generation(generation)
        return self._bind_native_invocation_locked(
            generation, participant_id, runner_instance_id, invocation_id,
            session_id=session_id,
        )

    @_transactional
    def persist_native_admission(self, request_id: str, generation: Any,
                                 admission: Mapping[str, Any]) -> Dict[str, Any]:
        """Atomically persist pre-allow intent under the same lock as sealing."""
        request_id = _id(request_id, "native admission request ID") or ""
        _native_positive_generation(generation, "native admission generation")
        self._check_generation(generation)
        context = self._native_context
        if context is None:
            raise _error("unsupported", "native admission context is not registered")
        value = self._validate_native_admission(admission, context)
        self._check_native_authority(context)
        operation = self._operations.get(self._active_operation_id or "")
        if (context["fenced"] or operation is None or operation.phase != "released"
                or operation.generation != generation
                or operation.release_count != 1 or operation.uncertainty):
            raise _error("busy", "native admission is fenced until explicit release")
        coordinator = self._participants[self._coordinator_id]
        receipts = operation.metadata.get("release_receipts", {})
        if not isinstance(receipts, Mapping):
            raise _error("invalid", "native coordinator release receipts are malformed")
        released, reason = self._runtime_released(
            receipts.get(coordinator.participant_id), coordinator, operation,
            context["runner_incarnation"],
        )
        if not released:
            raise _error("uncertain-effect", "native coordinator release is unproven: " + reason)
        old = self._native_admissions.get(request_id)
        if old is not None:
            if old["digest"] != _digest(value):
                raise _error("invalid", "native admission request ID was reused with different content")
            return _json_value(old["ack"])
        if self._native_historical_identity_conflict(
                admission_id=value["admission_id"],
                tool_use_id=value["tool_use_id"],
        ):
            raise _error("invalid", "native admission identity was used by a terminal invocation")
        if request_id in self._requests:
            raise _error("invalid", "native admission request ID belongs to another operation")
        if len(self._native_admissions) >= 256:
            raise _error("busy", "native admission ledger requires reconciliation")
        for existing in self._native_admissions.values():
            prior = existing["admission"]
            if value["admission_id"] == prior["admission_id"] or value["tool_use_id"] == prior["tool_use_id"]:
                raise _error("invalid", "native admission identity was reused")
            if value["watermark"] <= prior["watermark"]:
                raise _error("stale-generation", "native admission watermark did not advance")
        parent_binding = None
        if value["parent"].get("agent_id") is not None:
            admissions = self._native_child_admission_bodies()
            observations = self._native_child_observation_bodies()
            parent_binding = self._native_child_call(
                _derive_native_parent_binding,
                value, context=context, admissions=admissions,
                observations=observations,
            )
            if parent_binding is None:
                raise _error("ownership-conflict", "nested native admission has no parent observation")
            self._native_child_call(
                _validate_native_parent_binding,
                value, parent_binding, context=context,
                admissions=admissions, observations=observations,
            )
            self._native_child_call(
                _require_live_native_parent,
                value, parent_binding, context=context, observations=observations,
            )
        ack = self._native_admission_ack(value)
        record = {
            **native_record_marker("pending-admission"), "request_id": request_id,
            "digest": _digest(value), "admission": value,
            "claim_ref": _json_value(context["lineage"]["workspace_claim"]), "ack": ack,
        }
        if parent_binding is not None:
            record["parent_observation"] = _json_value(parent_binding)
        self._native_admissions[request_id] = record
        self._persist({"event": "native-admission-persisted", "request_id": request_id,
                       "admission_id": value["admission_id"]})
        return _json_value(ack)

    @_transactional
    def persist_native_child_observation(
            self, observation_id: str, generation: Any,
            observation: Mapping[str, Any], *, expected_daemon_id: str,
    ) -> Dict[str, Any]:
        """Persist one joined native child observation under current authority.

        This is intentionally a controller-only callback.  It records no
        runtime capability and never creates a route, launch, or lifecycle
        operation for the observed child.
        """
        observation_id = _id(observation_id, "native child observation ID") or ""
        _native_positive_generation(generation, "native child observation generation")
        self._check_generation(generation)
        expected_daemon_id = _id(expected_daemon_id, "native child observation daemon ID") or ""
        context = self._native_context
        if context is None:
            raise _error("unsupported", "native child observation context is not registered")
        # Authority is checked before even looking at an idempotent row.  A
        # stale daemon must not use an old ACK as proof that it still owns the
        # source context.
        self._check_native_authority(context, expected_daemon_id=expected_daemon_id)
        source_identity = self._native_source_identity(generation, context)
        if any(
            isinstance(archive, Mapping)
            and archive.get("source_identity") == source_identity
            for archive in self._native_source_archives.values()
        ):
            raise _error("stale-generation", "native child source history is archived")
        source_operation = self._native_child_source_operation_locked(context)
        archived_source = any(
            isinstance(archive, Mapping)
            and archive.get("operation_id") == source_operation.operation_id
            for archive in self._native_source_archives.values()
        )
        if archived_source:
            raise _error("stale-generation", "native child source history is archived")

        incoming = _mapping(observation, "native child observation")
        incoming_id = incoming.get("observation_id")
        if incoming_id != observation_id:
            raise _error("invalid", "native child observation ID changed")
        child = incoming.get("child")
        child_admission_id = (
            child.get("admission_id") if isinstance(child, Mapping) else None
        )
        admission_record = next(
            (
                record for record in self._native_admissions.values()
                if isinstance(record, Mapping)
                and isinstance(record.get("admission"), Mapping)
                and record["admission"].get("admission_id") == child_admission_id
            ),
            None,
        )
        if admission_record is None:
            raise _error("ownership-conflict", "native child observation admission is unknown")
        admission = admission_record["admission"]
        normalized = self._native_child_join_observation(
            incoming, context=context, admission=admission,
        )
        digest = self._native_child_digest(normalized, "native child observation")
        run_id = _native_child_run_id(normalized)
        old = self._native_child_observations.get(observation_id)
        if old is not None:
            if (old.get("observation_digest") != digest
                    or old.get("child_run_id") != run_id
                    or old.get("observation") != normalized):
                raise _error("invalid", "native child observation ID was reused with different content")
            return _json_value(old["ack"])

        prior_entries = [
            record for record in self._native_child_observations.values()
            if record.get("child_run_id") == run_id
        ]
        status = normalized["child"]["status"]
        if context.get("fenced") is True and status == "active" and not prior_entries:
            raise _error("busy", "native child active observation is fenced")
        if context.get("fenced") is False and source_operation.phase != "released":
            raise _error("busy", "native child observation requires a released source")
        if context.get("fenced") is True and source_operation.phase not in {
            "paused", "indeterminate", "released",
        }:
            raise _error("stale-generation", "native child source is no longer observable")

        if len(prior_entries) >= _NATIVE_CHILD_OBSERVATIONS_PER_RUN_LIMIT:
            raise _error("busy", "native child observation run capacity is exhausted")
        prior_entries.sort(
            key=lambda record: record["observation"]["observation_watermark"]
        )
        if prior_entries:
            self._native_child_call(
                _validate_native_child_progress,
                prior_entries[-1]["observation"], normalized,
            )
        child_admission = normalized["child"]["admission_id"]
        child_tool = normalized["child"]["tool_use_id"]
        child_agent = normalized["child"]["agent_id"]
        child_task = normalized["child"]["task_id"]
        for existing in self._native_child_observations.values():
            if existing.get("child_run_id") == run_id:
                continue
            existing_child = existing.get("observation", {}).get("child", {})
            if any(
                existing_child.get(key) == value
                for key, value in (
                    ("admission_id", child_admission),
                    ("tool_use_id", child_tool),
                    ("agent_id", child_agent),
                    ("task_id", child_task),
                )
            ):
                raise _error("invalid", "native child identity was reused")
        if self._native_historical_identity_conflict(
                observation_id=observation_id,
                admission_id=child_admission,
                tool_use_id=child_tool,
                agent_id=child_agent,
                task_id=child_task,
        ):
            raise _error("invalid", "native child identity was used by a terminal invocation")
        prior_run_ids = {
            record.get("child_run_id")
            for record in self._native_child_observations.values()
        }
        if run_id not in prior_run_ids and len(prior_run_ids) >= _NATIVE_CHILD_OBSERVATION_LIMIT:
            raise _error("busy", "native child observation run capacity is exhausted")
        ack = {
            "recorded": True,
            "observation_id": observation_id,
            "observation_digest": digest,
            "child_run_id": run_id,
            "observation_watermark": normalized["observation_watermark"],
        }
        entry = {
            **native_record_marker("native-child-observation"),
            "observation_id": observation_id,
            "observation": _json_value(normalized),
            "observation_digest": digest,
            "child_run_id": run_id,
            "source_operation_id": source_operation.operation_id,
            "ack": ack,
        }
        self._native_child_observations_present = True
        self._native_child_observations[observation_id] = entry
        self._persist({
            "event": "native-child-observation-persisted",
            "observation_id": observation_id,
            "child_run_id": run_id,
            "source_operation_id": source_operation.operation_id,
        })
        return _json_value(ack)

    @contextlib.contextmanager
    def _transaction(self):
        """Take the shared store lock only around state read/mutation/write."""
        depth = int(getattr(self._transaction_local, "depth", 0))
        if depth:
            yield
            return
        lock = getattr(self.store, "locked", None)
        context = lock() if callable(lock) else self._local_lock
        with context:
            self._transaction_local.depth = depth + 1
            try:
                self._load()
                yield
            finally:
                self._transaction_local.depth = depth

    # ---- validation and request identity ------------------------------

    @staticmethod
    def _generation_valid(generation: Any) -> Any:
        if generation is None or isinstance(generation, bool):
            raise _error("invalid", "generation is required")
        if isinstance(generation, str) and not generation:
            raise _error("invalid", "generation is empty")
        if not isinstance(generation, (str, int, float)):
            raise _error("invalid", "generation is not scalar")
        return generation

    def _check_generation(self, generation: Any) -> None:
        self._generation_valid(generation)
        if self._generation is None or generation != self._generation:
            raise _error(
                "stale-generation",
                "generation %s does not match current generation %s"
                % (generation, self._generation),
            )

    def _admit_generation(self, generation: Any) -> None:
        """Admit the current owner generation or a proven monotonic rollover.

        ``start`` and ``enroll`` are both valid entry points after a durable
        unenrollment.  They must share the same owner proof; otherwise start
        would reject a valid new generation while enroll could accept one from
        a caller-controlled integer alone.
        """
        generation = self._generation_valid(generation)
        if self._generation is None:
            return
        if generation == self._generation:
            # A committed unenrollment closes the generation permanently.  A
            # controller reload keeps the old generation for stale-history
            # checks, so equality alone must not let a caller re-enroll that
            # generation after the roster/owner were cleared.
            if self._active_operation_id is None and any(
                operation.mode == "unenroll"
                and operation.generation == self._generation
                and operation.phase == "complete"
                for operation in self._operations.values()
            ):
                raise _error(
                    "stale-generation",
                    "the committed unenrollment generation cannot be reused",
                )
            return
        if (
            isinstance(self._generation, int)
            and not isinstance(self._generation, bool)
            and isinstance(generation, int)
            and not isinstance(generation, bool)
            and generation <= self._generation
        ):
            raise _error("stale-generation", "managed generation rollover is not monotonic")
        owner_reader = getattr(self.store, "read_owner", None)
        if not callable(owner_reader):
            raise _error(
                "unsupported",
                "generation rollover requires the authoritative state owner",
            )
        try:
            owner = owner_reader()
        except ControllerError:
            raise
        except Exception as exc:
            raise _error("ownership-conflict", "managed owner could not be verified: %s" % exc)
        if (
            not isinstance(owner, Mapping)
            or owner.get("mode") != "managed"
            or owner.get("generation") != generation
        ):
            raise _error(
                "stale-generation",
                "managed owner does not prove the requested generation rollover",
            )
        if self._participants or self._coordinator_id is not None or self._active_operation_id is not None:
            raise _error("busy", "managed controller still has an enrolled roster")
        if any(
            operation.phase not in _TERMINAL_OPERATION_PHASES
            for operation in self._operations.values()
        ):
            raise _error("uncertain-effect", "managed controller has unresolved prior operations")
        # Keep all old terminal operations, mail, archived identities, and
        # session history.  Only the active generation rolls forward.
        self._generation = generation

    def _validate_bound_lane(self, participant: Participant) -> None:
        """Bind participant guard identity to the store's canonical lane."""
        identity = getattr(self.store, "identity", None)
        canonical_lane = getattr(identity, "lane", None)
        if canonical_lane is not None and participant.bound_lane != canonical_lane:
            raise _error(
                "ownership-conflict",
                "participant bound_lane is not the durable lane identity",
            )

    def _request_seen(self, request_id: str, content: Any, kind: str) -> Any:
        if request_id in self._native_admissions:
            raise _error("invalid", "request ID belongs to a native admission")
        digest = _digest(content)
        old = self._requests.get(request_id)
        if old is not None:
            if old.get("digest") != digest:
                raise _error("invalid", "request ID was reused with different content")
            if old.get("kind") not in (None, kind):
                raise _error("invalid", "request ID was reused for another operation")
            result = old.get("result")
            if result is not None:
                return result
            return None
        self._requests[request_id] = {"digest": digest, "kind": kind, "result": None}
        return None

    def _save_request_result(self, request_id: str, result: Any) -> None:
        entry = self._requests.setdefault(request_id, {})
        entry["result"] = _json_value(result)

    @staticmethod
    def _validate_claimless_read_only(participant: Participant) -> None:
        """Require an explicit pre-execution read-only capability proof.

        A permission mode is not a capability boundary.  The durable roster
        therefore has to carry a concrete allowlist, a strict denylist, and
        an enforced allowlist policy.  Unknown MCP/tools are rejected rather
        than being treated as harmless omissions.
        """
        metadata = participant.metadata
        if metadata.get("read_only_enforced") is not True:
            raise _error(
                "permission-mismatch",
                "claimless participants require enforced read-only tool controls",
            )

        raw_allow = metadata.get("tool_allowlist")
        if raw_allow is None:
            raw_allow = metadata.get("allowed_tools")
        if raw_allow is None:
            raw_allow = metadata.get("read_only_tools")
        if not isinstance(raw_allow, (list, tuple, set, frozenset)) or not raw_allow:
            raise _error(
                "permission-mismatch",
                "claimless participants require an explicit builtin tool allowlist",
            )
        allow = set()
        for value in raw_allow:
            if not isinstance(value, str) or not value.strip():
                raise _error("invalid", "read-only tool allowlist contains an invalid name")
            name = value.strip().casefold()
            if name.startswith("mcp__") or name not in _READ_ONLY_BUILTIN_TOOLS:
                raise _error("unsupported", "unknown or non-read-only tool is not allowed")
            allow.add(name)
        if "tools" in metadata:
            raw_tools = metadata.get("tools")
            if not isinstance(raw_tools, (list, tuple, set, frozenset)):
                raise _error("permission-mismatch", "read-only runtime tools are malformed")
            tool_names = set()
            for value in raw_tools:
                if not isinstance(value, str) or not value.strip():
                    raise _error("invalid", "read-only runtime tools contain an invalid name")
                tool_names.add(value.strip().casefold())
            if tool_names and tool_names != allow:
                raise _error("permission-mismatch", "runtime tools differ from the read-only allowlist")

        raw_deny = metadata.get("tool_denylist")
        if raw_deny is None:
            raw_deny = metadata.get("denylist")
        if not isinstance(raw_deny, (list, tuple, set, frozenset)):
            raise _error(
                "permission-mismatch",
                "claimless participants require an explicit pre-execution denylist",
            )
        deny = set()
        for value in raw_deny:
            if not isinstance(value, str) or not value.strip():
                raise _error("invalid", "read-only tool denylist contains an invalid name")
            deny.add(value.strip().casefold())
        if not all(group.intersection(deny) for group in _READ_ONLY_DENIAL_GROUPS):
            raise _error(
                "permission-mismatch",
                "read-only controls must deny writes, execution, and native participants",
            )

        # The permissions object is the persisted policy that the runtime
        # adapter consumes.  Requiring it prevents a descriptive metadata flag
        # from being mistaken for an actual PreToolUse boundary.
        permissions = metadata.get("permissions")
        if not isinstance(permissions, Mapping):
            raise _error(
                "permission-mismatch",
                "claimless participants require an enforced permission policy",
            )
        if permissions.get("mode") != "allowlist" or permissions.get("enforced") is not True:
            raise _error(
                "permission-mismatch",
                "claimless participants require an enforced allowlist policy",
            )
        permission_allow = permissions.get("allow")
        if not isinstance(permission_allow, (list, tuple, set, frozenset)):
            raise _error("permission-mismatch", "permission allowlist is missing")
        if any(not isinstance(value, str) or not value.strip() for value in permission_allow):
            raise _error("invalid", "permission allowlist contains an invalid name")
        if {value.strip().casefold() for value in permission_allow} != allow:
            raise _error("permission-mismatch", "permission allowlist differs from tool allowlist")
        permission_deny = permissions.get("deny")
        if not isinstance(permission_deny, (list, tuple, set, frozenset)):
            raise _error("permission-mismatch", "permission denylist is missing")
        if any(not isinstance(value, str) or not value.strip() for value in permission_deny):
            raise _error("invalid", "permission denylist contains an invalid name")
        permission_deny_names = {value.strip().casefold() for value in permission_deny}
        if not all(group.intersection(permission_deny_names) for group in _READ_ONLY_DENIAL_GROUPS):
            raise _error("permission-mismatch", "permission policy does not deny unsafe tools")

        mcp_servers = metadata.get("mcp_servers")
        if not isinstance(mcp_servers, (list, tuple, set, frozenset)) or mcp_servers:
            raise _error(
                "unsupported",
                "claimless participants cannot admit unknown MCP capabilities",
            )
        permission_mcp = permissions.get("mcp")
        if permission_mcp not in ([], (), set(), frozenset()):
            raise _error(
                "unsupported",
                "claimless participants cannot admit unknown MCP capabilities",
            )

        # If a caller records an explicit hook/configuration marker, it must
        # affirm enforcement.  Missing optional markers are covered by the
        # required strict policy above; a false marker is an explicit refusal.
        for key in ("pre_tool_use_enforced", "pre_execution_denied", "strict_tool_policy"):
            if key in metadata and metadata[key] is not True:
                raise _error("permission-mismatch", "read-only pre-execution controls are not enforced")

    @staticmethod
    def _reject_historical_rebind_state(value: Any, label: str) -> None:
        """Refuse the superseded cross-parent rebind projection unchanged."""
        if not isinstance(value, Mapping):
            return
        legacy_keys = {
            "ctx_rebind",
            "parent_task_history",
            "rebound_participants",
            "rebound_release_authorizations",
            "rebound_status_evidence",
        }
        if legacy_keys.intersection(value):
            raise _error(
                "schema-mismatch",
                "%s contains unsupported historical ctx rebind state" % label,
            )

    @staticmethod
    def _reject_historical_rebind_operation(operation: Operation) -> None:
        ManagedController._reject_historical_rebind_state(
            operation.metadata, "managed operation metadata"
        )
        ctx_intent = operation.metadata.get("ctx_intent")
        if isinstance(ctx_intent, Mapping) and ctx_intent.get("worker_policy") == "rebind":
            raise _error(
                "schema-mismatch",
                "managed operation uses the superseded ctx rebind policy",
            )
        request_content = operation.metadata.get("request_content")
        if (isinstance(request_content, Mapping) and
                request_content.get("mode") == "ctx" and
                request_content.get("worker_policy") == "rebind"):
            raise _error(
                "schema-mismatch",
                "managed operation request uses the superseded ctx rebind policy",
            )

    @staticmethod
    def _validate_participant(participant: Participant) -> None:
        if not isinstance(participant, Participant):
            raise _error("invalid", "participant must be a Participant")
        # The guard identity is part of the managed participant, not an
        # inherited environment hint.  Older callers may omit the explicit
        # session name while constructing a model; establish that bounded
        # default exactly once before the first durable validation.  The lane
        # may be recovered from an explicit writer claim, but never invented.
        metadata_session_name = participant.metadata.get("session_name")
        if participant.session_name is None and metadata_session_name is not None:
            participant.session_name = _optional_text(metadata_session_name, "session_name")
        elif (
            participant.session_name is not None
            and metadata_session_name is not None
            and participant.session_name != metadata_session_name
        ):
            raise _error("ownership-conflict", "participant session_name copies disagree")
        if participant.session_name is None:
            base = re.sub(r"[^A-Za-z0-9._-]+", "-", participant.participant_id).strip("-")
            if not base:
                base = "session"
            participant.session_name = _id("managed-" + base[: MAX_ID_LENGTH - 8], "session_name")

        metadata_lane = participant.metadata.get("bound_lane")
        claim_lane = participant.writer_claim.lane if participant.writer_claim is not None else None
        if participant.bound_lane is None:
            if metadata_lane is not None:
                participant.bound_lane = _optional_text(metadata_lane, "bound_lane")
            elif claim_lane is not None:
                participant.bound_lane = _optional_text(claim_lane, "bound_lane")
        elif metadata_lane is not None and participant.bound_lane != metadata_lane:
            raise _error("ownership-conflict", "participant bound_lane copies disagree")
        if participant.bound_lane is None:
            raise _error(
                "invalid",
                "managed participants require the canonical bound_lane",
            )
        if not _BOUND_LANE_RE.fullmatch(participant.bound_lane):
            raise _error("invalid", "bound_lane is not a canonical lane component")
        if claim_lane is not None and participant.bound_lane != claim_lane:
            raise _error("ownership-conflict", "writer claim lane differs from bound_lane")
        participant.metadata["session_name"] = participant.session_name
        participant.metadata["bound_lane"] = participant.bound_lane
        ManagedController._reject_historical_rebind_state(
            participant.metadata, "participant metadata"
        )
        role = participant.role.casefold()
        if role not in {"coordinator", "worker"}:
            raise _error("invalid", "participant role must be coordinator or worker")
        kind = participant.kind.casefold().replace(" ", "_")
        if kind in _BANNED_KIND_WORDS or any(
            word in kind for word in ("agent", "task", "team", "background", "detached")
        ):
            raise _error("unsupported", "native Agent/Task/team/background/detached participants are unsupported")
        if kind not in _ALLOWED_KIND_WORDS:
            raise _error("unsupported", "participant kind is not an independent top-level session")
        for name in (
            "native_agent",
            "native_task",
            "native_team",
            "team",
            "run_in_background",
            "background",
            "detached",
        ):
            value = participant.metadata.get(name)
            if value:
                raise _error("unsupported", "native Agent/Task/team/background/detached participants are unsupported")
        if participant.background or participant.detached:
            raise _error("unsupported", "native Agent/Task/team/background/detached participants are unsupported")
        if not isinstance(participant.read_only, bool):
            raise _error("invalid", "participant read_only must be boolean")
        if participant.read_only and participant.writer_claim is not None:
            raise _error("ownership-conflict", "read-only participants cannot own writer claims")
        if participant.role.casefold() == "worker" and not participant.parent_id:
            raise _error("invalid", "worker parent_id is required")
        if not participant.task_id:
            raise _error("invalid", "participant task_id is required")
        if participant.read_only:
            ManagedController._validate_claimless_read_only(participant)
        if participant.role.casefold() == "worker" and not participant.read_only and participant.writer_claim is None:
            raise _error("ownership-conflict", "writable worker requires an exclusive writer claim")
        if participant.role.casefold() == "coordinator" and not participant.read_only and participant.writer_claim is None:
            raise _error("ownership-conflict", "writable coordinator requires an exclusive writer claim")
        if not participant.mailbox_id:
            raise _error("invalid", "participant mailbox_id is required")

    @staticmethod
    def _validate_durable_participant(participant: Participant) -> None:
        """Reject secret-bearing participant metadata before durable writes."""
        ManagedController._validate_participant(participant)
        secret_key = _contains_secret_key(participant.metadata)
        if secret_key is not None:
            raise _error(
                "unsupported",
                "participant metadata contains credential or environment key %s" % secret_key,
            )
        if participant.writer_claim is not None:
            secret_key = _contains_secret_key(participant.writer_claim.to_dict())
            if secret_key is not None:
                raise _error(
                    "unsupported",
                    "writer claim metadata contains credential or environment key %s" % secret_key,
                )
        for key in ("runner_spec", "spec"):
            if key in participant.metadata:
                safe = _safe_runner_projection(
                    participant.metadata[key],
                    "participant metadata.%s" % key,
                )
                # Keep the durable object itself sanitized.  The adapter gets
                # the original ephemeral spec from its call boundary, while
                # reload/recovery only ever sees this projection.
                participant.metadata[key] = safe

    @staticmethod
    def _participant_request_projection(participant: Participant) -> Dict[str, Any]:
        """Stable request identity without raw metadata or prompt material."""
        result: Dict[str, Any] = {
            "participant_id": participant.participant_id,
            "session_id": participant.session_id,
            "session_name": participant.session_name,
            "bound_lane": participant.bound_lane,
            "role": participant.role,
            "parent_id": participant.parent_id,
            "task_id": participant.task_id,
            "mailbox_id": participant.mailbox_id,
            "kind": participant.kind,
            "read_only": participant.read_only,
            "model": participant.model,
            "permission_mode": participant.permission_mode,
            "fingerprint": _safe_json_projection(
                participant.fingerprint, "participant fingerprint"
            ) if participant.fingerprint is not None else None,
        }
        if participant.writer_claim is not None:
            claim = participant.writer_claim
            result["writer_claim"] = {
                "participant_id": claim.participant_id,
                "worktree": str(claim.worktree),
                "repository": str(claim.repository) if claim.repository is not None else None,
                "lane": claim.lane,
            }
        else:
            result["writer_claim"] = None
        return result

    @staticmethod
    def _validate_native_swap_metadata(value: Any, operation: Operation) -> Dict[str, Any]:
        """Validate one bounded mutable native same-UUID swap record."""
        if not isinstance(value, Mapping) or set(value) != _NATIVE_SWAP_FIELDS:
            raise _error("invalid", "durable native swap record fields are malformed")
        raw = _native_validate(
            value, record_kind="native-swap", label="durable native swap record"
        )
        if type(raw.get("swap_schema")) is not int or raw["swap_schema"] != _NATIVE_SWAP_SCHEMA:
            raise _error("invalid", "durable native swap schema is unsupported")
        if raw.get("state") not in _NATIVE_SWAP_STATES:
            raise _error("invalid", "durable native swap state is unsupported")
        _id(raw.get("request_epoch_id"), "native swap request epoch ID")
        _id(raw.get("daemon_id"), "native swap daemon ID")
        _id(raw.get("source_operation_id"), "native swap source operation ID")
        if operation.metadata.get("previous_active_operation_id") != raw["source_operation_id"]:
            raise _error("ownership-conflict", "durable native swap source operation changed")
        source_identity = raw.get("source_identity")
        if not isinstance(source_identity, Mapping):
            raise _error("invalid", "durable native swap source identity is malformed")
        expected_identity = {
            "owner_generation", "lineage_id", "lineage_generation",
            "session_uuid", "runner_incarnation", "invocation_id",
        }
        if set(source_identity) != expected_identity:
            raise _error("invalid", "durable native swap source identity fields are malformed")
        for key in ("lineage_id", "session_uuid", "runner_incarnation", "invocation_id"):
            _id(source_identity[key], "native swap source " + key)
        _native_positive_generation(source_identity["owner_generation"], "native swap source owner_generation")
        _native_positive_generation(source_identity["lineage_generation"], "native swap source lineage_generation")
        if source_identity["owner_generation"] != operation.generation:
            raise _error("stale-generation", "native swap source owner changed")
        for key in ("source_context_digest", "source_claim_digest", "target_spec_digest"):
            if (not isinstance(raw[key], str)
                    or re.fullmatch(r"[0-9a-f]{64}", raw[key]) is None):
                raise _error(
                    "invalid",
                    "durable native swap %s is not a SHA-256 digest" % key,
                )
        source_context = raw.get("source_context")
        if not isinstance(source_context, Mapping):
            raise _error("invalid", "durable native swap source context is malformed")
        source_context = ManagedController._validate_native_context(source_context)
        source_startup = raw.get("source_startup")
        if not isinstance(source_startup, Mapping):
            raise _error("invalid", "durable native swap startup binding is malformed")
        source_startup = _native_validate(
            source_startup,
            record_kind="coordinator-startup",
            label="durable native swap source startup",
        )
        if set(source_startup) != {
            "schema_version", "architecture", "record_kind", "participant_id",
            "session_id", "runner_incarnation", "lineage_id", "lineage_generation",
            "lineage", "definitions", "invocation_id", "invocation_bound",
        }:
            raise _error("invalid", "durable native swap source startup fields are malformed")
        if source_startup["lineage"] != source_context["lineage"]:
            raise _error("ownership-conflict", "durable native swap source lineage changed")
        if source_startup["runner_incarnation"] != source_context["runner_incarnation"]:
            raise _error("ownership-conflict", "durable native swap source runner changed")
        if source_startup["invocation_id"] != source_context["invocation_id"]:
            raise _error("ownership-conflict", "durable native swap source invocation changed")
        if source_startup["definitions"] != source_context["definitions"]:
            raise _error("permission-mismatch", "durable native swap source definitions changed")
        if (
            source_identity["owner_generation"] != source_context["lineage"]["owner_generation"]
            or source_identity["lineage_id"] != source_context["lineage"]["lineage_id"]
            or source_identity["lineage_generation"] != source_context["lineage"]["lineage_generation"]
            or source_identity["session_uuid"] != source_context["lineage"]["session_uuid"]
            or source_identity["runner_incarnation"] != source_context["runner_incarnation"]
            or source_identity["invocation_id"] != source_context["invocation_id"]
        ):
            raise _error("ownership-conflict", "durable native swap source identity changed")
        if raw["source_context_digest"] != _native_swap_digest(source_context):
            raise _error("invalid", "durable native swap source context digest changed")
        if raw["source_claim_digest"] != _native_swap_digest(
                source_context["lineage"]["workspace_claim"]
        ):
            raise _error("invalid", "durable native swap source claim digest changed")
        if not isinstance(raw.get("target_profile"), Mapping):
            raise _error("invalid", "durable native swap target profile is malformed")
        target_specs = raw.get("target_specs")
        if not isinstance(target_specs, Mapping) or not target_specs:
            raise _error("invalid", "durable native swap target specifications are malformed")
        for participant_id, spec in target_specs.items():
            _id(participant_id, "native swap target participant ID")
            normalized_spec = _safe_runner_projection(
                spec, "native swap target specification"
            )
            if normalized_spec != spec:
                raise _error("invalid", "durable native swap target specification changed")
        if len(target_specs) != 1:
            raise _error("invalid", "durable native swap target roster is not singular")
        target_spec = next(iter(target_specs.values()))
        if not isinstance(target_spec, Mapping):
            raise _error("invalid", "durable native swap target specification is missing")
        if raw["target_spec_digest"] != _native_swap_digest(target_spec):
            raise _error("invalid", "durable native swap target specification digest changed")
        target_fingerprint = target_spec.get("fingerprint")
        if not isinstance(target_fingerprint, Mapping):
            raise _error("invalid", "durable native swap target fingerprint is malformed")
        target_native_config = target_fingerprint.get("native_config")
        if (not isinstance(target_native_config, Mapping)
                or target_native_config.get("native_swap_target") is not True):
            raise _error(
                "invalid",
                "durable native swap target is missing its native_swap_target marker",
            )
        target_lineage = target_fingerprint.get("lineage_context")
        if not isinstance(target_lineage, Mapping) or set(target_lineage) != {
            "owner_generation", "lineage_id", "lineage_generation", "runner_incarnation"
        }:
            raise _error("invalid", "durable native swap target lineage context is malformed")
        for key, expected in (
            ("owner_generation", source_identity["owner_generation"]),
            ("lineage_id", source_identity["lineage_id"]),
            ("lineage_generation", source_identity["lineage_generation"]),
            ("runner_incarnation", raw["target_runner_incarnation"]),
        ):
            if target_lineage.get(key) != expected:
                raise _error("ownership-conflict", "durable native swap target lineage changed")
        if target_fingerprint.get("lineage_claim") != source_context["lineage"]["workspace_claim"]:
            raise _error("ownership-conflict", "durable native swap target claim changed")
        for key in ("target_runner_incarnation", "target_runner_instance_id",
                    "interrupt_id", "source_archive_id", "release_id",
                    "release_validation_id"):
            if raw[key] is not None:
                _id(raw[key], "native swap " + key)
        for key in ("interrupt_intent_digest", "source_archive_digest",
                    "release_intent_digest"):
            if raw[key] is not None:
                if (not isinstance(raw[key], str)
                        or re.fullmatch(r"[0-9a-f]{64}", raw[key]) is None):
                    raise _error(
                        "invalid",
                        "durable native swap %s is not a SHA-256 digest" % key,
                    )
        evidence = raw.get("native_swap_evidence")
        runtime_digest = raw.get("runtime_identity_digest")
        source_runtime_digest = raw.get("source_runtime_identity_digest")
        if (not isinstance(source_runtime_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", source_runtime_digest) is None):
            raise _error("invalid", "durable native swap source runtime identity is invalid")
        if not isinstance(evidence, Mapping):
            raise _error("invalid", "durable native swap evidence is malformed")
        capture = raw.get("entry_capture")
        if capture is not None:
            if not isinstance(capture, Mapping) or set(capture) != {
                "capture_id", "binding", "state", "observation_digest",
            }:
                raise _error("invalid", "durable native swap entry capture is malformed")
            _id(capture["capture_id"], "native swap entry capture ID")
            try:
                capture_binding = _validate_native_swap_binding(capture["binding"])
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
            if capture_binding.get("stage") != "entry":
                raise _error("invalid", "native swap entry capture stage is not entry")
            expected_capture_binding = {
                "schema_version": 2,
                "architecture": "native-coordinator-lineage",
                "record_kind": "native-swap-evidence-request",
                "stage": "entry",
                "operation_id": operation.operation_id,
                "owner_generation": operation.generation,
                "expected_daemon_id": raw["daemon_id"],
                "source_identity": _json_value(raw["source_identity"]),
                "source_context_digest": raw["source_context_digest"],
                "source_claim_digest": raw["source_claim_digest"],
                "target_spec_digest": raw["target_spec_digest"],
                "request_epoch_id": raw["request_epoch_id"],
                "interrupt_id": None,
                "interrupt_intent_digest": None,
                "source_archive_digest": None,
                "target_runner_incarnation": raw["target_runner_incarnation"],
                "release_id": None,
                "release_intent_digest": None,
                "release_boundary": None,
            }
            if capture_binding != expected_capture_binding:
                raise _error("ownership-conflict", "native swap entry capture binding changed")
            capture_state = capture["state"]
            if capture_state not in {"pending", "captured-unvalidated", "accepted"}:
                raise _error("invalid", "native swap entry capture state is unsupported")
            observation_digest = capture["observation_digest"]
            if capture_state == "pending":
                if observation_digest is not None:
                    raise _error("invalid", "pending native swap entry capture has an observation")
            elif (not isinstance(observation_digest, str)
                  or re.fullmatch(r"[0-9a-f]{64}", observation_digest) is None):
                raise _error("invalid", "native swap entry capture digest is malformed")
            if capture_state == "accepted":
                entry_record = evidence.get("entry")
                if (not isinstance(entry_record, Mapping)
                        or entry_record.get("evidence_digest") != observation_digest):
                    raise _error("invalid", "accepted native swap entry capture has no matching evidence")
            elif "entry" in evidence:
                raise _error("stale-generation", "native swap entry evidence precedes capture acceptance")
        if evidence:
            if not isinstance(runtime_digest, str):
                raise _error("invalid", "durable native swap runtime identity is missing")
            try:
                _validate_native_swap_stage_records(
                    evidence, runtime_identity_digest=runtime_digest
                )
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
        elif runtime_digest is not None:
            if (not isinstance(runtime_digest, str)
                    or re.fullmatch(r"[0-9a-f]{64}", runtime_digest) is None):
                raise _error("invalid", "durable native swap runtime identity is invalid")
        if raw.get("release_binding") is not None:
            try:
                _validate_native_swap_release_binding(raw["release_binding"])
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
        if raw.get("release_boundary") is not None:
            if raw.get("release_binding") is None:
                raise _error("invalid", "native swap release boundary has no binding")
            try:
                _validate_native_swap_boundary(
                    raw["release_boundary"], expected_binding=raw["release_binding"]
                )
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
        if raw.get("release_authorization") is not None:
            if raw.get("release_binding") is None or raw.get("release_validation_id") is None:
                raise _error("invalid", "native swap authorization is unbound")
            try:
                _validate_native_swap_authorization(
                    raw["release_authorization"],
                    expected_validation_id=raw["release_validation_id"],
                    expected_binding=raw["release_binding"],
                )
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
        evidence_stages = list(evidence)
        if evidence_stages and evidence_stages[0] != "entry":
            raise _error("invalid", "native swap evidence does not begin at entry")
        if "graph-drained" in evidence and "entry" not in evidence:
            raise _error("stale-generation", "native swap graph evidence has no entry proof")
        if "source-excluded" in evidence:
            if (raw.get("source_archive_digest") is None
                    or not isinstance(raw.get("shutdown_intent"), Mapping)
                    or raw["shutdown_intent"].get("state") != "complete"):
                raise _error(
                    "stale-generation",
                    "native swap source exclusion is not joined to its archive and shutdown",
                )
        if "target-held" in evidence:
            if ("source-excluded" not in evidence
                    or not isinstance(raw.get("target_open_intent"), Mapping)
                    or raw["target_open_intent"].get("state") != "ready"
                    or raw.get("target_runner_instance_id") is None):
                raise _error(
                    "stale-generation",
                    "native swap target-held evidence is not joined to source exclusion",
                )
        if "pre-release" in evidence:
            if ("target-held" not in evidence
                    or raw.get("release_id") is None
                    or raw.get("release_intent_digest") is None):
                raise _error(
                    "stale-generation",
                    "native swap pre-release evidence is not joined to its held target",
                )
        if "release-boundary" in evidence:
            if ("pre-release" not in evidence
                    or raw.get("release_binding") is None
                    or raw.get("release_receipt") is None
                    or raw.get("release_boundary") is None):
                raise _error(
                    "stale-generation",
                    "native swap release-boundary evidence is not fully joined",
                )
        if operation.phase == "ready-held":
            try:
                target_held_stages = NATIVE_SWAP_STAGES[:
                    NATIVE_SWAP_STAGES.index("target-held") + 1
                ]
                if any(stage not in evidence for stage in target_held_stages):
                    raise _error(
                        "invalid",
                        "ready-held native swap evidence prefix is incomplete",
                    )
                target_held_prefix = {
                    stage: evidence[stage] for stage in target_held_stages
                }
                _require_native_swap_stages(
                    target_held_prefix,
                    runtime_identity_digest=runtime_digest,
                    through_stage="target-held",
                )
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
        if operation.phase == "released":
            try:
                _require_native_swap_stages(
                    evidence,
                    runtime_identity_digest=runtime_digest,
                    through_stage="release-boundary",
                )
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
        if raw.get("state") == "released" and operation.phase != "released":
            raise _error("stale-generation", "native swap released state is not joined to phase")
        for key in ("worker_dispositions",):
            if not isinstance(raw[key], Mapping):
                raise _error("invalid", "durable native swap %s is malformed" % key)
        for key in ("shutdown_intent", "target_open_intent"):
            if raw[key] is not None and not isinstance(raw[key], Mapping):
                raise _error("invalid", "durable native swap %s is malformed" % key)
        if raw.get("release_receipt") is not None and not isinstance(raw["release_receipt"], Mapping):
            raise _error("invalid", "durable native swap release receipt is malformed")
        if raw.get("uncertainty") is not None and not isinstance(raw["uncertainty"], Mapping):
            raise _error("invalid", "durable native swap uncertainty is malformed")
        return _json_value(dict(raw))

    @staticmethod
    def _validate_durable_operation(operation: Operation) -> None:
        """Fail closed if a snapshot contains secret-bearing launch state."""
        ManagedController._reject_historical_rebind_state(
            operation.metadata, "durable operation metadata"
        )
        secret_key = _contains_secret_key(operation.metadata)
        if secret_key is not None:
            raise _error(
                "unsupported",
                "operation metadata contains credential or environment key %s" % secret_key,
            )
        native_adoption = operation.metadata.get("native_adoption")
        if native_adoption is not None:
            ManagedController._validate_native_adoption_reference(
                native_adoption, expected_operation_id=operation.operation_id,
            )
        native_swap = operation.metadata.get("native_swap")
        if native_swap is not None:
            ManagedController._validate_native_swap_metadata(native_swap, operation)
        for field_name in ("target_specs",):
            value = operation.metadata.get(field_name)
            if value is None:
                continue
            if not isinstance(value, Mapping):
                raise _error("invalid", "durable operation %s is malformed" % field_name)
            for participant_id, spec in value.items():
                _safe_runner_projection(spec, "durable %s for %s" % (field_name, participant_id))
        # These two records are the controller's durable control selection.
        # They are structural history on reload; liveness and send
        # authorization are rechecked by the live APIs.  A schema-valid
        # snapshot must still reject missing, changed, or partially written
        # epoch/selection fields rather than treating them as a fresh send.
        epoch = operation.metadata.get("coordinator_interrupt_epoch")
        native_fence_epoch = operation.metadata.get("native_fence_epoch")
        if epoch is None:
            if native_fence_epoch is not None:
                raise _error(
                    "invalid",
                    "durable native fence epoch has no coordinator request epoch",
                )
        elif (type(native_fence_epoch) is not int or native_fence_epoch <= 0):
            raise _error(
                "invalid",
                "durable native fence epoch is malformed",
            )
        if epoch is not None:
            epoch = _native_validate(
                epoch,
                record_kind="coordinator-request-epoch",
                label="durable coordinator request epoch",
            )
            epoch = _native_exact_fields(
                epoch,
                (
                    "schema_version", "architecture", "record_kind",
                    "request_epoch_id", "entry_at", "fence_epoch",
                ),
                "durable coordinator request epoch",
            )
            _id(epoch["request_epoch_id"], "durable coordinator request_epoch_id")
            entry_at = epoch["entry_at"]
            if (isinstance(entry_at, bool) or
                    not isinstance(entry_at, (int, float)) or
                    not math.isfinite(entry_at)):
                raise _error("invalid", "durable coordinator request epoch timestamp is invalid")
            _native_positive_generation(
                epoch["fence_epoch"], "durable coordinator fence_epoch"
            )
            if native_fence_epoch != epoch["fence_epoch"]:
                raise _error(
                    "stale-generation",
                    "durable native fence epoch does not match the request epoch",
                )
        selection = operation.metadata.get("coordinator_interrupt_selection")
        if selection is not None:
            if epoch is None:
                raise _error(
                    "invalid",
                    "durable coordinator interrupt selection has no request epoch",
                )
            selection = _native_exact_fields(
                selection,
                (
                    "operation_id", "interrupt_id", "fence_epoch",
                    "request_epoch_id", "capability_digest",
                ),
                "durable coordinator interrupt selection",
            )
            if selection["operation_id"] != operation.operation_id:
                raise _error(
                    "ownership-conflict",
                    "durable coordinator interrupt selection changed operation",
                )
            _id(selection["interrupt_id"], "durable coordinator interrupt_id")
            _native_positive_generation(
                selection["fence_epoch"], "durable coordinator selection fence_epoch"
            )
            _id(
                selection["request_epoch_id"],
                "durable coordinator selection request_epoch_id",
            )
            ManagedController._native_interrupt_digest(
                selection["capability_digest"],
                "durable coordinator selection capability_digest",
            )
            if (selection["request_epoch_id"] != epoch["request_epoch_id"] or
                    selection["fence_epoch"] != epoch["fence_epoch"]):
                raise _error(
                    "stale-generation",
                    "durable coordinator selection is outside its request epoch",
                )
        intents = operation.metadata.get("launch_intents")
        if intents is not None:
            if not isinstance(intents, Mapping):
                raise _error("invalid", "durable launch intents are malformed")
            for participant_id, intent in intents.items():
                if not isinstance(intent, Mapping):
                    raise _error("invalid", "durable launch intent is malformed")
                if "spec" in intent:
                    _safe_runner_projection(
                        intent["spec"], "durable launch intent for %s" % participant_id
                    )
        request_content = operation.metadata.get("request_content")
        if isinstance(request_content, Mapping):
            if request_content.get("mode") == "ctx":
                if request_content.get("worker_policy") == "rebind":
                    raise _error(
                        "schema-mismatch",
                        "durable ctx request uses the superseded rebind policy",
                    )
                if ("worker_mapping" in request_content and
                        request_content.get("worker_mapping") is not None):
                    raise _error(
                        "invalid",
                        "durable ctx request contains an unsupported worker mapping",
                    )
            if request_content.get("runner_specs") is not None:
                runner_specs = request_content.get("runner_specs")
                if not isinstance(runner_specs, Mapping):
                    raise _error("invalid", "durable operation runner_specs are malformed")
                for participant_id, spec in runner_specs.items():
                    _safe_runner_projection(
                        spec, "durable request runner specification for %s" % participant_id
                    )
        sealed = set(operation.sealed_participants)
        held = operation.metadata.get("held_participants")
        restart = operation.metadata.get("restart_participants")
        for field_name, value in (
            ("held_participants", held),
            ("restart_participants", restart),
        ):
            if value is None:
                continue
            if not isinstance(value, list):
                raise _error("invalid", "durable operation %s is malformed" % field_name)
            if any(not isinstance(item, str) or not item for item in value):
                raise _error("invalid", "durable operation %s contains an invalid participant" % field_name)
            if len(set(value)) != len(value):
                raise _error("invalid", "durable operation %s contains duplicate participants" % field_name)
            if not set(value).issubset(sealed):
                raise _error("invalid", "durable operation %s is outside its seal" % field_name)
        ctx_intent = operation.metadata.get("ctx_intent")
        if isinstance(ctx_intent, Mapping):
            policy = ctx_intent.get("worker_policy")
            if policy == "rebind":
                raise _error(
                    "schema-mismatch",
                    "durable ctx operation uses the superseded rebind policy",
                )
            if policy not in {"hold", "restart"}:
                raise _error("invalid", "ctx worker policy is unsupported")
            if restart and policy != "restart":
                raise _error("invalid", "ctx hold operation contains restart participants")
            if policy == "restart" and held is None:
                raise _error("invalid", "ctx restart operation has no held worker set")
            mapping = ctx_intent.get("worker_mapping")
            if mapping not in (None, {}):
                raise _error(
                    "invalid",
                    "durable ctx operation contains an unsupported worker mapping",
                )
        if "checkpoint" in operation.metadata:
            self_checkpoint = operation.metadata["checkpoint"]
            normalized_checkpoint = ManagedController._checkpoint_reference(self_checkpoint)
            if _json_value(normalized_checkpoint) != _json_value(self_checkpoint):
                raise _error("invalid", "durable operation checkpoint is not canonical")

    @staticmethod
    def _claim_for(participant: Participant) -> Optional[WriterClaim]:
        claim = participant.writer_claim
        if claim is None:
            return None
        if claim.participant_id != participant.participant_id:
            raise _error("ownership-conflict", "writer claim belongs to another participant")
        return claim

    def claim_lineage_workspace(
            self, lineage: Any, *, repository: Any = None,
            parent_read_only: Optional[bool] = None) -> LineageRecord:
        """Claim a native lineage workspace and return the real store row.

        This is a claim-boundary adapter, not a participant/lifecycle
        enrollment path.  It deliberately calls the state store's native
        API and reconstructs the returned record so lane, host, common-dir,
        and generation scope cannot be dropped by the controller.
        """

        if isinstance(lineage, LineageRecord):
            record = lineage
        else:
            record = LineageRecord.from_dict(lineage)
        method = getattr(self.store, "claim_lineage_workspace", None)
        if not callable(method):
            raise _error("unsupported", "managed state store lacks native lineage claims")
        claim = record.workspace_claim
        claim_repository = repository
        if claim_repository is None:
            claim_repository = claim.get("repository")
        if claim_repository is None:
            raise _error("unsupported", "native lineage claim has no repository identity")
        if parent_read_only is not None and not isinstance(parent_read_only, bool):
            raise _error("invalid", "native lineage parent_read_only is invalid")
        if parent_read_only is not None and parent_read_only != record.read_only:
            raise _error(
                "ownership-conflict",
                "native lineage parent_read_only does not match the lineage record",
            )
        read_only = record.read_only
        try:
            result = method(
                lineage_id=record.lineage_id,
                owner_generation=record.owner_generation,
                lineage_generation=record.lineage_generation,
                workspace=record.workspace,
                common_dir=record.common_dir,
                repository=claim_repository,
                parent_read_only=read_only,
                coordinator_session_uuid=record.session_uuid,
            )
        except ControllerError:
            raise
        except Exception as exc:
            raise _error(str(getattr(exc, "code", "ownership-conflict")),
                         "native lineage workspace claim refused: %s" % exc)
        if not isinstance(result, Mapping):
            raise _error("uncertain-effect", "native lineage workspace claim result is malformed")
        return LineageRecord.from_store_claim(
            result, session_uuid=record.session_uuid,
            transcript=record.transcript, read_only=read_only,
            state=record.state,
        )

    def claim_child_worktree(
            self, child: Any, worktree: Any = None, *,
            repository: Any = None) -> ChildTaskRecord:
        """Claim an optional isolated worktree for an actual native child."""

        method = getattr(self.store, "claim_child_worktree", None)
        if not callable(method):
            raise _error("unsupported", "managed state store lacks native child claims")
        if isinstance(child, ChildTaskRecord):
            raw_child = child.to_dict()
        else:
            raw_child = child
        if not isinstance(raw_child, Mapping):
            raise _error("invalid", "native child record is malformed")

        # A new child may introduce one claim, but a retry for an existing
        # native child must be checked against the exact state-store row
        # before its candidate workspace/generation reaches the claim API.
        # Otherwise a changed immutable claim can be mistaken for a new
        # request while retaining the same native agent/task identity.
        expected_claim: Optional[Mapping[str, Any]] = None
        claim_reader = getattr(self.store, "read_lineage_claims", None)
        if callable(claim_reader):
            try:
                claims = claim_reader()
            except ControllerError:
                raise
            except Exception as exc:
                raise _error(
                    "ownership-conflict",
                    "native child claim authority could not be read: %s" % exc,
                )
            if not isinstance(claims, list):
                raise _error("invalid", "native child claim authority is malformed")
            raw_lineage_id = raw_child.get("lineage_id")
            raw_agent_id = raw_child.get("agent_id")
            raw_task_id = raw_child.get("task_id")
            for candidate in claims:
                if not isinstance(candidate, Mapping):
                    raise _error("invalid", "native child claim authority is malformed")
                if (
                    candidate.get("claim_kind") == "child-worktree"
                    and candidate.get("lineage_id") == raw_lineage_id
                    and candidate.get("agent_id") == raw_agent_id
                    and candidate.get("task_id") == raw_task_id
                ):
                    expected_claim = candidate
                    break
        record = ChildTaskRecord.from_dict(
            raw_child, expected_claim=expected_claim
        )
        claim = record.claim_ref
        if claim.get("claim_kind") != "child-worktree":
            raise _error("unsupported", "native child does not select an isolated worktree claim")
        selected_worktree = worktree if worktree is not None else claim.get("worktree")
        selected_repository = repository if repository is not None else claim.get("repository")
        if selected_worktree is None or selected_repository is None:
            raise _error("unsupported", "native child claim lacks worktree/repository identity")
        try:
            result = method(
                lineage_id=record.lineage_id,
                child=None,
                worktree=selected_worktree,
                repository=selected_repository,
                coordinator_session_uuid=record.parent_links.get("session_uuid"),
                owner_generation=claim.get("owner_generation"),
                lineage_generation=claim.get("lineage_generation"),
                workspace=claim.get("workspace"),
                common_dir=claim.get("common_dir"),
                agent_id=record.agent_id,
                task_id=record.task_id,
                definition_digest=claim.get("definition_digest"),
                capability_digest=claim.get("capability_digest"),
            )
        except ControllerError:
            raise
        except Exception as exc:
            raise _error(str(getattr(exc, "code", "ownership-conflict")),
                         "native child worktree claim refused: %s" % exc)
        if not isinstance(result, Mapping):
            raise _error("uncertain-effect", "native child worktree claim result is malformed")
        return ChildTaskRecord.from_store_claim(record.to_dict(), result)

    # ---- roster --------------------------------------------------------

    @_transactional
    def enroll(self, generation: Any, coordinator: Participant) -> Participant:
        generation = self._generation_valid(generation)
        self._validate_durable_participant(coordinator)
        self._validate_bound_lane(coordinator)
        if coordinator.role.casefold() != "coordinator":
            raise _error("invalid", "enroll requires one coordinator participant")
        self._admit_generation(generation)
        if self._coordinator_id is not None:
            existing = self._participants.get(self._coordinator_id)
            if existing is not None and existing.to_dict() == coordinator.to_dict():
                return existing
            raise _error("busy", "managed lane already has a coordinator")
        if any(item.role.casefold() == "coordinator" for item in self._participants.values()):
            raise _error("busy", "managed lane already has a coordinator")
        if coordinator.participant_id in self._participants:
            raise _error("busy", "participant ID is already enrolled")
        if any(item.session_id == coordinator.session_id for item in self._participants.values()):
            raise _error("busy", "session UUID is already enrolled")
        if coordinator.participant_id in self._archived_participants:
            raise _error("ownership-conflict", "participant ID is reserved by prior enrollment")
        if any(
            item.session_id == coordinator.session_id
            for item in self._archived_participants.values()
        ) or coordinator.session_id in self._session_history:
            raise _error("ownership-conflict", "session UUID is reserved by prior enrollment")
        if any(item.mailbox_id == coordinator.mailbox_id for item in self._archived_participants.values()):
            raise _error("ownership-conflict", "mailbox identity is reserved by prior enrollment")
        # Claim before changing the in-memory generation/owner.  If the
        # global index refuses, this transaction leaves the current roster
        # untouched as well as leaving the durable snapshot untouched.
        self._claim_writer(coordinator)
        self._generation = generation
        self._coordinator_id = coordinator.participant_id
        self._participants[coordinator.participant_id] = coordinator
        self._session_history.add(coordinator.session_id)
        self._persist({"event": "enroll", "participant_id": coordinator.participant_id})
        return coordinator

    def _claim_writer(self, participant: Participant) -> None:
        claim = self._claim_for(participant)
        if claim is None:
            return
        method = getattr(self.store, "claim_writer", None) if self.store is not None else None
        if not callable(method):
            raise _error("unsupported", "managed writer claims require the global state store")
        try:
            result = method(participant.participant_id, claim.worktree, claim.repository)
        except ControllerError:
            raise
        except Exception as exc:
            code = getattr(exc, "code", "ownership-conflict")
            raise _error(str(code), "writer claim refused: %s" % exc)
        if isinstance(result, Mapping):
            claim.state = str(result.get("state", "active"))
            if result.get("lane") is not None:
                claim.lane = str(result.get("lane"))
            if result.get("repository") is not None:
                repository = result.get("repository")
                if not isinstance(repository, (str, Path)) or not Path(repository).is_absolute():
                    raise _error("invalid", "writer claim repository proof is not absolute")
                claim.repository = Path(repository)
            claim.metadata.update({key: value for key, value in result.items()
                                   if key not in {"state", "lane"}})

    def _transfer_writer_claim_exact(
        self,
        old_participant: Participant,
        new_participant: Participant,
        generation: Any,
    ) -> Mapping[str, Any]:
        """Atomically replace one exact shared claim after old-stop proof."""
        old_claim = self._claim_for(old_participant)
        new_claim = self._claim_for(new_participant)
        if old_claim is None:
            if new_claim is None:
                return {"state": "not-required"}
            raise _error("ownership-conflict", "new ctx coordinator has an unexpected writer claim")
        if new_claim is None:
            raise _error("ownership-conflict", "ctx claim transfer target has no exact claim")
        if old_claim.repository is None or old_claim.lane is None:
            raise _error(
                "unsupported",
                "ctx claim transfer requires the persisted repository and lane identity",
            )
        if isinstance(generation, bool) or not isinstance(generation, int) or generation <= 0:
            raise _error("invalid", "ctx claim transfer requires a positive integer generation")
        method = getattr(self.store, "transfer_writer_claim", None)
        if not callable(method):
            raise _error(
                "unsupported",
                "managed state store lacks atomic writer-claim transfer",
            )
        try:
            result = method(
                old_participant.participant_id,
                old_claim.worktree,
                old_claim.repository,
                old_claim.lane,
                generation,
                new_participant.participant_id,
            )
        except ControllerError:
            raise
        except Exception as exc:
            code = getattr(exc, "code", "ownership-conflict")
            raise _error(str(code), "writer claim transfer refused: %s" % exc)
        if not isinstance(result, Mapping):
            raise _error("uncertain-effect", "writer claim transfer result is malformed")
        if (
            result.get("participant_id") != new_participant.participant_id
            or result.get("state") != "active"
            or str(result.get("worktree")) != str(old_claim.worktree)
            or str(result.get("repository")) != str(old_claim.repository)
            or result.get("generation") != generation
        ):
            raise _error("uncertain-effect", "writer claim transfer result does not match the exact claim")
        old_claim.state = "released"
        new_claim.state = "active"
        if result.get("lane") is not None:
            new_claim.lane = str(result.get("lane"))
        new_claim.metadata.update({
            key: _json_value(value)
            for key, value in result.items()
            if key not in {"state", "lane"}
        })
        return _json_value(dict(result))

    def _trusted_claim_index_record(
        self,
        participant: Participant,
        generation: Any,
    ) -> Optional[Dict[str, Any]]:
        """Read the exact shared claim index under its own read lock.

        This is intentionally an internal state-store proof, not a public
        recovery payload.  The controller accepts a released local claim only
        when the authoritative owner generation and claim index agree that no
        exact active row remains.
        """
        owner_reader = getattr(self.store, "read_owner", None)
        claims_loader = getattr(self.store, "_load_claims", None)
        state_lock = getattr(self.store, "locked", None)
        if not all(callable(item) for item in (owner_reader, claims_loader, state_lock)):
            raise _error(
                "unsupported",
                "trusted shared claim reconciliation requires the managed state store",
            )
        try:
            owner = owner_reader()
            if not isinstance(owner, Mapping):
                raise _error("invalid", "managed owner proof is malformed")
            if owner.get("mode") == "managed":
                if owner.get("generation") != generation:
                    raise _error("stale-generation", "shared claim owner generation is stale")
            elif owner:
                raise _error("ownership-conflict", "shared claim owner is not managed")
            else:
                generation_loader = getattr(self.store, "_load_generation", None)
                if not callable(generation_loader):
                    raise _error("unsupported", "shared claim generation proof is unavailable")
                if generation_loader() != generation:
                    raise _error("stale-generation", "shared claim tombstone generation is stale")
            identity = getattr(self.store, "identity", None)
            lane_key = getattr(identity, "lane_key", None)
            if not isinstance(lane_key, str) or not lane_key:
                raise _error("unsupported", "shared claim lane identity is unavailable")
            with state_lock(shared=True):
                claims = claims_loader()
            if not isinstance(claims, list):
                raise _error("invalid", "shared claim index is malformed")
            matches = []
            expected_worktree = str(participant.writer_claim.worktree) if participant.writer_claim else None
            expected_repository = (
                str(participant.writer_claim.repository)
                if participant.writer_claim and participant.writer_claim.repository is not None
                else None
            )
            if participant.writer_claim is not None and expected_repository is None:
                repository_resolver = getattr(self.store, "_canonical_repository", None)
                if not callable(repository_resolver):
                    raise _error(
                        "unsupported",
                        "shared claim repository identity is unavailable",
                    )
                expected_repository = str(
                    repository_resolver(None, participant.writer_claim.worktree)
                )
            for claim in claims:
                if not isinstance(claim, Mapping):
                    raise _error("invalid", "shared claim index entry is malformed")
                if (
                    claim.get("lane_key") == lane_key
                    and claim.get("participant_id") == participant.participant_id
                    and claim.get("generation") == generation
                    and claim.get("worktree") == expected_worktree
                    and claim.get("repository") == expected_repository
                ):
                    matches.append(dict(claim))
            if len(matches) > 1:
                raise _error("ownership-conflict", "shared claim index has duplicate exact claims")
            return matches[0] if matches else None
        except ControllerError:
            raise
        except Exception as exc:
            raise _error("uncertain-effect", "shared claim index proof failed: %s" % exc)

    @_transactional
    def add_worker(self, participant: Participant) -> Participant:
        self._validate_durable_participant(participant)
        self._validate_bound_lane(participant)
        if participant.role.casefold() != "worker":
            raise _error("invalid", "add_worker requires a worker participant")
        if self._coordinator_id is None:
            raise _error("busy", "managed lane has no coordinator")
        if participant.parent_id != self._coordinator_id:
            raise _error("invalid", "worker parent_id must name the enrolled coordinator")
        active = self._active_operation()
        if active is not None and active.phase not in _TERMINAL_OPERATION_PHASES:
            raise _error("busy", "participant admission is fenced by operation %s" % active.operation_id)
        if participant.participant_id in self._participants:
            raise _error("busy", "participant ID is already enrolled")
        if any(item.session_id == participant.session_id for item in self._participants.values()):
            raise _error("busy", "session UUID is already enrolled")
        # Claim before publishing the participant.  A rejected claim leaves
        # the roster untouched and the store's global index authoritative.
        self._claim_writer(participant)
        self._participants[participant.participant_id] = participant
        self._session_history.add(participant.session_id)
        self._persist({"event": "add-worker", "participant_id": participant.participant_id})
        return participant

    async def add_worker_held(
        self,
        request_id: str,
        generation: Any,
        participant: Participant,
        runner_spec: Mapping[str, Any],
    ) -> Operation:
        """Enroll and open one worker into a durable ready-held operation.

        This is the launch-bearing worker-admission boundary.  It performs
        every profile, transcript, permission, identity, and writer-claim
        check before publishing the roster or calling the runtime.  The
        launch intent and participant reservation are then durable before the
        single exact ``open(participant_id, spec)`` await.  No prompt or send
        is ever issued by this method.
        """
        request_id = _id(request_id, "request_id") or ""
        generation = self._generation_valid(generation)
        if not isinstance(participant, Participant):
            raise _error("invalid", "add_worker_held participant must be a Participant")
        if participant.role.casefold() != "worker":
            raise _error("invalid", "add_worker_held requires a worker participant")
        if participant.state.casefold() not in {"reserved", "held"}:
            raise _error("invalid", "add_worker_held requires a reserved or held worker")
        if not isinstance(runner_spec, Mapping):
            raise _error("invalid", "add_worker_held runner_spec must be an object")
        opener = getattr(self.runtime, "open", None) if self.runtime is not None else None
        if not callable(opener):
            raise _error("unsupported", "managed runtime open is unavailable")

        # Validate all caller-controlled durable material before touching the
        # request ledger, writer index, or roster.  In particular, this keeps
        # environment/auth/settings bags out of launch intent snapshots.
        self._validate_durable_participant(participant)
        self._validate_bound_lane(participant)
        raw_spec = _safe_runner_projection(
            runner_spec, "add-worker runner specification"
        )
        # Request identity is based on caller-supplied stable participant and
        # spec semantics, not on profile/transcript facts that adoption may
        # refresh after the first successful launch.  This lets an exact
        # retry after a reload resolve its original durable operation before
        # duplicate-roster or active-operation checks run.
        stable_participant = {
            "participant_id": participant.participant_id,
            "session_id": participant.session_id,
            # Guard identity is part of the caller's admission semantics,
            # even when the raw runner spec omits it.  This keeps an exact
            # retry tied to the persisted per-participant name/lane and makes
            # a changed name or lane a request conflict rather than a second
            # launch attempt.
            "session_name": participant.session_name,
            "bound_lane": participant.bound_lane,
            "role": participant.role,
            "parent_id": participant.parent_id,
            "task_id": participant.task_id,
            "mailbox_id": participant.mailbox_id,
            "kind": participant.kind,
            "read_only": participant.read_only,
            "writer_claim": (
                {
                    "worktree": str(participant.writer_claim.worktree),
                    "repository": (
                        str(participant.writer_claim.repository)
                        if participant.writer_claim.repository is not None
                        else None
                    ),
                    "lane": participant.writer_claim.lane,
                }
                if participant.writer_claim is not None
                else None
            ),
        }
        request_content = {
            "mode": "add-worker",
            "generation": generation,
            "participant": stable_participant,
            "runner_spec": _json_value(raw_spec),
        }
        _digest(request_content)

        operation_id: Optional[str] = None
        operation: Optional[Operation] = None
        with self._transaction():
            self._check_generation(generation)
            was_seen = request_id in self._requests
            if was_seen:
                seen = self._request_seen(request_id, request_content, "operation")
                if not isinstance(seen, Mapping):
                    raise _error(
                        "uncertain-effect",
                        "add-worker request was recorded without a durable result",
                    )
                stored = Operation.from_dict(seen)
                current = self._operations.get(stored.operation_id)
                if current is None:
                    raise _error(
                        "invalid",
                        "add-worker request ledger points to a missing operation",
                    )
                if current.phase in {"ready-held", "released"}:
                    return current
                raise _error(
                    "uncertain-effect",
                    "add-worker launch requires explicit recovery",
                )
            coordinator = self._participants.get(self._coordinator_id or "")
            if coordinator is None or coordinator.role.casefold() != "coordinator":
                raise _error("unknown", "managed lane has no enrolled coordinator")
            active = self._active_operation()
            if active is not None:
                raise _error(
                    "busy",
                    "participant admission is fenced by operation %s" % active.operation_id,
                )
            if participant.parent_id != coordinator.participant_id:
                raise _error(
                    "invalid",
                    "worker parent_id must name the enrolled coordinator",
                )
            all_participants = list(self._participants.values()) + list(
                self._archived_participants.values()
            )
            if any(item.participant_id == participant.participant_id for item in all_participants):
                raise _error("busy", "participant ID is already enrolled or archived")
            if any(item.session_id == participant.session_id for item in all_participants):
                raise _error("ownership-conflict", "session UUID is already enrolled or archived")
            if any(item.mailbox_id == participant.mailbox_id for item in all_participants):
                raise _error("invalid", "mailbox identity is already enrolled or archived")

            profile = self._participant_profile_summary(participant)
            provisional = Operation(
                operation_id="add-worker-preflight-" + uuid.uuid4().hex,
                request_id=request_id,
                mode="add-worker",
                generation=generation,
                phase="preflight",
            )
            spec = self._swap_spec(
                participant,
                provisional,
                profile,
                {participant.participant_id: raw_spec},
            )
            transcript = self._trusted_transcript_preflight(
                participant, profile, spec
            )
            self._apply_transcript_preflight(participant, transcript)
            self._request_seen(request_id, request_content, "operation")

            # Claim admission and roster publication share this transaction;
            # a rejected global claim leaves no visible worker or operation.
            self._claim_writer(participant)
            participant.state = "held"
            self._participants[participant.participant_id] = participant
            self._session_history.add(participant.session_id)
            operation = Operation(
                operation_id="op-" + uuid.uuid4().hex,
                request_id=request_id,
                mode="add-worker",
                generation=generation,
                phase="starting",
                sealed_participants=(participant.participant_id,),
                metadata={
                    "request_content": _json_value(request_content),
                    "target_profile": _json_value(profile),
                    "target_specs": {
                        participant.participant_id: _json_value(spec),
                    },
                    "transcript_preflight": {
                        participant.participant_id: _json_value(transcript),
                    },
                    "runner_instances": {},
                    "launch_processes": {},
                    "open_evidence": {},
                    "launch_intents": {
                        participant.participant_id: {
                            "state": "pending",
                            "participant_id": participant.participant_id,
                            "session_id": participant.session_id,
                            "generation": generation,
                            "spec": _json_value(spec),
                        },
                    },
                },
            )
            self._operations[operation.operation_id] = operation
            self._active_operation_id = operation.operation_id
            operation_id = operation.operation_id
            self._carry_unsent_mail(operation)
            self._save_request_result(request_id, operation.to_dict())
            self._persist({
                "event": "add-worker-launch-intent",
                "operation_id": operation_id,
                "participant_id": participant.participant_id,
            })

        # Mark the crossing of the runtime boundary in its own durable write.
        # This distinguishes a never-attempted pending intent from a call
        # whose outcome must be reconciled rather than replayed.
        with self._transaction():
            current = self._current_operation(operation_id or "", generation)
            intent = current.metadata.get("launch_intents", {}).get(
                participant.participant_id
            )
            if not isinstance(intent, Mapping) or intent.get("state") != "pending":
                raise _error("uncertain-effect", "worker launch intent is unresolved")
            current.metadata["launch_intents"][participant.participant_id] = {
                **dict(intent),
                "state": "in-progress",
                "started_at": self.clock(),
            }
            self._persist({
                "event": "add-worker-open-intent",
                "operation_id": operation_id,
                "participant_id": participant.participant_id,
            })

        try:
            opened = opener(participant.participant_id, dict(spec))
            if not inspect.isawaitable(opened):
                raise TypeError("managed runtime open must be awaitable")
            opened = await opened
            # Register the adapter incarnation and OS identity immediately
            # after open returns, before readiness interpretation.
            with self._transaction():
                current = self._current_operation(operation_id or "", generation)
                current_participant = self._participants.get(participant.participant_id)
                if current_participant is None:
                    raise _error("unknown", "added worker is no longer enrolled")
                runner_instance = self._runtime_runner_instance(opened)
                if runner_instance is None:
                    raise ValueError("worker open response has no runner instance identity")
                process = self._runtime_process(opened, "add-worker-open")
                current.metadata["runner_instances"][participant.participant_id] = runner_instance
                current.metadata["launch_processes"][participant.participant_id] = _json_value(process)
                current.metadata["launch_intents"][participant.participant_id] = {
                    **dict(current.metadata["launch_intents"][participant.participant_id]),
                    "state": "registered",
                    "runner_instance_id": runner_instance,
                    "process": _json_value(process),
                }
                self._persist({
                    "event": "add-worker-launch-registered",
                    "operation_id": operation_id,
                    "participant_id": participant.participant_id,
                })
                operation = current

            valid, reason = self._runtime_ready(opened, current_participant, operation, spec)
            if not valid:
                raise ValueError(reason)
            runner_instance = self._runtime_runner_instance(opened)
            if runner_instance is None:
                raise ValueError("worker open response has no runner instance identity")
            with self._transaction():
                current = self._current_operation(operation_id or "", generation)
                current_participant = self._participants.get(participant.participant_id)
                if current_participant is None:
                    raise _error("unknown", "added worker is no longer enrolled")
                profile = current.metadata.get("target_profile")
                if not isinstance(profile, Mapping):
                    raise _error("invalid", "added worker profile evidence is missing")
                self._adopt_target_runner(
                    current_participant,
                    spec,
                    profile,
                    runner_instance_id=runner_instance,
                    process=process,
                )
                current.metadata["open_evidence"][participant.participant_id] = _json_value(opened)
                current.metadata["launch_intents"][participant.participant_id] = {
                    **dict(current.metadata["launch_intents"][participant.participant_id]),
                    "state": "ready",
                }
                current.readiness[participant.participant_id] = {
                    "session_id": participant.session_id,
                    "runner_instance_id": runner_instance,
                    "spec": _json_value(spec),
                    "evidence": _json_value(opened),
                }
                current.phase = "ready-held"
                current.metadata["ready_generation"] = generation
                self._persist({
                    "event": "add-worker-ready-held",
                    "operation_id": operation_id,
                    "participant_id": participant.participant_id,
                })
                return current
        except BaseException as exc:
            self._mark_operation_failure(
                operation_id or "",
                "add-worker:%s" % participant.participant_id,
                "uncertain-effect",
                str(exc),
            )
            if isinstance(exc, asyncio.CancelledError):
                raise
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "worker launch outcome is uncertain")

    # ---- operation and mailbox state ----------------------------------

    def _active_operation(self) -> Optional[Operation]:
        if self._active_operation_id is None:
            return None
        operation = self._operations.get(self._active_operation_id)
        if operation is None or operation.phase in _TERMINAL_OPERATION_PHASES:
            return None
        return operation

    def _carry_unsent_mail(self, operation: Operation) -> None:
        """Attach only unsent backlog to a newly active lifecycle gate.

        A released operation may leave queued or fenced entries behind when
        their recipient was busy.  Those entries retain their message,
        recipient, ordering, and hold state while moving to the new gate.
        Acknowledged, in-flight, and uncertain effects are never migrated.
        Archived recipients are intentionally excluded; ctx owns their
        explicit archival policy and must not retarget their mail.
        """
        for entry in self._mailboxes.values():
            if entry.generation != operation.generation:
                continue
            if entry.recipient_id not in self._participants:
                continue
            if entry.state not in {"queued", "fenced"}:
                continue
            if entry.operation_id == operation.operation_id:
                continue
            if entry.operation_id is None:
                entry.operation_id = operation.operation_id
                continue
            previous = self._operations.get(entry.operation_id)
            if previous is not None and previous.phase in _TERMINAL_OPERATION_PHASES:
                entry.operation_id = operation.operation_id

    @_transactional
    def begin_operation(
        self,
        request_id: str,
        mode: str,
        generation: Any,
        request_content: Any = None,
    ) -> Operation:
        request_id = _id(request_id, "request_id") or ""
        generation = self._generation_valid(generation)
        self._check_generation(generation)
        if not isinstance(mode, str) or not mode or "\x00" in mode:
            raise _error("invalid", "operation mode is required")
        content = {"request_id": request_id, "mode": mode, "generation": generation}
        if request_content is not None:
            # Swap inputs are part of the durable request identity.  A retry
            # with a different target profile/specification must not reuse a
            # previously created operation.
            content["request_content"] = request_content
        was_seen = request_id in self._requests
        seen = self._request_seen(request_id, content, "operation")
        if was_seen:
            if not isinstance(seen, Mapping):
                # The request ledger itself is durable authority.  A request
                # that was recorded without its operation result cannot safely
                # be replayed or replaced by a new operation.
                raise _error(
                    "uncertain-effect",
                    "operation request was recorded without a durable result",
                )
            stored_operation = Operation.from_dict(seen)
            current_operation = self._operations.get(stored_operation.operation_id)
            if current_operation is None:
                raise _error(
                    "invalid",
                    "operation request ledger points to a missing operation",
                )
            return current_operation
        active = self._active_operation()
        if active is not None:
            raise _error("busy", "operation %s is already active" % active.operation_id)
        operation = Operation(
            operation_id="op-" + uuid.uuid4().hex,
            request_id=request_id,
            mode=mode,
            generation=generation,
            phase="preflight",
            metadata=(
                {"request_content": _json_value(request_content)}
                if request_content is not None
                else {}
            ),
        )
        self._operations[operation.operation_id] = operation
        if mode == "swap" and self._active_operation_id is not None:
            operation.metadata["previous_active_operation_id"] = self._active_operation_id
        self._active_operation_id = operation.operation_id
        self._save_request_result(request_id, operation.to_dict())
        self._persist({"event": "begin-operation", "operation_id": operation.operation_id,
                       "mode": operation.mode})
        return operation

    def _operation(self, operation_id: str) -> Operation:
        operation_id = _id(operation_id, "operation_id") or ""
        operation = self._operations.get(operation_id)
        if operation is None:
            raise _error("unknown", "managed operation %s is unknown" % operation_id)
        if self._active_operation_id != operation_id and operation.phase not in _TERMINAL_OPERATION_PHASES:
            raise _error("busy", "another managed operation is active")
        return operation

    @_transactional
    def fence(self, operation_id: str) -> Operation:
        operation = self._operation(operation_id)
        if operation.phase in _TERMINAL_OPERATION_PHASES:
            return operation
        if operation.phase not in {"preflight", "quiescing"}:
            raise _error("busy", "operation %s cannot be fenced in phase %s" %
                         (operation.operation_id, operation.phase))
        operation.phase = "paused"
        operation.sealed_participants = tuple(self._participants.keys())
        if self._native_context is not None:
            self._native_context["fenced"] = True
            operation.metadata["sealed_native_admissions"] = [
                value["admission"]["admission_id"] for value in self._native_admissions.values()
            ]
        for entry in self._mailboxes.values():
            if entry.generation != operation.generation:
                continue
            if entry.state not in {"queued", "fenced"}:
                # Acknowledged, in-flight, and uncertain transport effects
                # retain their original operation/correlation forever.
                continue
            if entry.recipient_id not in self._participants:
                # Archived coordinator mail is not silently retargeted by a
                # later swap/ctx gate.
                continue
            if entry.operation_id not in (None, operation.operation_id):
                previous = self._operations.get(entry.operation_id)
                if previous is None or previous.phase not in _TERMINAL_OPERATION_PHASES:
                    continue
            entry.state = "fenced"
            entry.operation_id = operation.operation_id
        self._persist({"event": "fence", "operation_id": operation.operation_id,
                       "sealed_participants": list(operation.sealed_participants)})
        return operation

    # ---- promptless swap lifecycle ------------------------------------

    @staticmethod
    def _profile_summary(profile: Any) -> Dict[str, Any]:
        """Extract only non-secret launch identity from a resolved profile."""
        if profile is None:
            raise _error("profile-mismatch", "an explicit target profile is required")
        if isinstance(profile, str):
            raise _error(
                "unsupported",
                "swap requires a resolved active OAuth profile, not a profile name",
            )
        name = _get(profile, "name", "profile_name", default=None)
        email = _get(profile, "email", "account_email", default=None)
        family = _get(profile, "family", "storage_family", default=None)
        status = _get(profile, "status", default=None)
        authentication = _get(profile, "authentication", "auth", default=None)
        config_dir = _get(profile, "config_dir", "profile_dir", default=None)
        transcript_store = _get(
            profile,
            "transcript_store",
            "canonical_transcript_store",
            "projects_transcript_store",
            default=None,
        )
        transcript_project = _get(
            profile,
            "transcript_project",
            "canonical_project",
            "projects_project",
            default=None,
        )
        transcript_holder = _get(
            profile,
            "transcript_holder",
            "canonical_transcript_holder",
            "projects_transcript_holder",
            default=None,
        )
        if not all(isinstance(value, str) and value for value in (name, email, family)):
            raise _error("profile-mismatch", "target profile identity is incomplete")
        if str(status).casefold() != "active":
            raise _error("unsupported", "target profile is not actively eligible")
        auth_type = _get(authentication, "type", "kind", default=None)
        if str(auth_type).casefold().replace("-", "_") != "subscription_oauth":
            raise _error(
                "unsupported",
                "target profile does not have an eligible subscription OAuth capability",
            )
        if config_dir is not None and not isinstance(config_dir, (str, Path)):
            raise _error("invalid", "target profile config directory is invalid")
        result: Dict[str, Any] = {
            "name": name,
            "email": email,
            "family": family,
            "status": "active",
            "authentication": {"type": "subscription_oauth"},
        }
        if config_dir is not None:
            result["config_dir"] = str(config_dir)
        if transcript_store is not None:
            result["transcript_store"] = _json_value(transcript_store)
        if transcript_project is not None:
            result["transcript_project"] = _json_value(transcript_project)
        if transcript_holder is not None:
            result["transcript_holder"] = _json_value(transcript_holder)
        return result

    @staticmethod
    def _participant_profile_family(participant: Participant) -> Optional[str]:
        value = participant.metadata.get(
            "profile_family",
            participant.metadata.get("family", participant.metadata.get("storage_family")),
        )
        return value if isinstance(value, str) and value else None

    @staticmethod
    def _participant_workspace(participant: Participant) -> Optional[str]:
        value = participant.metadata.get(
            "workspace",
            participant.metadata.get("transcript_store", participant.metadata.get("cwd")),
        )
        if value is None and participant.writer_claim is not None:
            value = participant.writer_claim.worktree
        if isinstance(value, Path):
            return str(value)
        return value if isinstance(value, str) and value else None

    @staticmethod
    def _participant_profile_summary(participant: Participant) -> Dict[str, Any]:
        """Resolve the already-bound profile used by an initial runner start."""
        metadata = participant.metadata
        profile: Dict[str, Any] = {
            "name": metadata.get("profile_name"),
            "email": metadata.get("account_email"),
            "family": metadata.get("profile_family"),
            "status": metadata.get("profile_status"),
            "authentication": metadata.get("profile_authentication"),
            "config_dir": metadata.get("config_dir"),
        }
        for key in (
            "transcript_store",
            "transcript_project",
            "transcript_holder",
        ):
            if key in metadata:
                profile[key] = metadata.get(key)
        return ManagedController._profile_summary(profile)

    @staticmethod
    def _checkpoint_reference(value: Any) -> Any:
        """Validate and bound an explicit checkpoint reference or record."""
        if value is None or isinstance(value, bool):
            raise _error("invalid", "an explicit checkpoint is required")
        if isinstance(value, str):
            return _opaque_payload_reference(value, "checkpoint")
        # A structured checkpoint is still a reference, never a transcript
        # body.  Only the stable reference and its optional content digest may
        # cross the controller boundary.
        if not isinstance(value, Mapping):
            raise _error("invalid", "checkpoint must be an opaque reference")
        if not set(value).issubset({"ref", "digest"}):
            raise _error("unsupported", "checkpoint contains body or unbounded content")
        if "ref" not in value and "digest" not in value:
            raise _error("invalid", "checkpoint reference is empty")
        normalized: Dict[str, Any] = {}
        if "ref" in value:
            normalized["ref"] = _opaque_payload_reference(value["ref"], "checkpoint.ref")
        if "digest" in value:
            digest = value["digest"]
            if (
                not isinstance(digest, str)
                or len(digest) != 64
                or any(char not in "0123456789abcdef" for char in digest)
            ):
                raise _error("invalid", "checkpoint digest is malformed")
            normalized["digest"] = digest
        return normalized

    def _trusted_transcript_preflight(
        self,
        participant: Participant,
        profile: Mapping[str, Any],
        spec: Mapping[str, Any],
        *,
        allow_reserved_written_promotion: bool = False,
    ) -> Dict[str, Any]:
        """Prove the canonical projects store and current transcript holder.

        The participant metadata and runner spec are inputs, not proof.  The
        exact injected seam is ``transcript_verifier(profile_name, session_id,
        workspace)``; its native resolver facts are interpreted here by phase.
        A bare store/path, ``trusted`` flag, or public profile field can never
        authorize swap.
        """
        source_store = participant.metadata.get(
            "transcript_store", participant.metadata.get("transcript_path")
        )
        target_store = profile.get("transcript_store")
        if target_store is None:
            target_store = spec.get("transcript_store", spec.get("transcript_path"))

        verifier = self.transcript_verifier
        evidence: Any = None
        if not callable(verifier):
            raise _error(
                "unknown",
                "canonical transcript store and holder verifier is unavailable",
            )
        try:
            # Only the injected resolver can authorize this boundary.  Public
            # profile/spec fields are diagnostic inputs, not self-certifying
            # proof of a projects-directory holder.
            workspace = self._participant_workspace(participant)
            if workspace is None:
                raise _error("unknown", "participant workspace is unavailable")
            evidence = verifier(profile["name"], participant.session_id, workspace)
        except ControllerError:
            raise
        except Exception as exc:
            raise _error("unknown", "trusted transcript preflight could not be read: %s" % exc)
        if not isinstance(evidence, Mapping):
            raise _error("unknown", "canonical transcript preflight result is malformed")
        returned_profile = evidence.get("profile")
        if returned_profile is None:
            raise _error("unknown", "canonical transcript profile identity is missing")
        if isinstance(returned_profile, Mapping):
            returned_name = _get(returned_profile, "name", "profile_name", default=None)
            if returned_name != profile["name"]:
                raise _error("profile-mismatch", "canonical transcript profile differs from the target")
            returned_email = _get(returned_profile, "email", "account_email", default=None)
            if returned_email is not None and returned_email != profile["email"]:
                raise _error("account-mismatch", "canonical transcript profile account differs from the target")
            returned_family = _get(returned_profile, "family", "storage_family", default=None)
            if returned_family is not None and returned_family != profile["family"]:
                raise _error("profile-mismatch", "canonical transcript profile family differs from the target")
            returned_config = _get(returned_profile, "config_dir", "profile_dir", default=None)
            if returned_config is not None and str(returned_config) != str(profile.get("config_dir")):
                raise _error("profile-mismatch", "canonical transcript profile config differs from the target")
        elif returned_profile != profile["name"]:
            raise _error("profile-mismatch", "canonical transcript profile differs from the target")
        returned_session = evidence.get("session_id")
        if returned_session != participant.session_id:
            raise _error("profile-mismatch", "canonical transcript evidence has the wrong session UUID")
        returned_workspace = evidence.get("workspace")
        expected_workspace = self._participant_workspace(participant)
        if returned_workspace is None or expected_workspace is None:
            raise _error("unknown", "canonical transcript workspace evidence is missing")
        if str(returned_workspace) != str(expected_workspace):
            raise _error("profile-mismatch", "canonical transcript workspace differs from the participant")
        if evidence.get("ambiguous") is True or evidence.get("unknown_holders") in (True, "unknown"):
            raise _error("unknown", "canonical transcript holder evidence is ambiguous")
        actual_store = evidence.get("transcript_store")
        if actual_store is None:
            raise _error("unknown", "canonical transcript store evidence is missing")
        if source_store is None:
            raise _error("profile-mismatch", "participant transcript store is missing")
        if _json_value(actual_store) != _json_value(source_store):
            raise _error("profile-mismatch", "canonical transcript store differs from the participant")
        if target_store is not None and _json_value(actual_store) != _json_value(target_store):
            raise _error("profile-mismatch", "target canonical transcript store differs from the participant")

        expected_project = profile.get("transcript_project") or spec.get("transcript_project")
        actual_project = evidence.get("transcript_project")
        if expected_project is not None and _json_value(actual_project) != _json_value(expected_project):
            raise _error("profile-mismatch", "canonical transcript project differs from the target")

        holders = evidence.get("holders")
        if not isinstance(holders, list):
            raise _error("unknown", "canonical transcript holders are missing or malformed")
        if len(holders) > 1:
            raise _error("ownership-conflict", "canonical transcript holder is ambiguous")
        unknown_holders = evidence.get("unknown_holders")
        if unknown_holders not in (None, False, [], ()):
            raise _error("unknown", "canonical transcript holder domain is unknown")
        holder = holders[0] if holders else None
        mode = str(spec.get("mode", "resume")).casefold()
        transcript = _get(
            evidence,
            "transcript",
            "transcript_identity",
            "transcript_evidence",
            default=None,
        )
        if not isinstance(transcript, Mapping):
            raise _error("unknown", "canonical transcript identity evidence is missing")
        if transcript.get("session_id") != participant.session_id:
            raise _error("profile-mismatch", "canonical transcript UUID does not match the participant")
        for key in ("exists", "written", "reserved"):
            if key not in transcript or not isinstance(transcript.get(key), bool):
                raise _error("unknown", "canonical transcript identity evidence is malformed")
        promote_reserved_written = bool(
            allow_reserved_written_promotion
            and mode == "fresh"
            and transcript.get("exists") is True
            and transcript.get("written") is True
            and transcript.get("reserved") is False
            and isinstance(holders, list)
            and len(holders) == 1
            and evidence.get("unknown_holders") in (None, False, [], ())
        )
        effective_mode = "resume" if promote_reserved_written else mode
        if mode == "fresh" and holder is not None and not promote_reserved_written:
            raise _error("ownership-conflict", "initial fresh UUID has a live or unknown holder")
        # A fresh reserved UUID has no projects holder yet.  ``None`` is a
        # positive empty-holder fact from the trusted verifier, not unknown.
        if holder is None:
            if mode != "fresh" and isinstance(participant.metadata.get("runner_process"), Mapping):
                raise _error("unknown", "canonical transcript holder evidence is missing")
        else:
            if isinstance(holder, (list, tuple, set, frozenset)):
                if len(holder) != 1:
                    raise _error("ownership-conflict", "canonical transcript holder is ambiguous")
                holder = next(iter(holder))
            if not isinstance(holder, Mapping):
                raise _error("unknown", "canonical transcript holder evidence is malformed")
            if holder.get("unknown") is True or holder.get("ambiguous") is True:
                raise _error("unknown", "canonical transcript holder evidence is ambiguous")
            if "authoritative" in holder and holder.get("authoritative") is not True:
                raise _error("unknown", "canonical transcript holder is not authoritative")
            if "live" in holder and holder.get("live") is not True:
                raise _error("ownership-conflict", "canonical transcript holder is not live")
            if "state" in holder and str(holder.get("state")).casefold() not in {
                "active", "held", "owned", "live"
            }:
                raise _error("ownership-conflict", "canonical transcript holder is not active")
            # Native holder records are deliberately not allowed to assert a
            # managed logical owner.  The controller binds the native facts
            # below to its enrolled participant; accepting a self-claimed ID
            # would turn untrusted holder JSON into authority.
            if any(
                key in holder
                for key in ("participant_id", "owner_participant_id", "owner", "runner_id")
            ):
                raise _error(
                    "ownership-conflict",
                    "canonical transcript holder contains a logical self-claim",
                )
            holder_session = _get(holder, "session_id", "session_uuid", default=None)
            if holder_session != participant.session_id:
                raise _error("ownership-conflict", "canonical transcript holder has the wrong session UUID")
            workspace = _get(holder, "workspace", "worktree", "cwd", default=None)
            expected_workspace = self._participant_workspace(participant)
            if workspace is None or expected_workspace is None:
                raise _error("unknown", "canonical transcript holder workspace identity is missing")
            if str(workspace) != str(expected_workspace):
                raise _error("ownership-conflict", "canonical transcript holder has the wrong workspace")
            source_profile_name = participant.metadata.get("profile_name")
            holder_profile_name = _get(holder, "profile_name", "profile", default=None)
            if not isinstance(source_profile_name, str) or not source_profile_name:
                raise _error("unknown", "participant source profile identity is missing")
            if not isinstance(holder_profile_name, str) or not holder_profile_name:
                raise _error("unknown", "canonical transcript holder profile identity is missing")
            if holder_profile_name != source_profile_name:
                raise _error(
                    "ownership-conflict",
                    "canonical transcript holder belongs to another source profile",
                )
            source_config = participant.metadata.get("config_dir")
            holder_config = _get(holder, "config_dir", "profile_dir", default=None)
            if source_config is not None:
                if holder_config is None:
                    raise _error("unknown", "canonical transcript holder config identity is missing")
                if str(holder_config) != str(source_config):
                    raise _error(
                        "ownership-conflict",
                        "canonical transcript holder belongs to another profile config",
                    )
            holder_store = _get(
                holder, "projects_store", "transcript_store", "store", default=None
            )
            if source_store is not None:
                if holder_store is None:
                    raise _error("unknown", "canonical transcript holder store identity is missing")
                if _json_value(holder_store) != _json_value(source_store):
                    raise _error(
                        "ownership-conflict",
                        "canonical transcript holder belongs to another transcript store",
                    )
            pid_domain = _get(holder, "pid_domain", "pidDomain", default=None)
            if pid_domain is None or not isinstance(pid_domain, str) or not pid_domain:
                raise _error("unknown", "canonical transcript holder PID domain is unknown")
            if pid_domain.casefold() in {"participant", "runner", "owned", "unknown", "local"}:
                raise _error("unknown", "canonical transcript holder PID domain is synthetic or unknown")
            expected_domain = None
            expected_process = participant.metadata.get("runner_process")
            if isinstance(expected_process, Mapping):
                expected_domain = expected_process.get("pid_domain")
            if expected_domain is not None and pid_domain != expected_domain:
                raise _error("ownership-conflict", "canonical transcript holder is in another process domain")
            if "process_group_member" in holder and holder.get("process_group_member") is not True:
                raise _error("ownership-conflict", "canonical transcript holder is not in the owned process group")
            # For an existing/resumed transcript, native holder facts must
            # correspond to the persisted runner process.  This prevents a
            # same-session or same-workspace process from claiming the store.
            holder_process = holder.get("process") if isinstance(holder.get("process"), Mapping) else holder
            if effective_mode != "fresh":
                if not isinstance(expected_process, Mapping):
                    raise _error("unknown", "current runner process identity is unavailable")
                if (
                    isinstance(holder_process.get("pid"), bool)
                    or not isinstance(holder_process.get("pid"), int)
                    or holder_process.get("pid") <= 0
                    or not isinstance(holder_process.get("process_start_token"), str)
                    or not holder_process.get("process_start_token")
                ):
                    raise _error("unknown", "canonical transcript holder native process identity is malformed")
                for key in ("pid", "process_start_token"):
                    if key not in holder_process or not holder_process.get(key):
                        raise _error("unknown", "canonical transcript holder native process identity is missing")
                if "process_group_id" not in holder_process:
                    raise _error("unknown", "canonical transcript holder process group is missing")
                if str(holder_process.get("process_group_id")) != str(expected_process.get("process_group_id")):
                    raise _error("ownership-conflict", "canonical transcript holder is outside the owned process group")
        if mode == "fresh" and not promote_reserved_written and (
            transcript.get("exists") is True or transcript.get("written") is True
        ):
            # A stale reserved marker cannot authorize a second fixed-ID
            # fresh launch once the canonical projects record was seeded.
            raise _error(
                "profile-mismatch",
                "known-written transcript cannot use a fresh fallback",
            )
        result = {
            "trusted": True,
            "profile": _json_value(evidence.get("profile")),
            "session_id": participant.session_id,
            "workspace": _json_value(returned_workspace),
            "transcript_store": _json_value(actual_store),
            "holders": _json_value(holders),
            "unknown_holders": _json_value(unknown_holders),
        }
        if actual_project is not None:
            result["transcript_project"] = _json_value(actual_project)
        result["transcript"] = _json_value(transcript)
        return result

    @staticmethod
    def _reserved_written_promotion(
            spec: Mapping[str, Any], evidence: Mapping[str, Any],
    ) -> bool:
        """Recognize the one swap-only fresh-to-written transition."""
        transcript = evidence.get("transcript")
        holders = evidence.get("holders")
        return bool(
            str(spec.get("mode", "resume")).casefold() == "fresh"
            and isinstance(transcript, Mapping)
            and transcript.get("exists") is True
            and transcript.get("written") is True
            and transcript.get("reserved") is False
            and isinstance(holders, list)
            and len(holders) == 1
            and evidence.get("unknown_holders") in (None, False, [], ())
        )

    @staticmethod
    def _resume_target_spec(spec: Mapping[str, Any]) -> Dict[str, Any]:
        """Make the recomputed swap target explicitly resume-only."""
        resumed = dict(spec)
        resumed["mode"] = "resume"
        resumed["resume"] = True
        resumed.pop("fresh", None)
        return resumed

    @staticmethod
    def _apply_transcript_preflight(
        participant: Participant,
        evidence: Mapping[str, Any],
    ) -> None:
        """Persist a trusted reserved-to-written transcript transition.

        A reserved UUID is valid only while the canonical projects lookup
        still proves that no transcript has been written.  Once that same
        lookup proves a written record, update the durable participant source
        and its current runner spec to resume mode so stale ``reserved`` flags
        cannot force a fresh launch on a later operation.
        """
        transcript = evidence.get("transcript")
        if not isinstance(transcript, Mapping):
            return
        if transcript.get("session_id") != participant.session_id:
            raise _error("profile-mismatch", "canonical transcript UUID does not match the participant")
        if transcript.get("exists") is not True or transcript.get("written") is not True:
            return
        participant.metadata["transcript"] = _json_value(transcript)
        runner_spec = participant.metadata.get("runner_spec", participant.metadata.get("spec"))
        if not isinstance(runner_spec, Mapping):
            return
        updated = dict(runner_spec)
        updated["mode"] = "resume"
        updated["resume"] = True
        updated.pop("fresh", None)
        participant.metadata["runner_spec"] = _json_value(updated)
        participant.metadata["spec"] = _json_value(updated)

    @staticmethod
    def _runtime_object(value: Any, label: str) -> Mapping[str, Any]:
        if dataclasses.is_dataclass(value) and not isinstance(value, type):
            value = _json_value(value)
        if not isinstance(value, Mapping):
            raise _error("uncertain-effect", "%s runtime evidence is malformed" % label)
        return value

    @staticmethod
    def _runtime_evidence(value: Any, label: str) -> Mapping[str, Any]:
        response = ManagedController._runtime_object(value, label)
        evidence = response.get("evidence")
        if not isinstance(evidence, Mapping):
            raise _error("uncertain-effect", "%s runtime evidence is missing" % label)
        return evidence

    @staticmethod
    def _runtime_runner_instance(value: Any) -> Optional[str]:
        response = ManagedController._runtime_object(value, "participant")
        runner_instance_id = response.get("runner_instance_id")
        if not isinstance(runner_instance_id, str) or not runner_instance_id:
            return None
        return runner_instance_id

    @staticmethod
    def _runtime_identity_matches(
        value: Any,
        participant: Participant,
        operation: Operation,
        *,
        require_session: bool = True,
        expected_runner_instance_id: Optional[str] = None,
    ) -> Tuple[bool, str]:
        """Check tags emitted by the exact per-participant runtime seam."""
        try:
            response = ManagedController._runtime_object(value, "participant")
            evidence = ManagedController._runtime_evidence(value, "participant")
        except ControllerError as exc:
            return False, exc.message
        participant_id = response.get("participant_id")
        if participant_id != participant.participant_id:
            return False, "runtime evidence has the wrong participant identity"
        session_id = response.get("session_id")
        if require_session and session_id != participant.session_id:
            return False, "runtime evidence has the wrong session UUID"
        if session_id != participant.session_id:
            return False, "runtime evidence has the wrong session UUID"
        runner_instance_id = response.get("runner_instance_id")
        if not isinstance(runner_instance_id, str) or not runner_instance_id:
            return False, "runtime evidence has no runner instance identity"
        if expected_runner_instance_id is not None and runner_instance_id != expected_runner_instance_id:
            return False, "runtime evidence has the wrong runner instance identity"
        if evidence.get("participant_id") != participant.participant_id:
            return False, "nested runtime evidence has the wrong participant identity"
        if evidence.get("session_id") != participant.session_id:
            return False, "nested runtime evidence has the wrong session UUID"
        if evidence.get("runner_instance_id") != runner_instance_id:
            return False, "nested runtime evidence has the wrong runner instance identity"
        return True, ""

    @staticmethod
    def _runtime_process(value: Any, label: str = "runtime") -> Mapping[str, Any]:
        """Validate the canonical process identity before readiness handling."""
        evidence = ManagedController._runtime_evidence(value, label)
        process = evidence.get("process")
        if not isinstance(process, Mapping):
            raise _error("uncertain-effect", "%s process evidence is missing" % label)
        required = (
            "pid",
            "process_group_id",
            "process_start_token",
            "process_group_owned",
            "exited",
            "group_excluded",
        )
        if any(key not in process for key in required):
            raise _error("uncertain-effect", "%s process evidence is incomplete" % label)
        if (
            isinstance(process.get("pid"), bool)
            or not isinstance(process.get("pid"), int)
            or process.get("pid") <= 0
            or not isinstance(process.get("process_group_id"), (str, int))
            or not isinstance(process.get("process_start_token"), str)
            or not process.get("process_start_token")
            or process.get("process_group_owned") is not True
        ):
            raise _error("uncertain-effect", "%s process identity is not owned" % label)
        return process

    @staticmethod
    def _runtime_quiescent(
        value: Any,
        participant: Participant,
        operation: Operation,
        expected_runner_instance_id: Optional[str] = None,
    ) -> Tuple[bool, str]:
        valid, reason = ManagedController._runtime_identity_matches(
            value,
            participant,
            operation,
            require_session=True,
            expected_runner_instance_id=expected_runner_instance_id,
        )
        if not valid:
            return False, reason
        evidence = ManagedController._runtime_evidence(value, "status")
        flags = (
            ("active_turn", False),
            ("turn_terminal", True),
            ("drained", True),
            ("participant_quiescent", True),
            ("tools_quiescent", True),
            ("quiescent", True),
        )
        if any(
            not isinstance(evidence.get(name), bool) or evidence.get(name) is not expected
            for name, expected in flags
        ):
            return False, "runtime status has not authoritatively drained"
        tools = evidence.get("tools")
        if not isinstance(tools, list):
            return False, "runtime tool evidence is missing"
        process = evidence.get("process")
        if not isinstance(process, Mapping):
            return False, "runtime process-group evidence is missing"
        required_process = (
            "pid",
            "process_group_id",
            "process_start_token",
            "process_group_owned",
            "exited",
            "group_excluded",
        )
        if any(key not in process for key in required_process):
            return False, "runtime process-group evidence is incomplete"
        if process.get("process_group_owned") is not True:
            return False, "old process group is not owned by this participant"
        uncertain = evidence.get("uncertain_effects")
        if not isinstance(uncertain, list) or uncertain:
            return False, "runtime evidence reports unknown effects"
        return True, ""

    @staticmethod
    def _runtime_shutdown(
        value: Any,
        participant: Participant,
        operation: Operation,
        expected_runner_instance_id: str,
    ) -> Tuple[bool, str]:
        valid, reason = ManagedController._runtime_identity_matches(
            value,
            participant,
            operation,
            require_session=True,
            expected_runner_instance_id=expected_runner_instance_id,
        )
        if not valid:
            return False, reason
        evidence = ManagedController._runtime_evidence(value, "shutdown")
        process = evidence.get("process")
        if not isinstance(process, Mapping):
            return False, "runtime shutdown process-group evidence is missing"
        required_process = (
            "pid",
            "process_group_id",
            "process_start_token",
            "process_group_owned",
            "exited",
            "group_excluded",
        )
        if any(key not in process for key in required_process):
            return False, "runtime shutdown process-group evidence is incomplete"
        if (
            process.get("process_group_owned") is not True
            or process.get("exited") is not True
            or process.get("group_excluded") is not True
        ):
            return False, "old process group has not exited and been excluded"
        if evidence.get("uncertain_effects") != []:
            return False, "runtime shutdown reports unknown effects"
        return True, ""

    @staticmethod
    def _runtime_released(
        value: Any,
        participant: Participant,
        operation: Operation,
        expected_runner_instance_id: str,
    ) -> Tuple[bool, str]:
        valid, reason = ManagedController._runtime_identity_matches(
            value,
            participant,
            operation,
            require_session=True,
            expected_runner_instance_id=expected_runner_instance_id,
        )
        if not valid:
            return False, reason
        evidence = ManagedController._runtime_evidence(value, "release")
        if evidence.get("released") is not True:
            return False, "runtime release was not acknowledged"
        if evidence.get("uncertain_effects") != []:
            return False, "runtime release reports unknown effects"
        return True, ""

    @staticmethod
    def _runtime_ready(
        value: Any,
        participant: Participant,
        operation: Operation,
        spec: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        # SDK initialization may omit session_id/model.  The exact UUID and
        # launch model are established by the prevalidated spec instead.
        valid, reason = ManagedController._runtime_identity_matches(
            value, participant, operation, require_session=True
        )
        if not valid:
            return False, reason
        evidence = ManagedController._runtime_evidence(value, "open")
        if any(
            spec.get(key) != getattr(participant, key)
            for key in ("session_name", "bound_lane")
        ):
            return False, "runtime guard identity does not match the participant"
        required_evidence = (
            "ready",
            "released",
            "active_turn",
            "turn_terminal",
            "drained",
            "participant_quiescent",
            "tools_quiescent",
            "uncertain_effects",
            "process",
            "initialization",
        )
        if any(key not in evidence for key in required_evidence):
            return False, "runtime ready evidence is incomplete"
        if evidence.get("ready") is not True:
            return False, "runtime initialization did not reach ready-held state"
        if any(
            not isinstance(evidence.get(key), bool) or evidence.get(key) is not expected
            for key, expected in (
                ("released", False),
                ("active_turn", False),
                ("turn_terminal", True),
                ("drained", True),
                ("participant_quiescent", True),
                ("tools_quiescent", True),
            )
        ) or evidence.get("uncertain_effects") != []:
            return False, "runtime ready evidence is not held and quiescent"
        try:
            process = ManagedController._runtime_process(value, "open")
        except ControllerError as exc:
            return False, exc.message
        if process.get("exited") is not False or process.get("group_excluded") is not False:
            return False, "ready-held runner process is not alive and exclusively present"
        initialization = evidence.get("initialization")
        if not isinstance(initialization, Mapping):
            return False, "runtime initialization evidence is missing"
        if any(key not in initialization for key in ("account_email", "permission_mode", "model", "fingerprint")):
            return False, "runtime initialization evidence is incomplete"
        expected_email = _get(spec, "account_email", default=None)
        actual_email = initialization.get("account_email")
        if expected_email is not None and actual_email != expected_email:
            return False, "runtime account identity does not match the selected profile"
        expected_permission = _get(spec, "permission_mode", default=None)
        actual_permission = initialization.get("permission_mode")
        if expected_permission is not None and actual_permission != expected_permission:
            return False, "runtime permission mode does not match the launch settings"
        expected_model = _get(spec, "model", default=None)
        actual_model = initialization.get("model")
        if expected_model is not None and actual_model != expected_model:
            return False, "runtime model does not match the launch settings"
        expected_fingerprint = _get(spec, "fingerprint", default=None)
        actual_fingerprint = initialization.get("fingerprint")
        if expected_fingerprint is not None:
            if _json_value(actual_fingerprint) != _json_value(expected_fingerprint):
                return False, "runtime launch fingerprint does not match"
        return True, ""

    def _swap_spec(
        self,
        participant: Participant,
        operation: Operation,
        profile: Mapping[str, Any],
        runner_specs: Optional[Mapping[str, Any]],
    ) -> Dict[str, Any]:
        if runner_specs is not None:
            if not isinstance(runner_specs, Mapping):
                raise _error("invalid", "runner_specs must be an object keyed by participant ID")
            raw = runner_specs.get(participant.participant_id)
            if raw is None:
                raise _error("invalid", "runner specification is missing for participant")
        else:
            raw = participant.metadata.get("runner_spec", participant.metadata.get("spec"))
            if raw is None:
                raw = {}
        # Project the exact SDK object before any field access.  This keeps
        # typed default-only transport slots out of the durable target while
        # leaving mappings, subclasses, and lookalike dataclasses strict.
        spec = _safe_runner_projection(raw, "runner specification")
        mode = str(spec.get("mode", "resume")).casefold()
        if mode not in {"resume", "fresh"}:
            raise _error("unsupported", "swap only supports exact resume or fixed fresh mode")
        session_id = spec.get("session_id", spec.get("session_uuid"))
        if session_id != participant.session_id:
            raise _error("loader-failed", "runner UUID does not match the enrolled participant")
        for identity_key, expected in (
            ("session_name", participant.session_name),
            ("bound_lane", participant.bound_lane),
        ):
            supplied = spec.get(identity_key)
            if supplied is not None and supplied != expected:
                raise _error(
                    "loader-failed",
                    "runner %s does not match the enrolled participant" % identity_key,
                )
        if mode == "resume" and (spec.get("resume") is False or spec.get("fresh") is True):
            raise _error("loader-failed", "resume cannot fall back to a fresh runner")
        if mode == "fresh" and (spec.get("fresh") is not True or spec.get("resume") is True):
            raise _error("loader-failed", "fresh restore requires an explicit fixed-ID fresh runner")
        for forbidden in (
            "prompt",
            "query",
            "title",
            "picker",
            "fork",
            "continue",
            "continuation",
            "continuation_prompt",
            "fallback",
            "resume_fallback",
            "unknown_id_fallback",
        ):
            if forbidden in spec:
                raise _error("unsupported", "swap runner specification contains a model or fork fallback")
        source_family = self._participant_profile_family(participant)
        if source_family is None:
            raise _error("profile-mismatch", "participant has no proven source profile family")
        if source_family.casefold() != str(profile["family"]).casefold():
            raise _error("profile-mismatch", "target profile is outside the participant storage family")
        source_status = participant.metadata.get("profile_status")
        if str(source_status).casefold() != "active":
            raise _error("unsupported", "participant source profile eligibility is unknown")
        source_auth = participant.metadata.get("profile_authentication")
        source_auth_type = _get(source_auth, "type", default=None)
        if str(source_auth_type).casefold().replace("-", "_") != "subscription_oauth":
            raise _error("unsupported", "participant source profile capability is unknown")
        workspace = self._participant_workspace(participant)
        spec_workspace = spec.get("workspace", spec.get("worktree", spec.get("cwd")))
        if workspace is not None:
            if spec_workspace is None:
                spec_workspace = workspace
            if str(workspace) != str(spec_workspace):
                raise _error("profile-mismatch", "runner workspace does not match the participant assignment")
        transcript_store = participant.metadata.get(
            "transcript_store", participant.metadata.get("transcript_path")
        )
        spec_transcript_store = spec.get("transcript_store", spec.get("transcript_path"))
        if transcript_store is not None:
            if spec_transcript_store is None:
                spec_transcript_store = transcript_store
            if str(transcript_store) != str(spec_transcript_store):
                raise _error("profile-mismatch", "runner transcript store does not match the participant")
        if transcript_store is None or spec_transcript_store is None:
            raise _error("profile-mismatch", "runner transcript store equality is unproven")
        transcript = participant.metadata.get("transcript")
        if mode == "resume":
            if not isinstance(transcript, Mapping):
                raise _error("profile-mismatch", "participant transcript identity is unproven")
            if transcript.get("session_id") != participant.session_id:
                raise _error("profile-mismatch", "participant transcript UUID does not match the runner")
            if transcript.get("exists") is not True or transcript.get("written") is not True:
                raise _error("profile-mismatch", "known-written transcript is missing or incomplete")
        else:
            reserved = participant.state.casefold() == "reserved" or any(
                participant.metadata.get(name) is True
                for name in ("reserved_uuid", "session_reserved", "fresh_reserved")
            )
            if isinstance(transcript, Mapping):
                if transcript.get("session_id") != participant.session_id:
                    raise _error("profile-mismatch", "reserved transcript UUID does not match the runner")
                if transcript.get("exists") is True or transcript.get("written") is True:
                    raise _error("profile-mismatch", "known-written transcript cannot use a fresh fallback")
                reserved = reserved or transcript.get("reserved") is True
            elif transcript is not None:
                raise _error("profile-mismatch", "reserved transcript evidence is malformed")
            if not reserved:
                raise _error("profile-mismatch", "fresh restore requires an explicit never-written reserved UUID")
        for name in (
            "unknown_holders",
            "unknown_descendants",
            "unknown_effects",
            "unresolved_effects",
        ):
            if participant.metadata.get(name):
                raise _error("uncertain-effect", "participant has unresolved holders or effects")
        # These tags are part of the controller/runtime contract, not prompt
        # content.  The adapter uses them to correlate each response.
        spec.setdefault("mode", "resume")
        spec["session_id"] = participant.session_id
        spec["participant_id"] = participant.participant_id
        spec["session_name"] = participant.session_name
        spec["bound_lane"] = participant.bound_lane
        spec["profile_name"] = profile["name"]
        spec["profile_family"] = profile["family"]
        spec["account_email"] = profile["email"]
        # Target identity replaces the source identity even when the target
        # profile has no explicit config directory; retaining the source path
        # would silently mix profile stores.
        spec["config_dir"] = profile.get("config_dir")
        if workspace is not None:
            spec["workspace"] = workspace
        if transcript_store is not None:
            spec["transcript_store"] = transcript_store
        if participant.permission_mode is not None:
            spec["permission_mode"] = participant.permission_mode
        if participant.model is not None:
            spec["model"] = participant.model
        # Repoint identity-only fingerprint values to the target profile while
        # retaining execution settings (model, effort, tools, permissions,
        # cwd, and other launch controls) from the enrolled participant.
        source_fingerprint = participant.fingerprint if isinstance(participant.fingerprint, Mapping) else {}
        fingerprint = dict(source_fingerprint)
        raw_fingerprint = spec.get("fingerprint", {})
        if not isinstance(raw_fingerprint, Mapping):
            raise _error("invalid", "runner launch fingerprint is malformed")
        fingerprint.update(raw_fingerprint)
        fingerprint["profile_name"] = profile["name"]
        fingerprint["account_email"] = profile["email"]
        fingerprint["config_dir"] = profile.get("config_dir")
        spec["fingerprint"] = fingerprint
        return _safe_runner_projection(spec, "runner specification")

    @staticmethod
    def _adopt_target_runner(
        participant: Participant,
        spec: Mapping[str, Any],
        profile: Mapping[str, Any],
        *,
        runner_instance_id: Optional[str] = None,
        process: Optional[Mapping[str, Any]] = None,
    ) -> None:
        """Publish the identity of the runner that was actually opened.

        A swap target is not merely operation metadata.  Once the adapter has
        accepted the launch and the controller has validated ready-held
        evidence, the participant's durable source-of-truth must point at the
        target profile and exact launch spec.  This is intentionally performed
        inside the transaction that records open evidence, so a reload cannot
        observe a target runner while retaining the old profile identity.
        """
        if not isinstance(spec, Mapping):
            raise _error("invalid", "adopted runner specification is malformed")
        if not isinstance(profile, Mapping):
            raise _error("invalid", "adopted runner profile is malformed")
        required = ("name", "family", "email")
        if any(not isinstance(profile.get(key), str) or not profile.get(key) for key in required):
            raise _error("profile-mismatch", "adopted runner profile identity is incomplete")
        fingerprint = spec.get("fingerprint")
        if not isinstance(fingerprint, Mapping):
            raise _error("invalid", "adopted runner launch fingerprint is malformed")
        for identity_key in ("session_name", "bound_lane"):
            if spec.get(identity_key) != getattr(participant, identity_key):
                raise _error(
                    "ownership-conflict",
                    "adopted runner %s does not match the participant" % identity_key,
                )

        # These are the participant's current identity fields.  In particular,
        # do not retain the source account/config path after a successful
        # profile swap, including when the target has no explicit config_dir.
        participant.metadata["profile_name"] = profile["name"]
        participant.metadata["profile_family"] = profile["family"]
        participant.metadata["profile_status"] = "active"
        participant.metadata["profile_authentication"] = {
            "type": "subscription_oauth"
        }
        participant.metadata["account_email"] = profile["email"]
        participant.metadata["config_dir"] = profile.get("config_dir")
        participant.metadata["session_name"] = participant.session_name
        participant.metadata["bound_lane"] = participant.bound_lane
        participant.metadata["runner_spec"] = _json_value(spec)
        # ``spec`` is the compatibility-free current launch record used when
        # a participant has no separately named runner_spec.  Keep both names
        # synchronized so future swaps cannot accidentally source the old
        # launch.
        participant.metadata["spec"] = _json_value(spec)
        participant.fingerprint = _json_value(fingerprint)
        participant.model = _optional_text(spec.get("model"), "participant model")
        participant.permission_mode = _optional_text(
            spec.get("permission_mode"), "participant permission_mode"
        )
        if runner_instance_id is not None:
            if not isinstance(runner_instance_id, str) or not runner_instance_id:
                raise _error("invalid", "adopted runner instance identity is invalid")
            participant.metadata["runner_instance_id"] = runner_instance_id
        if process is not None:
            participant.metadata["runner_process"] = _json_value(process)

    @staticmethod
    def _capability_gate_projection(value: Any) -> Dict[str, Any]:
        """Keep only the bounded, non-secret fields of a Gate 0 result."""
        if isinstance(value, Mapping):
            getter = value.get
        else:
            getter = lambda name, default=None: getattr(value, name, default)

        verdict = getter("verdict")
        reason_code = getter("reason_code")
        reason = getter("reason")
        identity_digest = getter("identity_digest")
        if identity_digest is None:
            identity = getter("identity")
            if isinstance(identity, Mapping):
                identity_digest = identity.get("identity_digest")
            elif identity is not None:
                identity_digest = getattr(identity, "identity_digest", None)
        evidence_reference = getter("evidence_reference")

        if verdict not in {"verified", "unsupported", "inconclusive"}:
            return {
                "verdict": "inconclusive",
                "reason_code": "capability-decision-malformed",
                "reason": "runtime capability preflight returned no valid verdict",
            }
        if not isinstance(reason_code, str) or not reason_code.strip():
            return {
                "verdict": "inconclusive",
                "reason_code": "capability-decision-malformed",
                "reason": "runtime capability preflight returned no reason code",
            }
        if not isinstance(reason, str) or not reason.strip():
            return {
                "verdict": "inconclusive",
                "reason_code": "capability-decision-malformed",
                "reason": "runtime capability preflight returned no reason",
            }

        result: Dict[str, Any] = {
            "verdict": verdict,
            "reason_code": reason_code,
            "reason": reason,
        }
        if isinstance(identity_digest, str) and re.fullmatch(r"[0-9a-f]{64}", identity_digest):
            result["identity_digest"] = identity_digest
        if (isinstance(evidence_reference, str) and evidence_reference.strip()
                and len(evidence_reference) <= 512):
            result["evidence_reference"] = evidence_reference

        # A verified decision without both bindings is malformed evidence.  A
        # missing identity or evidence reference must never become a pass.
        if verdict == "verified" and (
            "identity_digest" not in result or "evidence_reference" not in result
        ):
            return {
                "verdict": "inconclusive",
                "reason_code": "capability-decision-unbound",
                "reason": "verified capability result lacks identity or evidence binding",
            }
        return result

    @classmethod
    def _capability_gate_refusal(
        cls, operation: Operation
    ) -> Optional[Dict[str, Any]]:
        metadata = operation.metadata
        direct = metadata.get("capability_gate")
        if isinstance(direct, Mapping):
            decision = cls._capability_gate_projection(direct)
            if decision["verdict"] != "verified":
                return decision
        gates = metadata.get("capability_gates")
        if isinstance(gates, Mapping):
            for raw_decision in gates.values():
                if not isinstance(raw_decision, Mapping):
                    return {
                        "verdict": "inconclusive",
                        "reason_code": "capability-decision-malformed",
                        "reason": "durable capability gate record is malformed",
                    }
                decision = cls._capability_gate_projection(raw_decision)
                if decision["verdict"] != "verified":
                    return decision
        return None

    @classmethod
    def _raise_capability_refusal(cls, operation: Operation) -> None:
        decision = cls._capability_gate_refusal(operation)
        if decision is None:
            return
        raise _error(
            "unsupported" if decision["verdict"] == "unsupported" else "live-unverified",
            "managed runtime capability preflight refused: %s: %s"
            % (decision["reason_code"], decision["reason"]),
        )

    def _capability_evidence_for(
        self, participant_id: str, spec: Mapping[str, Any]
    ) -> Any:
        """Read Gate 0 evidence only from an internal provider seam."""
        provider = self._capability_evidence_provider
        if callable(provider):
            return provider(dict(spec), participant_id)
        return provider

    async def _runtime_capability_preflight(
        self, participant_id: str, spec: Mapping[str, Any]
    ) -> Dict[str, Any]:
        """Invoke the exact adapter Gate 0 method and fail closed."""
        method = (
            getattr(self.runtime, "preflight_held_swap", None)
            if self.runtime is not None
            else None
        )
        if not callable(method):
            return {
                "verdict": "inconclusive",
                "reason_code": "capability-preflight-unavailable",
                "reason": "managed runtime capability preflight is unavailable",
            }
        try:
            evidence = self._capability_evidence_for(participant_id, spec)
        except Exception as exc:
            return {
                "verdict": "inconclusive",
                "reason_code": "capability-evidence-provider-failed",
                "reason": "internal capability evidence provider failed: %s" % exc,
            }
        try:
            decision = method(dict(spec), evidence)
            if inspect.isawaitable(decision):
                decision = await decision
        except ControllerError as exc:
            verdict = "unsupported" if exc.code == "unsupported" else "inconclusive"
            return {
                "verdict": verdict,
                "reason_code": exc.code,
                "reason": exc.message,
            }
        except Exception as exc:
            return {
                "verdict": "inconclusive",
                "reason_code": "capability-preflight-error",
                "reason": "managed runtime capability preflight failed: %s" % exc,
            }
        return self._capability_gate_projection(decision)

    def _persist_capability_gate(
        self,
        operation_id: str,
        generation: Any,
        participant_id: str,
        decision: Mapping[str, Any],
    ) -> None:
        decision = self._capability_gate_projection(decision)
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            gates = operation.metadata.get("capability_gates")
            if not isinstance(gates, dict):
                gates = {}
                operation.metadata["capability_gates"] = gates
            gates[participant_id] = decision
            if decision["verdict"] != "verified":
                native_swap = operation.metadata.get("native_swap")
                entry_capture = (
                    native_swap.get("entry_capture")
                    if isinstance(native_swap, Mapping) else None
                )
                # A target preflight refusal after the one-shot native entry
                # provider crossed its boundary is an effect-window
                # uncertainty, even though the operation has not reached the
                # interrupt fence yet.  Do not roll back to the released
                # source or make the provider response recapturable.
                capture_window = (
                    isinstance(entry_capture, Mapping)
                    and entry_capture.get("state")
                    in {"pending", "captured-unvalidated"}
                )
                before_fence = (
                    operation.phase in {"preflight", "quiescing"}
                    and not capture_window
                )
                operation.metadata["capability_gate"] = decision
                # A refusal before the fence completed without runtime
                # effects. Keep it terminal so it does not strand the prior
                # released operation; later-stage uncertainty stays active.
                if capture_window:
                    operation.phase = "indeterminate"
                    if isinstance(native_swap, dict):
                        native_swap["state"] = "uncertain"
                        native_swap["uncertainty"] = {
                            "code": (
                                "unsupported"
                                if decision["verdict"] == "unsupported"
                                else "live-unverified"
                            ),
                            "message": decision["reason"],
                        }
                        operation.metadata["native_swap"] = native_swap
                else:
                    operation.phase = "complete" if before_fence else "failed"
                operation.metadata["outcome"] = "capability-refused"
                operation.metadata["last_error"] = {
                    "code": "unsupported" if decision["verdict"] == "unsupported" else "live-unverified",
                    "message": decision["reason"],
                }
                previous = self._operations.get(operation.metadata.get("previous_active_operation_id"))
                if before_fence:
                    self._active_operation_id = (
                        previous.operation_id
                        if operation.mode == "swap" and previous is not None
                        and previous.phase == "released" else None
                    )
                self._save_request_result(operation.request_id, operation.to_dict())
                self._persist({
                    "event": "capability-preflight-refused",
                    "operation_id": operation_id,
                    "participant_id": participant_id,
                    "verdict": decision["verdict"],
                    "reason_code": decision["reason_code"],
                })
            else:
                self._persist({
                    "event": "capability-preflight-verified",
                    "operation_id": operation_id,
                    "participant_id": participant_id,
                    "evidence_reference": decision.get("evidence_reference"),
                })
        if decision["verdict"] != "verified":
            raise _error(
                "unsupported" if decision["verdict"] == "unsupported" else "live-unverified",
                "managed runtime capability preflight refused: %s: %s"
                % (decision["reason_code"], decision["reason"]),
            )

    async def _preflight_operation_specs(
        self,
        operation_id: str,
        generation: Any,
        target_specs: Mapping[str, Any],
    ) -> None:
        if not isinstance(target_specs, Mapping):
            raise _error("invalid", "durable target runner specifications are malformed")
        for raw_participant_id, raw_spec in target_specs.items():
            participant_id = str(raw_participant_id)
            if not isinstance(raw_spec, Mapping):
                raise _error("invalid", "durable target runner specification is malformed")
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                gates = operation.metadata.get("capability_gates")
                prior = gates.get(participant_id) if isinstance(gates, Mapping) else None
            if isinstance(prior, Mapping):
                prior_decision = self._capability_gate_projection(prior)
                if prior_decision["verdict"] == "verified":
                    continue
            decision = await self._runtime_capability_preflight(
                participant_id, raw_spec
            )
            self._persist_capability_gate(
                operation_id, generation, participant_id, decision
            )

    def _mark_operation_failure(
        self, operation_id: str, marker: str, code: str, detail: str
    ) -> None:
        with self._transaction():
            operation = self._operations.get(operation_id)
            if operation is None:
                return
            if operation.phase not in _TERMINAL_OPERATION_PHASES:
                operation.phase = "indeterminate" if marker else "failed"
            if marker and marker not in operation.uncertainty:
                operation.uncertainty.append(marker)
            operation.metadata["last_error"] = {"code": code, "message": detail}
            self._persist({
                "event": "operation-failure",
                "operation_id": operation_id,
                "code": code,
                "marker": marker,
            })

    def _current_operation(self, operation_id: str, generation: Any) -> Operation:
        """Reloaded-operation guard used immediately after every await."""
        operation = self._operation(operation_id)
        if (
            self._active_operation_id != operation.operation_id
            or self._generation != generation
            or operation.generation != generation
        ):
            raise _error("stale-generation", "managed operation or generation changed")
        return operation

    async def start(
        self,
        request_id: str,
        generation: Any,
        coordinator: Participant,
        participants: Iterable[Participant],
        runner_specs: Mapping[str, Any],
    ) -> Operation:
        """Launch an explicit roster into ready-held state without prompting.

        Start is the initial managed-lane admission boundary.  Every roster,
        profile, fixed UUID, transcript holder, and launch spec is validated in
        one transaction before a writer claim or runtime call is made.  The
        durable operation and one launch-intent record per participant are
        persisted before the first adapter ``open`` await.
        """
        request_id = _id(request_id, "request_id") or ""
        generation = self._generation_valid(generation)
        if not isinstance(coordinator, Participant):
            raise _error("invalid", "start coordinator must be a Participant")
        if isinstance(participants, (str, bytes, Mapping)):
            raise _error("invalid", "start participants must be an iterable of workers")
        try:
            workers = list(participants)
        except TypeError:
            raise _error("invalid", "start participants must be an iterable of workers")
        if not isinstance(runner_specs, Mapping):
            raise _error("invalid", "start runner_specs must be an object keyed by participant ID")
        opener = getattr(self.runtime, "open", None) if self.runtime is not None else None
        if not callable(opener):
            raise _error("unsupported", "managed runtime open is unavailable")

        roster = [coordinator] + workers
        if any(not isinstance(item, Participant) for item in roster):
            raise _error("invalid", "start roster contains a non-participant")
        if coordinator.role.casefold() != "coordinator":
            raise _error("invalid", "start requires one coordinator participant")
        if any(worker.role.casefold() != "worker" for worker in workers):
            raise _error("invalid", "start participants must all be workers")
        participant_ids = [item.participant_id for item in roster]
        session_ids = [item.session_id for item in roster]
        mailbox_ids = [item.mailbox_id for item in roster]
        if len(set(participant_ids)) != len(participant_ids):
            raise _error("invalid", "start roster contains duplicate participant IDs")
        if len(set(session_ids)) != len(session_ids):
            raise _error("invalid", "start roster contains duplicate session UUIDs")
        if len(set(mailbox_ids)) != len(mailbox_ids):
            raise _error("invalid", "start roster contains duplicate mailbox identities")
        if any(worker.parent_id != coordinator.participant_id for worker in workers):
            raise _error("invalid", "start worker parent_id must name the coordinator")
        if set(runner_specs) != set(participant_ids):
            raise _error("invalid", "start runner_specs must exactly cover the roster")

        # Validate and project every launch before request identity or any
        # durable start record is created.  This is the last point at which a
        # caller-supplied environment/settings bag could otherwise cross the
        # controller boundary.
        for item in roster:
            self._validate_durable_participant(item)
            self._validate_bound_lane(item)
        safe_runner_specs = {
            item.participant_id: _safe_runner_projection(
                runner_specs[item.participant_id],
                "start runner specification for %s" % item.participant_id,
            )
            for item in roster
        }
        runner_specs = safe_runner_specs

        # The request digest includes the complete semantic start input but no
        # operation ID.  It is recorded only as a digest in the request ledger;
        # the operation keeps the bounded launch specs needed for recovery.
        request_content = {
            "coordinator": self._participant_request_projection(coordinator),
            "participants": [self._participant_request_projection(item) for item in workers],
            "runner_specs": _json_value(runner_specs),
            "generation": generation,
        }
        _digest(request_content)

        # Capability refusal must not reserve claims or enroll a roster that
        # never had permission to launch. Persist only the request outcome.
        with self._transaction():
            prior_request = self._requests.get(request_id)
            if prior_request is not None:
                if (prior_request.get("digest") != _digest(request_content)
                        or prior_request.get("kind") != "operation"):
                    raise _error("invalid", "request ID was reused with different content")
                prior_result = prior_request.get("result")
                prior_operation = (self._operations.get(prior_result.get("operation_id"))
                                   if isinstance(prior_result, Mapping) else None)
                if prior_operation is None:
                    raise _error("uncertain-effect", "start request has no durable operation")
                self._raise_capability_refusal(prior_operation)
            else:
                self._admit_generation(generation)
                if self._participants:
                    raise _error("busy", "managed lane is already enrolled")
        if prior_request is None:
            for item in roster:
                decision = await self._runtime_capability_preflight(
                    item.participant_id, runner_specs[item.participant_id]
                )
                if decision["verdict"] == "verified":
                    continue
                with self._transaction():
                    self._admit_generation(generation)
                    if self._participants:
                        raise _error("busy", "managed lane changed during capability preflight")
                    prior = self._request_seen(request_id, request_content, "operation")
                    if isinstance(prior, Mapping):
                        refused_operation = self._operations.get(prior.get("operation_id"))
                        if refused_operation is None:
                            raise _error("invalid", "start request has no durable operation")
                    else:
                        self._generation = generation
                        refused_operation = Operation(
                            operation_id="op-" + uuid.uuid4().hex,
                            request_id=request_id, mode="start", generation=generation,
                            phase="complete", metadata={
                                "request_content": _json_value(request_content),
                                "capability_gate": decision,
                                "outcome": "capability-refused",
                            },
                        )
                        self._operations[refused_operation.operation_id] = refused_operation
                        # No admission or launch took place. Keep the prior
                        # control operation (or none), so explicit unenroll
                        # can still clear an otherwise empty managed owner.
                        self._save_request_result(request_id, refused_operation.to_dict())
                        self._persist({"event": "start-capability-refused",
                                       "operation_id": refused_operation.operation_id})
                self._raise_capability_refusal(refused_operation)
                raise _error("uncertain-effect", "start request changed during capability preflight")

        operation_id: Optional[str] = None
        operation: Optional[Operation] = None
        with self._transaction():
            self._admit_generation(generation)
            was_seen = request_id in self._requests
            # The complete participant projection is the stable caller
            # identity.  Do not replace it with an operation snapshot after
            # launch: that would let a changed task/claim/session name/lane
            # reuse the request ID merely because its runner specs match.
            seen = self._request_seen(request_id, request_content, "operation")
            if was_seen:
                if not isinstance(seen, Mapping):
                    raise _error(
                        "uncertain-effect",
                        "start request was recorded without a durable result",
                    )
                stored = Operation.from_dict(seen)
                current = self._operations.get(stored.operation_id)
                if current is None:
                    raise _error(
                        "invalid",
                        "start request ledger points to a missing operation",
                    )
                operation = current
                operation_id = current.operation_id
            else:
                if self._participants or self._generation not in (None, generation):
                    raise _error("busy", "managed lane is already enrolled")
                if any(
                    item.participant_id in self._archived_participants
                    for item in roster
                ):
                    raise _error("ownership-conflict", "start roster reuses a prior participant ID")
                if any(
                    item.session_id in self._session_history
                    or any(old.session_id == item.session_id for old in self._archived_participants.values())
                    for item in roster
                ):
                    raise _error("ownership-conflict", "start roster reuses a prior session UUID")
                if any(
                    any(old.mailbox_id == item.mailbox_id for old in self._archived_participants.values())
                    for item in roster
                ):
                    raise _error("ownership-conflict", "start roster reuses a prior mailbox identity")

                # Validate every participant/profile/spec/holder first.  No
                # claim or roster mutation happens until this entire loop
                # succeeds, so a bad later worker cannot leave a partial lane.
                profiles: Dict[str, Dict[str, Any]] = {}
                target_specs: Dict[str, Dict[str, Any]] = {}
                transcript_preflight: Dict[str, Dict[str, Any]] = {}
                provisional = Operation(
                    operation_id="start-preflight-" + uuid.uuid4().hex,
                    request_id=request_id,
                    mode="start",
                    generation=generation,
                    phase="preflight",
                )
                for item in roster:
                    self._validate_durable_participant(item)
                    profiles[item.participant_id] = self._participant_profile_summary(item)
                for item in roster:
                    target_spec = self._swap_spec(
                        item,
                        provisional,
                        profiles[item.participant_id],
                        runner_specs,
                    )
                    trusted_transcript = self._trusted_transcript_preflight(
                        item,
                        profiles[item.participant_id],
                        target_spec,
                    )
                    self._apply_transcript_preflight(item, trusted_transcript)
                    target_specs[item.participant_id] = target_spec
                    transcript_preflight[item.participant_id] = trusted_transcript

                claimed: list[Participant] = []
                try:
                    for item in roster:
                        self._claim_writer(item)
                        if item.writer_claim is not None:
                            claimed.append(item)
                except BaseException as exc:
                    rollback_error: Optional[BaseException] = None
                    for item in reversed(claimed):
                        try:
                            self._release_claim(item)
                        except BaseException as release_exc:
                            rollback_error = release_exc
                            break
                    if rollback_error is not None:
                        raise _error(
                            "uncertain-effect",
                            "start writer-claim rollback is uncertain: %s" % rollback_error,
                        )
                    raise exc

                self._generation = generation
                self._coordinator_id = coordinator.participant_id
                for item in roster:
                    self._participants[item.participant_id] = item
                    self._session_history.add(item.session_id)
                operation = Operation(
                    operation_id="op-" + uuid.uuid4().hex,
                    request_id=request_id,
                    mode="start",
                    generation=generation,
                    phase="preflight",
                    sealed_participants=tuple(participant_ids),
                    metadata={
                        "request_content": _json_value(request_content),
                        "profiles": profiles,
                        "target_specs": target_specs,
                        "transcript_preflight": transcript_preflight,
                        "runner_instances": {},
                        "launch_processes": {},
                        "open_evidence": {},
                        "launch_intents": {
                            item.participant_id: {
                                "state": "pending",
                                "participant_id": item.participant_id,
                                "session_id": item.session_id,
                                "generation": generation,
                                "spec": _json_value(target_specs[item.participant_id]),
                            }
                            for item in roster
                        },
                    },
                )
                self._operations[operation.operation_id] = operation
                self._active_operation_id = operation.operation_id
                self._save_request_result(request_id, operation.to_dict())
                self._persist({
                    "event": "start-preflight",
                    "operation_id": operation.operation_id,
                    "participants": participant_ids,
                })
                operation.phase = "starting"
                self._persist({
                    "event": "start-launching",
                    "operation_id": operation.operation_id,
                })
                operation_id = operation.operation_id

        if operation is None or operation_id is None:
            raise _error("invalid", "start operation was not created")
        self._raise_capability_refusal(operation)
        if operation.phase in {"ready-held", "released"}:
            return operation
        if operation.phase in {"failed", "indeterminate", "starting", "preflight"}:
            if was_seen:
                with self._transaction():
                    current = self._current_operation(operation_id, generation)
                    intents = current.metadata.get("launch_intents", {})
                    if not isinstance(intents, Mapping):
                        raise _error("invalid", "durable start launch intents are malformed")
                    states = {
                        item.get("state")
                        for item in intents.values()
                        if isinstance(item, Mapping)
                    }
                    if any(state not in {"ready", "pending"} for state in states):
                        raise _error(
                            "uncertain-effect",
                            "start operation requires explicit recovery before retry",
                        )
                    current.phase = "starting"
                    current.uncertainty = []
                    self._persist({"event": "start-resume-pending", "operation_id": operation_id})
                    operation = current

        with self._transaction():
            current = self._current_operation(operation_id, generation)
            roster = [
                self._participants[item]
                for item in current.sealed_participants
                if item in self._participants
                and self._participants[item].state.casefold() not in {"completed", "stopped"}
            ]
            metadata = current.metadata
            target_specs = metadata.get("target_specs", {})
            profiles = metadata.get("profiles", {})
            launch_intents = metadata.get("launch_intents", {})
            if not all(isinstance(value, Mapping) for value in (target_specs, profiles, launch_intents)):
                self._mark_operation_failure(
                    operation_id,
                    "start",
                    "invalid",
                    "durable start launch maps are malformed",
                )
                raise _error("invalid", "durable start launch maps are malformed")

        await self._preflight_operation_specs(operation_id, generation, target_specs)

        # Native coordinator context is a startup authority, not a runner
        # event.  Prepare it after the existing capability gate and before the
        # first ``open`` await.  The helper is a no-op for ordinary independent
        # starts and refuses an explicitly selected native configuration before
        # any runtime effect when its durable claim/definition proof is absent.
        with self._transaction():
            current = self._current_operation(operation_id, generation)
            coordinator_spec = current.metadata.get("target_specs", {}).get(
                coordinator.participant_id
            )
            if not isinstance(coordinator_spec, Mapping):
                raise _error("invalid", "native coordinator startup specification is missing")
            current_coordinator = self._participants.get(coordinator.participant_id)
            if current_coordinator is None:
                raise _error("unknown", "native coordinator disappeared before startup")
            self._prepare_native_coordinator_locked(
                current, generation, current_coordinator, coordinator_spec
            )

        for participant in roster:
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                spec = current.metadata["target_specs"].get(participant.participant_id)
                intent = current.metadata["launch_intents"].get(participant.participant_id)
                if not isinstance(spec, Mapping) or not isinstance(intent, Mapping):
                    raise _error("invalid", "durable start participant launch is incomplete")
                if intent.get("state") == "ready":
                    continue
                if intent.get("state") != "pending":
                    self._mark_operation_failure(
                        operation_id,
                        "start:%s" % participant.participant_id,
                        "uncertain-effect",
                        "start launch intent is already in progress or complete",
                    )
                    raise _error("uncertain-effect", "start launch intent is not pending")
                current.metadata["launch_intents"][participant.participant_id] = {
                    **dict(intent),
                    "state": "in-progress",
                    "started_at": self.clock(),
                }
                self._persist({
                    "event": "start-launch-intent",
                    "operation_id": operation_id,
                    "participant_id": participant.participant_id,
                })

            try:
                opened = opener(participant.participant_id, dict(spec))
                if not inspect.isawaitable(opened):
                    raise TypeError("managed runtime open must be awaitable")
                opened = await opened
                with self._transaction():
                    current = self._current_operation(operation_id, generation)
                    runner_instance = self._runtime_runner_instance(opened)
                    if runner_instance is None:
                        raise ValueError("start open response has no runner instance identity")
                    process = self._runtime_process(opened, "start-open")
                    current.metadata["runner_instances"][participant.participant_id] = runner_instance
                    current.metadata["launch_processes"][participant.participant_id] = _json_value(process)
                    current.metadata["launch_intents"][participant.participant_id] = {
                        **dict(current.metadata["launch_intents"][participant.participant_id]),
                        "state": "registered",
                        "runner_instance_id": runner_instance,
                        "process": _json_value(process),
                    }
                    self._persist({
                        "event": "start-launch-registered",
                        "operation_id": operation_id,
                        "participant_id": participant.participant_id,
                    })
                    operation = current
                with self._transaction():
                    current = self._current_operation(operation_id, generation)
                    current_participant = self._participants.get(participant.participant_id)
                    if current_participant is None:
                        raise _error("unknown", "started participant is no longer enrolled")
                valid, reason = self._runtime_ready(opened, current_participant, operation, spec)
                if not valid:
                    raise ValueError(reason)
                runner_instance = self._runtime_runner_instance(opened)
                if runner_instance is None:
                    raise ValueError("start open response has no runner instance identity")
                with self._transaction():
                    current = self._current_operation(operation_id, generation)
                    current_participant = self._participants.get(participant.participant_id)
                    if current_participant is None:
                        raise ValueError("started participant is no longer enrolled")
                    profile = current.metadata["profiles"].get(participant.participant_id)
                    if not isinstance(profile, Mapping):
                        raise ValueError("started participant profile evidence is missing")
                    self._adopt_target_runner(
                        current_participant,
                        spec,
                        profile,
                        runner_instance_id=runner_instance,
                        process=process,
                    )
                    current.metadata["open_evidence"][participant.participant_id] = _json_value(opened)
                    current.metadata["launch_intents"][participant.participant_id] = {
                        **dict(current.metadata["launch_intents"][participant.participant_id]),
                        "state": "ready",
                    }
                    current.readiness[participant.participant_id] = {
                        "session_id": participant.session_id,
                        "runner_instance_id": runner_instance,
                        "spec": _json_value(spec),
                        "evidence": _json_value(opened),
                    }
                    self._persist({
                        "event": "start-open-ready-held",
                        "operation_id": operation_id,
                        "participant_id": participant.participant_id,
                    })
            except BaseException as exc:
                self._mark_operation_failure(
                    operation_id,
                    "start:%s" % participant.participant_id,
                    "uncertain-effect",
                    str(exc),
                )
                if isinstance(exc, asyncio.CancelledError):
                    raise
                raise _error("uncertain-effect", "start runner outcome is uncertain")

        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            operation.phase = "ready-held"
            operation.metadata["ready_generation"] = generation
            self._persist({"event": "start-ready-held", "operation_id": operation_id})
            return operation

    @_transactional
    def handoff(
        self,
        request_id: str,
        generation: Any,
        checkpoint: Any,
    ) -> Dict[str, Any]:
        """Record one explicit checkpoint without changing runner lifecycle.

        Handoff is deliberately not an ``Operation``.  Its durable checkpoint
        ledger is separate from the active swap/ctx/start operation, so a
        released dispatch gate, writer claims, and ready-held roster remain
        exactly as they were.  No runtime method is consulted or invoked.
        """
        request_id = _id(request_id, "request_id") or ""
        generation = self._generation_valid(generation)
        checkpoint = self._checkpoint_reference(checkpoint)
        request_content = {
            "mode": "handoff",
            "generation": generation,
            "checkpoint": checkpoint,
        }
        _digest(request_content)
        self._check_generation(generation)
        operation = self._operations.get(self._active_operation_id or "")
        if operation is not None and operation.phase in {
            "preflight",
            "quiescing",
            "paused",
            "starting",
        }:
            raise _error("busy", "handoff is serialized behind an active operation")
        if operation is not None and operation.phase in {"failed", "indeterminate"}:
            raise _error("uncertain-effect", "handoff is blocked by unresolved operation effects")
        was_seen = request_id in self._requests
        seen = self._request_seen(request_id, request_content, "operation")
        if was_seen:
            if not isinstance(seen, Mapping):
                raise _error("uncertain-effect", "handoff request has no durable checkpoint result")
            result = dict(seen)
            if result.get("request_id") != request_id:
                raise _error("invalid", "handoff request result has the wrong identity")
            return result

        record = {
            "request_id": request_id,
            "generation": generation,
            "checkpoint": checkpoint,
            "checkpoint_digest": _digest(checkpoint),
            "operation_id": operation.operation_id if operation is not None else None,
            "operation_phase": operation.phase if operation is not None else None,
            "created_at": self.clock(),
        }
        self._checkpoints[request_id] = record
        self._save_request_result(request_id, record)
        self._persist({
            "event": "handoff-checkpoint",
            "request_id": request_id,
            "operation_id": record["operation_id"],
        })
        return dict(record)

    @staticmethod
    def _has_native_config_marker(value: Any) -> bool:
        """Recognize only explicit native startup/configuration markers."""
        if not isinstance(value, Mapping):
            return False
        if "native_config" in value:
            return True
        fingerprint = value.get("fingerprint")
        return isinstance(fingerprint, Mapping) and "native_config" in fingerprint

    def _has_native_lifecycle_state(
            self, *, runner_specs: Any = None,
    ) -> bool:
        """Detect native state before a legacy participant lifecycle path."""
        if self._native_context is not None or self._native_admissions:
            return True

        for operation in self._operations.values():
            metadata = operation.metadata
            if "native_startup" in metadata or "native_context" in metadata:
                return True
            target_specs = metadata.get("target_specs")
            if isinstance(target_specs, Mapping) and any(
                    self._has_native_config_marker(spec)
                    for spec in target_specs.values()
            ):
                return True

        for participant in self._participants.values():
            if (self._has_native_config_marker(participant.fingerprint) or
                    "native_config" in participant.metadata or
                    "native_startup" in participant.metadata or
                    self._has_native_config_marker(participant.metadata.get("runner_spec")) or
                    self._has_native_config_marker(participant.metadata.get("spec"))):
                return True

        if isinstance(runner_specs, Mapping):
            if self._has_native_config_marker(runner_specs):
                return True
            return any(
                self._has_native_config_marker(spec)
                for spec in runner_specs.values()
            )
        return False

    def _reject_native_legacy_lifecycle(
            self, operation_name: str, *, runner_specs: Any = None,
    ) -> None:
        if self._has_native_lifecycle_state(runner_specs=runner_specs):
            raise _error(
                "unsupported",
                "%s is unsupported for native coordinator context/startup until "
                "native lineage stop/transfer is implemented" % operation_name,
            )

    @staticmethod
    def _ctx_worker_mapping(
        worker_policy: Any,
        worker_mapping: Any,
        worker_ids: Sequence[str],
    ) -> Dict[str, Dict[str, Any]]:
        """Validate ctx's explicit policy without inventing links.

        ``restart`` remains mapping-free on the wire, but this independent
        participant controller refuses it until native restart admission is
        implemented.  The reusable prototype behavior is ``hold`` only; it
        never rewrites an old child's parent or task identity into the new
        lineage.
        """
        if not isinstance(worker_policy, str) or worker_policy not in {"hold", "restart"}:
            raise _error("invalid", "ctx worker_policy must be exactly hold or restart")
        if worker_mapping is not None:
            raise _error("invalid", "ctx %s cannot include a worker mapping" % worker_policy)
        return {}

    @staticmethod
    def _ctx_fresh_spec(
        participant: Participant,
        session_id: str,
        participant_id: str,
        session_name: str,
    ) -> Dict[str, Any]:
        """Derive a fresh fixed-ID launch from the current runner controls."""
        raw = participant.metadata.get("runner_spec", participant.metadata.get("spec"))
        if not isinstance(raw, Mapping):
            raise _error("invalid", "current coordinator runner specification is missing")
        spec = _safe_runner_projection(raw, "current coordinator runner specification")
        spec.pop("resume", None)
        spec["mode"] = "fresh"
        spec["fresh"] = True
        spec["resume"] = False
        spec["session_id"] = session_id
        spec["participant_id"] = participant_id
        spec["session_name"] = session_name
        spec["bound_lane"] = participant.bound_lane
        return _safe_runner_projection(spec, "ctx fresh coordinator runner specification")

    @staticmethod
    def _ctx_claim(participant: Participant, participant_id: str) -> Optional[WriterClaim]:
        claim = participant.writer_claim
        if claim is None:
            return None
        return WriterClaim(
            participant_id=participant_id,
            worktree=claim.worktree,
            repository=claim.repository,
            state="active",
            lane=claim.lane,
            metadata=_safe_json_projection(claim.metadata, "ctx writer claim metadata"),
        )

    def _ctx_checkpoint_mailbox_conflict(
        self,
        coordinator_id: str,
        checkpoint: Any,
    ) -> Optional[str]:
        """Reject old-coordinator work that cannot be safely migrated."""
        for entry in self._mailboxes.values():
            if entry.recipient_id != coordinator_id or entry.state == "acknowledged":
                continue
            # An exact checkpoint reference is the sole bounded exception.  It
            # remains attached to the archived operation and is not silently
            # retargeted; all other queued/uncertain work is a migration gap.
            if _json_value(entry.payload_ref) != _json_value(checkpoint):
                return entry.message_id
        return None

    async def ctx(
        self,
        request_id: str,
        generation: Any,
        checkpoint: Any,
        worker_policy: Any,
        worker_mapping: Any = None,
    ) -> Operation:
        """Create a fresh held coordinator context under the current profile.

        The old coordinator is interrupted, drained, shut down, and archived;
        unfinished independent workers retain their existing runner/session
        identity under a historical hold.  The ``restart`` wire policy is
        accepted for request compatibility but refused until native restart
        admission is implemented.
        No prompt is generated and the checkpoint is queued as an opaque
        reference for the later explicit release.
        """
        request_id = _id(request_id, "request_id") or ""
        generation = self._generation_valid(generation)
        checkpoint = self._checkpoint_reference(checkpoint)
        checkpoint_payload = checkpoint if isinstance(checkpoint, str) else checkpoint.get("ref")
        if not isinstance(checkpoint_payload, str):
            raise _error("invalid", "ctx checkpoint must include a dispatchable ref")
        # Validate the caller shape before entering the durable transaction.
        # The native-state guard is repeated inside each transaction below so
        # a controller constructed before a peer's native startup/context
        # publication cannot use its cached roster to bypass the refusal.
        self._ctx_worker_mapping(worker_policy, worker_mapping, ())
        with self._transaction():
            # _transaction has just reloaded the authoritative snapshot.
            # Refuse before request deduplication or any ctx mutation.
            self._reject_native_legacy_lifecycle("ctx")
            if worker_policy == "restart":
                raise _error(
                    "unsupported",
                    "ctx restart is unsupported until native restart admission is implemented",
                )
            self._check_generation(generation)
            existing = self._requests.get(request_id)
            request_content = {
                "mode": "ctx",
                "generation": generation,
                "checkpoint": checkpoint,
                "worker_policy": worker_policy,
                "worker_mapping": _json_value(worker_mapping),
            }
            request_digest = _digest(request_content)
            if existing is not None:
                if existing.get("digest") != request_digest:
                    raise _error("invalid", "request ID was reused with different content")
                if existing.get("kind") not in (None, "operation"):
                    raise _error("invalid", "request ID was reused for another operation")
                result = existing.get("result")
                if not isinstance(result, Mapping):
                    raise _error("uncertain-effect", "ctx request has no durable result")
                stored = Operation.from_dict(result)
                current = self._operations.get(stored.operation_id)
                if current is None:
                    raise _error("invalid", "ctx request ledger points to a missing operation")
                if current.phase in {"failed", "indeterminate"}:
                    raise _error("uncertain-effect", "ctx operation requires explicit recovery")
                if current.phase not in {"ready-held", "released"}:
                    raise _error("uncertain-effect", "ctx operation requires explicit recovery")
                return current
            operation = self._operations.get(self._active_operation_id or "")
            if operation is None or operation.phase not in {"ready-held", "released"}:
                raise _error("busy", "ctx requires the current operation to be ready-held or released")
            if operation.generation != generation:
                raise _error("stale-generation", "ctx operation generation is stale")
            old_coordinator = self._participants.get(self._coordinator_id or "")
            if old_coordinator is None or old_coordinator.role.casefold() != "coordinator":
                raise _error("unknown", "ctx has no active coordinator")
            old_claim = self._claim_for(old_coordinator)
            if old_claim is not None:
                if old_claim.repository is None or old_claim.lane is None:
                    raise _error(
                        "unsupported",
                        "ctx claim transfer requires the persisted repository and lane identity",
                    )
                if not callable(getattr(self.store, "transfer_writer_claim", None)):
                    raise _error(
                        "unsupported",
                        "managed state store lacks atomic writer-claim transfer",
                    )
            active_workers = [
                item for item in self._participants.values()
                if item.role.casefold() == "worker"
                and item.state.casefold() not in {"completed", "stopped"}
            ]
            worker_ids = [item.participant_id for item in active_workers]
            normalized_mapping = self._ctx_worker_mapping(
                worker_policy, worker_mapping, worker_ids
            )
            conflict = self._ctx_checkpoint_mailbox_conflict(
                old_coordinator.participant_id, checkpoint
            )
            if conflict is not None:
                raise _error(
                    "uncertain-effect",
                    "old coordinator has unacknowledged mailbox %s beyond the checkpoint" % conflict,
                )
            # The old runner and every retained worker must have a durable,
            # canonical ready evidence record before the fence.  Metadata
            # strings alone cannot prove a process or transcript holder.
            evidence_map = operation.metadata.get("open_evidence", {})
            runner_map = operation.metadata.get("runner_instances", {})
            target_map = operation.metadata.get("target_specs", {})
            if not all(isinstance(value, Mapping) for value in (evidence_map, runner_map, target_map)):
                raise _error("uncertain-effect", "ctx current runner evidence is incomplete")
            for item in [old_coordinator] + active_workers:
                evidence = evidence_map.get(item.participant_id)
                runner = runner_map.get(item.participant_id)
                spec = item.metadata.get("runner_spec", item.metadata.get("spec"))
                if evidence is None and item.participant_id in target_map:
                    evidence = operation.readiness.get(item.participant_id, {}).get("evidence")
                if not isinstance(evidence, Mapping) or not isinstance(runner, str) or not runner:
                    raise _error("uncertain-effect", "ctx runner evidence is missing for %s" % item.participant_id)
                if not isinstance(spec, Mapping):
                    raise _error("uncertain-effect", "ctx runner specification is missing for %s" % item.participant_id)
                valid, reason = self._runtime_ready(evidence, item, operation, spec)
                if not valid:
                    raise _error("uncertain-effect", "ctx runner is not ready-held: %s" % reason)
            profile = self._participant_profile_summary(old_coordinator)
            # Generate a fresh logical identity and native session UUID.  The
            # IDs are not published until the atomic fence below.
            new_id = "ctx-coordinator-" + uuid.uuid4().hex
            new_session = str(uuid.uuid4())
            new_session_name = "ctx-" + uuid.uuid4().hex
            new_task = "ctx-task-" + uuid.uuid4().hex
            new_mailbox = "ctx-mailbox-" + uuid.uuid4().hex
            if (
                new_id in self._participants
                or new_id in self._archived_participants
                or new_session in self._session_history
                or any(item.session_id == new_session for item in self._participants.values())
                or any(item.session_id == new_session for item in self._archived_participants.values())
            ):
                raise _error("ownership-conflict", "ctx generated a reused participant/session identity")
            active_session_names = {
                item.session_name for item in self._participants.values()
                if item.session_name is not None
            }
            if new_session_name in active_session_names:
                raise _error("ownership-conflict", "ctx generated a reused session name")
            fresh_spec = self._ctx_fresh_spec(
                old_coordinator, new_session, new_id, new_session_name
            )
            fresh_spec["session_id"] = new_session
            fresh_spec["participant_id"] = new_id
            fresh_spec = _safe_runner_projection(
                fresh_spec, "ctx fresh coordinator runner specification"
            )
            metadata = _json_value(old_coordinator.metadata)
            if not isinstance(metadata, Mapping):
                raise _error("invalid", "current coordinator metadata is malformed")
            metadata = dict(metadata)
            metadata["transcript"] = {
                "session_id": new_session,
                "exists": False,
                "written": False,
                "reserved": True,
            }
            metadata["reserved_uuid"] = True
            metadata["session_reserved"] = True
            metadata["fresh_reserved"] = True
            metadata.pop("runner_instance_id", None)
            metadata.pop("runner_process", None)
            metadata["runner_spec"] = fresh_spec
            metadata["spec"] = fresh_spec
            metadata["session_name"] = new_session_name
            metadata["bound_lane"] = old_coordinator.bound_lane
            target = Participant(
                participant_id=new_id,
                session_id=new_session,
                session_name=new_session_name,
                bound_lane=old_coordinator.bound_lane,
                role="coordinator",
                parent_id=None,
                task_id=new_task,
                mailbox_id=new_mailbox,
                kind="independent",
                state="reserved",
                writer_claim=self._ctx_claim(old_coordinator, new_id),
                read_only=old_coordinator.read_only,
                background=False,
                detached=False,
                model=old_coordinator.model,
                permission_mode=old_coordinator.permission_mode,
                fingerprint=_json_value(old_coordinator.fingerprint),
                metadata=metadata,
            )
            self._validate_durable_participant(target)
            self._validate_bound_lane(target)
            # Only the injected trusted verifier can establish the target
            # canonical projects holder.  This happens before the lane fence.
            target_preflight = self._trusted_transcript_preflight(
                target, profile, fresh_spec
            )
            self._apply_transcript_preflight(target, target_preflight)
            if target.metadata.get("runner_spec") != fresh_spec:
                fresh_spec = _safe_runner_projection(
                    target.metadata.get("runner_spec"),
                    "ctx adopted fresh runner specification",
                )

        interrupt = getattr(self.runtime, "interrupt", None) if self.runtime is not None else None
        status_call = getattr(self.runtime, "status", None) if self.runtime is not None else None
        shutdown = getattr(self.runtime, "shutdown", None) if self.runtime is not None else None
        opener = getattr(self.runtime, "open", None) if self.runtime is not None else None
        if not all(callable(method) for method in (interrupt, status_call, shutdown, opener)):
            raise _error("unsupported", "managed runtime lifecycle is incomplete")

        # Publish the fence, archive, fresh reservation, and checkpoint queue
        # atomically.  Runtime calls begin only after this durable transition.
        with self._transaction():
            # Preflight ran outside the lock.  Re-read native state at the
            # fence boundary so a peer that registered startup/context during
            # preflight cannot let this legacy participant lifecycle proceed.
            self._reject_native_legacy_lifecycle("ctx")
            # The preflight transaction intentionally does not reserve the
            # request: another controller may win the race while either
            # caller is outside the state lock.  Reserve the validated
            # semantic request in this transaction immediately before any
            # ctx mutation.  A racing caller that finds the completed result
            # returns the same durable operation and never fences a second
            # roster.
            was_seen = request_id in self._requests
            seen = self._request_seen(request_id, request_content, "operation")
            if was_seen:
                if not isinstance(seen, Mapping):
                    raise _error("uncertain-effect", "ctx request has no durable result")
                stored = Operation.from_dict(seen)
                current = self._operations.get(stored.operation_id)
                if current is None:
                    raise _error("invalid", "ctx request ledger points to a missing operation")
                if current.phase in {"failed", "indeterminate"}:
                    raise _error("uncertain-effect", "ctx operation requires explicit recovery")
                if current.phase not in {"ready-held", "released"}:
                    raise _error("uncertain-effect", "ctx operation requires explicit recovery")
                return current
            operation = self._current_operation(operation.operation_id, generation)
            if operation.phase not in {"ready-held", "released"}:
                raise _error("busy", "ctx operation changed during preflight")
            old_coordinator = self._participants.get(old_coordinator.participant_id)
            if old_coordinator is None:
                raise _error("unknown", "ctx coordinator disappeared during preflight")
            old_operation_id = operation.operation_id
            ctx_operation = Operation(
                operation_id="op-" + uuid.uuid4().hex,
                request_id=request_id,
                mode="ctx",
                generation=generation,
                phase="quiescing",
                sealed_participants=tuple([target.participant_id] + worker_ids),
                metadata={
                    "request_content": _json_value(request_content),
                    "target_profile": _json_value(profile),
                    "target_specs": {
                        target.participant_id: _json_value(fresh_spec),
                        **{
                            item.participant_id: _json_value(
                                item.metadata.get("runner_spec", item.metadata.get("spec"))
                            )
                            for item in active_workers
                        },
                    },
                    "transcript_preflight": {target.participant_id: _json_value(target_preflight)},
                    "old_coordinator_id": old_coordinator.participant_id,
                    "old_runner_instances": {
                        item.participant_id: runner_map[item.participant_id]
                        for item in [old_coordinator] + active_workers
                    },
                    "runner_instances": {
                        item.participant_id: runner_map[item.participant_id]
                        for item in active_workers
                    },
                    "launch_processes": {
                        item.participant_id: _json_value(
                            operation.metadata.get("launch_processes", {}).get(item.participant_id)
                        )
                        for item in active_workers
                    },
                    "open_evidence": {
                        item.participant_id: _json_value(evidence_map[item.participant_id])
                        for item in active_workers
                    },
                    # A surviving worker that was already explicitly released
                    # in the previous operation must not receive a second
                    # release call merely because the coordinator changed.
                    # Keep those receipts as history only; they are not
                    # authorization for this operation's release boundary.
                    "carried_release_receipts": {
                        item.participant_id: _json_value(
                            operation.metadata.get("release_receipts", {}).get(item.participant_id)
                        )
                        for item in active_workers
                        if isinstance(operation.metadata.get("release_receipts"), Mapping)
                        and operation.metadata.get("release_receipts", {}).get(item.participant_id) is not None
                    },
                    "release_receipts": {},
                    # This legacy independent-worker path retains old worker
                    # records behind the new coordinator only for ``hold``.
                    # Native ``restart`` admission is refused before this
                    # durable operation is created.
                    "held_participants": list(worker_ids),
                    "restart_participants": (
                        list(worker_ids) if worker_policy == "restart" else []
                    ),
                    "restart_release_authorizations": {},
                    "interrupt_receipts": {},
                    "status_evidence": {},
                    "shutdown_receipts": {},
                    "worker_status_evidence": {},
                    "launch_intents": {
                        target.participant_id: {
                            "state": "pending",
                            "participant_id": target.participant_id,
                            "session_id": target.session_id,
                            "generation": generation,
                            "spec": _json_value(fresh_spec),
                        }
                    },
                    "ctx_intent": {
                        "state": "in-progress",
                        "old_coordinator_id": old_coordinator.participant_id,
                        "new_coordinator_id": target.participant_id,
                        "worker_policy": worker_policy,
                        "worker_mapping": _json_value(normalized_mapping),
                    },
                    "claim_transfer": {
                        "state": "pending" if old_coordinator.writer_claim is not None else "not-required",
                        "old_participant_id": old_coordinator.participant_id,
                        "new_participant_id": target.participant_id,
                    },
                    "checkpoint": checkpoint,
                    "checkpoint_digest": _digest(checkpoint),
                },
            )
            old_archive = old_coordinator
            old_archive.state = "stopped"
            self._archived_participants[old_archive.participant_id] = old_archive
            self._participants.pop(old_archive.participant_id, None)
            self._participants[target.participant_id] = target
            self._coordinator_id = target.participant_id
            self._session_history.add(target.session_id)
            # No policy rewrites parent/task identity. The fresh coordinator
            # owns only its own native lineage; retained worker records remain
            # evidence from the old lineage until an explicit restart is
            # correlated after release.
            for worker_id in worker_ids:
                current_worker = self._participants.get(worker_id)
                if current_worker is None:
                    raise _error("unknown", "ctx retained worker disappeared")
                current_worker.state = "held"
                current_worker.metadata["ctx_hold"] = {
                    "operation_id": ctx_operation.operation_id,
                    "generation": generation,
                    "policy": worker_policy,
                    "restart_pending": False,
                    "parent_id": current_worker.parent_id,
                    "task_id": current_worker.task_id,
                }
            # Carry only legitimate unsent backlog from the prior released
            # gate.  Acknowledged/in-flight/uncertain entries retain their
            # original correlation, and archived coordinator mail remains
            # attached to the archived identity rather than being silently
            # retargeted to the new coordinator.
            self._carry_unsent_mail(ctx_operation)
            for entry in self._mailboxes.values():
                if (
                    entry.operation_id == ctx_operation.operation_id
                    and entry.recipient_id in self._participants
                    and entry.state in {"queued", "fenced"}
                ):
                    entry.state = "fenced"
            checkpoint_entry = MailboxEntry(
                message_id="msg-" + uuid.uuid4().hex,
                request_id=request_id,
                sender_id=old_archive.participant_id,
                recipient_id=target.participant_id,
                task_id=target.task_id,
                payload_ref=checkpoint_payload,
                state="fenced",
                generation=generation,
                operation_id=ctx_operation.operation_id,
                metadata={"checkpoint_digest": _digest(checkpoint)},
            )
            self._mailboxes[checkpoint_entry.message_id] = checkpoint_entry
            self._operations[old_operation_id].phase = "complete"
            self._operations[old_operation_id].metadata["superseded_by"] = ctx_operation.operation_id
            self._operations[ctx_operation.operation_id] = ctx_operation
            self._active_operation_id = ctx_operation.operation_id
            self._save_request_result(request_id, ctx_operation.to_dict())
            self._persist({
                "event": "ctx-fenced",
                "operation_id": ctx_operation.operation_id,
                "old_coordinator_id": old_archive.participant_id,
                "new_coordinator_id": target.participant_id,
            })
            operation_id = ctx_operation.operation_id

        async def _call(method: Any, participant_id: str) -> Any:
            result = method(participant_id)
            if not inspect.isawaitable(result):
                raise TypeError("managed runtime lifecycle method must be awaitable")
            return await result

        try:
            # Retained workers are not restarted.  Their status must prove a
            # drained, tool-quiescent turn before the coordinator is retired.
            for worker in active_workers:
                with self._transaction():
                    current = self._current_operation(operation_id, generation)
                    expected_runner = current.metadata["runner_instances"].get(worker.participant_id)
                status = await _call(status_call, worker.participant_id)
                with self._transaction():
                    current = self._current_operation(operation_id, generation)
                valid, reason = self._runtime_quiescent(
                    status, worker, current, expected_runner_instance_id=expected_runner
                )
                if not valid:
                    raise _error("uncertain-effect", "ctx worker is not quiescent: %s" % reason)
                with self._transaction():
                    current = self._current_operation(operation_id, generation)
                    current.metadata["worker_status_evidence"][worker.participant_id] = _json_value(status)
                    self._persist({"event": "ctx-worker-quiescent", "operation_id": operation_id,
                                   "participant_id": worker.participant_id})

            with self._transaction():
                current = self._current_operation(operation_id, generation)
                old_id = current.metadata["old_coordinator_id"]
                old_runner = current.metadata["old_runner_instances"][old_id]
                old_participant = self._archived_participants.get(old_id)
                if old_participant is None:
                    raise _error("unknown", "ctx archived coordinator is missing")
            receipt = await _call(interrupt, old_id)
            with self._transaction():
                current = self._current_operation(operation_id, generation)
            valid, reason = self._runtime_identity_matches(
                receipt, old_participant, current,
                expected_runner_instance_id=old_runner,
            )
            if not valid:
                raise _error("uncertain-effect", "ctx interrupt receipt is invalid: %s" % reason)
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current.metadata["interrupt_receipts"][old_id] = _json_value(receipt)
                self._persist({"event": "ctx-interrupt-receipt", "operation_id": operation_id})

            status = await _call(status_call, old_id)
            with self._transaction():
                current = self._current_operation(operation_id, generation)
            valid, reason = self._runtime_quiescent(
                status, old_participant, current, expected_runner_instance_id=old_runner
            )
            if not valid:
                raise _error("uncertain-effect", "ctx coordinator is not quiescent: %s" % reason)
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current.metadata["status_evidence"][old_id] = _json_value(status)
                self._persist({"event": "ctx-coordinator-quiescent", "operation_id": operation_id})

            shutdown_result = await _call(shutdown, old_id)
            with self._transaction():
                current = self._current_operation(operation_id, generation)
            valid, reason = self._runtime_shutdown(
                shutdown_result, old_participant, current, old_runner
            )
            if not valid:
                raise _error("uncertain-effect", "ctx old process exclusion is unproven: %s" % reason)
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current.metadata["shutdown_receipts"][old_id] = _json_value(shutdown_result)
                self._persist({"event": "ctx-old-shutdown", "operation_id": operation_id})

            # Transfer a writable coordinator's claim only after its old
            # process group is authoritatively excluded.  The state store's
            # exact transfer primitive replaces the index row atomically; a
            # release-then-claim pair would expose an unclaimed interval.
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                transfer = current.metadata["claim_transfer"]
                if transfer.get("state") == "pending":
                    old_participant = self._archived_participants[transfer["old_participant_id"]]
                    new_participant = self._participants[transfer["new_participant_id"]]
                    transfer.update({
                        "state": "in-progress",
                        "generation": generation,
                        "started_at": self.clock(),
                    })
                    self._persist({
                        "event": "ctx-claim-transfer-intent",
                        "operation_id": operation_id,
                    })
                    result = self._transfer_writer_claim_exact(
                        old_participant,
                        new_participant,
                        generation,
                    )
                    transfer.update({
                        "state": "complete",
                        "result": _json_value(result),
                        "completed_at": self.clock(),
                    })
                    self._persist({"event": "ctx-claim-transferred", "operation_id": operation_id})
                elif transfer.get("state") == "in-progress":
                    raise _error(
                        "uncertain-effect",
                        "ctx writer claim transfer is already in progress; recover explicitly",
                    )

            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current.phase = "starting"
                current.metadata["launch_intents"][target.participant_id]["state"] = "in-progress"
                current.metadata["launch_intents"][target.participant_id]["started_at"] = self.clock()
                self._persist({"event": "ctx-launch-intent", "operation_id": operation_id})
                target = self._participants[target.participant_id]
                spec = current.metadata["target_specs"][target.participant_id]
                target_profile = current.metadata["target_profile"]
        except BaseException as exc:
            self._mark_operation_failure(operation_id, "ctx", "uncertain-effect", str(exc))
            if isinstance(exc, asyncio.CancelledError):
                raise
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "ctx lifecycle outcome is uncertain")

        # The prior block stops immediately before open so that the spec is
        # loaded after the last durable transition without holding a state
        # lock across the adapter await.
        try:
            opened = opener(target.participant_id, dict(spec))
            if not inspect.isawaitable(opened):
                raise TypeError("managed runtime open must be awaitable")
            opened = await opened
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current_target = self._participants.get(target.participant_id)
                if current_target is None:
                    raise _error("unknown", "ctx fresh coordinator is no longer enrolled")
                runner_instance = self._runtime_runner_instance(opened)
                process = self._runtime_process(opened, "ctx-open")
                valid, reason = self._runtime_ready(opened, current_target, current, spec)
                if not valid:
                    raise _error("loader-failed", "ctx fresh coordinator is not ready-held: %s" % reason)
                target_profile = current.metadata.get("target_profile")
                if not isinstance(target_profile, Mapping) or runner_instance is None:
                    raise _error("loader-failed", "ctx target identity is incomplete")
                current.metadata["runner_instances"][target.participant_id] = runner_instance
                current.metadata["launch_processes"][target.participant_id] = _json_value(process)
                current.metadata["open_evidence"][target.participant_id] = _json_value(opened)
                intent = dict(current.metadata["launch_intents"][target.participant_id])
                intent.update({"state": "ready", "runner_instance_id": runner_instance,
                               "process": _json_value(process)})
                current.metadata["launch_intents"][target.participant_id] = intent
                self._adopt_target_runner(
                    current_target, spec, target_profile,
                    runner_instance_id=runner_instance, process=process,
                )
                current.readiness[target.participant_id] = {
                    "session_id": current_target.session_id,
                    "runner_instance_id": runner_instance,
                    "spec": _json_value(spec),
                    "evidence": _json_value(opened),
                }
                current.phase = "ready-held"
                current.metadata["ctx_intent"]["state"] = "complete"
                current.metadata["ctx_intent"]["completed_at"] = self.clock()
                current.metadata["ready_generation"] = generation
                checkpoint_entry = next(
                    entry for entry in self._mailboxes.values()
                    if entry.request_id == request_id and entry.operation_id == operation_id
                )
                # Checkpoint remains fenced until explicit release.
                checkpoint_entry.state = "fenced"
                self._persist({"event": "ctx-ready-held", "operation_id": operation_id})
                return current
        except BaseException as exc:
            self._mark_operation_failure(operation_id, "ctx-open", "uncertain-effect", str(exc))
            if isinstance(exc, asyncio.CancelledError):
                raise
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "ctx fresh coordinator outcome is uncertain")

    @staticmethod
    def _native_swap_contract_error(exc: BaseException) -> ControllerError:
        if isinstance(exc, NativeSwapContractError):
            return _error(exc.code, exc.message)
        if isinstance(exc, ControllerError):
            return exc
        return _error("invalid", str(exc))

    def _native_swap_source_locked(
            self, operation: Operation, source_operation: Operation,
            coordinator: Participant,
    ) -> Dict[str, Any]:
        """Capture immutable source facts before native swap effects."""
        startup = source_operation.metadata.get("native_startup")
        if not isinstance(startup, Mapping):
            raise _error("unsupported", "native swap source startup is unavailable")
        lineage = startup.get("lineage")
        if not isinstance(lineage, Mapping):
            raise _error("invalid", "native swap source lineage is malformed")
        source_context = self._native_context
        if not isinstance(source_context, Mapping):
            # A same-UUID swap archives an actual invocation, rather than a
            # startup descriptor.  There is no safe identity to archive when
            # the first mailbox has not bound a native context yet.
            raise _error(
                "unsupported",
                "native swap requires a bound source invocation",
            )
        source_context = self._validate_native_context(source_context)
        source_runner = source_context.get("runner_incarnation")
        invocation_id = source_context.get("invocation_id")
        source_runner = _id(source_runner, "native swap source runner incarnation") or ""
        invocation_id = _id(invocation_id, "native swap source invocation ID") or ""
        source_lineage = LineageRecord.from_dict(lineage)
        if source_lineage.owner_generation != operation.generation:
            raise _error("stale-generation", "native swap source owner generation changed")
        if source_context["lineage"] != source_lineage.to_dict():
            raise _error("ownership-conflict", "native swap source lineage changed")
        if startup.get("runner_incarnation") != source_runner:
            raise _error("ownership-conflict", "native swap source startup runner changed")
        if startup.get("invocation_id") != invocation_id:
            raise _error("ownership-conflict", "native swap source startup invocation changed")
        if startup.get("definitions") != source_context.get("definitions"):
            raise _error("permission-mismatch", "native swap source startup definitions changed")
        if coordinator.metadata.get("runner_instance_id") != source_runner:
            raise _error("ownership-conflict", "native swap source runner changed")
        # Source capture happens at account-control entry while A is still
        # released and accepting no new lifecycle operation.  The native
        # interrupt path below establishes the swap operation's durable fence
        # immediately before its one runtime control call; requiring the
        # source context to be fenced here would reject a genuine bound A
        # invocation and lose the immutable source identity.
        self._check_coordinator_interrupt_authority(source_context)
        gates = source_operation.metadata.get("capability_gates")
        gate = gates.get(coordinator.participant_id) if isinstance(gates, Mapping) else None
        source_capability_digest = gate.get("identity_digest") if isinstance(gate, Mapping) else None
        if (not isinstance(gate, Mapping) or gate.get("verdict") != "verified"
                or not isinstance(source_capability_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", source_capability_digest) is None):
            raise _error(
                "unsupported",
                "native swap source capability identity is unavailable",
            )
        source_identity = {
            "owner_generation": source_lineage.owner_generation,
            "lineage_id": source_lineage.lineage_id,
            "lineage_generation": source_lineage.lineage_generation,
            "session_uuid": source_lineage.session_uuid,
            "runner_incarnation": source_runner,
            "invocation_id": invocation_id,
        }
        return {
            "source_operation_id": source_operation.operation_id,
            "source_identity": source_identity,
            "source_context": _json_value(source_context),
            "source_context_digest": _native_swap_digest(source_context),
            "source_startup": _json_value(dict(startup)),
            "source_claim_digest": _native_swap_digest(source_lineage.workspace_claim),
            "source_runtime_identity_digest": source_capability_digest,
            "lineage": source_lineage.to_dict(),
        }

    def _native_swap_target_spec_locked(
            self, operation: Operation, coordinator: Participant,
            profile: Mapping[str, Any], runner_specs: Optional[Mapping[str, Any]],
            source: Mapping[str, Any],
    ) -> Dict[str, Any]:
        target = self._swap_spec(coordinator, operation, profile, runner_specs)
        fingerprint = target.get("fingerprint")
        if not isinstance(fingerprint, Mapping):
            raise _error("invalid", "native swap target fingerprint is malformed")
        fingerprint = copy.deepcopy(dict(fingerprint))
        source_startup = source["source_startup"]
        source_lineage = source["lineage"]
        source_fingerprint = coordinator.fingerprint
        native_config = None
        if isinstance(source_fingerprint, Mapping):
            native_config = source_fingerprint.get("native_config")
        if not isinstance(native_config, Mapping):
            native_config = fingerprint.get("native_config")
        if not isinstance(native_config, Mapping):
            native_config = {}
        target_runner = "native-swap-runner-" + uuid.uuid4().hex
        native_config = copy.deepcopy(dict(native_config))
        native_config.update({
            # This immutable launch marker is a restrictive adapter mode
            # selection, not a capability grant.  The SDK requires it before
            # accepting a native-swap release binding; ordinary initial/ctx
            # startup specs never receive it.
            "native_swap_target": True,
            "lineage_id": source_lineage["lineage_id"],
            "lineage_generation": source_lineage["lineage_generation"],
            "runner_incarnation": target_runner,
            "trusted_definitions": _json_value(
                native_config.get("trusted_definitions", source_startup.get("definitions", {}))
            ),
        })
        fingerprint["native_config"] = native_config
        fingerprint["lineage_context"] = {
            "owner_generation": source["source_identity"]["owner_generation"],
            "lineage_id": source_lineage["lineage_id"],
            "lineage_generation": source_lineage["lineage_generation"],
            "runner_incarnation": target_runner,
        }
        fingerprint["lineage_claim"] = _json_value(
            source_lineage["workspace_claim"]
        )
        target["fingerprint"] = fingerprint
        target = _safe_runner_projection(target, "native swap target specification")
        return target

    def _native_swap_binding_locked(
            self, operation: Operation, stage: str,
    ) -> Dict[str, Any]:
        native_swap = operation.metadata.get("native_swap")
        if not isinstance(native_swap, Mapping):
            raise _error("invalid", "native swap metadata is missing")
        interrupt_id = native_swap.get("interrupt_id")
        interrupt_digest = native_swap.get("interrupt_intent_digest")
        archive_digest = native_swap.get("source_archive_digest")
        target_runner = native_swap.get("target_runner_incarnation")
        release_id = native_swap.get("release_id")
        release_digest = native_swap.get("release_intent_digest")
        index = NATIVE_SWAP_STAGES.index(stage)
        if index == 0:
            interrupt_id = interrupt_digest = archive_digest = None
            release_id = release_digest = None
        elif index == 1:
            archive_digest = release_id = release_digest = None
        elif index == 2:
            release_id = release_digest = None
        elif index == 3:
            release_id = release_digest = None
        elif index == 4:
            pass
        elif index == 5:
            pass
        return {
            "schema_version": 2,
            "architecture": "native-coordinator-lineage",
            "record_kind": "native-swap-evidence-request",
            "stage": stage,
            "operation_id": operation.operation_id,
            "owner_generation": operation.generation,
            "expected_daemon_id": native_swap["daemon_id"],
            "source_identity": _json_value(native_swap["source_identity"]),
            "source_context_digest": native_swap["source_context_digest"],
            "source_claim_digest": native_swap["source_claim_digest"],
            "target_spec_digest": native_swap["target_spec_digest"],
            "request_epoch_id": native_swap["request_epoch_id"],
            "interrupt_id": interrupt_id,
            "interrupt_intent_digest": interrupt_digest,
            "source_archive_digest": archive_digest,
            "target_runner_incarnation": target_runner,
            "release_id": release_id,
            "release_intent_digest": release_digest,
            "release_boundary": (
                _json_value(native_swap.get("release_boundary"))
                if stage == "release-boundary" else None
            ),
        }

    @staticmethod
    def _native_swap_observation_satisfied(observation: Mapping[str, Any], stage: str) -> bool:
        request_observation = observation.get("request_observation")
        if not isinstance(request_observation, Mapping):
            return False
        if (request_observation.get("observable") is not True
                or request_observation.get("continuous") is not True
                or request_observation.get("new_requests") != 0):
            return False
        if stage != "entry":
            clear = observation.get("worker_state_clear")
            if not isinstance(clear, Mapping) or clear.get("cleared") is not True:
                return False
        return True

    def _native_swap_runtime_identity_locked(self, operation: Operation) -> str:
        native_swap = operation.metadata.get("native_swap")
        if not isinstance(native_swap, Mapping):
            raise _error("invalid", "native swap metadata is missing")
        value = native_swap.get("runtime_identity_digest")
        if not isinstance(value, str) or not re.fullmatch(r"[0-9a-f]{64}", value):
            raise _error("live-unverified", "native swap runtime identity is unproven")
        return value

    @staticmethod
    def _native_swap_source_runtime_identity_locked(operation: Operation) -> str:
        native_swap = operation.metadata.get("native_swap")
        if not isinstance(native_swap, Mapping):
            raise _error("invalid", "native swap metadata is missing")
        value = native_swap.get("source_runtime_identity_digest")
        if not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{64}", value) is None:
            raise _error("unsupported", "native swap source capability identity is unproven")
        return value

    def _native_swap_owner_claim_matches_locked(self, operation: Operation) -> None:
        """Recheck the retained A owner/claim across every native await."""
        native_swap = operation.metadata.get("native_swap")
        if not isinstance(native_swap, Mapping):
            raise _error("invalid", "native swap metadata is missing")
        source_startup = native_swap.get("source_startup")
        lineage = source_startup.get("lineage") if isinstance(source_startup, Mapping) else None
        if not isinstance(lineage, Mapping):
            raise _error("ownership-conflict", "native swap source lineage is unavailable")
        self._check_generation(operation.generation)
        owner_reader = getattr(self.store, "read_owner", None)
        claims_reader = getattr(self.store, "read_lineage_claims", None)
        if not callable(owner_reader) or not callable(claims_reader):
            raise _error("unsupported", "native swap owner authority is unavailable")
        owner = owner_reader()
        claim = lineage.get("workspace_claim")
        if (
            not isinstance(owner, Mapping)
            or owner.get("mode") != "managed"
            or owner.get("generation") != operation.generation
            or owner.get("lane") != lineage.get("lane")
            or owner.get("daemon_id") != native_swap.get("daemon_id")
            or not isinstance(claim, Mapping)
            or claim.get("state") not in {"held", "active"}
            or claim not in claims_reader()
        ):
            raise _error("ownership-conflict", "native swap owner or workspace claim changed")

    def _native_swap_prepare_entry_capture(
            self, operation_id: str, generation: Any,
    ) -> Tuple[str, Dict[str, Any]]:
        """Persist the immutable entry-capture intent before any preflight await."""
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            native_swap = operation.metadata.get("native_swap")
            if not isinstance(native_swap, dict):
                raise _error("invalid", "native swap metadata is missing")
            binding = self._native_swap_binding_locked(operation, "entry")
            existing = native_swap.get("entry_capture")
            if existing is not None:
                if not isinstance(existing, Mapping):
                    raise _error("invalid", "native swap entry capture is malformed")
                if existing.get("binding") != binding:
                    raise _error("stale-generation", "native swap entry capture binding changed")
                if existing.get("state") != "pending":
                    raise _error(
                        "uncertain-effect",
                        "native swap entry capture already crossed its one observation boundary",
                    )
                raise _error(
                    "uncertain-effect",
                    "native swap entry capture is pending without its captured response",
                )
            capture = {
                "capture_id": "native-swap-entry-" + uuid.uuid4().hex,
                "binding": _json_value(binding),
                "state": "pending",
                "observation_digest": None,
            }
            native_swap["entry_capture"] = capture
            operation.metadata["native_swap"] = native_swap
            self._persist({
                "event": "native-swap-entry-capture-pending",
                "operation_id": operation_id,
                "capture_id": capture["capture_id"],
            })
            return capture["capture_id"], _json_value(binding)

    def _native_swap_capture_entry(
            self, operation_id: str, generation: Any,
    ) -> Tuple[str, Dict[str, Any]]:
        """Capture one provider response in memory, then persist only its digest."""
        provider = self._native_swap_evidence_provider
        if not callable(provider):
            raise _error("unsupported", "native swap evidence provider is unavailable")
        capture_id, binding = self._native_swap_prepare_entry_capture(
            operation_id, generation
        )
        try:
            response = provider(copy.deepcopy(binding))
            if inspect.isawaitable(response):
                raise _error(
                    "unsupported",
                    "native swap evidence provider must be synchronous",
                )
            encoded = _canonical_json(response, "native swap entry capture").encode("utf-8")
            if len(encoded) > _NATIVE_SWAP_ENTRY_CAPTURE_BYTES:
                raise _error("invalid", "native swap entry capture exceeds capacity")
            response = _json_value(response)
            if not isinstance(response, Mapping):
                raise _error("invalid", "native swap entry capture response is malformed")
            observation_digest = _native_swap_digest(response)
        except ControllerError:
            raise
        except Exception as exc:
            raise _error("uncertain-effect", "native swap entry capture outcome is unknown") from exc
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            native_swap = operation.metadata.get("native_swap")
            capture = native_swap.get("entry_capture") if isinstance(native_swap, Mapping) else None
            if (not isinstance(capture, dict)
                    or capture.get("capture_id") != capture_id
                    or capture.get("state") != "pending"
                    or capture.get("binding") != binding):
                raise _error("stale-generation", "native swap entry capture changed")
            capture["state"] = "captured-unvalidated"
            capture["observation_digest"] = observation_digest
            native_swap["entry_capture"] = capture
            operation.metadata["native_swap"] = native_swap
            self._persist({
                "event": "native-swap-entry-captured",
                "operation_id": operation_id,
                "capture_id": capture_id,
            })
        return capture_id, response

    def _native_swap_accept_entry_capture(
            self, operation_id: str, generation: Any,
            capture_id: str, response: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Validate the frozen response against the independent target pin."""
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            native_swap = operation.metadata.get("native_swap")
            if not isinstance(native_swap, dict):
                raise _error("invalid", "native swap metadata is missing")
            capture = native_swap.get("entry_capture")
            if (not isinstance(capture, Mapping)
                    or capture.get("capture_id") != capture_id
                    or capture.get("state") != "captured-unvalidated"):
                raise _error("uncertain-effect", "native swap entry capture is unavailable")
            if not isinstance(response, Mapping):
                raise _error("invalid", "native swap entry response is malformed")
            if capture.get("observation_digest") != _native_swap_digest(response):
                raise _error("stale-generation", "native swap entry capture response changed")
            binding = self._native_swap_binding_locked(operation, "entry")
            runtime_identity_digest = self._native_swap_runtime_identity_locked(operation)
            records = native_swap.get("native_swap_evidence")
            if not isinstance(records, dict) or records:
                raise _error("stale-generation", "native swap entry stage is no longer first")
            try:
                normalized = _validate_native_swap_response(
                    binding,
                    response,
                    runtime_identity_digest=runtime_identity_digest,
                    prior_records={},
                )
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
            records["entry"] = {
                "observation": _json_value(normalized),
                "evidence_digest": _native_swap_digest(normalized),
            }
            capture = dict(capture)
            capture["state"] = "accepted"
            if capture["observation_digest"] != records["entry"]["evidence_digest"]:
                raise _error("stale-generation", "native swap entry observation digest changed")
            native_swap["entry_capture"] = capture
            native_swap["native_swap_evidence"] = records
            operation.metadata["native_swap"] = native_swap
            self._persist({
                "event": "native-swap-entry-accepted",
                "operation_id": operation_id,
                "capture_id": capture_id,
            })
            return _json_value(normalized)

    def _native_swap_provider_stage(
            self, operation_id: str, generation: Any, stage: str,
    ) -> Dict[str, Any]:
        """Observe and durably append one independent provider stage."""
        provider = self._native_swap_evidence_provider
        if not callable(provider):
            raise _error("unsupported", "native swap evidence provider is unavailable")
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            native_swap = operation.metadata.get("native_swap")
            if not isinstance(native_swap, Mapping):
                raise _error("invalid", "native swap metadata is missing")
            records = native_swap.get("native_swap_evidence")
            if not isinstance(records, Mapping):
                raise _error("invalid", "native swap evidence ledger is malformed")
            binding = self._native_swap_binding_locked(operation, stage)
            runtime_identity_digest = self._native_swap_runtime_identity_locked(operation)
            previous = _json_value(records)
        try:
            result = provider(copy.deepcopy(binding))
            if inspect.isawaitable(result):
                raise _error("unsupported", "native swap evidence provider must be synchronous")
            try:
                normalized = _validate_native_swap_response(
                    binding, result,
                    runtime_identity_digest=runtime_identity_digest,
                    prior_records=previous,
                )
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
        except ControllerError:
            raise
        except Exception as exc:
            raise _error("uncertain-effect", "native swap evidence outcome is unknown") from exc
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            native_swap = operation.metadata.get("native_swap")
            records = native_swap.get("native_swap_evidence")
            if not isinstance(records, dict):
                raise _error("invalid", "native swap evidence ledger changed")
            if stage in records:
                if records[stage].get("observation") != normalized:
                    raise _error("stale-generation", "native swap evidence stage was rewritten")
                return _json_value(normalized)
            expected_prior_stages = set(
                NATIVE_SWAP_STAGES[:NATIVE_SWAP_STAGES.index(stage)]
            )
            # Durable JSON writers may reorder mapping keys.  Stage identity
            # is semantic; compare the exact prefix set rather than the
            # incidental insertion order while retaining the pure validator's
            # chronology and sticky-evidence checks above.
            if set(records) != expected_prior_stages:
                raise _error("stale-generation", "native swap evidence stage order changed")
            records[stage] = {
                "observation": _json_value(normalized),
                "evidence_digest": _native_swap_digest(normalized),
            }
            native_swap["native_swap_evidence"] = records
            operation.metadata["native_swap"] = native_swap
            self._persist({
                "event": "native-swap-evidence",
                "operation_id": operation_id,
                "stage": stage,
            })
            return _json_value(normalized)

    def _native_swap_require_stage(
            self, operation_id: str, generation: Any, stage: str,
    ) -> None:
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            native_swap = operation.metadata["native_swap"]
            records = _json_value(native_swap["native_swap_evidence"])
            runtime_identity_digest = self._native_swap_runtime_identity_locked(operation)
        try:
            # The pure contract intentionally accepts a bounded successful
            # prefix; it is not a capability grant and is rechecked before
            # every subsequent runtime effect.
            _require_native_swap_stages(
                records,
                runtime_identity_digest=runtime_identity_digest,
                through_stage=stage,
            )
        except NativeSwapContractError as exc:
            raise _error(exc.code, exc.message) from exc

    async def _native_swap(
            self, request_id: str, generation: Any, profile: Any,
            runner_specs: Optional[Mapping[str, Any]],
    ) -> Operation:
        profile_summary = self._profile_summary(profile)
        request_id = _id(request_id, "request_id") or ""
        generation = self._generation_valid(generation)
        with self._transaction():
            if self._native_swap_evidence_provider is None:
                # The absence is a constructor capability refusal, not a
                # public opt-in.  Do not start any native runtime effect.
                provider_absent = True
            else:
                provider_absent = False
            coordinator = self._participants.get(self._coordinator_id or "")
            if coordinator is None or coordinator.role.casefold() != "coordinator":
                raise _error("unsupported", "native swap coordinator is unavailable")
            if any(item.role.casefold() != "coordinator" for item in self._participants.values()):
                raise _error("migration-required", "native swap cannot mix independent workers")
            semantic_specs = runner_specs
            if semantic_specs is None:
                semantic_specs = {
                    coordinator.participant_id: coordinator.metadata.get(
                        "runner_spec", coordinator.metadata.get("spec")
                    )
                }
            semantic_specs = {
                str(key): _safe_runner_projection(value, "native swap runner specification")
                for key, value in semantic_specs.items()
            }
            request_content = {
                "profile": _json_value(profile_summary),
                "runner_specs": _json_value(semantic_specs),
            }
            # A completed native swap adopts the target runner into the
            # participant record.  When a caller retries the same request
            # without an explicit runner_specs map, that mutable current
            # record is no longer the original request content.  Reuse the
            # durable operation snapshot for exact request-ID deduplication;
            # an explicitly supplied replacement map remains a new digest and
            # is rejected by the normal request ledger.
            if runner_specs is None:
                prior_request = self._requests.get(request_id)
                prior_result = (
                    prior_request.get("result")
                    if isinstance(prior_request, Mapping)
                    and prior_request.get("kind") == "operation"
                    else None
                )
                if isinstance(prior_result, Mapping):
                    prior_operation = self._operations.get(
                        prior_result.get("operation_id")
                    )
                    prior_content = (
                        prior_operation.metadata.get("request_content")
                        if prior_operation is not None
                        else None
                    )
                    if isinstance(prior_content, Mapping):
                        prior_specs = prior_content.get("runner_specs")
                        if prior_specs is not None:
                            request_content["runner_specs"] = _json_value(prior_specs)
        operation = self.begin_operation(
            request_id, "swap", generation, request_content=request_content
        )
        operation_id = operation.operation_id
        resume_native = isinstance(operation.metadata.get("native_swap"), Mapping)
        if operation.phase in {"ready-held", "released"}:
            return operation
        if operation.phase in {"failed", "indeterminate"}:
            raise _error("uncertain-effect", "native swap requires explicit recovery")
        try:
            if not resume_native:
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    source_operation_id = operation.metadata.get("previous_active_operation_id")
                    source_operation = self._operations.get(source_operation_id)
                    coordinator = self._participants.get(self._coordinator_id or "")
                    if source_operation is None or source_operation.phase != "released":
                        raise _error("busy", "native swap source operation changed")
                    if coordinator is None:
                        raise _error("unknown", "native swap coordinator disappeared")
                    source = self._native_swap_source_locked(
                        operation, source_operation, coordinator
                    )
                    target_spec = self._native_swap_target_spec_locked(
                        operation, coordinator, profile_summary, runner_specs, source
                    )
                    daemon_id = (
                        self._coordinator_interrupt_daemon_id
                        or self._native_stop_daemon_id
                        or self._native_daemon_id_locked()
                    )
                    # The source startup descriptor is immutable identity evidence;
                    # daemon ownership is carried by the swap record itself and
                    # must not be injected into the startup schema.
                    source_startup = copy.deepcopy(source["source_startup"])
                    native_swap = {
                        **native_record_marker("native-swap"),
                        "swap_schema": _NATIVE_SWAP_SCHEMA,
                        "state": "entry",
                        "request_epoch_id": "native-swap-epoch-" + uuid.uuid4().hex,
                        "daemon_id": daemon_id,
                        "source_operation_id": source["source_operation_id"],
                        "source_identity": _json_value(source["source_identity"]),
                        "source_context": _json_value(source["source_context"]),
                        "source_context_digest": source["source_context_digest"],
                        "source_startup": _json_value(source_startup),
                        "source_claim_digest": source["source_claim_digest"],
                        "source_runtime_identity_digest": source["source_runtime_identity_digest"],
                        "target_profile": _json_value(profile_summary),
                        "target_specs": {coordinator.participant_id: _json_value(target_spec)},
                        "target_spec_digest": _native_swap_digest(target_spec),
                        "target_runner_incarnation": target_spec["fingerprint"]["lineage_context"]["runner_incarnation"],
                        "target_runner_instance_id": None,
                        "interrupt_id": "native-swap-interrupt-" + uuid.uuid4().hex,
                        "interrupt_intent_digest": None,
                        "source_archive_id": "native-swap-archive-" + uuid.uuid4().hex,
                        "source_archive_digest": None,
                        "runtime_identity_digest": None,
                        "native_swap_evidence": {},
                        "entry_capture": None,
                        "worker_dispositions": {},
                        "release_id": None,
                        "release_intent_digest": None,
                        "release_binding": None,
                        "release_validation_id": None,
                        "release_authorization": None,
                        "release_boundary": None,
                        "release_receipt": None,
                        "shutdown_intent": None,
                        "target_open_intent": None,
                        "uncertainty": None,
                    }
                    gate = operation.metadata.get("capability_gates")
                    gate_value = gate.get(coordinator.participant_id) if isinstance(gate, Mapping) else None
                    # The static runtime gate is an independent pin.  The private
                    # provider cannot manufacture or replace this identity.
                    if isinstance(gate_value, Mapping):
                        native_swap["runtime_identity_digest"] = gate_value.get("identity_digest")
                    operation.metadata["native_swap"] = native_swap
                    operation.metadata["target_profile"] = _json_value(profile_summary)
                    operation.metadata["target_specs"] = {coordinator.participant_id: _json_value(target_spec)}
                    operation.metadata.setdefault("runner_instances", {})
                    operation.metadata.setdefault("open_evidence", {})
                    operation.metadata.setdefault("launch_intents", {})
                    operation.metadata.setdefault("launch_processes", {})
                    operation.metadata["launch_intents"][coordinator.participant_id] = {
                        "state": "pending",
                        "participant_id": coordinator.participant_id,
                        "session_id": coordinator.session_id,
                        "generation": generation,
                        "spec": _json_value(target_spec),
                    }
                    operation.phase = "quiescing"
                    self._persist({"event": "native-swap-entry", "operation_id": operation_id})
                if provider_absent:
                    raise _error("unsupported", "native swap evidence provider is unavailable")
                # Capture the entry observation exactly once while the real source
                # invocation is still bound and released.  The response remains
                # in memory only; durable state receives its binding, capture ID,
                # and digest, never an unchecked provider body.
                entry_capture_id, entry_response = self._native_swap_capture_entry(
                    operation_id, generation
                )
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    coordinator = self._participants[self._coordinator_id]
                    trusted = self._trusted_transcript_preflight(
                        coordinator, profile_summary, target_spec,
                        allow_reserved_written_promotion=False,
                    )
                    self._apply_transcript_preflight(coordinator, trusted)
                    operation.metadata["transcript_preflight"] = {
                        coordinator.participant_id: _json_value(trusted)
                    }
                    self._persist({
                        "event": "native-swap-transcript-preflight",
                        "operation_id": operation_id,
                    })
                await self._preflight_operation_specs(
                    operation_id, generation,
                    {coordinator.participant_id: target_spec},
                )
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    self._native_swap_owner_claim_matches_locked(operation)
                    native_swap = operation.metadata["native_swap"]
                    gate = operation.metadata.get("capability_gates")
                    gate_value = gate.get(coordinator.participant_id) if isinstance(gate, Mapping) else None
                    if not isinstance(gate_value, Mapping) or gate_value.get("verdict") != "verified":
                        raise _error("live-unverified", "native swap capability gate is not verified")
                    native_swap["runtime_identity_digest"] = gate_value.get("identity_digest")
                    operation.metadata["native_swap"] = native_swap
                    self._persist({"event": "native-swap-capability-bound", "operation_id": operation_id})
                self._native_swap_accept_entry_capture(
                    operation_id, generation, entry_capture_id, entry_response
                )
            else:
                if provider_absent:
                    raise _error("unsupported", "native swap evidence provider is unavailable")

            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                native_records = operation.metadata["native_swap"]["native_swap_evidence"]
            if "graph-drained" not in native_records:
                await self._native_swap_entry_and_interrupt(operation_id, generation)
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                native_records = operation.metadata["native_swap"]["native_swap_evidence"]
            if "source-excluded" not in native_records:
                await self._native_swap_shutdown_archive(operation_id, generation)
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                native_records = operation.metadata["native_swap"]["native_swap_evidence"]
            if "target-held" not in native_records:
                await self._native_swap_target_open(operation_id, generation)
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                self._native_swap_owner_claim_matches_locked(operation)
                operation.phase = "ready-held"
                operation.metadata["ready_generation"] = generation
                operation.metadata["native_swap"]["state"] = "ready-held"
                self._persist({"event": "native-swap-ready-held", "operation_id": operation_id})
                return operation
        except asyncio.CancelledError:
            self._mark_operation_failure(operation_id, "native-swap", "uncertain-effect", "native swap was cancelled")
            raise
        except ControllerError as exc:
            with self._transaction():
                current = self._operations.get(operation_id)
                if current is not None and current.phase not in {
                    "ready-held", "released", "failed", "indeterminate",
                }:
                    native_swap = current.metadata.get("native_swap")
                    evidence = (
                        native_swap.get("native_swap_evidence")
                        if isinstance(native_swap, Mapping) else None
                    )
                    effect_window = current.phase not in {"preflight", "quiescing"}
                    effect_window = effect_window or bool(evidence)
                    effect_window = effect_window or (
                        isinstance(native_swap, Mapping)
                        and any(
                            native_swap.get(name) is not None
                            for name in ("interrupt_intent_digest", "shutdown_intent",
                                         "source_archive_digest", "target_open_intent",
                                         "target_runner_instance_id")
                        )
                    )
                    effect_window = effect_window or (
                        isinstance(native_swap, Mapping)
                        and isinstance(native_swap.get("entry_capture"), Mapping)
                        and native_swap["entry_capture"].get("state")
                        in {"pending", "captured-unvalidated"}
                    )
                    current.phase = (
                        "indeterminate"
                        if effect_window or exc.code not in {
                            "unsupported", "live-unverified", "invalid"
                        }
                        else "failed"
                    )
                    if isinstance(native_swap, dict):
                        native_swap["state"] = "failed" if current.phase == "failed" else "uncertain"
                        native_swap["uncertainty"] = {"code": exc.code, "message": exc.message}
                    self._persist({"event": "native-swap-refused", "operation_id": operation_id, "code": exc.code})
            raise
        except Exception as exc:
            self._mark_operation_failure(operation_id, "native-swap", "uncertain-effect", str(exc))
            raise _error("uncertain-effect", "native swap outcome is uncertain") from exc

    async def _native_swap_entry_and_interrupt(self, operation_id: str, generation: Any) -> None:
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            native_swap = operation.metadata["native_swap"]
            native_records = native_swap.get("native_swap_evidence")
            if not isinstance(native_records, Mapping):
                raise _error("invalid", "native swap evidence ledger is malformed")
            already_drained = "graph-drained" in native_records
            participant = self._participants[self._coordinator_id]
            runner = native_swap["source_identity"]["runner_incarnation"]
        if already_drained:
            self._native_swap_require_stage(operation_id, generation, "graph-drained")
            return
        self._native_swap_require_stage(operation_id, generation, "entry")
        status_call = getattr(self.runtime, "status", None) if self.runtime is not None else None
        if not callable(status_call):
            raise _error("unsupported", "native swap runtime status is unavailable")
        status = status_call(participant.participant_id)
        if inspect.isawaitable(status):
            status = await status
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            context = self._native_context
            if not isinstance(context, Mapping):
                raise _error("unsupported", "native swap source context is unavailable")
            if context.get("invocation_id") != native_swap["source_identity"]["invocation_id"]:
                raise _error("stale-generation", "native swap source invocation changed")
            if context.get("runner_incarnation") != runner:
                raise _error("stale-generation", "native swap source runner changed")
            self._check_coordinator_interrupt_authority(context)
            self._native_swap_source_runtime_identity_locked(operation)
        valid, reason = self._runtime_identity_matches(
            status, participant, operation,
            expected_runner_instance_id=runner,
        )
        if not valid:
            raise _error("uncertain-effect", "native swap source identity is unproven: " + reason)
        process = self._runtime_process(status, "native swap source pre-interrupt")
        if (
            process.get("exited") is not False
            or process.get("group_excluded") is not False
        ):
            raise _error(
                "uncertain-effect",
                "native swap source process is not live and exclusively owned",
            )
        await self.interrupt_native_coordinator(
            operation_id, generation,
            interrupt_id=native_swap["interrupt_id"],
            capability_digest=self._native_swap_source_runtime_identity_locked(operation),
            request_epoch_id=native_swap["request_epoch_id"],
        )
        # ``interrupt_native_coordinator`` seals the exact selection only
        # after the durable fence is in place.  Bind that persisted selection
        # into the evidence request after the adapter boundary; constructing
        # a digest from a pre-call guess would permit a stale/competing
        # interrupt frame to masquerade as this swap.
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            native_swap = operation.metadata["native_swap"]
            selection = operation.metadata.get("coordinator_interrupt_selection")
            if not isinstance(selection, Mapping):
                raise _error(
                    "uncertain-effect",
                    "native swap interrupt selection was not durably committed",
                )
            native_swap["interrupt_intent_digest"] = _digest(selection)
            operation.metadata["native_swap"] = native_swap
            self._persist({"event": "native-swap-source-status", "operation_id": operation_id})
        status = status_call(participant.participant_id)
        if inspect.isawaitable(status):
            status = await status
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
        valid, reason = self._runtime_quiescent(
            status, participant, operation, expected_runner_instance_id=runner
        )
        evidence = self._runtime_evidence(status, "native swap graph status")
        if not valid:
            raise _error("uncertain-effect", "native swap graph drain is unproven: " + reason)
        try:
            interrupt_status = self.coordinator_interrupt_status(
                native_swap["interrupt_id"]
            )
        except ControllerError as exc:
            raise _error(
                "uncertain-effect",
                "native coordinator interrupt status is unavailable: " + exc.message,
            ) from exc
        if (
            interrupt_status.get("runtime_acknowledged") is not True
            or interrupt_status.get("graph_quiescent") is not True
            or not isinstance(interrupt_status.get("children"), list)
            or any(
                not isinstance(child, Mapping)
                or child.get("status") not in {"completed", "stopped"}
                for child in interrupt_status["children"]
            )
        ):
            raise _error(
                "uncertain-effect",
                "native coordinator interrupt status has unresolved graph facts",
            )
        self._native_swap_provider_stage(operation_id, generation, "graph-drained")
        self._native_swap_require_stage(operation_id, generation, "graph-drained")

    async def _native_swap_shutdown_archive(self, operation_id: str, generation: Any) -> None:
        skip_shutdown = False
        receipt: Any = None
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            native_swap = operation.metadata["native_swap"]
            participant = self._participants[self._coordinator_id]
            runner = native_swap["source_identity"]["runner_incarnation"]
            native_records = native_swap.get("native_swap_evidence")
            if not isinstance(native_records, Mapping):
                raise _error("invalid", "native swap evidence ledger is malformed")
            if ("source-excluded" in native_records
                    and native_swap.get("source_archive_digest") is not None):
                skip_shutdown = True
            elif native_swap.get("shutdown_intent") is None:
                native_swap["shutdown_intent"] = {
                    "state": "in-progress",
                    "participant_id": participant.participant_id,
                    "runner_instance_id": runner,
                    "generation": generation,
                }
                operation.phase = "paused"
                operation.metadata["native_swap"] = native_swap
                self._persist({"event": "native-swap-shutdown-intent", "operation_id": operation_id})
            elif native_swap["shutdown_intent"].get("state") == "complete":
                # A completed intent is an immutable proof that the runtime
                # boundary was already attempted.  Recovery may finish the
                # controller archive, but must never issue shutdown again.
                skip_shutdown = True
                receipt = native_swap["shutdown_intent"].get("receipt")
            else:
                raise _error("uncertain-effect", "native swap shutdown intent is unresolved")
        if skip_shutdown and native_swap.get("source_archive_digest") is not None:
            if "source-excluded" not in native_records:
                self._native_swap_provider_stage(
                    operation_id, generation, "source-excluded"
                )
            return
        if not skip_shutdown:
            shutdown = getattr(self.runtime, "shutdown", None) if self.runtime is not None else None
            if not callable(shutdown):
                raise _error("unsupported", "native swap runtime shutdown is unavailable")
            receipt = shutdown(participant.participant_id)
            if inspect.isawaitable(receipt):
                receipt = await receipt
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
        valid, reason = self._runtime_shutdown(
            receipt, participant, operation, runner
        )
        if not valid:
            raise _error("uncertain-effect", "native swap source shutdown is unproven: " + reason)
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            native_swap = operation.metadata["native_swap"]
            native_swap["shutdown_intent"] = {
                **dict(native_swap["shutdown_intent"]),
                "state": "complete",
                "receipt": _json_value(receipt),
            }
            operation.metadata["native_swap"] = native_swap
            self._persist({"event": "native-swap-source-shutdown", "operation_id": operation_id})
        archive = self.archive_native_source(
            "native-swap-archive-" + operation_id,
            operation_id,
            generation,
        )
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            native_swap = operation.metadata["native_swap"]
            native_swap["source_archive_id"] = archive["archive_id"]
            native_swap["source_archive_digest"] = archive["snapshot_digest"]
            # The archive now owns the complete A admission/stop/interrupt
            # ledgers.  Retire those live maps before target activation so a
            # later B context cannot validate or allocate against A-owned
            # identities.  The immutable archive remains the source of
            # historical evidence and identity-reuse checks.
            self._native_admissions.clear()
            self._native_child_observations.clear()
            self._native_stops.clear()
            self._coordinator_interrupts.clear()
            operation.metadata["native_swap"] = native_swap
            self._persist({"event": "native-swap-source-archived", "operation_id": operation_id})
        self._native_swap_provider_stage(operation_id, generation, "source-excluded")

    async def _native_swap_target_open(self, operation_id: str, generation: Any) -> None:
        opener = getattr(self.runtime, "open", None) if self.runtime is not None else None
        if not callable(opener):
            raise _error("unsupported", "native swap runtime open is unavailable")
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            native_swap = operation.metadata["native_swap"]
            records = native_swap.get("native_swap_evidence")
            runtime_identity_digest = self._native_swap_runtime_identity_locked(operation)
            try:
                _require_native_swap_stages(
                    records,
                    runtime_identity_digest=runtime_identity_digest,
                    through_stage="source-excluded",
                )
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
            participant = self._participants[self._coordinator_id]
            spec = native_swap["target_specs"][participant.participant_id]
            intent = native_swap.get("target_open_intent")
            if intent is not None and intent.get("state") != "ready":
                raise _error("uncertain-effect", "native swap target open intent is unresolved")
            native_swap["target_open_intent"] = {
                "state": "in-progress",
                "participant_id": participant.participant_id,
                "session_id": participant.session_id,
                "target_runner_incarnation": native_swap["target_runner_incarnation"],
                "spec": _json_value(spec),
            }
            operation.phase = "starting"
            operation.metadata["native_swap"] = native_swap
            operation.metadata["launch_intents"][participant.participant_id] = {
                **dict(operation.metadata["launch_intents"].get(participant.participant_id, {})),
                "state": "in-progress",
                "spec": _json_value(spec),
            }
            self._persist({"event": "native-swap-target-open-intent", "operation_id": operation_id})
        opened = opener(participant.participant_id, dict(spec))
        if not inspect.isawaitable(opened):
            raise _error("uncertain-effect", "managed native swap open is not awaitable")
        opened = await opened
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            runtime_runner = self._runtime_runner_instance(opened)
            process = self._runtime_process(opened, "native swap open")
            if runtime_runner is None:
                raise _error("uncertain-effect", "native swap target runner identity is missing")
            operation.metadata["runner_instances"][participant.participant_id] = runtime_runner
            operation.metadata["launch_processes"][participant.participant_id] = _json_value(process)
            operation.metadata["open_evidence"][participant.participant_id] = _json_value(opened)
            operation.metadata["launch_intents"][participant.participant_id]["state"] = "registered"
            operation.metadata["launch_intents"][participant.participant_id]["runner_instance_id"] = runtime_runner
            self._persist({"event": "native-swap-target-opened", "operation_id": operation_id})
        valid, reason = self._runtime_ready(opened, participant, operation, spec)
        if not valid:
            raise _error("uncertain-effect", "native swap target is not ready-held: " + reason)
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            native_swap = operation.metadata["native_swap"]
            expected_runner = native_swap.get("target_runner_incarnation")
            runtime_runner = self._runtime_runner_instance(opened)
            if runtime_runner != expected_runner:
                raise _error(
                    "stale-generation",
                    "native swap target runner does not match its reserved incarnation",
                )
            # Bind the exact opened target before asking the independent
            # target-held observer.  This is still pre-activation: participant
            # profile/context remain A until the following atomic adoption.
            native_swap["target_runner_instance_id"] = runtime_runner
            native_swap["target_open_intent"] = {
                **dict(native_swap["target_open_intent"]),
                "state": "ready",
                "runner_instance_id": runtime_runner,
            }
            operation.metadata["native_swap"] = native_swap
            self._persist({
                "event": "native-swap-target-open-ready",
                "operation_id": operation_id,
            })
        # The independent target-held observation must precede activation of
        # the replacement participant.  A ready runtime response alone is not
        # permission to publish the new profile/runner as the current source.
        self._native_swap_provider_stage(operation_id, generation, "target-held")
        self._native_swap_require_stage(operation_id, generation, "target-held")
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            participant = self._participants[self._coordinator_id]
            profile = operation.metadata["target_profile"]
            runtime_runner = self._runtime_runner_instance(opened)
            process = self._runtime_process(opened, "native swap open")
            native_swap = operation.metadata["native_swap"]
            if runtime_runner != native_swap.get("target_runner_incarnation"):
                raise _error(
                    "stale-generation",
                    "native swap target runner changed before activation",
                )
            self._adopt_target_runner(
                participant, spec, profile,
                runner_instance_id=runtime_runner, process=process,
            )
            # The old A invocation is now immutable archive evidence.  The
            # replacement target has not bound a B invocation yet, so do not
            # leave the live native context pointing at A's runner; the next
            # ordinary dispatch binds B through its own durable mailbox.
            self._native_context = None
            native_swap["target_runner_instance_id"] = runtime_runner
            native_swap["target_open_intent"] = {
                **dict(native_swap["target_open_intent"]),
                "state": "ready",
                "runner_instance_id": runtime_runner,
            }
            native_swap["state"] = "target-held"
            operation.metadata["native_swap"] = native_swap
            operation.metadata["launch_intents"][participant.participant_id]["state"] = "ready"
            operation.readiness[participant.participant_id] = {
                "session_id": participant.session_id,
                "runner_instance_id": runtime_runner,
                "spec": _json_value(spec),
                "evidence": _json_value(opened),
            }
            operation.metadata["native_startup"] = {
                **native_record_marker("coordinator-startup"),
                "participant_id": participant.participant_id,
                "session_id": participant.session_id,
                "runner_incarnation": native_swap["target_runner_incarnation"],
                "lineage_id": native_swap["source_identity"]["lineage_id"],
                "lineage_generation": native_swap["source_identity"]["lineage_generation"],
                "lineage": native_swap["source_startup"]["lineage"],
                "definitions": _json_value(native_swap["source_startup"].get("definitions", {})),
                "invocation_id": None,
                "invocation_bound": False,
            }
            self._persist({"event": "native-swap-target-held", "operation_id": operation_id})

    def _native_swap_release_binding_locked(self, operation: Operation) -> Dict[str, Any]:
        """Build the one immutable target-held-to-release binding."""
        native_swap = operation.metadata.get("native_swap")
        if not isinstance(native_swap, Mapping):
            raise _error("invalid", "native swap metadata is missing")
        existing = native_swap.get("release_binding")
        existing_binding: Optional[Dict[str, Any]] = None
        if existing is not None:
            try:
                existing_binding = _validate_native_swap_release_binding(existing)
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc
        release_id = native_swap.get("release_id")
        release_intent_digest = native_swap.get("release_intent_digest")
        if not isinstance(release_id, str) or not release_id:
            raise _error("invalid", "native swap release ID is not prepared")
        if (not isinstance(release_intent_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", release_intent_digest) is None):
            raise _error("invalid", "native swap release intent digest is not prepared")
        records = native_swap.get("native_swap_evidence")
        if not isinstance(records, Mapping) or "pre-release" not in records:
            raise _error("busy", "native swap pre-release evidence is not committed")
        pre_release = records["pre-release"]
        if not isinstance(pre_release, Mapping):
            raise _error("invalid", "native swap pre-release evidence is malformed")
        pre_release_digest = pre_release.get("evidence_digest")
        if (not isinstance(pre_release_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", pre_release_digest) is None):
            raise _error("invalid", "native swap pre-release evidence digest is malformed")
        source_identity = native_swap.get("source_identity")
        participant = self._participants.get(self._coordinator_id or "")
        if not isinstance(source_identity, Mapping) or participant is None:
            raise _error("ownership-conflict", "native swap release target is unavailable")
        target_runner = native_swap.get("target_runner_incarnation")
        if not isinstance(target_runner, str) or not target_runner:
            raise _error("invalid", "native swap target runner is not bound")
        binding = {
            "schema_version": 2,
            "architecture": "native-coordinator-lineage",
            "record_kind": "native-swap-release-binding",
            "operation_id": operation.operation_id,
            "owner_generation": operation.generation,
            "expected_daemon_id": native_swap["daemon_id"],
            "participant_id": participant.participant_id,
            "session_id": participant.session_id,
            "runner_incarnation": target_runner,
            "lineage_id": source_identity["lineage_id"],
            "lineage_generation": source_identity["lineage_generation"],
            "request_epoch_id": native_swap["request_epoch_id"],
            "release_id": release_id,
            "release_intent_digest": release_intent_digest,
            "pre_release_evidence_digest": pre_release_digest,
            "binding_digest": "",
        }
        binding["binding_digest"] = _native_swap_digest({
            key: value for key, value in binding.items() if key != "binding_digest"
        })
        if existing_binding is not None and existing_binding != binding:
            raise _error(
                "stale-generation",
                "native swap release binding does not match its current operation",
            )
        try:
            return _validate_native_swap_release_binding(binding)
        except NativeSwapContractError as exc:
            raise _error(exc.code, exc.message) from exc

    def _native_swap_released_retry_locked(self, operation: Operation) -> Operation:
        """Return a durably released swap for an exact read-only retry.

        A public release retry is observational only.  The durable operation,
        evidence ledger, controller authorization, runner binding, boundary,
        and safe runtime receipt must all still form one completed six-stage
        record before this path returns.  In particular, this helper performs
        no provider call, runtime call, authorization, or persistence.
        """
        native_swap = operation.metadata.get("native_swap")
        if not isinstance(native_swap, Mapping):
            raise _error("unsupported", "native swap release is unavailable")
        if operation.release_count != 1 or native_swap.get("state") != "released":
            raise _error("busy", "native swap release is not durably complete")
        if native_swap.get("uncertainty") is not None:
            raise _error(
                "uncertain-effect",
                "native swap release retains unresolved uncertainty",
            )

        # The operation-side joins cover the source archive, source/target
        # capability gates, interrupt selection, and every stage binding.
        # They are deliberately rechecked here rather than relying only on
        # the load-time validator: this is the fresh authority boundary for a
        # caller retrying after a controller reload.
        self._validate_native_swap_record_links(operation, native_swap)
        records = native_swap.get("native_swap_evidence")
        runtime_identity_digest = self._native_swap_runtime_identity_locked(operation)
        try:
            _require_native_swap_stages(
                records,
                runtime_identity_digest=runtime_identity_digest,
                through_stage="release-boundary",
            )
        except NativeSwapContractError as exc:
            raise _error(exc.code, exc.message) from exc

        expected_binding = self._native_swap_release_binding_locked(operation)
        stored_binding = native_swap.get("release_binding")
        if not isinstance(stored_binding, Mapping) or stored_binding != expected_binding:
            raise _error(
                "stale-generation",
                "native swap release binding is not durably joined",
            )

        validation_id = native_swap.get("release_validation_id")
        authorization = native_swap.get("release_authorization")
        if not isinstance(validation_id, str) or not validation_id:
            raise _error("uncertain-effect", "native swap release authorization is missing")
        if not isinstance(authorization, Mapping):
            raise _error("uncertain-effect", "native swap release authorization is missing")
        try:
            normalized_authorization = _validate_native_swap_authorization(
                authorization,
                expected_validation_id=validation_id,
                expected_binding=expected_binding,
            )
        except NativeSwapContractError as exc:
            raise _error(exc.code, exc.message) from exc
        if normalized_authorization.get("authorized") is not True:
            raise _error(
                "uncertain-effect",
                "native swap release authorization is not a committed grant",
            )

        boundary = native_swap.get("release_boundary")
        if not isinstance(boundary, Mapping):
            raise _error("uncertain-effect", "native swap release boundary is missing")
        try:
            _validate_native_swap_boundary(
                boundary, expected_binding=expected_binding
            )
        except NativeSwapContractError as exc:
            raise _error(exc.code, exc.message) from exc

        receipt = native_swap.get("release_receipt")
        if not isinstance(receipt, Mapping):
            raise _error("uncertain-effect", "native swap release receipt is missing")
        participant_id = expected_binding["participant_id"]
        participant = self._participants.get(participant_id)
        if participant is None:
            raise _error("stale-generation", "native swap release participant is unavailable")
        target_runner_instance = native_swap.get("target_runner_instance_id")
        if not isinstance(target_runner_instance, str) or not target_runner_instance:
            raise _error("stale-generation", "native swap target runner is unavailable")
        if participant.metadata.get("runner_instance_id") != target_runner_instance:
            raise _error("stale-generation", "native swap target runner incarnation changed")
        valid, reason = self._runtime_released(
            receipt, participant, operation, target_runner_instance
        )
        if not valid:
            raise _error("uncertain-effect", "native swap release is unproven: " + reason)
        return operation

    def authorize_native_swap_release(
            self, validation_id: str, binding: Mapping[str, Any]
    ) -> Dict[str, Any]:
        """Grant one daemon-authenticated native target release gate.

        The daemon has already authenticated the callback's participant,
        session, and actual runner identity.  This transaction independently
        rechecks the current held target and returns an immutable first grant;
        a same-ID retry is an observation and never a second grant.
        """
        validation_id = _id(validation_id, "native swap release validation ID") or ""
        try:
            binding = _validate_native_swap_release_binding(binding)
        except NativeSwapContractError as exc:
            raise _error(exc.code, exc.message) from exc
        with self._transaction():
            operation = self._current_operation(
                binding["operation_id"], binding["owner_generation"]
            )
            native_swap = operation.metadata.get("native_swap")
            if not isinstance(native_swap, Mapping):
                raise _error("unsupported", "native swap release authority is unavailable")
            stored_authorization = native_swap.get("release_authorization")
            retrying_committed_authorization = (
                operation.phase == "indeterminate"
                and isinstance(stored_authorization, Mapping)
            )
            if (
                operation.phase not in {"ready-held", "released"}
                and not retrying_committed_authorization
            ) or native_swap.get("state") not in {
                "ready-held", "target-held", "released", "uncertain"
            }:
                raise _error("stale-generation", "native swap target is not currently held or durably released")
            # A first grant is allowed only after the held target's
            # pre-release prefix is satisfied.  Once the release boundary is
            # durably complete, an exact validation-ID retry is an
            # observation of that completed ledger and must not be rejected
            # merely because the prefix has advanced.
            records = native_swap.get("native_swap_evidence")
            required_stage = (
                "release-boundary"
                if operation.phase == "released"
                or (
                    retrying_committed_authorization
                    and isinstance(records, Mapping)
                    and "release-boundary" in records
                )
                else "pre-release"
            )
            self._native_swap_require_stage(
                operation.operation_id, operation.generation, required_stage
            )
            expected_binding = self._native_swap_release_binding_locked(operation)
            if binding != expected_binding:
                raise _error("stale-generation", "native swap release binding changed")
            coordinator = self._participants.get(binding["participant_id"])
            if coordinator is None or coordinator.session_id != binding["session_id"]:
                raise _error("ownership-conflict", "native swap release participant changed")
            actual_runner = coordinator.metadata.get("runner_instance_id")
            if not isinstance(actual_runner, str) or not actual_runner:
                raise _error("stale-generation", "native swap target runner is unavailable")
            # The source context remains an immutable archive authority; the
            # current participant/claim and owner are the authority for this
            # target gate after activation.
            source_startup = native_swap.get("source_startup")
            if not isinstance(source_startup, Mapping):
                raise _error("ownership-conflict", "native swap source binding is unavailable")
            lineage = source_startup.get("lineage")
            if not isinstance(lineage, Mapping):
                raise _error("ownership-conflict", "native swap lineage is unavailable")
            self._check_generation(binding["owner_generation"])
            owner_reader = getattr(self.store, "read_owner", None)
            claims_reader = getattr(self.store, "read_lineage_claims", None)
            if not callable(owner_reader) or not callable(claims_reader):
                raise _error("unsupported", "native swap release owner authority is unavailable")
            owner = owner_reader()
            claim = lineage.get("workspace_claim")
            if (
                not isinstance(owner, Mapping)
                or owner.get("mode") != "managed"
                or owner.get("generation") != binding["owner_generation"]
                or owner.get("lane") != lineage.get("lane")
                or owner.get("daemon_id") != binding["expected_daemon_id"]
                or not isinstance(claim, Mapping)
                or claim.get("state") not in {"held", "active"}
                or claim not in claims_reader()
            ):
                raise _error("ownership-conflict", "native swap release owner or claim changed")
            if actual_runner != native_swap.get("target_runner_instance_id"):
                raise _error("stale-generation", "native swap target runner incarnation changed")
            stored_validation_id = native_swap.get("release_validation_id")
            stored = native_swap.get("release_authorization")
            if stored is not None:
                if stored_validation_id != validation_id:
                    raise _error(
                        "uncertain-effect",
                        "native swap release already has a different authorization",
                    )
                if not isinstance(stored, Mapping):
                    raise _error("invalid", "native swap release authorization is malformed")
                authorization_id = stored.get("authorization_id")
                if not isinstance(authorization_id, str) or not authorization_id:
                    raise _error("invalid", "native swap authorization ID is malformed")
                acknowledgement = {
                    "validation_id": validation_id,
                    "authorized": False,
                    "authorization_id": authorization_id,
                    "binding": _json_value(binding),
                    "authorization_digest": "",
                }
                acknowledgement["authorization_digest"] = _native_swap_digest({
                    key: value for key, value in acknowledgement.items()
                    if key != "authorization_digest"
                })
                try:
                    return _validate_native_swap_authorization(
                        acknowledgement,
                        expected_validation_id=validation_id,
                        expected_binding=binding,
                    )
                except NativeSwapContractError as exc:
                    raise _error(exc.code, exc.message) from exc
            if stored_validation_id is not None and stored_validation_id != validation_id:
                raise _error("stale-generation", "native swap release validation ID changed")
            authorization_id = "native-swap-authorization-" + uuid.uuid4().hex
            acknowledgement = {
                "validation_id": validation_id,
                "authorized": True,
                "authorization_id": authorization_id,
                "binding": _json_value(binding),
                "authorization_digest": "",
            }
            acknowledgement["authorization_digest"] = _native_swap_digest({
                key: value for key, value in acknowledgement.items()
                if key != "authorization_digest"
            })
            native_swap["release_validation_id"] = validation_id
            native_swap["release_authorization"] = _json_value(acknowledgement)
            operation.metadata["native_swap"] = native_swap
            self._persist({
                "event": "native-swap-release-authorized",
                "operation_id": operation.operation_id,
                "validation_id": validation_id,
            })
            try:
                return _validate_native_swap_authorization(
                    acknowledgement,
                    expected_validation_id=validation_id,
                    expected_binding=binding,
                )
            except NativeSwapContractError as exc:
                raise _error(exc.code, exc.message) from exc

    async def _native_swap_release(
            self, operation_id: str, generation: Any
    ) -> Operation:
        """Complete the target-held release only after its same-epoch proof."""
        generation = self._generation_valid(generation)
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            native_swap = operation.metadata.get("native_swap")
            if not isinstance(native_swap, Mapping):
                raise _error("unsupported", "native swap release is unavailable")
            if operation.phase == "released":
                return self._native_swap_released_retry_locked(operation)
            if operation.phase != "ready-held":
                raise _error("busy", "native swap target is not ready-held")
            self._native_swap_require_stage(operation_id, generation, "target-held")
            records = native_swap.get("native_swap_evidence")
            if not isinstance(records, Mapping) or "target-held" not in records:
                raise _error("busy", "native swap target-held evidence is missing")
            if native_swap.get("release_receipt") is not None:
                raise _error("uncertain-effect", "native swap release already crossed its gate")
            if native_swap.get("release_id") is None:
                release_id = "native-swap-release-" + uuid.uuid4().hex
                intent = {
                    "operation_id": operation.operation_id,
                    "owner_generation": operation.generation,
                    "participant_id": self._coordinator_id,
                    "request_epoch_id": native_swap["request_epoch_id"],
                    "release_id": release_id,
                    "state": "in-progress",
                }
                native_swap["release_id"] = release_id
                native_swap["release_intent_digest"] = _native_swap_digest(intent)
                native_swap["release_validation_id"] = None
                native_swap["release_binding"] = None
                native_swap["release_authorization"] = None
                native_swap["release_boundary"] = None
                operation.metadata["native_swap"] = native_swap
                self._persist({
                    "event": "native-swap-release-intent",
                    "operation_id": operation.operation_id,
                    "release_id": release_id,
                })
            elif native_swap.get("release_authorization") is not None:
                raise _error("uncertain-effect", "native swap release authorization is already consumed")
            operation_id = operation.operation_id
        try:
            self._native_swap_provider_stage(operation_id, generation, "pre-release")
            self._native_swap_require_stage(operation_id, generation, "pre-release")
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                self._native_swap_owner_claim_matches_locked(operation)
                native_swap = operation.metadata["native_swap"]
                binding = self._native_swap_release_binding_locked(operation)
                native_swap["release_binding"] = _json_value(binding)
                # The runner allocates validation_id immediately before its
                # authenticated private IPC request.  The controller records
                # that stable ID only when the daemon callback reaches this
                # authority; it never pre-grants or invents one here.
                native_swap["release_validation_id"] = None
                operation.metadata["native_swap"] = native_swap
                self._persist({
                    "event": "native-swap-release-binding",
                    "operation_id": operation_id,
                })
                participant = self._participants[self._coordinator_id]
                actual_runner = participant.metadata.get("runner_instance_id")
            releaser = getattr(self.runtime, "release", None) if self.runtime is not None else None
            if not callable(releaser):
                raise _error("unsupported", "managed native swap release is unavailable")
            if not isinstance(actual_runner, str) or not actual_runner:
                raise _error("stale-generation", "native swap target runner is unavailable")
            receipt = releaser(participant.participant_id, native_swap_binding=copy.deepcopy(binding))
            if not inspect.isawaitable(receipt):
                raise _error("uncertain-effect", "managed native swap release must be awaitable")
            receipt = await receipt
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                self._native_swap_owner_claim_matches_locked(operation)
                participant = self._participants[self._coordinator_id]
            valid, reason = self._runtime_released(
                receipt, participant, operation, actual_runner
            )
            if not valid:
                raise _error("uncertain-effect", "native swap release is unproven: " + reason)
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                self._native_swap_owner_claim_matches_locked(operation)
                native_swap = operation.metadata.get("native_swap")
                authorization = (
                    native_swap.get("release_authorization")
                    if isinstance(native_swap, Mapping) else None
                )
            if not isinstance(authorization, Mapping) or authorization.get("authorized") is not True:
                raise _error(
                    "uncertain-effect",
                    "native swap release authorization was not committed",
                )
            evidence = self._runtime_evidence(receipt, "native swap release")
            boundary = receipt.get("native_swap_release_boundary")
            if boundary is None:
                boundary = evidence.get("native_swap_release_boundary")
            # The runtime has crossed its release gate at this point.  Persist
            # the safe receipt and an indeterminate phase before asking the
            # independent same-epoch observer for final proof.  A missing or
            # malformed boundary must never leave a reload looking
            # ready-held, and it must never be replayed automatically.
            safe_receipt = _json_value(receipt)
            if isinstance(safe_receipt, dict):
                safe_receipt.pop("native_swap_release_boundary", None)
                safe_evidence = safe_receipt.get("evidence")
                if isinstance(safe_evidence, Mapping):
                    safe_evidence = dict(safe_evidence)
                    safe_evidence.pop("native_swap_release_boundary", None)
                    safe_receipt["evidence"] = safe_evidence
            boundary_error: Optional[ControllerError] = None
            try:
                if boundary is None:
                    raise _error(
                        "uncertain-effect",
                        "native swap release boundary receipt is missing",
                    )
                boundary = _validate_native_swap_boundary(
                    boundary, expected_binding=binding
                )
            except NativeSwapContractError as exc:
                boundary_error = _error(exc.code, exc.message)
            except ControllerError as exc:
                boundary_error = exc
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                self._native_swap_owner_claim_matches_locked(operation)
                native_swap = operation.metadata["native_swap"]
                native_swap["release_receipt"] = safe_receipt
                native_swap["release_boundary"] = (
                    _json_value(boundary) if boundary_error is None else None
                )
                operation.phase = "indeterminate"
                native_swap["state"] = "uncertain"
                native_swap["uncertainty"] = {
                    "code": "uncertain-effect",
                    "message": (
                        "native swap release is awaiting final boundary proof"
                        if boundary_error is None
                        else boundary_error.message
                    ),
                }
                operation.metadata["native_swap"] = native_swap
                self._persist({
                    "event": "native-swap-release-receipt",
                    "operation_id": operation_id,
                })
            if boundary_error is not None:
                raise boundary_error
            self._native_swap_provider_stage(operation_id, generation, "release-boundary")
            self._native_swap_require_stage(operation_id, generation, "release-boundary")
        except asyncio.CancelledError:
            self._mark_operation_failure(operation_id, "native-swap-release", "uncertain-effect", "native swap release was cancelled")
            raise
        except ControllerError as exc:
            with self._transaction():
                current = self._operations.get(operation_id)
                if current is not None and current.phase != "released":
                    current.phase = "indeterminate"
                    native_swap = current.metadata.get("native_swap")
                    if isinstance(native_swap, dict):
                        native_swap["state"] = "uncertain"
                        native_swap["uncertainty"] = {
                            "code": exc.code,
                            "message": exc.message,
                        }
                        current.metadata["native_swap"] = native_swap
                    self._persist({
                        "event": "native-swap-release-uncertain",
                        "operation_id": operation_id,
                        "code": exc.code,
                    })
            raise
        except Exception as exc:
            self._mark_operation_failure(
                operation_id, "native-swap-release", "uncertain-effect", str(exc)
            )
            raise _error("uncertain-effect", "native swap release outcome is uncertain") from exc
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            self._native_swap_owner_claim_matches_locked(operation)
            native_swap = operation.metadata["native_swap"]
            operation.release_count = 1
            operation.phase = "released"
            operation.metadata["released_generation"] = generation
            native_swap["state"] = "released"
            native_swap["uncertainty"] = None
            operation.metadata["native_swap"] = native_swap
            participant = self._participants.get(self._coordinator_id or "")
            if participant is not None and participant.state.casefold() not in {"completed", "stopped"}:
                participant.state = "active"
            self._persist({"event": "native-swap-released", "operation_id": operation_id})
            return operation

    async def swap(
        self,
        request_id: str,
        generation: Any,
        profile: Any,
        runner_specs: Optional[Mapping[str, Any]] = None,
    ) -> Operation:
        """Promptlessly interrupt, restore, and hold one exact roster.

        Runtime calls are intentionally outside all controller/state locks.
        Any missing or ambiguous evidence leaves the durable operation
        indeterminate; this method never asks a model for a checkpoint and
        never retries an uncertain effect.
        """
        profile_summary = self._profile_summary(profile)
        request_id = _id(request_id, "request_id") or ""
        generation = self._generation_valid(generation)
        with self._transaction():
            native_swap = self._has_native_lifecycle_state(runner_specs=runner_specs)
        if native_swap:
            return await self._native_swap(
                request_id, generation, profile, runner_specs
            )
        with self._transaction():
            # _transaction has just reloaded the authoritative snapshot.
            # Public swap still has the legacy per-participant lifecycle
            # below, so refuse native context/startup/configuration before
            # begin_operation.  The internal coordinator-interrupt
            # persistence/send seam is intentionally outside this guard.
            self._reject_native_legacy_lifecycle(
                "swap", runner_specs=runner_specs
            )
            semantic_specs: Any = runner_specs
            if semantic_specs is None:
                semantic_specs = {
                    participant.participant_id: participant.metadata.get(
                        "runner_spec", participant.metadata.get("spec")
                    )
                    for participant in self._participants.values()
                    if participant.state.casefold() not in {"completed", "stopped"}
                }
            if not isinstance(semantic_specs, Mapping):
                raise _error("invalid", "runner_specs must be an object keyed by participant ID")
            semantic_specs = {
                str(participant_id): _safe_runner_projection(
                    raw_spec,
                    "swap runner specification for %s" % participant_id,
                )
                for participant_id, raw_spec in semantic_specs.items()
            }
            semantic_input = {
                "profile": profile_summary,
                "runner_specs": _json_value(semantic_specs),
            }
            # A successful swap adopts the target runner into each
            # participant.  For a retry that omits runner_specs, those current
            # participant records are no longer the original request input;
            # use the durable semantic snapshot captured by begin_operation so
            # the same request still deduplicates.  An explicit replacement
            # spec remains part of the new digest and therefore refuses.
            if runner_specs is None:
                prior_request = self._requests.get(request_id)
                prior_result = (
                    prior_request.get("result")
                    if isinstance(prior_request, Mapping)
                    and prior_request.get("kind") == "operation"
                    else None
                )
                if isinstance(prior_result, Mapping):
                    prior_operation_id = prior_result.get("operation_id")
                    prior_operation = self._operations.get(prior_operation_id)
                    prior_content = (
                        prior_operation.metadata.get("request_content")
                        if prior_operation is not None
                        else None
                    )
                    if isinstance(prior_content, Mapping):
                        prior_specs = prior_content.get("runner_specs")
                        if prior_specs is not None:
                            semantic_input["runner_specs"] = _json_value(prior_specs)
            # Keep the native guard and begin_operation under this same
            # reloaded store lock.  A peer cannot publish native startup or
            # context between the guard and the request/operation write.
            operation = self.begin_operation(
                request_id, "swap", generation, request_content=semantic_input
            )
        operation_id = operation.operation_id
        self._raise_capability_refusal(operation)
        if operation.phase in {"failed", "indeterminate"}:
            raise _error("uncertain-effect", "swap operation requires explicit recovery before retry")
        if operation.phase in {"ready-held", "released"}:
            return operation

        # Build and validate every target spec while still in preflight.  A
        # bad profile, source capability, transcript store, or UUID therefore
        # leaves the old roster untouched and never reaches an interrupt call.
        try:
            should_fence = False
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                if operation.phase == "preflight":
                    participants = [
                        participant
                        for participant in self._participants.values()
                        if participant.state.casefold() not in {"completed", "stopped"}
                    ]
                    target_specs: Dict[str, Dict[str, Any]] = {}
                    transcript_preflight: Dict[str, Dict[str, Any]] = {}
                    for participant in participants:
                        # Resolve the exact target launch first, then prove
                        # that the current participant is still the holder of
                        # the canonical projects transcript store.  Both are
                        # completed before the fence/interrupt boundary.
                        target_spec = self._swap_spec(
                            participant, operation, profile_summary, runner_specs
                        )
                        trusted_transcript = self._trusted_transcript_preflight(
                            participant,
                            profile_summary,
                            target_spec,
                            allow_reserved_written_promotion=runner_specs is None,
                        )
                        self._apply_transcript_preflight(
                            participant, trusted_transcript
                        )
                        if self._reserved_written_promotion(
                                target_spec, trusted_transcript):
                            # Recompute through the ordinary resume path after
                            # trusted written-history promotion.  The fresh
                            # candidate is never persisted or opened.
                            resumed_spec = self._resume_target_spec(target_spec)
                            target_spec = self._swap_spec(
                                participant,
                                operation,
                                profile_summary,
                                {participant.participant_id: resumed_spec},
                            )
                        transcript_preflight[participant.participant_id] = trusted_transcript
                        target_specs[participant.participant_id] = target_spec
                    operation.metadata["target_profile"] = profile_summary
                    operation.metadata["target_specs"] = target_specs
                    operation.metadata["transcript_preflight"] = transcript_preflight
                    operation.metadata["snapshot"] = {
                        "generation": operation.generation,
                        "participants": [item.to_dict() for item in self._participants.values()],
                        "mailboxes": [item.to_dict() for item in self._mailboxes.values()],
                    }
                    operation.phase = "quiescing"
                    self._persist({"event": "swap-snapshot", "operation_id": operation_id})
                    should_fence = True
                elif operation.phase == "quiescing":
                    should_fence = True
                elif operation.phase not in {"paused", "starting"}:
                    raise _error("uncertain-effect", "swap operation is not in recoverable preflight")
            await self._preflight_operation_specs(
                operation_id, generation, operation.metadata["target_specs"]
            )
            if should_fence:
                self.fence(operation_id)
        except ControllerError as exc:
            # A preflight refusal has not crossed the fence and is therefore a
            # failed operation, not an indeterminate runtime effect.
            with self._transaction():
                current = self._operations.get(operation_id)
                preflight = current is not None and current.phase in {"preflight", "quiescing"}
            if preflight:
                self._mark_operation_failure(operation_id, "", exc.code, exc.message)
            raise
        except Exception as exc:
            self._mark_operation_failure(operation_id, "", "invalid", str(exc))
            raise _error("invalid", "swap preflight was refused")

        participants = []
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            participants = [
                self._participants[item]
                for item in operation.sealed_participants
                if item in self._participants
                and self._participants[item].state.casefold() not in {"completed", "stopped"}
            ]
            operation.metadata.setdefault("interrupt_receipts", {})
            operation.metadata.setdefault("status_evidence", {})
            operation.metadata.setdefault("shutdown_receipts", {})
            operation.metadata.setdefault("old_runner_instances", {})
            operation.metadata.setdefault("runner_instances", {})
            operation.metadata.setdefault("open_evidence", {})
            operation.metadata.setdefault("launch_intents", {})
            operation.metadata.setdefault("launch_processes", {})
            self._persist({"event": "swap-paused", "operation_id": operation_id})

        interrupt = getattr(self.runtime, "interrupt", None) if self.runtime is not None else None
        status_call = getattr(self.runtime, "status", None) if self.runtime is not None else None
        shutdown = getattr(self.runtime, "shutdown", None) if self.runtime is not None else None
        opener = getattr(self.runtime, "open", None) if self.runtime is not None else None
        if not all(callable(method) for method in (interrupt, status_call, shutdown, opener)):
            self._mark_operation_failure(operation_id, "runtime", "unsupported",
                                          "managed runtime lifecycle is incomplete")
            raise _error("unsupported", "managed runtime lifecycle is incomplete")

        # Interrupt is only a receipt.  A separate status round proves final
        # turn drain and tool quiescence, then shutdown proves old-group
        # exclusion before an exact same-UUID open is attempted.
        for participant in participants:
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                receipts = current.metadata.get("interrupt_receipts", {})
                old_runners = current.metadata.get("old_runner_instances", {})
                prior_receipt = receipts.get(participant.participant_id) if isinstance(receipts, Mapping) else None
                prior_runner = old_runners.get(participant.participant_id) if isinstance(old_runners, Mapping) else None
            if prior_receipt is not None:
                valid, reason = self._runtime_identity_matches(
                    prior_receipt,
                    participant,
                    current,
                    expected_runner_instance_id=prior_runner,
                )
                if not valid or self._runtime_runner_instance(prior_receipt) is None:
                    self._mark_operation_failure(
                        operation_id,
                        "interrupt:%s" % participant.participant_id,
                        "uncertain-effect",
                        reason or "stored interrupt receipt has no runner identity",
                    )
                    raise _error("uncertain-effect", "stored interrupt receipt is invalid")
                continue
            try:
                receipt = interrupt(participant.participant_id)
                if not inspect.isawaitable(receipt):
                    raise TypeError("managed runtime interrupt must be awaitable")
                receipt = await receipt
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    old_runner = operation.metadata["old_runner_instances"].get(
                        participant.participant_id
                    )
                valid, reason = self._runtime_identity_matches(
                    receipt,
                    participant,
                    operation,
                    require_session=True,
                    expected_runner_instance_id=old_runner,
                )
                if not valid:
                    raise ValueError(reason)
                runner_instance = self._runtime_runner_instance(receipt)
                if runner_instance is None:
                    raise ValueError("interrupt receipt has no runner instance identity")
            except BaseException as exc:
                self._mark_operation_failure(operation_id, "interrupt:%s" % participant.participant_id,
                                              "uncertain-effect", str(exc))
                if isinstance(exc, asyncio.CancelledError):
                    raise
                raise _error("uncertain-effect", "participant interrupt outcome is uncertain")
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current.metadata["old_runner_instances"][participant.participant_id] = runner_instance
                current.metadata["interrupt_receipts"][participant.participant_id] = _json_value(receipt)
                self._persist({"event": "interrupt-receipt", "operation_id": operation_id,
                               "participant_id": participant.participant_id})

        for participant in participants:
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                evidence_map = current.metadata.get("status_evidence", {})
                prior_status = evidence_map.get(participant.participant_id) if isinstance(evidence_map, Mapping) else None
                old_runner = current.metadata.get("old_runner_instances", {}).get(participant.participant_id)
            if prior_status is not None:
                valid, reason = self._runtime_quiescent(
                    prior_status, participant, current, expected_runner_instance_id=old_runner
                )
                if not valid:
                    self._mark_operation_failure(
                        operation_id,
                        "status:%s" % participant.participant_id,
                        "uncertain-effect",
                        reason,
                    )
                    raise _error("uncertain-effect", "stored quiescence evidence is invalid")
                continue
            try:
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    old_runner = operation.metadata["old_runner_instances"][participant.participant_id]
                status = status_call(participant.participant_id)
                if not inspect.isawaitable(status):
                    raise TypeError("managed runtime status must be awaitable")
                status = await status
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                valid, reason = self._runtime_quiescent(
                    status, participant, operation, expected_runner_instance_id=old_runner
                )
                if not valid:
                    raise ValueError(reason)
            except BaseException as exc:
                self._mark_operation_failure(operation_id, "status:%s" % participant.participant_id,
                                              "uncertain-effect", str(exc))
                if isinstance(exc, asyncio.CancelledError):
                    raise
                raise _error("uncertain-effect", "participant quiescence evidence is insufficient")
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current.metadata["status_evidence"][participant.participant_id] = _json_value(status)
                self._persist({"event": "status-quiescent", "operation_id": operation_id,
                               "participant_id": participant.participant_id})

        for participant in participants:
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                evidence_map = current.metadata.get("shutdown_receipts", {})
                prior_shutdown = evidence_map.get(participant.participant_id) if isinstance(evidence_map, Mapping) else None
                old_runner = current.metadata.get("old_runner_instances", {}).get(participant.participant_id)
            if prior_shutdown is not None:
                if not isinstance(old_runner, str) or not old_runner:
                    self._mark_operation_failure(
                        operation_id,
                        "shutdown:%s" % participant.participant_id,
                        "uncertain-effect",
                        "stored shutdown receipt has no runner identity",
                    )
                    raise _error("uncertain-effect", "stored shutdown receipt is unbound")
                valid, reason = self._runtime_shutdown(
                    prior_shutdown, participant, current, old_runner
                )
                if not valid:
                    self._mark_operation_failure(
                        operation_id,
                        "shutdown:%s" % participant.participant_id,
                        "uncertain-effect",
                        reason,
                    )
                    raise _error("uncertain-effect", "stored shutdown evidence is invalid")
                continue
            try:
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    old_runner = operation.metadata["old_runner_instances"][participant.participant_id]
                shutdown_result = shutdown(participant.participant_id)
                if not inspect.isawaitable(shutdown_result):
                    raise TypeError("managed runtime shutdown must be awaitable")
                shutdown_result = await shutdown_result
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                valid, reason = self._runtime_shutdown(
                    shutdown_result, participant, operation, old_runner
                )
                if not valid:
                    raise ValueError(reason)
            except BaseException as exc:
                self._mark_operation_failure(operation_id, "shutdown:%s" % participant.participant_id,
                                              "uncertain-effect", str(exc))
                if isinstance(exc, asyncio.CancelledError):
                    raise
                raise _error("uncertain-effect", "old participant shutdown is unproven")
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current.metadata["shutdown_receipts"][participant.participant_id] = _json_value(shutdown_result)
                self._persist({"event": "shutdown-excluded", "operation_id": operation_id,
                               "participant_id": participant.participant_id})

        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            operation.phase = "starting"
            self._persist({"event": "swap-starting", "operation_id": operation_id})

        target_specs = operation.metadata.get("target_specs", {})
        for participant in participants:
            spec = target_specs.get(participant.participant_id)
            if not isinstance(spec, Mapping):
                self._mark_operation_failure(operation_id, "open:%s" % participant.participant_id,
                                              "invalid", "persisted target runner specification is missing")
                raise _error("invalid", "persisted target runner specification is missing")
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                evidence_map = current.metadata.get("open_evidence", {})
                prior_open = evidence_map.get(participant.participant_id) if isinstance(evidence_map, Mapping) else None
                prior_runner = current.metadata.get("runner_instances", {}).get(participant.participant_id)
            if prior_open is not None:
                valid, reason = self._runtime_ready(
                    prior_open, participant, current, spec
                )
                if not valid or not isinstance(prior_runner, str) or not prior_runner:
                    self._mark_operation_failure(
                        operation_id,
                        "open:%s" % participant.participant_id,
                        "loader-failed",
                        reason or "stored open evidence has no runner identity",
                    )
                    raise _error("loader-failed", "stored open evidence is invalid")
                continue
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                launch_intents = current.metadata.get("launch_intents", {})
                if not isinstance(launch_intents, dict):
                    self._mark_operation_failure(
                        operation_id,
                        "open:%s" % participant.participant_id,
                        "invalid",
                        "durable launch intent ledger is malformed",
                    )
                    raise _error("invalid", "durable launch intent ledger is malformed")
                prior_intent = launch_intents.get(participant.participant_id)
                if prior_intent is not None and (
                    not isinstance(prior_intent, Mapping)
                    or prior_intent.get("state") != "ready"
                ):
                    self._mark_operation_failure(
                        operation_id,
                        "open:%s" % participant.participant_id,
                        "uncertain-effect",
                        "runner launch intent is unresolved; explicit recovery is required",
                    )
                    raise _error("uncertain-effect", "runner launch intent is unresolved")
                launch_intents[participant.participant_id] = {
                    "state": "in-progress",
                    "participant_id": participant.participant_id,
                    "session_id": participant.session_id,
                    "generation": generation,
                    "spec": _json_value(spec),
                    "started_at": self.clock(),
                }
                self._persist({"event": "launch-intent", "operation_id": operation_id,
                               "participant_id": participant.participant_id})
            try:
                opened = opener(participant.participant_id, dict(spec))
                if not inspect.isawaitable(opened):
                    raise TypeError("managed runtime open must be awaitable")
                opened = await opened
                # Register the adapter's opaque runner and process identity as
                # soon as the response exposes them, before interpreting the
                # readiness flags.  A failed readiness validation must retain
                # ownership for reconciliation rather than retrying a launch.
                with self._transaction():
                    current = self._current_operation(operation_id, generation)
                    runtime_runner = self._runtime_runner_instance(opened)
                    if runtime_runner is None:
                        raise ValueError("open response has no runner instance identity")
                    process = self._runtime_process(opened, "open")
                    current.metadata.setdefault("runner_instances", {})[participant.participant_id] = runtime_runner
                    current.metadata.setdefault("launch_processes", {})[participant.participant_id] = _json_value(process)
                    current.metadata["launch_intents"][participant.participant_id]["state"] = "registered"
                    current.metadata["launch_intents"][participant.participant_id]["runner_instance_id"] = runtime_runner
                    self._persist({"event": "launch-registered", "operation_id": operation_id,
                                   "participant_id": participant.participant_id})
                    operation = current
                valid, reason = self._runtime_ready(opened, participant, operation, spec)
                if not valid:
                    raise ValueError(reason)
                new_runner = self._runtime_runner_instance(opened)
                if new_runner is None:
                    raise ValueError("open response has no runner instance identity")
            except BaseException as exc:
                self._mark_operation_failure(operation_id, "open:%s" % participant.participant_id,
                                              "loader-failed", str(exc))
                if isinstance(exc, asyncio.CancelledError):
                    raise
                raise _error("loader-failed", "participant did not reach ready-held state")
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current_participant = self._participants.get(participant.participant_id)
                if current_participant is None:
                    raise _error("unknown", "opened participant is no longer enrolled")
                target_profile = current.metadata.get("target_profile")
                if not isinstance(target_profile, Mapping):
                    raise _error("invalid", "persisted target profile is missing")
                # Adoption and ready evidence share one durable transaction:
                # after reload, the participant always describes this runner's
                # target identity rather than the source profile it replaced.
                self._adopt_target_runner(
                    current_participant,
                    spec,
                    target_profile,
                    runner_instance_id=new_runner,
                    process=process,
                )
                current.metadata["runner_instances"][participant.participant_id] = new_runner
                current.metadata["open_evidence"][participant.participant_id] = _json_value(opened)
                current.metadata["launch_intents"][participant.participant_id]["state"] = "ready"
                current.readiness[participant.participant_id] = {
                    "session_id": participant.session_id,
                    "runner_instance_id": new_runner,
                    "spec": _json_value(spec),
                    "evidence": _json_value(opened),
                }
                self._persist({"event": "open-ready-held", "operation_id": operation_id,
                               "participant_id": participant.participant_id})

        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            operation.phase = "ready-held"
            operation.metadata["ready_generation"] = operation.generation
            self._persist({"event": "swap-ready-held", "operation_id": operation_id})
            return operation

    async def release(self, operation_id: str, generation: Any) -> Operation:
        """Release one ready-held operation exactly once, without dispatch."""
        generation = self._generation_valid(generation)
        with self._transaction():
            candidate = self._operation(operation_id)
            native_swap = isinstance(candidate.metadata.get("native_swap"), Mapping)
        if native_swap:
            return await self._native_swap_release(operation_id, generation)
        with self._transaction():
            operation = self._operation(operation_id)
            self._check_generation(generation)
            if self._active_operation_id != operation.operation_id or operation.generation != generation:
                raise _error("stale-generation", "release does not match the current operation generation")
            if operation.phase == "released" or operation.release_count:
                raise _error("busy", "operation has already been released")
            release_intent = operation.metadata.get("release_intent")
            if isinstance(release_intent, Mapping):
                intent_state = release_intent.get("state")
                if intent_state == "in-progress":
                    raise _error(
                        "uncertain-effect",
                        "release is already in progress and requires reconciliation",
                    )
                if intent_state == "complete":
                    raise _error("busy", "operation has already been released")
            if operation.phase != "ready-held":
                raise _error("busy", "only a ready-held operation may be released")
            self._reject_historical_rebind_operation(operation)
            for participant in list(self._participants.values()) + list(
                self._archived_participants.values()
            ):
                self._reject_historical_rebind_state(
                    participant.metadata, "participant metadata"
                )
            held_participants = operation.metadata.get("held_participants", [])
            if not isinstance(held_participants, (list, tuple, set, frozenset)):
                raise _error("invalid", "operation held participant set is malformed")
            if any(not isinstance(item, str) or not item for item in held_participants):
                raise _error("invalid", "operation held participant set contains an invalid ID")
            held_participants = set(held_participants)
            if not held_participants.issubset(set(operation.sealed_participants)):
                raise _error("invalid", "operation held participant set is outside its seal")
            participants = [
                self._participants[item]
                for item in operation.sealed_participants
                if item in self._participants
                and self._participants[item].state.casefold() not in {"completed", "stopped"}
                and item not in held_participants
            ]
            receipts = operation.metadata.setdefault("release_receipts", {})
            if not isinstance(receipts, dict):
                self._mark_operation_failure(
                    operation.operation_id,
                    "release",
                    "invalid",
                    "release receipt ledger is malformed",
                )
                raise _error("invalid", "release receipt ledger is malformed")
            # This intent is the release boundary.  It is persisted before
            # looking up or calling the runtime so a crash/cancellation can
            # never be mistaken for a fresh release request.
            operation.metadata["release_intent"] = {
                "state": "in-progress",
                "generation": generation,
                "participants": [item.participant_id for item in participants],
                "started_at": self.clock(),
            }
            self._persist({"event": "release-intent", "operation_id": operation_id,
                           "generation": generation})

        releaser = getattr(self.runtime, "release", None) if self.runtime is not None else None
        if not callable(releaser):
            self._mark_operation_failure(operation_id, "release", "unsupported",
                                          "managed runtime release is unavailable")
            raise _error("unsupported", "managed runtime release is unavailable")
        for participant in participants:
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                receipts = current.metadata.get("release_receipts")
                if not isinstance(receipts, Mapping):
                    self._mark_operation_failure(
                        operation_id,
                        "release",
                        "invalid",
                        "release receipt ledger is malformed",
                    )
                    raise _error("invalid", "release receipt ledger is malformed")
                previous = receipts.get(participant.participant_id)
                expected_runner = current.metadata.get("runner_instances", {}).get(
                    participant.participant_id
                )
                if previous is not None:
                    if not isinstance(expected_runner, str) or not expected_runner:
                        self._mark_operation_failure(
                            operation_id,
                            "release:%s" % participant.participant_id,
                            "uncertain-effect",
                            "stored release receipt has no runner identity",
                        )
                        raise _error("uncertain-effect", "stored release receipt is unbound")
                    valid, reason = self._runtime_released(
                        previous, participant, current, expected_runner
                    )
                    if not valid:
                        self._mark_operation_failure(
                            operation_id,
                            "release:%s" % participant.participant_id,
                            "uncertain-effect",
                            reason,
                        )
                        raise _error("uncertain-effect", "stored release receipt is invalid")
                    continue
                if not isinstance(expected_runner, str) or not expected_runner:
                    self._mark_operation_failure(
                        operation_id,
                        "release:%s" % participant.participant_id,
                        "uncertain-effect",
                        "ready runner has no instance identity",
                    )
                    raise _error("uncertain-effect", "ready runner has no instance identity")
            try:
                receipt = releaser(participant.participant_id)
                if not inspect.isawaitable(receipt):
                    raise TypeError("managed runtime release must be awaitable")
                receipt = await receipt
                with self._transaction():
                    current = self._current_operation(operation_id, generation)
                    expected_runner = current.metadata.get("runner_instances", {}).get(
                        participant.participant_id
                    )
                if not isinstance(expected_runner, str) or not expected_runner:
                    raise ValueError("ready runner has no instance identity")
                valid, reason = self._runtime_released(
                    receipt, participant, current, expected_runner
                )
                if not valid:
                    raise ValueError(reason)
            except BaseException as exc:
                self._mark_operation_failure(operation_id, "release:%s" % participant.participant_id,
                                              "uncertain-effect", str(exc))
                if isinstance(exc, asyncio.CancelledError):
                    raise
                raise _error("uncertain-effect", "participant release outcome is uncertain")
            with self._transaction():
                current = self._current_operation(operation_id, generation)
                current.metadata["release_receipts"][participant.participant_id] = _json_value(receipt)
                current_participant = self._participants.get(participant.participant_id)
                if current_participant is not None and current_participant.state.casefold() not in {
                    "completed", "stopped"
                }:
                    current_participant.state = "active"
                self._persist({"event": "release-receipt", "operation_id": operation_id,
                               "participant_id": participant.participant_id})
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            expected = {
                item.participant_id
                for item in self._participants.values()
                if item.participant_id in operation.sealed_participants
                and item.state.casefold() not in {"completed", "stopped"}
                and item.participant_id not in set(
                    operation.metadata.get("held_participants", [])
                )
            }
            receipts = operation.metadata.get("release_receipts")
            if not isinstance(receipts, Mapping) or not expected.issubset(receipts):
                raise _error("uncertain-effect", "release evidence is incomplete")
            operation.release_count = 1
            operation.phase = "released"
            operation.metadata["released_generation"] = generation
            operation.metadata["release_intent"] = {
                "state": "complete",
                "generation": generation,
                "participants": sorted(expected),
                "completed_at": self.clock(),
            }
            self._persist({"event": "release", "operation_id": operation_id})
            return operation

    @_transactional
    def submit(
        self,
        request_id: str,
        recipient_id: str,
        payload_ref: Any,
        sender_id: str = "user",
        task_id: Optional[str] = None,
        *,
        generation: Any = None,
    ) -> MailboxEntry:
        """Atomically enqueue one payload for the expected lane generation.

        The expected generation is checked after the durable transaction has
        reloaded the latest controller record and before request deduplication
        or mailbox mutation.  ``None`` is retained as the local API default
        for direct callers and resolves to that transaction's current
        generation; the daemon always supplies the generation from its wire
        envelope explicitly.
        """
        request_id = _id(request_id, "request_id") or ""
        recipient_id = _id(recipient_id, "recipient_id") or ""
        sender_id = _id(sender_id, "sender_id") or ""
        payload_ref = _opaque_payload_reference(payload_ref)
        expected_generation = self._generation if generation is None else generation
        self._check_generation(expected_generation)
        if recipient_id not in self._participants:
            raise _error("unknown", "recipient participant is not enrolled")
        if task_id is not None:
            task_id = _id(task_id, "task_id", required=False)
        content = {
            "recipient_id": recipient_id,
            "payload_ref": payload_ref,
            "sender_id": sender_id,
            "task_id": task_id,
            "generation": expected_generation,
        }
        active = self._active_operation()
        seen = self._request_seen(request_id, content, "submit")
        if seen is not None:
            if isinstance(seen, Mapping):
                return MailboxEntry.from_dict(seen)
            raise _error("invalid", "stored mailbox result is invalid")
        active = self._active_operation()
        state = "fenced" if active is not None and active.phase in _FENCED_PHASES else "queued"
        entry = MailboxEntry(
            message_id="msg-" + uuid.uuid4().hex,
            request_id=request_id,
            sender_id=sender_id,
            recipient_id=recipient_id,
            task_id=task_id,
            payload_ref=payload_ref,
            state=state,
            generation=expected_generation,
            operation_id=active.operation_id if active is not None else None,
        )
        self._mailboxes[entry.message_id] = entry
        self._save_request_result(request_id, entry.to_dict())
        self._persist({"event": "submit", "message_id": entry.message_id,
                       "recipient_id": recipient_id, "state": entry.state})
        return entry

    # ---- runtime dispatch ---------------------------------------------

    def _dispatchable_mailboxes(
        self,
        operation: Operation,
        recipient_id: Optional[str] = None,
    ) -> list[MailboxEntry]:
        """Return dispatch candidates without changing durable mailbox state.

        A recipient with a dispatch already in flight or an unresolved
        dispatch outcome is held until its acknowledgement/recovery is
        reconciled.  This is per recipient: an uncertain or busy worker must
        not starve independent eligible workers in the same released lane.
        ``fenced`` entries are candidates only after the operation has been
        explicitly released; selection below performs the actual unfencing
        and intent write atomically.
        """
        self._reject_historical_rebind_operation(operation)
        for participant in list(self._participants.values()) + list(
            self._archived_participants.values()
        ):
            self._reject_historical_rebind_state(
                participant.metadata, "participant metadata"
            )
        blocked_recipients = {
            entry.recipient_id
            for entry in self._mailboxes.values()
            if entry.generation == operation.generation
            and entry.operation_id in (None, operation.operation_id)
            and entry.state in {"dispatch-intent", "uncertain"}
        }
        result: list[MailboxEntry] = []
        for entry in self._mailboxes.values():
            if entry.generation != operation.generation:
                continue
            if recipient_id is not None and entry.recipient_id != recipient_id:
                continue
            if entry.recipient_id not in self._participants:
                # Archived coordinators/workers retain history, never a live
                # dispatch destination for a newer released operation.
                continue
            if entry.operation_id not in (None, operation.operation_id):
                continue
            if entry.recipient_id in blocked_recipients:
                continue
            if entry.state not in {"queued", "fenced"}:
                continue
            if entry.state == "fenced" and operation.phase != "released":
                continue
            participant = self._participants.get(entry.recipient_id)
            if participant is None or participant.state.casefold() in {
                "reserved", "held", "completed", "stopped"
            }:
                continue
            completion_intent = participant.metadata.get("completion_intent")
            if isinstance(completion_intent, Mapping) and completion_intent.get("state") not in {
                None,
                "complete",
            }:
                # A worker completion fence is durable admission state.  It
                # blocks both the candidate read and the later intent write.
                continue
            result.append(entry)
        return result

    @_transactional
    def dispatch_candidates(self, operation_id: str) -> list[Dict[str, str]]:
        """List eligible queued message/recipient IDs without mutation.

        This is the read side of the bounded dispatch pump.  It validates the
        current released operation and generation from the latest durable
        snapshot, but does not unfence mail, claim a recipient, or write an
        intent.  A caller may inspect the result and perform its own runtime
        idle check before invoking :meth:`dispatch_next` for one recipient.
        """
        operation_id = _id(operation_id, "operation_id") or ""
        operation = self._operation(operation_id)
        if self._active_operation_id != operation.operation_id:
            raise _error(
                "stale-generation",
                "operation %s is no longer the current managed operation"
                % operation.operation_id,
            )
        if self._generation != operation.generation:
            raise _error(
                "stale-generation",
                "operation %s does not match the current generation"
                % operation.operation_id,
            )
        if operation.phase != "released":
            raise _error(
                "busy",
                "operation %s is not released (phase %s)"
                % (operation.operation_id, operation.phase),
            )
        return [
            {
                "message_id": entry.message_id,
                "recipient_id": entry.recipient_id,
            }
            for entry in self._dispatchable_mailboxes(operation)
        ]

    def _next_mailbox(
        self,
        operation: Operation,
        recipient_id: Optional[str] = None,
    ) -> Optional[MailboxEntry]:
        candidates = self._dispatchable_mailboxes(operation, recipient_id)
        if not candidates:
            return None
        entry = candidates[0]
        if entry.state == "fenced" and operation.phase == "released":
            entry.state = "queued"
        entry.operation_id = operation.operation_id
        return entry

    @staticmethod
    def _dispatch_uncertain_for(
        mailboxes: Iterable[MailboxEntry],
        operation: Operation,
        recipient_id: Optional[str] = None,
    ) -> Optional[MailboxEntry]:
        for entry in mailboxes:
            if entry.generation != operation.generation:
                continue
            if recipient_id is not None and entry.recipient_id != recipient_id:
                continue
            if entry.operation_id not in (None, operation.operation_id):
                continue
            if entry.state in {"dispatch-intent", "uncertain"}:
                return entry
        return None

    async def dispatch_next(
        self,
        operation_id: str,
        *,
        recipient_id: Optional[str] = None,
    ) -> Optional[MailboxEntry]:
        """Persist intent, send one entry, and durably record its ack.

        The injected runtime has one deliberately narrow interface.  The
        controller never probes alternate method names or adapts a callable:
        ``send(recipient_id, message_id, payload_ref)`` is an async transport
        boundary, and its returned acknowledgement must carry the same
        message ID.
        """
        operation_id = _id(operation_id, "operation_id") or ""
        if recipient_id is not None:
            recipient_id = _id(recipient_id, "recipient_id")
        rollover_id: Optional[str] = None
        rollover_request: Optional[Dict[str, Any]] = None
        # The lock intentionally ends before the runtime call below.  A
        # transport may await or hang; holding the global state lock there
        # would block unrelated lane recovery and claim reconciliation.
        with self._transaction():
            operation = self._operation(operation_id)
            if self._active_operation_id != operation.operation_id:
                raise _error(
                    "stale-generation",
                    "operation %s is no longer the current managed operation"
                    % operation.operation_id,
                )
            if self._generation != operation.generation:
                raise _error(
                    "stale-generation",
                    "operation %s does not match the current generation"
                    % operation.operation_id,
                )
            self._reject_historical_rebind_operation(operation)
            if operation.phase != "released":
                raise _error(
                    "busy",
                    "operation %s is not released (phase %s)"
                    % (operation.operation_id, operation.phase),
                )
            if recipient_id is not None and recipient_id not in self._participants:
                raise _error(
                    "unknown",
                    "dispatch recipient %s is not enrolled" % recipient_id,
                )
            # Revalidate the released operation/current generation in this
            # same transaction immediately before selecting the requested
            # recipient.  A daemon may have awaited a runtime idle check
            # since it read candidates; a concurrent fence therefore refuses
            # here before a dispatch-intent is written.
            entry = self._next_mailbox(operation, recipient_id)
            if entry is None:
                uncertain = self._dispatch_uncertain_for(
                    self._mailboxes.values(), operation, recipient_id
                )
                if uncertain is not None:
                    raise _error(
                        "uncertain-effect",
                        "mailbox message %s has an uncertain dispatch outcome"
                        % uncertain.message_id,
                    )
                return None
            # Move the selected durable mailbox to dispatch-intent before the
            # native bind.  The bind then authenticates this exact row, rather
            # than accepting an arbitrary transport/request ID.  Both writes
            # are in this short transaction and precede every runtime call.
            entry.operation_id = operation.operation_id
            runner_instances = operation.metadata.get("runner_instances", {})
            runner_instance_id = (
                runner_instances.get(entry.recipient_id)
                if isinstance(runner_instances, Mapping) else None
            )
            native_startup = operation.metadata.get("native_startup")
            is_native_coordinator = (
                entry.recipient_id == self._coordinator_id
                and (self._native_context is not None or isinstance(native_startup, Mapping))
            )
            committed_rollover = self._native_rollover_for_mailbox_locked(
                operation.operation_id, entry.message_id
            )
            is_committed_rollover_retry = bool(
                committed_rollover is not None
                and committed_rollover.get("reservation_binding") is not None
                and committed_rollover.get("state") in {"send-pending", "reconciled"}
            )
            is_native_rollover = bool(
                is_native_coordinator
                and self._native_context is not None
                and self._native_context.get("invocation_id") != entry.message_id
                and not is_committed_rollover_retry
            )
            if is_native_rollover:
                rollover_id, _rollover, rollover_request = self._native_begin_rollover_locked(
                    operation, entry
                )
                # Preparation is a distinct durable stage.  Keep B queued and
                # do not create a dispatch-intent until the runtime reservation
                # and terminal proof are atomically committed with A history.
                self._persist({
                    "event": "native-rollover-preparation",
                    "operation_id": operation.operation_id,
                    "rollover_id": rollover_id,
                    "message_id": entry.message_id,
                })
            elif is_committed_rollover_retry:
                rollover_id = committed_rollover.get("rollover_id")
                if not isinstance(rollover_id, str) or not rollover_id:
                    raise _error("invalid", "native rollover identity is missing")
                entry.dispatch_attempt += 1
                entry.state = "dispatch-intent"
                self._persist({
                    "event": "native-rollover-dispatch-resume",
                    "message_id": entry.message_id,
                    "operation_id": operation.operation_id,
                    "attempt": entry.dispatch_attempt,
                })
            elif is_native_coordinator and isinstance(runner_instance_id, str) and runner_instance_id:
                entry.dispatch_attempt += 1
                entry.state = "dispatch-intent"
                self._bind_native_invocation_locked(
                    operation.generation,
                    entry.recipient_id,
                    runner_instance_id,
                    entry.message_id,
                )
                # This write is the dispatch boundary.  It completes before
                # any runtime method is called, and no store lock is retained.
                self._persist({"event": "dispatch-intent", "message_id": entry.message_id,
                               "operation_id": operation.operation_id,
                               "attempt": entry.dispatch_attempt})
            elif not is_native_rollover:
                entry.dispatch_attempt += 1
                entry.state = "dispatch-intent"
                self._persist({"event": "dispatch-intent", "message_id": entry.message_id,
                               "operation_id": operation.operation_id,
                               "attempt": entry.dispatch_attempt})
            recipient_id = entry.recipient_id
            message_id = entry.message_id
            payload_ref = entry.payload_ref
        if rollover_request is not None:
            prepare = getattr(self.runtime, "prepare_invocation", None) if self.runtime is not None else None
            if not callable(prepare):
                self._mark_native_rollover_uncertain(
                    rollover_id, "native runtime does not support prepare-invocation"
                )
                raise _error(
                    "unsupported",
                    "native runtime does not support prepare-invocation",
                )
            try:
                self._native_dispatch_inflight[message_id] = "prepare"
                try:
                    reservation = prepare(
                        recipient_id,
                        rollover_request,
                        deadline=None,
                    )
                    if inspect.isawaitable(reservation):
                        reservation = await reservation
                finally:
                    self._native_dispatch_inflight.pop(message_id, None)
                # Busy is a normal bounded pump result: it retains B queued
                # and consumes no reservation or send effect.
                if isinstance(reservation, Mapping) and reservation.get("state") == "busy":
                    self._validate_native_prepare_response(rollover_request, reservation)
                    with self._transaction():
                        current_rollover = self._native_invocation_rollovers.get(rollover_id or "")
                        if current_rollover is not None:
                            current_rollover["uncertainty"] = {
                                "stage": "preparation",
                                "code": "busy",
                                "reason": "parent-not-terminal",
                                "reservation_outcome": "not-reserved",
                            }
                            current_rollover["integrity_digest"] = self._native_record_integrity(
                                current_rollover, "integrity_digest"
                            )
                            self._persist({
                                "event": "native-rollover-busy",
                                "operation_id": operation_id,
                                "rollover_id": rollover_id,
                            })
                    raise _error("busy", "native coordinator invocation remains busy")
                if not isinstance(reservation, Mapping):
                    raise _error("invalid", "native rollover reservation response is malformed")
                with self._transaction():
                    current_operation = self._current_operation(
                        operation_id, operation.generation
                    )
                    self._native_commit_rollover_locked(
                        current_operation, rollover_id or "", reservation
                    )
            except ControllerError:
                raise
            except Exception as exc:
                error_code = getattr(exc, "code", None)
                detail = str(exc)
                no_reservation_busy = (
                    error_code == "busy"
                    and not any(
                        marker in detail.casefold()
                        for marker in (
                            "different native reservation",
                            "different native invocation reservation",
                            "already outstanding",
                            "already sealed",
                        )
                    )
                )
                if no_reservation_busy:
                    with self._transaction():
                        current_rollover = self._native_invocation_rollovers.get(rollover_id or "")
                        if current_rollover is not None:
                            current_rollover["state"] = "preparation-pending"
                            current_rollover["uncertainty"] = {
                                "stage": "preparation",
                                "code": "busy",
                                "reason": detail,
                                "reservation_outcome": "not-reserved",
                            }
                            current_rollover["integrity_digest"] = self._native_record_integrity(
                                current_rollover, "integrity_digest"
                            )
                            self._persist({
                                "event": "native-rollover-busy",
                                "operation_id": operation_id,
                                "rollover_id": rollover_id,
                            })
                    raise _error("busy", "native coordinator invocation remains busy")
                self._mark_native_rollover_uncertain(
                    rollover_id, "native rollover reservation failed: %s" % exc
                )
                raise _error(
                    "uncertain-effect",
                    "native rollover reservation outcome is uncertain: %s" % exc,
                )
        sender = getattr(self.runtime, "send", None) if self.runtime is not None else None
        if not callable(sender):
            self._mark_dispatch_uncertain(message_id, operation_id, "no managed runtime sender is configured")
            raise _error("unsupported", "no managed runtime sender is configured")
        resolver = self.payload_resolver
        if not callable(resolver):
            self._mark_dispatch_uncertain(
                message_id,
                operation_id,
                "trusted payload resolver is unavailable",
            )
            raise _error("unsupported", "trusted payload resolver is unavailable")
        try:
            resolved_payload = resolver(payload_ref)
            if inspect.isawaitable(resolved_payload):
                resolved_payload = await resolved_payload
            if not isinstance(resolved_payload, str):
                raise ValueError("trusted payload resolver returned non-text content")
            if len(resolved_payload.encode("utf-8")) > MAX_PAYLOAD_REFERENCE_BYTES:
                raise ValueError("resolved payload exceeds one MiB")
            # The resolver may itself await.  Revalidate the current released
            # gate and completion fence immediately before crossing the
            # runtime send boundary.
            with self._transaction():
                current_operation = self._current_operation(
                    operation_id, operation.generation
                )
                if current_operation.phase != "released":
                    raise _error(
                        "busy",
                        "operation %s is not released (phase %s)"
                        % (current_operation.operation_id, current_operation.phase),
                    )
                if rollover_id is not None:
                    current_rollover = self._native_invocation_rollovers.get(rollover_id)
                    if (
                        current_rollover is None
                        or current_rollover.get("state") != "send-pending"
                        or current_rollover.get("reservation_binding") is None
                    ):
                        raise _error(
                            "uncertain-effect",
                            "native rollover reservation changed before send",
                        )
                    if self._native_daemon_id_locked() != current_rollover.get("daemon_id"):
                        raise _error(
                            "stale-generation",
                            "native rollover daemon incarnation changed before send",
                        )
                    if (
                        not isinstance(self._native_context, Mapping)
                        or self._native_context.get("invocation_id") != message_id
                    ):
                        raise _error(
                            "stale-generation",
                            "native rollover current invocation changed before send",
                        )
                    if self._native_context.get("runner_incarnation") != current_rollover.get(
                            "runner_incarnation"
                    ):
                        raise _error(
                            "stale-generation",
                            "native rollover runner changed before send",
                        )
                    current_lineage = self._native_context.get("lineage")
                    if (
                        not isinstance(current_lineage, Mapping)
                        or current_lineage.get("lineage_id") != current_rollover.get("lineage_id")
                        or current_lineage.get("lineage_generation") != current_rollover.get(
                            "lineage_generation"
                        )
                        or current_lineage.get("session_uuid") != current_rollover.get(
                            "coordinator", {}
                        ).get("session_uuid")
                    ):
                        raise _error(
                            "ownership-conflict",
                            "native rollover lineage changed before send",
                        )
                    current_runner = self._participants.get(recipient_id)
                    if (
                        current_runner is None
                        or current_runner.metadata.get("runner_instance_id")
                        != current_rollover.get("runner_incarnation")
                    ):
                        raise _error(
                            "stale-generation",
                            "native rollover participant runner changed before send",
                        )
                current_entry = self._mailboxes.get(message_id)
                if current_entry is None or current_entry.state != "dispatch-intent":
                    raise _error("uncertain-effect", "mailbox dispatch state changed during resolution")
                current_participant = self._participants.get(recipient_id)
                if current_participant is None or current_participant.state.casefold() in {
                    "reserved", "held", "completed", "stopped"
                }:
                    raise _error("busy", "dispatch recipient is no longer runnable")
                self._reject_historical_rebind_state(
                    current_participant.metadata, "participant metadata"
                )
                completion_intent = current_participant.metadata.get("completion_intent")
                if isinstance(completion_intent, Mapping) and completion_intent.get("state") not in {
                    None,
                    "complete",
                }:
                    raise _error("busy", "dispatch recipient is fenced for completion")
            # ``resolved_payload`` is intentionally scoped to this await.  It
            # is never included in an operation, journal event, or mailbox
            # snapshot; the runtime sees text only after durable intent.
            self._native_dispatch_inflight[message_id] = "send"
            try:
                result = sender(recipient_id, message_id, resolved_payload)
                if not inspect.isawaitable(result):
                    raise TypeError("managed runtime send must be awaitable")
                runtime_ack = await result
            finally:
                self._native_dispatch_inflight.pop(message_id, None)
            if not isinstance(runtime_ack, Mapping):
                raise ValueError("managed runtime acknowledgement is malformed")
            if (
                runtime_ack.get("message_id") != message_id
                or runtime_ack.get("accepted") is not True
                or runtime_ack.get("ack_kind") != "accepted-send"
            ):
                raise ValueError(
                    "managed runtime acknowledgement is not a correlated accepted-send"
                )
            _digest(runtime_ack)
        except Exception as exc:
            # A failed await may have crossed the transport boundary.  Mark
            # the durable intent uncertain while holding the store lock only
            # for this short state transition; the transport itself is never
            # called under that lock.
            self._mark_dispatch_uncertain(message_id, operation_id, str(exc))
            raise _error("uncertain-effect", "runtime dispatch outcome is uncertain: %s" % exc)
        with self._transaction():
            try:
                operation = self._current_operation(operation_id, operation.generation)
            except ControllerError as exc:
                # The send crossed the runtime boundary, so a concurrent
                # generation change cannot make it safe to forget the intent.
                self._mark_dispatch_uncertain(message_id, operation_id, exc.message)
                raise _error(
                    "uncertain-effect",
                    "runtime dispatch completed after the operation changed",
                )
            current = self._mailboxes.get(message_id)
            if current is None:
                raise _error("uncertain-effect", "dispatched mailbox message disappeared")
            if current.state == "acknowledged":
                if _json_value(current.runtime_ack) != _json_value(runtime_ack):
                    raise _error("uncertain-effect", "mailbox acknowledgement raced recovery")
                return current
            if current.state not in {"dispatch-intent", "uncertain"}:
                raise _error("uncertain-effect", "mailbox dispatch state raced runtime send")
            current_participant = self._participants.get(current.recipient_id)
            if current_participant is None:
                raise _error("uncertain-effect", "dispatch recipient disappeared")
            # Recheck the completion fence after the runtime await.  A
            # correlated accepted-send remains durable; completion's final
            # transaction separately refuses while this intent is pending.
            completion_intent = current_participant.metadata.get("completion_intent")
            if isinstance(completion_intent, Mapping) and completion_intent.get("state") not in {
                None,
                "complete",
            }:
                current.runtime_ack = runtime_ack
                current.state = "acknowledged"
                self._persist({
                    "event": "acknowledge",
                    "message_id": message_id,
                    "operation_id": operation_id,
                    "source": "runtime-send-completion-race",
                })
                return current
            current.runtime_ack = runtime_ack
            current.state = "acknowledged"
            marker = "mail:%s" % message_id
            operation.uncertainty = [item for item in operation.uncertainty if item != marker]
            rollover = self._native_rollover_for_mailbox_locked(
                operation.operation_id, message_id
            )
            if rollover is not None and rollover.get("state") == "send-pending":
                rollover["state"] = "delivered"
                rollover["uncertainty"] = None
                rollover["integrity_digest"] = self._native_record_integrity(
                    rollover, "integrity_digest"
                )
            self._persist({"event": "acknowledge", "message_id": message_id,
                           "operation_id": operation_id, "source": "runtime-send"})
            return current

    def _mark_dispatch_uncertain(
        self, message_id: str, operation_id: str, detail: str
    ) -> None:
        with self._transaction():
            entry = self._mailboxes.get(message_id)
            if entry is None:
                return
            if entry.state == "acknowledged":
                return
            entry.state = "uncertain"
            operation = self._operations.get(entry.operation_id or operation_id)
            if operation is not None:
                marker = "mail:%s" % message_id
                if marker not in operation.uncertainty:
                    operation.uncertainty.append(marker)
                rollover = self._native_rollover_for_mailbox_locked(
                    operation.operation_id, message_id
                )
                if rollover is not None and rollover.get("state") != "delivered":
                    rollover["state"] = "uncertain"
                    rollover["uncertainty"] = {
                        "stage": "send",
                        "reason": str(detail) or "runtime dispatch outcome is uncertain",
                    }
                    rollover["integrity_digest"] = self._native_record_integrity(
                        rollover, "integrity_digest"
                    )
            self._persist({"event": "dispatch-uncertain", "message_id": message_id,
                           "operation_id": operation_id, "detail": detail})

    def _mark_native_rollover_uncertain(
            self, rollover_id: Optional[str], detail: str,
    ) -> None:
        if not rollover_id:
            return
        with self._transaction():
            rollover = self._native_invocation_rollovers.get(rollover_id)
            if rollover is None or rollover.get("state") == "delivered":
                return
            rollover["state"] = "uncertain"
            rollover["uncertainty"] = {
                "stage": "preparation",
                "reason": str(detail) or "native reservation outcome is uncertain",
                "reservation_outcome": "unknown",
            }
            rollover["integrity_digest"] = self._native_record_integrity(
                rollover, "integrity_digest"
            )
            self._persist({
                "event": "native-rollover-uncertain",
                "rollover_id": rollover_id,
                "detail": str(detail),
            })

    @staticmethod
    def _ack_id(runtime_ack: Any) -> Optional[str]:
        if isinstance(runtime_ack, str):
            return runtime_ack
        return _get(runtime_ack, "message_id", "messageId", "id", "correlation_id", "correlationId")

    @_transactional
    def acknowledge(self, message_id: str, runtime_ack: Any) -> MailboxEntry:
        message_id = _id(message_id, "message_id") or ""
        _digest(runtime_ack)
        entry = self._mailboxes.get(message_id)
        if entry is None:
            raise _error("unknown", "mailbox message %s is unknown" % message_id)
        correlated = self._ack_id(runtime_ack)
        if correlated != message_id:
            raise _error("invalid", "runtime acknowledgement does not correlate message ID")
        if entry.state == "acknowledged":
            old = _json_value(entry.runtime_ack)
            if old == _json_value(runtime_ack):
                return entry
            raise _error("invalid", "message already has a different acknowledgement")
        if entry.state not in {"dispatch-intent", "uncertain"}:
            raise _error("invalid", "message is not awaiting a runtime acknowledgement")
        entry.runtime_ack = runtime_ack
        entry.state = "acknowledged"
        operation = self._operations.get(entry.operation_id or "")
        if operation is not None:
            marker = "mail:%s" % message_id
            operation.uncertainty = [item for item in operation.uncertainty if item != marker]
        self._persist({"event": "acknowledge", "message_id": message_id})
        return entry

    @staticmethod
    def _proves_no_send(transport_proof: Any) -> bool:
        if transport_proof is True:
            return True
        if isinstance(transport_proof, str):
            return transport_proof.casefold() in {"no-send", "not-sent", "no_send", "not_sent"}
        if isinstance(transport_proof, Mapping):
            authoritative = transport_proof.get("authoritative")
            if "authoritative" in transport_proof and authoritative is not True:
                return False
            # ``sent: false`` is not a transport receipt: it is commonly the
            # absence of a positive send flag.  Only an explicit no-send or
            # send_occurred=false result can reopen a dispatch intent.
            for key in ("no_send", "not_sent", "send_occurred"):
                if key in transport_proof:
                    value = transport_proof[key]
                    if key == "send_occurred" and value is False:
                        return True
                    if key in {"no_send", "not_sent"} and value is True:
                        return True
            status = str(transport_proof.get("status", "")).casefold()
            return status in {"no-send", "not-sent", "no_send", "not_sent", "proven-no-send"}
        return False

    @_transactional
    def recover_dispatch(self, message_id: str, transport_proof: Any = None) -> MailboxEntry:
        message_id = _id(message_id, "message_id") or ""
        entry = self._mailboxes.get(message_id)
        if entry is None:
            raise _error("unknown", "mailbox message %s is unknown" % message_id)
        if entry.state == "acknowledged":
            return entry
        if entry.state not in {"dispatch-intent", "uncertain"}:
            return entry
        operation = self._operations.get(entry.operation_id or "")
        native_rollover = (
            self._native_rollover_for_mailbox_locked(
                operation.operation_id, message_id
            )
            if operation is not None else None
        )
        # A first native invocation has no rollover row yet, but its
        # dispatch intent is still governed by the native runner identity and
        # daemon boundary.  Do not let the legacy boolean/string no-send
        # shortcut clear that intent either; the future native reconciliation
        # frame must bind the exact operation, runner, mailbox, and transport.
        native_dispatch = bool(
            native_rollover is not None
            or isinstance(self._native_context, Mapping)
            or (
                operation is not None
                and isinstance(operation.metadata.get("native_startup"), Mapping)
            )
        )
        if self._proves_no_send(transport_proof):
            if native_dispatch:
                # A native invocation reservation is an immutable A->B
                # transition.  Generic booleans/strings (or an unbound
                # ``authoritative`` mapping) cannot prove that this exact
                # daemon, runner, mailbox, and reservation crossed no send
                # boundary.  Until the bound SDK reconciliation frame is
                # available, preserve the dispatch intent and refuse rather
                # than clearing uncertainty and allowing a replay.
                raise _error(
                    "unsupported",
                    "native dispatch recovery requires bound transport evidence",
                )
            entry.state = "queued"
            entry.runtime_ack = None
            if operation is not None:
                marker = "mail:%s" % message_id
                operation.uncertainty = [item for item in operation.uncertainty if item != marker]
                rollover = self._native_rollover_for_mailbox_locked(
                    operation.operation_id, message_id
                )
                if rollover is not None and rollover.get("reservation_binding") is not None:
                    rollover["state"] = "send-pending"
                    rollover["uncertainty"] = None
                    rollover["integrity_digest"] = self._native_record_integrity(
                        rollover, "integrity_digest"
                    )
            self._persist({"event": "recover-no-send", "message_id": message_id})
            return entry
        entry.state = "uncertain"
        operation = self._operations.get(entry.operation_id or "")
        if operation is not None and "mail:%s" % message_id not in operation.uncertainty:
            operation.uncertainty.append("mail:%s" % message_id)
        self._persist({"event": "recover-uncertain", "message_id": message_id})
        return entry

    @staticmethod
    def _recovery_records(
            evidence: Any, *, allow_empty: bool = False
    ) -> Dict[str, Dict[str, Any]]:
        """Decode the bounded, participant-keyed recovery evidence envelope."""
        if not isinstance(evidence, Mapping):
            raise _error("invalid", "recovery evidence must be an object")
        known = {"generation", "operation_id", "participants", "interrupt", "status",
                 "shutdown", "open", "release"}
        records: Dict[str, Dict[str, Any]] = {}
        participant_block = evidence.get("participants")
        if participant_block is not None:
            if isinstance(participant_block, Mapping):
                items = participant_block.items()
                for participant_id, item in items:
                    participant_id = _id(participant_id, "recovery participant_id") or ""
                    if not isinstance(item, Mapping):
                        raise _error("invalid", "recovery participant evidence is malformed")
                    records[participant_id] = dict(item)
            elif isinstance(participant_block, list):
                for item in participant_block:
                    if not isinstance(item, Mapping):
                        raise _error("invalid", "recovery participant evidence is malformed")
                    participant_id = _id(item.get("participant_id"), "recovery participant_id") or ""
                    if participant_id in records:
                        raise _error("invalid", "recovery evidence repeats a participant")
                    records[participant_id] = dict(item)
            else:
                raise _error("invalid", "recovery participants are malformed")
        for stage in ("interrupt", "status", "shutdown", "open", "release"):
            block = evidence.get(stage)
            if block is None:
                continue
            if not isinstance(block, Mapping):
                raise _error("invalid", "recovery %s evidence is malformed" % stage)
            for participant_id, value in block.items():
                participant_id = _id(participant_id, "recovery participant_id") or ""
                if participant_id not in records:
                    records[participant_id] = {}
                if stage in records[participant_id]:
                    raise _error("invalid", "recovery evidence repeats a stage")
                records[participant_id][stage] = value
        if not records and not (set(evidence) & known):
            # A compact participant-id keyed form is useful to a recovery
            # caller, while still requiring each stage to be explicit.
            for participant_id, item in evidence.items():
                participant_id = _id(participant_id, "recovery participant_id") or ""
                if not isinstance(item, Mapping):
                    raise _error("invalid", "recovery participant evidence is malformed")
                records[participant_id] = dict(item)
        if not records and allow_empty:
            # Only the already-validated unenroll owner may use an empty
            # record set.  Keep the envelope closed even on that path: an
            # unknown top-level key or malformed known stage is never an
            # implicit empty reconciliation request.
            if set(evidence) - known:
                raise _error("invalid", "recovery evidence contains an unknown field")
            return records
        if not records:
            raise _error("invalid", "recovery evidence has no participant records")
        return records

    async def _recover_start(
        self,
        operation_id: str,
        generation: Any,
        evidence: Mapping[str, Any],
        records: Mapping[str, Mapping[str, Any]],
    ) -> Operation:
        """Reconcile a partially launched start without replaying opens.

        A durable ``pending`` intent has not crossed the runtime boundary and
        may be continued by an explicit duplicate ``start``.  ``in-progress``
        and ``registered`` intents have crossed it; they require fresh,
        identity-bound open/OS evidence and are never reopened automatically.
        """
        updates: Dict[str, Mapping[str, Any]] = {}
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            if operation.mode != "start":
                raise _error("invalid", "start recovery was requested for another operation mode")
            intents = operation.metadata.get("launch_intents")
            target_specs = operation.metadata.get("target_specs")
            profiles = operation.metadata.get("profiles")
            if not all(isinstance(value, Mapping) for value in (intents, target_specs, profiles)):
                raise _error("invalid", "durable start recovery maps are malformed")
            sealed = set(operation.sealed_participants)
            if set(records) - sealed:
                raise _error("invalid", "start recovery evidence names an unsealed participant")
            for participant_id in sealed:
                participant = self._participants.get(participant_id)
                if participant is None:
                    raise _error("unknown", "start participant is no longer enrolled")
                intent = intents.get(participant_id)
                if not isinstance(intent, Mapping):
                    raise _error("invalid", "start launch intent is malformed")
                state = intent.get("state")
                record = records.get(participant_id, {})
                if not isinstance(record, Mapping):
                    raise _error("invalid", "start recovery participant evidence is malformed")
                unknown_stages = set(record) - {"open", "status"}
                if unknown_stages:
                    raise _error("invalid", "start recovery only accepts fresh open/status evidence")
                open_evidence = record.get("open", record.get("status"))
                durable_open = operation.metadata.get("open_evidence", {}).get(participant_id)
                if state in {"in-progress", "registered"} and open_evidence is None and durable_open is None:
                    operation.phase = "indeterminate"
                    marker = "start:%s" % participant_id
                    if marker not in operation.uncertainty:
                        operation.uncertainty.append(marker)
                    operation.metadata["last_error"] = {
                        "code": "uncertain-effect",
                        "message": "in-progress start launch needs fresh open evidence",
                    }
                    self._persist({"event": "recover-start-uncertain", "operation_id": operation_id,
                                   "participant_id": participant_id})
                    raise _error("uncertain-effect", "start launch outcome is unresolved for %s" % participant_id)
                if open_evidence is None:
                    if state not in {"pending", "ready"}:
                        raise _error("uncertain-effect", "start launch intent cannot be replayed")
                    continue
                spec = target_specs.get(participant_id)
                profile = profiles.get(participant_id)
                if not isinstance(spec, Mapping) or not isinstance(profile, Mapping):
                    raise _error("invalid", "start recovery target identity is incomplete")
                expected_runner = operation.metadata.get("runner_instances", {}).get(participant_id)
                valid, reason = self._runtime_ready(
                    open_evidence,
                    participant,
                    operation,
                    spec,
                )
                if not valid:
                    raise _error("loader-failed", "start recovery open evidence is invalid: %s" % reason)
                returned_runner = self._runtime_runner_instance(open_evidence)
                if returned_runner is None:
                    raise _error("loader-failed", "start recovery has no runner instance")
                if expected_runner is not None and expected_runner != returned_runner:
                    raise _error("stale-generation", "start recovery changed runner identity")
                process = self._runtime_process(open_evidence, "recover-start-open")
                updates[participant_id] = {
                    "open": _json_value(open_evidence),
                    "runner_instance_id": returned_runner,
                    "process": _json_value(process),
                    "spec": _json_value(spec),
                    "profile": _json_value(profile),
                }

            # Apply all evidence in one short transaction only after every
            # supplied record has been validated, preventing partial adoption.
            for participant_id, update in updates.items():
                participant = self._participants[participant_id]
                operation.metadata.setdefault("open_evidence", {})[participant_id] = update["open"]
                operation.metadata.setdefault("runner_instances", {})[participant_id] = update["runner_instance_id"]
                operation.metadata.setdefault("launch_processes", {})[participant_id] = update["process"]
                intent = dict(operation.metadata["launch_intents"][participant_id])
                intent.update({
                    "state": "ready",
                    "runner_instance_id": update["runner_instance_id"],
                    "process": update["process"],
                })
                operation.metadata["launch_intents"][participant_id] = intent
                self._adopt_target_runner(
                    participant,
                    update["spec"],
                    update["profile"],
                    runner_instance_id=update["runner_instance_id"],
                    process=update["process"],
                )
                operation.readiness[participant_id] = {
                    "session_id": participant.session_id,
                    "runner_instance_id": update["runner_instance_id"],
                    "spec": update["spec"],
                    "evidence": update["open"],
                }
                operation.uncertainty = [
                    marker for marker in operation.uncertainty
                    if marker != "start:%s" % participant_id
                ]
            states = [
                operation.metadata["launch_intents"].get(participant_id, {}).get("state")
                for participant_id in operation.sealed_participants
            ]
            if all(state == "ready" for state in states):
                operation.phase = "ready-held"
                operation.metadata["ready_generation"] = generation
            elif all(state in {"ready", "pending"} for state in states):
                operation.phase = "starting"
            else:
                operation.phase = "indeterminate"
            operation.metadata["recovery_required"] = False
            self._save_request_result(operation.request_id, operation.to_dict())
            self._persist({"event": "recover-start", "operation_id": operation_id,
                           "phase": operation.phase})
            return operation

    async def _recover_add_worker(
        self,
        operation_id: str,
        generation: Any,
        evidence: Mapping[str, Any],
        records: Mapping[str, Mapping[str, Any]],
    ) -> Operation:
        """Reconcile one admission launch without inventing old-worker proof.

        Add-worker has no replaced incarnation to interrupt or shut down.  A
        durable in-progress/registered intent therefore requires fresh,
        identity-bound open/status evidence; recovery never calls ``open``.
        Once that evidence proves ready-held, the reserved UUID and claim are
        adopted exactly once and the admission operation remains held.
        """
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            if operation.mode != "add-worker":
                raise _error("invalid", "add-worker recovery was requested for another operation mode")
            intents = operation.metadata.get("launch_intents")
            target_specs = operation.metadata.get("target_specs")
            target_profile = operation.metadata.get("target_profile")
            if not isinstance(intents, Mapping) or not isinstance(target_specs, Mapping):
                raise _error("invalid", "durable add-worker launch maps are malformed")
            if not isinstance(target_profile, Mapping):
                raise _error("invalid", "durable add-worker profile is missing")
            sealed = tuple(operation.sealed_participants)
            if len(sealed) != 1 or sealed[0] not in self._participants:
                raise _error("invalid", "add-worker recovery has an invalid sealed worker")
            participant_id = sealed[0]
            if set(records) - {participant_id}:
                raise _error("invalid", "add-worker recovery evidence names an unsealed participant")
            participant = self._participants[participant_id]
            intent = intents.get(participant_id)
            spec = target_specs.get(participant_id)
            if not isinstance(intent, Mapping) or not isinstance(spec, Mapping):
                raise _error("invalid", "durable add-worker launch identity is incomplete")
            if spec.get("session_id") != participant.session_id:
                raise _error("profile-mismatch", "add-worker recovery UUID differs from the reservation")
            if str(spec.get("mode", "")).casefold() not in {"fresh", "resume"}:
                raise _error("unsupported", "add-worker recovery launch mode is unsupported")
            if str(spec.get("mode")).casefold() == "fresh":
                transcript = participant.metadata.get("transcript")
                reserved = participant.state.casefold() in {"reserved", "held"}
                if isinstance(transcript, Mapping):
                    reserved = reserved and transcript.get("session_id") == participant.session_id
                    reserved = reserved and transcript.get("exists") is False
                    reserved = reserved and transcript.get("written") is False
                    reserved = reserved and transcript.get("reserved") is True
                else:
                    reserved = False
                if not reserved:
                    raise _error(
                        "profile-mismatch",
                        "add-worker fresh recovery lacks a never-written reservation",
                    )
            record = records.get(participant_id, {})
            if not isinstance(record, Mapping):
                raise _error("invalid", "add-worker recovery participant evidence is malformed")
            unknown_stages = set(record) - {"open", "status"}
            if unknown_stages:
                raise _error("invalid", "add-worker recovery only accepts open/status evidence")
            open_evidence = record.get("open", record.get("status"))
            durable_open = operation.metadata.get("open_evidence", {}).get(participant_id)
            state = intent.get("state")
            if state in {"in-progress", "registered"} and open_evidence is None and durable_open is None:
                operation.phase = "indeterminate"
                marker = "add-worker:%s" % participant_id
                if marker not in operation.uncertainty:
                    operation.uncertainty.append(marker)
                operation.metadata["recovery_required"] = True
                operation.metadata["last_error"] = {
                    "code": "uncertain-effect",
                    "message": "in-progress add-worker launch needs fresh open evidence",
                }
                self._persist({
                    "event": "recover-add-worker-uncertain",
                    "operation_id": operation_id,
                    "participant_id": participant_id,
                })
                raise _error("uncertain-effect", "add-worker launch outcome is unresolved")
            if open_evidence is None:
                if state == "pending":
                    # No runtime boundary was crossed.  Recovery does not
                    # replay it; an explicit operator continuation owns any
                    # future launch decision.
                    operation.metadata["recovery_required"] = True
                    self._persist({
                        "event": "recover-add-worker-pending",
                        "operation_id": operation_id,
                        "participant_id": participant_id,
                    })
                    return operation
                if state == "ready" and isinstance(durable_open, Mapping):
                    open_evidence = durable_open
                else:
                    raise _error("uncertain-effect", "add-worker recovery has no launch evidence")
            valid, reason = self._runtime_ready(
                open_evidence, participant, operation, spec
            )
            if not valid:
                raise _error(
                    "loader-failed",
                    "add-worker recovery open evidence is invalid: %s" % reason,
                )
            runner_instance = self._runtime_runner_instance(open_evidence)
            if runner_instance is None:
                raise _error("loader-failed", "add-worker recovery has no runner instance")
            expected_runner = operation.metadata.get("runner_instances", {}).get(participant_id)
            if expected_runner is not None and expected_runner != runner_instance:
                raise _error("stale-generation", "add-worker recovery changed runner identity")
            process = self._runtime_process(open_evidence, "recover-add-worker-open")
            operation.metadata.setdefault("open_evidence", {})[participant_id] = _json_value(open_evidence)
            operation.metadata.setdefault("runner_instances", {})[participant_id] = runner_instance
            operation.metadata.setdefault("launch_processes", {})[participant_id] = _json_value(process)
            updated_intent = dict(intent)
            updated_intent.update({
                "state": "ready",
                "runner_instance_id": runner_instance,
                "process": _json_value(process),
            })
            operation.metadata["launch_intents"][participant_id] = updated_intent
            self._adopt_target_runner(
                participant,
                spec,
                target_profile,
                runner_instance_id=runner_instance,
                process=process,
            )
            participant.state = "held"
            operation.readiness[participant_id] = {
                "session_id": participant.session_id,
                "runner_instance_id": runner_instance,
                "spec": _json_value(spec),
                "evidence": _json_value(open_evidence),
            }
            operation.uncertainty = [
                marker for marker in operation.uncertainty
                if marker != "add-worker:%s" % participant_id
            ]
            operation.phase = "ready-held"
            operation.metadata["ready_generation"] = generation
            operation.metadata["recovery_required"] = False
            self._save_request_result(operation.request_id, operation.to_dict())
            self._persist({
                "event": "recover-add-worker-ready-held",
                "operation_id": operation_id,
                "participant_id": participant_id,
            })
            return operation

    def _mark_recovery_indeterminate(
        self,
        operation_id: str,
        generation: Any,
        marker: str,
        code: str,
        detail: str,
    ) -> None:
        """Keep a mode-specific recovery fence after incomplete evidence."""
        try:
            with self._transaction():
                operation = self._operations.get(operation_id)
                if operation is None or operation.generation != generation:
                    return
                if operation.phase not in _TERMINAL_OPERATION_PHASES:
                    operation.phase = "indeterminate"
                if marker and marker not in operation.uncertainty:
                    operation.uncertainty.append(marker)
                operation.metadata["recovery_required"] = True
                operation.metadata["last_error"] = {
                    "code": code,
                    "message": detail,
                }
                self._persist({
                    "event": "recovery-indeterminate",
                    "operation_id": operation_id,
                    "mode": operation.mode,
                    "code": code,
                })
        except ControllerError:
            # The original refusal remains the safest result when another
            # lifecycle transition won the race while recovery was deciding.
            return

    @staticmethod
    def _recovery_status_proof(
        value: Any,
        participant: Participant,
        operation: Operation,
        expected_runner_instance_id: str,
    ) -> Tuple[bool, str, Optional[Dict[str, Any]]]:
        """Validate either a full status response or its safe projection."""
        if isinstance(value, Mapping) and "evidence" in value:
            valid, reason = ManagedController._runtime_quiescent(
                value,
                participant,
                operation,
                expected_runner_instance_id=expected_runner_instance_id,
            )
            if not valid:
                return False, reason, None
            return True, "", ManagedController._runtime_safe_evidence(value, "recovery status")
        if not ManagedController._stored_quiescence_proof(value):
            return False, "stored status projection is not quiescent", None
        if value.get("participant_id") != participant.participant_id:
            return False, "stored status has the wrong participant identity", None
        if value.get("session_id") != participant.session_id:
            return False, "stored status has the wrong session UUID", None
        if value.get("runner_instance_id") != expected_runner_instance_id:
            return False, "stored status has the wrong runner identity", None
        return True, "", _json_value(value)

    @staticmethod
    def _recovery_shutdown_proof(
        value: Any,
        participant: Participant,
        operation: Operation,
        expected_runner_instance_id: str,
    ) -> Tuple[bool, str, Optional[Dict[str, Any]]]:
        """Validate either a full shutdown response or its safe projection."""
        if isinstance(value, Mapping) and "evidence" in value:
            valid, reason = ManagedController._runtime_shutdown(
                value,
                participant,
                operation,
                expected_runner_instance_id,
            )
            if not valid:
                return False, reason, None
            return True, "", ManagedController._runtime_safe_evidence(value, "recovery shutdown")
        if not ManagedController._stored_shutdown_proof(value):
            return False, "stored shutdown projection is not authoritative", None
        if value.get("participant_id") != participant.participant_id:
            return False, "stored shutdown has the wrong participant identity", None
        if value.get("session_id") != participant.session_id:
            return False, "stored shutdown has the wrong session UUID", None
        if value.get("runner_instance_id") != expected_runner_instance_id:
            return False, "stored shutdown has the wrong runner identity", None
        return True, "", _json_value(value)

    @staticmethod
    def _recovery_identity_proof(
        value: Any,
        participant: Participant,
        operation: Operation,
        expected_runner_instance_id: str,
    ) -> Tuple[bool, str, Optional[Dict[str, Any]]]:
        """Validate a full receipt or the controller's safe receipt copy."""
        if isinstance(value, Mapping) and "evidence" not in value:
            if value.get("participant_id") != participant.participant_id:
                return False, "stored receipt has the wrong participant identity", None
            if value.get("session_id") != participant.session_id:
                return False, "stored receipt has the wrong session UUID", None
            if value.get("runner_instance_id") != expected_runner_instance_id:
                return False, "stored receipt has the wrong runner identity", None
            return True, "", _json_value(value)
        valid, reason = ManagedController._runtime_identity_matches(
            value,
            participant,
            operation,
            expected_runner_instance_id=expected_runner_instance_id,
        )
        if not valid:
            return False, reason, None
        return True, "", ManagedController._runtime_safe_evidence(value, "recovery receipt")

    async def _recover_ctx(
        self,
        operation_id: str,
        generation: Any,
        evidence: Mapping[str, Any],
        records: Mapping[str, Mapping[str, Any]],
    ) -> Operation:
        """Reconcile ctx's retired coordinator and retained workers separately.

        Ctx never restarts retained workers.  Recovery accepts only the old
        coordinator's interrupt/status/shutdown facts, retained-worker status
        facts, and the fresh coordinator's already-observed open fact.  It
        never calls the runtime and never treats a missing stage as permission
        to reopen or release anything.
        """
        try:
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                if operation.mode != "ctx":
                    raise _error("invalid", "ctx recovery was requested for another operation mode")
                if operation.phase in {"ready-held", "released"}:
                    return operation
                metadata = operation.metadata
                ctx_intent = metadata.get("ctx_intent")
                if not isinstance(ctx_intent, Mapping):
                    raise _error("invalid", "durable ctx intent is malformed")
                old_id = _id(ctx_intent.get("old_coordinator_id"), "ctx old coordinator_id") or ""
                target_id = _id(ctx_intent.get("new_coordinator_id"), "ctx new coordinator_id") or ""
                old_participant = self._archived_participants.get(old_id)
                target = self._participants.get(target_id)
                if old_participant is None or target is None:
                    raise _error("unknown", "ctx recovery roster identities are missing")
                if target.role.casefold() != "coordinator" or old_participant.role.casefold() != "coordinator":
                    raise _error("invalid", "ctx recovery coordinator identities are malformed")
                policy = ctx_intent.get("worker_policy")
                if policy not in {"hold", "restart"}:
                    raise _error("invalid", "ctx recovery worker policy is malformed")
                if policy == "restart":
                    raise _error(
                        "unsupported",
                        "ctx restart recovery is unsupported until native restart admission is implemented",
                    )
                workers = [
                    self._participants[item]
                    for item in operation.sealed_participants
                    if item != target_id and item in self._participants
                ]
                if len(workers) != len(operation.sealed_participants) - 1:
                    raise _error("unknown", "ctx recovery retained workers are missing")
                worker_ids = [item.participant_id for item in workers]
                held_ids = metadata.get("held_participants", [])
                restart_ids = metadata.get("restart_participants", [])
                if not isinstance(held_ids, list) or not isinstance(restart_ids, list):
                    raise _error("invalid", "ctx recovery worker policy ledgers are malformed")
                if set(held_ids) != set(worker_ids) or restart_ids:
                    raise _error("invalid", "ctx recovery hold ledger does not cover workers")
                allowed = {old_id, target_id, *(item.participant_id for item in workers)}
                if set(records) - allowed:
                    raise _error("invalid", "ctx recovery evidence names an unsealed participant")
                old_runners = metadata.get("old_runner_instances")
                worker_runners = metadata.get("runner_instances")
                target_specs = metadata.get("target_specs")
                target_profile = metadata.get("target_profile")
                maps = {
                    "interrupt": metadata.get("interrupt_receipts", {}),
                    "status": metadata.get("status_evidence", {}),
                    "worker_status": metadata.get("worker_status_evidence", {}),
                    "shutdown": metadata.get("shutdown_receipts", {}),
                    "open": metadata.get("open_evidence", {}),
                    "launch": metadata.get("launch_intents", {}),
                }
                if not isinstance(old_runners, Mapping) or not isinstance(worker_runners, Mapping):
                    raise _error("invalid", "ctx recovery runner identity maps are malformed")
                if not isinstance(target_specs, Mapping) or not isinstance(target_profile, Mapping):
                    raise _error("invalid", "ctx recovery target identity is incomplete")
                if not all(isinstance(value, Mapping) for value in maps.values()):
                    raise _error("invalid", "ctx recovery evidence maps are malformed")
                old_runner = old_runners.get(old_id)
                if not isinstance(old_runner, str) or not old_runner:
                    raise _error("uncertain-effect", "ctx old coordinator runner identity is missing")
                old_record = records.get(old_id, {})
                target_record = records.get(target_id, {})
                if not isinstance(old_record, Mapping) or not isinstance(target_record, Mapping):
                    raise _error("invalid", "ctx recovery coordinator evidence is malformed")
                if set(old_record) - {"interrupt", "status", "shutdown"}:
                    raise _error("invalid", "ctx old coordinator recovery stage is unsupported")
                if set(target_record) - {"open"}:
                    raise _error("invalid", "ctx new coordinator recovery stage is unsupported")

                updates: Dict[str, Dict[str, Any]] = {}

                def validate_old(stage: str, value: Any) -> None:
                    if stage == "interrupt":
                        valid, reason = self._runtime_identity_matches(
                            value,
                            old_participant,
                            operation,
                            expected_runner_instance_id=old_runner,
                        )
                        if not valid:
                            raise _error("uncertain-effect", "ctx interrupt evidence is invalid: %s" % reason)
                        if self._runtime_runner_instance(value) != old_runner:
                            raise _error("stale-generation", "ctx interrupt evidence changed runner identity")
                        updates.setdefault(old_id, {})[stage] = _json_value(value)
                        return
                    if stage == "status":
                        valid, reason, safe = self._recovery_status_proof(
                            value, old_participant, operation, old_runner
                        )
                    else:
                        valid, reason, safe = self._recovery_shutdown_proof(
                            value, old_participant, operation, old_runner
                        )
                    if not valid or safe is None:
                        raise _error("uncertain-effect", "ctx %s evidence is invalid: %s" % (stage, reason))
                    updates.setdefault(old_id, {})[stage] = safe

                for stage, value in old_record.items():
                    validate_old(stage, value)

                for worker in workers:
                    worker_id = worker.participant_id
                    record = records.get(worker_id, {})
                    if not isinstance(record, Mapping):
                        raise _error("invalid", "ctx worker recovery evidence is malformed")
                    if set(record) - {"status"}:
                        raise _error("invalid", "ctx retained workers accept status evidence only")
                    expected = worker_runners.get(worker_id)
                    if not isinstance(expected, str) or not expected:
                        raise _error("uncertain-effect", "ctx worker runner identity is missing")
                    durable_status = maps["worker_status"].get(worker_id)
                    supplied_status = record.get("status")
                    status_value = supplied_status if supplied_status is not None else durable_status
                    if status_value is None:
                        continue
                    valid, reason, safe = self._recovery_status_proof(
                        status_value, worker, operation, expected
                    )
                    if not valid or safe is None:
                        raise _error("uncertain-effect", "ctx worker status is invalid: %s" % reason)
                    updates.setdefault(worker_id, {})["worker_status"] = safe

                target_spec = target_specs.get(target_id)
                if not isinstance(target_spec, Mapping):
                    raise _error("invalid", "ctx fresh coordinator specification is missing")
                durable_open = maps["open"].get(target_id)
                supplied_open = target_record.get("open")
                open_value = supplied_open if supplied_open is not None else durable_open
                target_open_safe: Optional[Dict[str, Any]] = None
                if open_value is not None:
                    valid, reason = self._runtime_ready(
                        open_value, target, operation, target_spec
                    )
                    if not valid:
                        raise _error("loader-failed", "ctx fresh coordinator open evidence is invalid: %s" % reason)
                    runner = self._runtime_runner_instance(open_value)
                    if runner is None:
                        raise _error("loader-failed", "ctx fresh coordinator has no runner identity")
                    expected_target = metadata.get("runner_instances", {}).get(target_id)
                    if expected_target is not None and expected_target != runner:
                        raise _error("stale-generation", "ctx fresh coordinator runner identity changed")
                    process = self._runtime_process(open_value, "ctx recovery open")
                    target_open_safe = _json_value(open_value)
                    updates[target_id] = {
                        "open": target_open_safe,
                        "runner_instance_id": runner,
                        "process": _json_value(process),
                    }

            # A second short transaction applies only already-validated facts.
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                metadata = operation.metadata
                for participant_id, values in updates.items():
                    if "interrupt" in values:
                        metadata.setdefault("interrupt_receipts", {})[participant_id] = values["interrupt"]
                    if "status" in values:
                        metadata.setdefault("status_evidence", {})[participant_id] = values["status"]
                    if "worker_status" in values:
                        metadata.setdefault("worker_status_evidence", {})[participant_id] = values["worker_status"]
                    if "shutdown" in values:
                        metadata.setdefault("shutdown_receipts", {})[participant_id] = values["shutdown"]
                    if "open" in values:
                        runner = values["runner_instance_id"]
                        metadata.setdefault("open_evidence", {})[participant_id] = values["open"]
                        metadata.setdefault("runner_instances", {})[participant_id] = runner
                        metadata.setdefault("launch_processes", {})[participant_id] = values["process"]
                        intents = metadata.setdefault("launch_intents", {})
                        intent = intents.get(participant_id)
                        if not isinstance(intent, Mapping):
                            raise _error("uncertain-effect", "ctx open recovery has no launch intent")
                        intents[participant_id] = {
                            **dict(intent),
                            "state": "ready",
                            "runner_instance_id": runner,
                            "process": values["process"],
                        }
                        current_target = self._participants.get(participant_id)
                        target_spec = metadata.get("target_specs", {}).get(participant_id)
                        target_profile = metadata.get("target_profile")
                        if current_target is None or not isinstance(target_spec, Mapping) or not isinstance(target_profile, Mapping):
                            raise _error("invalid", "ctx open recovery target identity is incomplete")
                        self._adopt_target_runner(
                            current_target,
                            target_spec,
                            target_profile,
                            runner_instance_id=runner,
                            process=values["process"],
                        )
                        operation.readiness[participant_id] = {
                            "session_id": current_target.session_id,
                            "runner_instance_id": runner,
                            "spec": _json_value(target_spec),
                            "evidence": values["open"],
                        }

                old_id = metadata["ctx_intent"]["old_coordinator_id"]
                target_id = metadata["ctx_intent"]["new_coordinator_id"]
                worker_ids = [item for item in operation.sealed_participants if item != target_id]
                old_status = metadata.get("status_evidence", {}).get(old_id)
                old_shutdown = metadata.get("shutdown_receipts", {}).get(old_id)
                old_interrupt = metadata.get("interrupt_receipts", {}).get(old_id)
                workers_ready = all(
                    item in metadata.get("worker_status_evidence", {})
                    for item in worker_ids
                )
                old_ready = old_interrupt is not None and old_status is not None and old_shutdown is not None
                target_ready = target_id in metadata.get("open_evidence", {})
                transfer = metadata.get("claim_transfer")
                if not isinstance(transfer, Mapping):
                    raise _error("invalid", "ctx writer claim transfer ledger is malformed")
                # A crash may occur after the state owner's atomic transfer
                # but before this controller records the completion.  Read
                # the exact shared claim index and reconcile that already-
                # completed replacement; never release/acquire again.
                if transfer.get("state") in {"pending", "in-progress"}:
                    old_for_claim = self._archived_participants.get(old_id)
                    target_for_claim = self._participants.get(target_id)
                    if old_for_claim is None or target_for_claim is None:
                        raise _error("unknown", "ctx claim-transfer identities are missing")
                    if old_for_claim.writer_claim is not None:
                        old_index = self._trusted_claim_index_record(old_for_claim, generation)
                        new_index = self._trusted_claim_index_record(target_for_claim, generation)
                        if old_index is None and new_index is not None:
                            old_for_claim.writer_claim.state = "released"
                            if target_for_claim.writer_claim is not None:
                                target_for_claim.writer_claim.state = "active"
                            transfer = dict(transfer)
                            transfer.update({
                                "state": "complete",
                                "result": _json_value(new_index),
                                "recovered_at": self.clock(),
                            })
                            metadata["claim_transfer"] = transfer
                        elif old_index is not None and new_index is not None:
                            raise _error("ownership-conflict", "ctx claim transfer has duplicate active identities")
                transfer_ready = isinstance(transfer, Mapping) and transfer.get("state") in {
                    "complete", "not-required"
                }
                # Restore the policy-specific admission state after reload.
                # Both policies retain the old records behind a durable hold;
                # restart is a later native action and never a parent/task
                # rewrite during ctx recovery.
                for worker_id in worker_ids:
                    worker = self._participants.get(worker_id)
                    if worker is None:
                        raise _error("unknown", "ctx retained worker is missing")
                    worker.state = "held"
                    worker.metadata["ctx_hold"] = {
                        "operation_id": operation_id,
                        "generation": generation,
                        "policy": "hold",
                        "restart_pending": False,
                        "parent_id": worker.parent_id,
                        "task_id": worker.task_id,
                    }
                if workers_ready and old_ready and target_ready and transfer_ready:
                    operation.phase = "ready-held"
                    metadata["ctx_intent"]["state"] = "complete"
                    metadata["ctx_intent"]["completed_at"] = self.clock()
                    metadata["ready_generation"] = generation
                    metadata["recovery_required"] = False
                    operation.uncertainty = [
                        marker for marker in operation.uncertainty if marker != "ctx"
                    ]
                    checkpoint = next(
                        (
                            entry for entry in self._mailboxes.values()
                            if entry.operation_id == operation_id
                            and entry.request_id == operation.request_id
                        ),
                        None,
                    )
                    if checkpoint is not None:
                        checkpoint.state = "fenced"
                else:
                    operation.phase = "indeterminate"
                    metadata["recovery_required"] = True
                    if "ctx" not in operation.uncertainty:
                        operation.uncertainty.append("ctx")
                self._save_request_result(operation.request_id, operation.to_dict())
                self._persist({
                    "event": "recover-ctx",
                    "operation_id": operation_id,
                    "phase": operation.phase,
                })
                return operation
        except BaseException as exc:
            self._mark_recovery_indeterminate(
                operation_id,
                generation,
                "ctx",
                getattr(exc, "code", "uncertain-effect"),
                str(exc),
            )
            if isinstance(exc, asyncio.CancelledError):
                raise
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "ctx recovery outcome is uncertain")

    async def _recover_shutdown(
        self,
        operation_id: str,
        generation: Any,
        evidence: Mapping[str, Any],
        records: Mapping[str, Mapping[str, Any]],
    ) -> Operation:
        """Reconcile shutdown evidence without reopening or releasing claims."""
        try:
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                if operation.mode != "shutdown":
                    raise _error("invalid", "shutdown recovery was requested for another operation mode")
                if operation.phase == "complete":
                    return operation
                sealed = tuple(operation.sealed_participants)
                if set(records) - set(sealed):
                    raise _error("invalid", "shutdown recovery evidence names an unsealed participant")
                runner_map = operation.metadata.get("runner_instances")
                intents = operation.metadata.get("shutdown_intents")
                status_map = operation.metadata.get("status_evidence")
                interrupt_map = operation.metadata.get("interrupt_receipts")
                shutdown_map = operation.metadata.get("shutdown_receipts")
                if not all(isinstance(value, Mapping) for value in (
                    runner_map, intents, status_map, interrupt_map, shutdown_map
                )):
                    raise _error("invalid", "durable shutdown recovery maps are malformed")
                updates: Dict[str, Dict[str, Any]] = {}
                for participant_id in sealed:
                    participant = self._participants.get(participant_id)
                    if participant is None:
                        raise _error("unknown", "shutdown participant is no longer enrolled")
                    record = records.get(participant_id, {})
                    if not isinstance(record, Mapping):
                        raise _error("invalid", "shutdown recovery participant evidence is malformed")
                    if set(record) - {"interrupt", "status", "shutdown"}:
                        raise _error("invalid", "shutdown recovery accepts no open or release stages")
                    expected = runner_map.get(participant_id)
                    if not isinstance(expected, str) or not expected:
                        raise _error("uncertain-effect", "shutdown runner identity is missing")
                    status_value = record.get("status", status_map.get(participant_id))
                    interrupt_value = record.get("interrupt", interrupt_map.get(participant_id))
                    shutdown_value = record.get("shutdown", shutdown_map.get(participant_id))
                    values: Dict[str, Any] = {}
                    if interrupt_value is not None:
                        valid, reason, interrupt_safe = self._recovery_identity_proof(
                            interrupt_value,
                            participant,
                            operation,
                            expected_runner_instance_id=expected,
                        )
                        if not valid:
                            raise _error("uncertain-effect", "shutdown interrupt evidence is invalid: %s" % reason)
                        values["interrupt"] = interrupt_safe
                    status_safe: Optional[Dict[str, Any]] = None
                    if status_value is not None:
                        valid, reason, status_safe = self._recovery_status_proof(
                            status_value, participant, operation, expected
                        )
                        if not valid or status_safe is None:
                            raise _error("uncertain-effect", "shutdown status evidence is invalid: %s" % reason)
                        values["status"] = status_safe
                    shutdown_safe: Optional[Dict[str, Any]] = None
                    if shutdown_value is not None:
                        # A shutdown receipt is not enough to establish that
                        # an active turn was drained; status proof must be
                        # present in the same durable recovery state.
                        if status_value is None:
                            raise _error("uncertain-effect", "shutdown recovery lacks quiescent status evidence")
                        valid, reason, shutdown_safe = self._recovery_shutdown_proof(
                            shutdown_value, participant, operation, expected
                        )
                        if not valid or shutdown_safe is None:
                            raise _error("uncertain-effect", "shutdown exclusion evidence is invalid: %s" % reason)
                        values["shutdown"] = shutdown_safe
                    updates[participant_id] = values

            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                metadata = operation.metadata
                for participant_id, values in updates.items():
                    for stage, value in values.items():
                        map_name = {
                            "interrupt": "interrupt_receipts",
                            "status": "status_evidence",
                            "shutdown": "shutdown_receipts",
                        }[stage]
                        metadata.setdefault(map_name, {})[participant_id] = value
                complete = True
                for participant_id in operation.sealed_participants:
                    participant = self._participants.get(participant_id)
                    if participant is None:
                        complete = False
                        continue
                    if (
                        participant_id not in metadata.get("status_evidence", {})
                        or participant_id not in metadata.get("shutdown_receipts", {})
                    ):
                        complete = False
                        continue
                    intent = metadata.get("shutdown_intents", {}).get(participant_id)
                    if not isinstance(intent, Mapping):
                        raise _error("invalid", "shutdown intent is malformed")
                    metadata["shutdown_intents"][participant_id] = {
                        **dict(intent),
                        "state": "complete",
                    }
                    participant.metadata["shutdown_evidence"] = {
                        "generation": generation,
                        "runner_instance_id": metadata["runner_instances"][participant_id],
                        "evidence": metadata["shutdown_receipts"][participant_id],
                    }
                    participant.state = "stopped"
                if complete:
                    operation.phase = "complete"
                    metadata["shutdown_complete"] = True
                    metadata["recovery_required"] = False
                    self._active_operation_id = None
                else:
                    operation.phase = "indeterminate"
                    metadata["recovery_required"] = True
                    if "shutdown" not in operation.uncertainty:
                        operation.uncertainty.append("shutdown")
                self._persist({
                    "event": "recover-shutdown",
                    "operation_id": operation_id,
                    "phase": operation.phase,
                })
                return operation
        except BaseException as exc:
            self._mark_recovery_indeterminate(
                operation_id,
                generation,
                "shutdown",
                getattr(exc, "code", "uncertain-effect"),
                str(exc),
            )
            if isinstance(exc, asyncio.CancelledError):
                raise
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "shutdown recovery outcome is uncertain")

    async def _recover_unenroll(
        self,
        operation_id: str,
        generation: Any,
        evidence: Mapping[str, Any],
        records: Mapping[str, Mapping[str, Any]],
    ) -> Operation:
        """Reconcile only already-durable unenrollment claims; never call runtime."""
        try:
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                if operation.mode != "unenroll":
                    raise _error("invalid", "unenroll recovery was requested for another operation mode")
                if operation.phase == "complete":
                    return operation
                sealed = tuple(operation.sealed_participants)
                if set(records) - set(sealed):
                    raise _error("invalid", "unenroll recovery evidence names an unsealed participant")
                intents = operation.metadata.get("unenroll_intents")
                if not isinstance(intents, Mapping):
                    raise _error("invalid", "durable unenroll intents are malformed")
                unresolved = []
                for participant_id in sealed:
                    participant = self._participants.get(participant_id)
                    if participant is None:
                        participant = self._archived_participants.get(participant_id)
                    if participant is None:
                        raise _error("unknown", "unenroll participant is missing")
                    record = records.get(participant_id, {})
                    if not isinstance(record, Mapping) or record:
                        # Caller-supplied claim/owner assertions are not
                        # authoritative recovery evidence.  The state store's
                        # already-persisted participant claim is the only fact
                        # this no-runtime reconciliation may consume.
                        raise _error("uncertain-effect", "unenroll recovery requires trusted claim state")
                    if participant.writer_claim is not None:
                        # A release can have reached the shared index before
                        # the controller snapshot/journal write.  Conversely,
                        # a stale or forged local ``state=released`` flag must
                        # not clear an actually active shared claim.  Always
                        # read the exact generation-bound index under the
                        # trusted state-store boundary.
                        active_claim = self._trusted_claim_index_record(
                            participant, generation
                        )
                        if active_claim is None:
                            participant.writer_claim.state = "released"
                            operation.metadata.setdefault("claim_reconciliation", {})[
                                participant_id
                            ] = {
                                "state": "released",
                                "generation": generation,
                            }
                        else:
                            unresolved.append(participant_id)
                if unresolved:
                    operation.phase = "indeterminate"
                    operation.metadata["recovery_required"] = True
                    operation.metadata["unresolved_claims"] = unresolved
                    if "unenroll" not in operation.uncertainty:
                        operation.uncertainty.append("unenroll")
                    self._persist({
                        "event": "recover-unenroll-held",
                        "operation_id": operation_id,
                        "participants": unresolved,
                    })
                    return operation
                for participant_id in sealed:
                    intent = intents.get(participant_id)
                    if not isinstance(intent, Mapping):
                        raise _error("invalid", "unenroll intent is malformed")
                    intents[participant_id] = {**dict(intent), "state": "complete"}
                    participant = self._participants.get(participant_id)
                    if participant is not None:
                        self._archived_participants[participant_id] = participant
                        self._participants.pop(participant_id, None)
                self._coordinator_id = None
                operation.phase = "complete"
                operation.metadata["unenrolled"] = True
                operation.metadata["recovery_required"] = False
                self._active_operation_id = None
                self._persist({
                    "event": "recover-unenroll-complete",
                    "operation_id": operation_id,
                })
                return operation
        except BaseException as exc:
            self._mark_recovery_indeterminate(
                operation_id,
                generation,
                "unenroll",
                getattr(exc, "code", "uncertain-effect"),
                str(exc),
            )
            if isinstance(exc, asyncio.CancelledError):
                raise
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "unenroll recovery outcome is uncertain")

    async def _recover_native_swap(
            self,
            operation_id: str,
            generation: Any,
            evidence: Mapping[str, Any],
            records: Mapping[str, Mapping[str, Any]],
    ) -> Operation:
        """Reconcile native swap windows without issuing lifecycle calls.

        The daemon may collect one fresh, identity-bound status envelope for
        the source or the reserved target.  Recovery consumes only that
        observation and the already durable stage ledger: it can complete a
        shutdown/archive or adopt an already-open target, but it never calls
        interrupt, shutdown, open, release, or a model query.
        """
        try:
            archive_needed = False
            target_observation: Optional[Mapping[str, Any]] = None
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                if operation.mode != "swap":
                    raise _error("invalid", "native swap recovery was requested for another operation mode")
                native_swap = operation.metadata.get("native_swap")
                if not isinstance(native_swap, dict):
                    raise _error("unsupported", "native swap recovery is unavailable")
                if operation.phase == "released":
                    return operation
                self._native_swap_owner_claim_matches_locked(operation)
                participant = self._participants.get(self._coordinator_id or "")
                if participant is None:
                    raise _error("ownership-conflict", "native swap recovery coordinator is unavailable")
                if set(records) - {participant.participant_id}:
                    raise _error("invalid", "native swap recovery evidence names an unsealed participant")
                participant_record = records.get(participant.participant_id, {})
                if not isinstance(participant_record, Mapping):
                    raise _error("invalid", "native swap recovery participant evidence is malformed")
                native_records = native_swap.get("native_swap_evidence")
                if not isinstance(native_records, Mapping):
                    raise _error("invalid", "native swap recovery evidence ledger is malformed")
                if native_swap.get("release_receipt") is not None:
                    raise _error(
                        "unsupported",
                        "native swap release recovery requires its bound gate evidence",
                    )
                source_runner = native_swap["source_identity"]["runner_incarnation"]
                target_specs = native_swap.get("target_specs")
                target_spec = (
                    target_specs.get(participant.participant_id)
                    if isinstance(target_specs, Mapping) else None
                )
                if not isinstance(target_spec, Mapping):
                    raise _error("invalid", "native swap recovery target specification is missing")

                # A durable graph-drained observation is sufficient to avoid
                # a second interrupt.  Without it, status cannot prove that
                # an uncertain interrupt did not cross the runtime boundary.
                if "graph-drained" not in native_records:
                    raise _error(
                        "uncertain-effect",
                        "native swap recovery lacks a bound terminal interrupt stage",
                    )

                if "source-excluded" not in native_records:
                    shutdown_intent = native_swap.get("shutdown_intent")
                    shutdown_observation = participant_record.get("shutdown")
                    if shutdown_observation is None:
                        shutdown_observation = participant_record.get("status")
                    if not isinstance(shutdown_intent, Mapping):
                        # The interrupt stage is durable, but shutdown has not
                        # crossed its own intent boundary.  Leave the durable
                        # operation resumable; an explicit swap continuation
                        # owns the next shutdown call.
                        operation.phase = "paused"
                        operation.metadata["recovery_required"] = False
                        self._persist({
                            "event": "recover-native-swap-paused",
                            "operation_id": operation_id,
                        })
                        return operation
                    if shutdown_intent.get("state") != "complete":
                        if shutdown_observation is None:
                            raise _error(
                                "uncertain-effect",
                                "native swap shutdown outcome is unresolved",
                            )
                        valid, reason = self._runtime_shutdown(
                            shutdown_observation,
                            participant,
                            operation,
                            source_runner,
                        )
                        if not valid:
                            raise _error(
                                "uncertain-effect",
                                "native swap shutdown recovery is unproven: " + reason,
                            )
                        native_swap["shutdown_intent"] = {
                            **dict(shutdown_intent),
                            "state": "complete",
                            "receipt": _json_value(shutdown_observation),
                        }
                        operation.phase = "paused"
                        operation.metadata["native_swap"] = native_swap
                        self._persist({
                            "event": "recover-native-swap-shutdown",
                            "operation_id": operation_id,
                        })
                    archive_needed = native_swap.get("source_archive_digest") is None

                if archive_needed:
                    # Defer archive_native_source until after this short
                    # transaction; it owns its own reload/validation boundary.
                    pass

            if archive_needed:
                archive = self.archive_native_source(
                    "native-swap-archive-" + operation_id,
                    operation_id,
                    generation,
                )
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    self._native_swap_owner_claim_matches_locked(operation)
                    native_swap = operation.metadata["native_swap"]
                    native_swap["source_archive_id"] = archive["archive_id"]
                    native_swap["source_archive_digest"] = archive["snapshot_digest"]
                    self._native_admissions.clear()
                    self._native_child_observations.clear()
                    self._native_stops.clear()
                    self._coordinator_interrupts.clear()
                    operation.metadata["native_swap"] = native_swap
                    self._persist({
                        "event": "recover-native-swap-archived",
                        "operation_id": operation_id,
                    })
                self._native_swap_provider_stage(
                    operation_id, generation, "source-excluded"
                )
                self._native_swap_require_stage(
                    operation_id, generation, "source-excluded"
                )

            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                self._native_swap_owner_claim_matches_locked(operation)
                native_swap = operation.metadata["native_swap"]
                native_records = native_swap["native_swap_evidence"]
                target_intent = native_swap.get("target_open_intent")
                if "target-held" in native_records:
                    operation.phase = "ready-held"
                    operation.metadata["ready_generation"] = generation
                    operation.metadata["recovery_required"] = False
                    self._save_request_result(operation.request_id, operation.to_dict())
                    self._persist({
                        "event": "recover-native-swap-ready-held",
                        "operation_id": operation_id,
                    })
                    return operation
                if not isinstance(target_intent, Mapping):
                    operation.phase = "paused"
                    operation.metadata["recovery_required"] = False
                    self._persist({
                        "event": "recover-native-swap-paused",
                        "operation_id": operation_id,
                    })
                    return operation
                if target_intent.get("state") != "in-progress":
                    raise _error("uncertain-effect", "native swap target open intent is unresolved")
                target_observation = participant_record.get("open")
                if target_observation is None:
                    target_observation = participant_record.get("status")
                if target_observation is None:
                    operation.phase = "paused"
                    operation.metadata["recovery_required"] = False
                    self._persist({
                        "event": "recover-native-swap-paused",
                        "operation_id": operation_id,
                    })
                    return operation

            assert target_observation is not None
            valid, reason = self._runtime_ready(
                target_observation, participant, operation, target_spec
            )
            if not valid:
                raise _error(
                    "uncertain-effect",
                    "native swap target recovery is unproven: " + reason,
                )
            target_runner = self._runtime_runner_instance(target_observation)
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                self._native_swap_owner_claim_matches_locked(operation)
                native_swap = operation.metadata["native_swap"]
                expected_runner = native_swap.get("target_runner_incarnation")
                if target_runner != expected_runner:
                    raise _error(
                        "stale-generation",
                        "native swap recovered target runner changed",
                    )
                process = self._runtime_process(
                    target_observation, "recover-native-swap-open"
                )
                target_observation = _json_value(target_observation)
                # Bind the observed target before asking the independent
                # target-held provider.  This is the recovery equivalent of
                # the normal open path: the source participant/context stays
                # active until the provider proves the target-held boundary,
                # but the exact target runner and ready open evidence are
                # durable before that evidence is appended.
                native_swap["target_runner_instance_id"] = target_runner
                native_swap["target_open_intent"] = {
                    **dict(native_swap["target_open_intent"]),
                    "state": "ready",
                    "runner_instance_id": target_runner,
                }
                operation.metadata["native_swap"] = native_swap
                participant_id = participant.participant_id
                operation.metadata.setdefault("runner_instances", {})[
                    participant_id
                ] = target_runner
                operation.metadata.setdefault("open_evidence", {})[
                    participant_id
                ] = _json_value(target_observation)
                operation.metadata.setdefault("launch_processes", {})[
                    participant_id
                ] = _json_value(process)
                operation.metadata.setdefault("launch_intents", {})[
                    participant_id
                ] = {
                    **dict(operation.metadata["launch_intents"].get(participant_id, {})),
                    "state": "ready",
                    "runner_instance_id": target_runner,
                }
                self._persist({
                    "event": "recover-native-swap-target-open-ready",
                    "operation_id": operation_id,
                })

            self._native_swap_provider_stage(
                operation_id, generation, "target-held"
            )
            self._native_swap_require_stage(
                operation_id, generation, "target-held"
            )
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                self._native_swap_owner_claim_matches_locked(operation)
                participant = self._participants[self._coordinator_id]
                native_swap = operation.metadata["native_swap"]
                profile = operation.metadata["target_profile"]
                spec = native_swap["target_specs"][participant.participant_id]
                if target_runner != native_swap.get("target_runner_incarnation"):
                    raise _error(
                        "stale-generation",
                        "native swap recovered target runner changed before activation",
                    )
                self._adopt_target_runner(
                    participant,
                    spec,
                    profile,
                    runner_instance_id=target_runner,
                    process=process,
                )
                self._native_context = None
                native_swap["target_runner_instance_id"] = target_runner
                native_swap["target_open_intent"] = {
                    **dict(native_swap["target_open_intent"]),
                    "state": "ready",
                    "runner_instance_id": target_runner,
                }
                native_swap["state"] = "ready-held"
                operation.metadata["native_swap"] = native_swap
                operation.metadata.setdefault("runner_instances", {})[
                    participant.participant_id
                ] = target_runner
                operation.metadata.setdefault("open_evidence", {})[
                    participant.participant_id
                ] = _json_value(target_observation)
                operation.metadata.setdefault("launch_processes", {})[
                    participant.participant_id
                ] = _json_value(process)
                operation.metadata.setdefault("launch_intents", {})[
                    participant.participant_id
                ] = {
                    **dict(operation.metadata["launch_intents"].get(
                        participant.participant_id, {}
                    )),
                    "state": "ready",
                    "runner_instance_id": target_runner,
                }
                operation.readiness[participant.participant_id] = {
                    "session_id": participant.session_id,
                    "runner_instance_id": target_runner,
                    "spec": _json_value(spec),
                    "evidence": _json_value(target_observation),
                }
                operation.phase = "ready-held"
                operation.metadata["ready_generation"] = generation
                operation.metadata["recovery_required"] = False
                self._save_request_result(operation.request_id, operation.to_dict())
                self._persist({
                    "event": "recover-native-swap-ready-held",
                    "operation_id": operation_id,
                })
                return operation
        except BaseException as exc:
            self._mark_recovery_indeterminate(
                operation_id,
                generation,
                "native-swap",
                getattr(exc, "code", "uncertain-effect"),
                str(exc),
            )
            if isinstance(exc, asyncio.CancelledError):
                raise
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "native swap recovery outcome is uncertain")

    async def _recover_native_invocation_rollover(
            self, operation_id: str, generation: Any,
    ) -> Operation:
        """Consume one exact adapter no-send receipt for a native rollover.

        Recovery is observational.  It may read one status result and, when
        that result proves the already-authorized reservation was not sent,
        atomically bind a pending reservation and/or return B to the normal
        released pump.  It never prepares, sends, queries, or pumps runtime
        work itself.
        """
        operation_id = _id(operation_id, "operation_id") or ""
        generation = self._generation_valid(generation)
        status_method = getattr(self.runtime, "status", None) if self.runtime is not None else None
        if not callable(status_method):
            raise _error(
                "unsupported",
                "native rollover recovery requires runtime status evidence",
            )

        def _authority_snapshot() -> Tuple[Dict[str, Any], List[Any]]:
            owner_reader = getattr(self.store, "read_owner", None)
            claims_reader = getattr(self.store, "read_lineage_claims", None)
            if not callable(owner_reader) or not callable(claims_reader):
                raise _error(
                    "unsupported",
                    "native rollover recovery requires durable daemon authority",
                )
            owner = owner_reader()
            claims = claims_reader()
            if not isinstance(owner, Mapping) or not isinstance(claims, list):
                raise _error(
                    "ownership-conflict",
                    "native rollover recovery authority evidence is malformed",
                )
            owner_copy = _json_value(owner)
            claims_copy = _json_value(claims)
            if not isinstance(owner_copy, dict) or not isinstance(claims_copy, list):
                raise _error(
                    "ownership-conflict",
                    "native rollover recovery authority evidence is malformed",
                )
            if not _id(owner_copy.get("daemon_id"), "native rollover daemon ID", required=False):
                raise _error(
                    "unsupported",
                    "native rollover recovery daemon authority is unavailable",
                )
            return owner_copy, claims_copy

        def _context_digest(context: Any) -> str:
            return _digest(_json_value(context))

        # Capture every controller-owned fence before crossing the one
        # observational runtime boundary.  No state is changed in this phase.
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            if operation.phase != "released" or operation.release_count != 1:
                raise _error(
                    "busy",
                    "native rollover recovery requires one released operation",
                )
            candidates = [
                value for value in self._native_invocation_rollovers.values()
                if value.get("operation_id") == operation_id
                and value.get("state") not in {"delivered", "reconciled"}
            ]
            if len(candidates) != 1:
                if not candidates:
                    raise _error(
                        "unknown",
                        "native rollover has no unresolved recovery record",
                    )
                raise _error(
                    "uncertain-effect",
                    "native rollover recovery has competing records",
                )
            rollover = candidates[0]
            rollover_id = _id(rollover.get("rollover_id"), "native rollover ID") or ""
            request = self._validate_native_prepare_request(
                rollover.get("preparation_intent", {}).get("request")
            )
            if self._native_dispatch_inflight.get(request["next_mailbox_id"]):
                raise _error(
                    "busy",
                    "native rollover has a live controller dispatch boundary",
                )
            entry = self._mailboxes.get(request["next_mailbox_id"])
            if entry is None or entry.recipient_id != request["participant_id"]:
                raise _error("ownership-conflict", "native rollover mailbox is unavailable")
            # Recovery may return a previously consumed receipt without a
            # runtime read, but that read-only path is still fenced by the
            # current owner/daemon/claim authority.  Validate it before any
            # early return so a stale caller cannot observe or reuse a grant.
            context = self._native_context
            if not isinstance(context, Mapping):
                raise _error("unsupported", "native rollover recovery has no current context")
            context = self._validate_native_context(context)
            self._check_native_authority(
                context, expected_daemon_id=rollover.get("daemon_id")
            )
            if entry.state in {"acknowledged"} or rollover.get("state") == "delivered":
                raise _error(
                    "uncertain-effect",
                    "native rollover transport has already been acknowledged",
                )
            if entry.state == "queued" and (
                rollover.get("native_reservation_no_send") is not None
                and rollover.get("native_reservation_no_send_consumption") is not None
            ):
                # A consumed receipt is a read-only fact.  In particular,
                # repeated recover calls must not poll the runtime again.
                return operation
            if (
                rollover.get("native_reservation_no_send") is not None
                or rollover.get("native_reservation_no_send_consumption") is not None
            ):
                raise _error(
                    "invalid",
                    "native rollover has a partial no-send receipt",
                )
            if entry.state not in {"queued", "dispatch-intent", "uncertain"}:
                raise _error("uncertain-effect", "native rollover mailbox is not recoverable")

            reservation = rollover.get("reservation_binding")
            committed = reservation is not None
            if committed:
                reservation = self._validate_native_prepare_response(request, reservation)
                if reservation.get("state") != "reserved":
                    raise _error("invalid", "native rollover reservation is not committed")
                if context.get("invocation_id") != request["next_invocation_id"]:
                    raise _error("stale-generation", "native rollover B context is not current")
                next_context = rollover.get("next_context")
                if not isinstance(next_context, Mapping):
                    raise _error("invalid", "native rollover B context is missing")
                if _context_digest(context) != _context_digest(next_context):
                    raise _error("ownership-conflict", "native rollover B context changed")
                if entry.state not in {"dispatch-intent", "uncertain"}:
                    raise _error(
                        "uncertain-effect",
                        "native rollover committed mailbox is not awaiting send",
                    )
            else:
                if context.get("invocation_id") != request["prior_invocation_id"]:
                    raise _error("stale-generation", "native rollover A context is not current")
                if entry.state != "queued":
                    raise _error(
                        "uncertain-effect",
                        "native rollover preparation mailbox is not queued",
                    )
                if rollover.get("history_id") is not None:
                    raise _error("invalid", "native rollover preparation has history")

            if context.get("runner_incarnation") != request["runner_incarnation"]:
                raise _error("stale-generation", "native rollover runner changed")
            lineage = context.get("lineage")
            if (
                not isinstance(lineage, Mapping)
                or lineage.get("lineage_id") != request["lineage_id"]
                or lineage.get("lineage_generation") != request["lineage_generation"]
                or lineage.get("session_uuid") != request["session_id"]
                or _digest(lineage.get("workspace_claim")) != request["claim_digest"]
            ):
                raise _error("ownership-conflict", "native rollover lineage changed")
            if context.get("invocation_watermark") != (
                rollover.get("next_watermark") if committed else request["prior_watermark"]
            ):
                raise _error("stale-generation", "native rollover context watermark changed")
            if _digest(context.get("definitions")) != request["definitions_digest"]:
                raise _error("permission-mismatch", "native rollover definitions changed")
            if _digest(self._native_prepare_permissions(context.get("definitions", {}))) != request[
                "permissions_digest"
            ]:
                raise _error("permission-mismatch", "native rollover permissions changed")

            coordinator = self._participants.get(request["participant_id"])
            if coordinator is None:
                raise _error("ownership-conflict", "native rollover coordinator disappeared")
            if coordinator.metadata.get("runner_instance_id") != request["runner_incarnation"]:
                raise _error("stale-generation", "native rollover coordinator runner changed")
            if coordinator.session_id != request["session_id"]:
                raise _error("ownership-conflict", "native rollover coordinator session changed")
            owner_before, claims_before = _authority_snapshot()
            rollover_before = _digest(rollover)
            entry_before = _digest(entry.to_dict())
            operation_before = _digest(operation.to_dict())
            request_before = _digest(request)
            context_before = _context_digest(context)
            history_before = (
                _digest(self._native_invocation_history.get(rollover["history_id"]))
                if rollover.get("history_id") is not None else None
            )
            reservation_before = _digest(reservation) if reservation is not None else None
            daemon_before = owner_before.get("daemon_id")
            claim_authority_before = _digest(claims_before)
            # The authority check above is intentionally not swallowed.  A
            # failed pre-await fence must refuse before status observation;
            # otherwise a replacement daemon could turn a stale receipt into
            # an apparently valid no-send grant.

        # A runtime status read is the only effect in this method.  It is
        # deliberately outside the state transaction and occurs exactly once.
        try:
            status = status_method(request["participant_id"])
            if inspect.isawaitable(status):
                try:
                    status = await asyncio.wait_for(
                        status, _NATIVE_RECOVERY_STATUS_TIMEOUT
                    )
                except asyncio.TimeoutError as exc:
                    raise _error(
                        "uncertain-effect",
                        "native rollover status observation timed out",
                    ) from exc
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            raise _error(
                "uncertain-effect",
                "native rollover status observation is unavailable: %s" % exc,
            )

        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            if operation.phase != "released" or operation.release_count != 1:
                raise _error("stale-generation", "native rollover operation changed during recovery")
            rollover = self._native_invocation_rollovers.get(rollover_id)
            if rollover is None:
                raise _error("stale-generation", "native rollover record disappeared")
            request = self._validate_native_prepare_request(
                rollover.get("preparation_intent", {}).get("request")
            )
            if request["next_mailbox_id"] != entry.message_id:
                raise _error("ownership-conflict", "native rollover mailbox binding changed")
            if self._native_dispatch_inflight.get(request["next_mailbox_id"]):
                raise _error("busy", "native rollover has a live dispatch boundary")
            current_entry = self._mailboxes.get(request["next_mailbox_id"])
            if current_entry is None:
                raise _error("ownership-conflict", "native rollover mailbox disappeared")
            if _digest(current_entry.to_dict()) != entry_before:
                raise _error("stale-generation", "native rollover mailbox changed during recovery")
            if _digest(operation.to_dict()) != operation_before:
                raise _error("stale-generation", "native rollover operation changed during recovery")
            if _digest(request) != request_before:
                raise _error("stale-generation", "native rollover request changed during recovery")
            if _digest(rollover) != rollover_before:
                raise _error("stale-generation", "native rollover binding changed during recovery")
            if current_entry.state in {"acknowledged"}:
                raise _error("uncertain-effect", "native rollover transport was acknowledged")
            current_context = self._native_context
            if not isinstance(current_context, Mapping):
                raise _error("stale-generation", "native rollover context disappeared")
            current_context = self._validate_native_context(current_context)
            if _context_digest(current_context) != context_before:
                raise _error("stale-generation", "native rollover context changed during recovery")
            if self._native_daemon_id_locked() != daemon_before:
                raise _error("stale-generation", "native rollover daemon changed during recovery")
            owner_after, claims_after = _authority_snapshot()
            if (
                owner_after.get("daemon_id") != daemon_before
                or _digest(claims_after) != claim_authority_before
            ):
                raise _error("stale-generation", "native rollover authority changed during recovery")
            self._check_native_authority(
                current_context, expected_daemon_id=rollover.get("daemon_id")
            )
            if rollover.get("history_id") is not None:
                history_after = self._native_invocation_history.get(rollover["history_id"])
                if history_after is None or _digest(history_after) != history_before:
                    raise _error("stale-generation", "native rollover history changed during recovery")
            current_reservation = rollover.get("reservation_binding")
            if current_reservation is not None and _digest(current_reservation) != reservation_before:
                raise _error("stale-generation", "native rollover reservation changed during recovery")

            coordinator = self._participants.get(request["participant_id"])
            if coordinator is None:
                raise _error("ownership-conflict", "native rollover coordinator disappeared")
            valid, reason = self._runtime_identity_matches(
                status,
                coordinator,
                operation,
                expected_runner_instance_id=request["runner_incarnation"],
            )
            if not valid:
                raise _error("uncertain-effect", "native rollover status identity is invalid: %s" % reason)
            evidence = self._runtime_evidence(status, "native rollover status")
            if "native_reservation_no_send" not in evidence:
                raise _error("uncertain-effect", "native rollover has no bound no-send receipt")
            receipt = self._validate_native_no_send_receipt(
                request, evidence["native_reservation_no_send"]
            )
            if current_reservation is not None and receipt["reservation_binding"] != current_reservation:
                raise _error("ownership-conflict", "native rollover receipt names another reservation")
            retained_receipts: List[Tuple[Mapping[str, Any], Optional[str], Optional[str]]] = []
            for other_id, other in self._native_invocation_rollovers.items():
                if other_id == rollover_id:
                    continue
                other_receipt = other.get("native_reservation_no_send")
                if isinstance(other_receipt, Mapping):
                    retained_receipts.append(
                        (
                            other_receipt,
                            other.get("operation_id"),
                            other.get("rollover_id"),
                        )
                    )
            # Immutable history normally has no receipt field, but older
            # archived snapshots may retain a copy of the logical rollover.
            # The same exact observation may agree with that copy; a changed
            # digest is a genuine observation-ID reuse and is refused.
            for history in self._native_invocation_history.values():
                history_receipt = history.get("native_reservation_no_send")
                if isinstance(history_receipt, Mapping):
                    retained_receipts.append((history_receipt, None, None))
            for archive in self._native_source_archives.values():
                snapshot = archive.get("snapshot") if isinstance(archive, Mapping) else None
                archived_rollovers = (
                    snapshot.get("native_invocation_rollovers")
                    if isinstance(snapshot, Mapping) else None
                )
                if not isinstance(archived_rollovers, Mapping):
                    continue
                for archived in archived_rollovers.values():
                    if not isinstance(archived, Mapping):
                        continue
                    archived_receipt = archived.get("native_reservation_no_send")
                    if isinstance(archived_receipt, Mapping):
                        retained_receipts.append(
                            (
                                archived_receipt,
                                archived.get("operation_id"),
                                archived.get("rollover_id"),
                            )
                        )
            for retained, retained_operation_id, retained_rollover_id in retained_receipts:
                if retained.get("observation_id") != receipt["observation_id"]:
                    continue
                same_logical_copy = (
                    retained_operation_id == operation_id
                    and retained_rollover_id == rollover_id
                )
                if not same_logical_copy or retained.get("receipt_digest") != receipt["receipt_digest"]:
                    raise _error("ownership-conflict", "native reservation observation ID was reused")

            if current_reservation is None:
                # Commit the already-issued adapter reservation and A history
                # without publishing an intermediate snapshot.  The receipt,
                # consumption marker, and queued B become one durable write.
                self._native_commit_rollover_locked(
                    operation,
                    rollover_id,
                    receipt["reservation_binding"],
                    persist=False,
                )
                rollover = self._native_invocation_rollovers.get(rollover_id)
                current_entry = self._mailboxes.get(request["next_mailbox_id"])
                if rollover is None or current_entry is None:
                    raise _error("invalid", "native rollover bind did not produce B")
            else:
                if current_entry.state not in {"dispatch-intent", "uncertain"}:
                    raise _error(
                        "uncertain-effect",
                        "native rollover mailbox is no longer an unsent dispatch intent",
                    )

            consumption = self._validate_native_no_send_consumption(
                {
                    "observation_id": receipt["observation_id"],
                    "receipt_digest": receipt["receipt_digest"],
                    "mailbox_id": request["next_mailbox_id"],
                    "consumed": True,
                },
                receipt,
                request["next_mailbox_id"],
            )
            rollover["native_reservation_no_send"] = _json_value(receipt)
            rollover["native_reservation_no_send_consumption"] = _json_value(consumption)
            rollover["state"] = "send-pending"
            rollover["uncertainty"] = None
            current_entry.state = "queued"
            current_entry.runtime_ack = None
            operation.uncertainty = [
                marker for marker in operation.uncertainty
                if marker != "mail:%s" % request["next_mailbox_id"]
            ]
            rollover["integrity_digest"] = self._native_record_integrity(
                rollover, "integrity_digest"
            )
            self._persist({
                "event": "native-rollover-no-send-reconciled",
                "operation_id": operation_id,
                "rollover_id": rollover_id,
                "observation_id": receipt["observation_id"],
                "message_id": request["next_mailbox_id"],
            })
            return operation

    async def recover(
        self,
        operation_id: str,
        generation: Any,
        evidence: Any = None,
    ) -> Operation:
        """Reconcile durable swap progress without replaying runtime effects.

        Recovery consumes explicit evidence for calls already made.  It never
        invokes interrupt/open/release itself and never turns an ambiguous
        effect into a fresh operation.  A subsequent ``swap`` may continue
        only from the durable stage proven by this method.
        """
        operation_id = _id(operation_id, "operation_id") or ""
        generation = self._generation_valid(generation)
        native_rollover_recovery = False
        with self._transaction():
            operation = self._operation(operation_id)
            self._check_generation(generation)
            if operation.generation != generation or self._active_operation_id != operation_id:
                raise _error("stale-generation", "recovery does not match the current operation")
            unresolved_rollovers = [
                value for value in self._native_invocation_rollovers.values()
                if value.get("operation_id") == operation_id
                and value.get("state") not in {"delivered", "reconciled"}
            ]
            if unresolved_rollovers:
                if evidence is not None:
                    raise _error(
                        "invalid",
                        "native rollover recovery does not accept caller-supplied evidence",
                    )
                if len(unresolved_rollovers) != 1:
                    raise _error(
                        "uncertain-effect",
                        "native rollover recovery has competing records",
                    )
                native_rollover_recovery = True

        if native_rollover_recovery:
            return await self._recover_native_invocation_rollover(
                operation_id, generation
            )
        if evidence is None:
            raise _error("invalid", "explicit recovery evidence is required")
        if not isinstance(evidence, Mapping):
            raise _error("invalid", "recovery evidence must be an object")
        _digest(evidence)
        with self._transaction():
            operation = self._operation(operation_id)
            self._check_generation(generation)
            if operation.generation != generation or self._active_operation_id != operation_id:
                raise _error("stale-generation", "recovery does not match the current operation")
            if isinstance(evidence.get("operation_id"), str) and evidence.get("operation_id") != operation_id:
                raise _error("stale-generation", "recovery evidence names another operation")
            if evidence.get("generation") is not None and evidence.get("generation") != generation:
                raise _error("stale-generation", "recovery evidence names another generation")
            mode = operation.mode
            # Validate the current operation/generation/active pointer before
            # deciding whether an empty evidence set is meaningful.  Only
            # unenroll has a trusted state-only reconciliation path; every
            # runtime-bearing mode retains the existing required-record gate.
            records = self._recovery_records(
                evidence, allow_empty=(mode == "unenroll")
            )
            native_swap_operation = (
                mode == "swap"
                and isinstance(operation.metadata.get("native_swap"), Mapping)
            )

        if native_swap_operation:
            return await self._recover_native_swap(
                operation_id, generation, evidence, records
            )

        # Recovery is mode-specific.  In particular, shutdown and unenroll
        # have no target runner to reopen, while ctx has no retained-worker
        # open/shutdown stages.  Keep these branches ahead of the swap-only
        # runner-map validation below so a crash cannot accidentally enter the
        # replacement lifecycle.
        if mode == "ctx":
            return await self._recover_ctx(
                operation_id, generation, evidence, records
            )
        if mode == "shutdown":
            return await self._recover_shutdown(
                operation_id, generation, evidence, records
            )
        if mode == "unenroll":
            return await self._recover_unenroll(
                operation_id, generation, evidence, records
            )
        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            participants = {
                item.participant_id: item
                for item in self._participants.values()
                if item.participant_id in operation.sealed_participants
                and item.state.casefold() not in {"completed", "stopped"}
            }
            target_specs = operation.metadata.get("target_specs", {})
            old_runners = operation.metadata.get("old_runner_instances", {})
            new_runners = operation.metadata.get("runner_instances", {})
            if not isinstance(old_runners, Mapping) or not isinstance(new_runners, Mapping):
                raise _error("invalid", "durable runner identity maps are malformed")
            existing = {
                "interrupt": operation.metadata.get("interrupt_receipts", {}),
                "status": operation.metadata.get("status_evidence", {}),
                "shutdown": operation.metadata.get("shutdown_receipts", {}),
                "open": operation.metadata.get("open_evidence", {}),
                "release": operation.metadata.get("release_receipts", {}),
            }
            if any(not isinstance(value, Mapping) for value in existing.values()):
                raise _error("invalid", "durable recovery evidence maps are malformed")
            phase = operation.phase

        if operation.mode == "start":
            return await self._recover_start(
                operation_id, generation, evidence, records
            )
        if operation.mode == "add-worker":
            return await self._recover_add_worker(
                operation_id, generation, evidence, records
            )

        unknown = set(records) - set(participants)
        if unknown:
            raise _error("invalid", "recovery evidence names an unsealed participant")
        updates: Dict[str, Dict[str, Any]] = {}
        for participant_id, participant_evidence in records.items():
            if not participant_evidence:
                raise _error("invalid", "recovery participant evidence is empty")
            unknown_stages = set(participant_evidence) - {"interrupt", "status", "shutdown", "open", "release"}
            if unknown_stages:
                raise _error("invalid", "recovery evidence has an unknown stage")
            updates[participant_id] = {}
            old_runner = old_runners.get(participant_id)
            new_runner = new_runners.get(participant_id)
            for stage in ("interrupt", "status", "shutdown"):
                value = participant_evidence.get(stage)
                if value is None:
                    continue
                expected = old_runner
                if stage == "interrupt" and expected is None:
                    expected = None
                if stage != "interrupt" and not isinstance(expected, str):
                    raise _error("uncertain-effect", "%s evidence has no old runner identity" % stage)
                if stage == "interrupt":
                    valid, reason = self._runtime_identity_matches(
                        value, participants[participant_id], operation,
                        expected_runner_instance_id=expected,
                    )
                elif stage == "status":
                    valid, reason = self._runtime_quiescent(
                        value, participants[participant_id], operation,
                        expected_runner_instance_id=expected,
                    )
                else:
                    valid, reason = self._runtime_shutdown(
                        value, participants[participant_id], operation, expected
                    )
                if not valid:
                    raise _error("uncertain-effect", "%s recovery evidence is invalid: %s" % (stage, reason))
                updates[participant_id][stage] = _json_value(value)
                if stage == "interrupt":
                    returned = self._runtime_runner_instance(value)
                    if returned is None:
                        raise _error("uncertain-effect", "interrupt evidence has no runner identity")
                    if old_runner is not None and old_runner != returned:
                        raise _error("stale-generation", "interrupt evidence changed runner identity")
                    old_runner = returned
            if "open" in participant_evidence:
                if not isinstance(target_specs, Mapping) or not isinstance(target_specs.get(participant_id), Mapping):
                    raise _error("invalid", "open recovery has no durable target specification")
                if not isinstance(operation.metadata.get("shutdown_receipts", {}).get(participant_id), Mapping) and "shutdown" not in updates[participant_id]:
                    raise _error("busy", "open recovery requires proven old process exclusion")
                valid, reason = self._runtime_ready(
                    participant_evidence["open"], participants[participant_id], operation,
                    target_specs[participant_id],
                )
                if not valid:
                    raise _error("loader-failed", "open recovery evidence is invalid: %s" % reason)
                returned = self._runtime_runner_instance(participant_evidence["open"])
                if returned is None:
                    raise _error("loader-failed", "open recovery has no runner identity")
                if new_runner is not None and new_runner != returned:
                    raise _error("stale-generation", "open recovery changed runner identity")
                updates[participant_id]["open"] = _json_value(participant_evidence["open"])
                # Keep the process identity alongside the recovered open
                # evidence.  The adapter may already have spawned this
                # incarnation before the controller crashed, so recovery must
                # adopt it rather than treating the UUID as a new launch.
                updates[participant_id]["open_process"] = _json_value(
                    self._runtime_process(participant_evidence["open"], "recover-open")
                )
                new_runner = returned
            if "release" in participant_evidence:
                if not isinstance(new_runner, str) or not new_runner:
                    raise _error("uncertain-effect", "release recovery has no runner identity")
                valid, reason = self._runtime_released(
                    participant_evidence["release"], participants[participant_id], operation, new_runner
                )
                if not valid:
                    raise _error("uncertain-effect", "release recovery evidence is invalid: %s" % reason)
                updates[participant_id]["release"] = _json_value(participant_evidence["release"])

        with self._transaction():
            operation = self._current_operation(operation_id, generation)
            maps = {
                "interrupt": operation.metadata.setdefault("interrupt_receipts", {}),
                "status": operation.metadata.setdefault("status_evidence", {}),
                "shutdown": operation.metadata.setdefault("shutdown_receipts", {}),
                "open": operation.metadata.setdefault("open_evidence", {}),
                "release": operation.metadata.setdefault("release_receipts", {}),
            }
            if any(not isinstance(value, dict) for value in maps.values()):
                raise _error("invalid", "durable recovery evidence maps are malformed")
            for participant_id, values in updates.items():
                for stage, value in values.items():
                    if stage in maps:
                        maps[stage][participant_id] = value
                if "interrupt" in values:
                    runner = self._runtime_runner_instance(values["interrupt"])
                    if runner is not None:
                        operation.metadata.setdefault("old_runner_instances", {})[participant_id] = runner
                if "open" in values:
                    runner = self._runtime_runner_instance(values["open"])
                    if runner is not None:
                        operation.metadata.setdefault("runner_instances", {})[participant_id] = runner
                    launch_processes = operation.metadata.setdefault("launch_processes", {})
                    if not isinstance(launch_processes, dict):
                        raise _error("invalid", "durable launch process ledger is malformed")
                    if "open_process" not in values:
                        raise _error("uncertain-effect", "open recovery has no process identity")
                    launch_processes[participant_id] = values["open_process"]
                    launch_intents = operation.metadata.setdefault("launch_intents", {})
                    if not isinstance(launch_intents, dict):
                        raise _error("invalid", "durable launch intent ledger is malformed")
                    intent = launch_intents.get(participant_id)
                    if not isinstance(intent, Mapping):
                        raise _error("uncertain-effect", "open recovery has no durable launch intent")
                    intent = dict(intent)
                    intent["state"] = "ready"
                    intent["runner_instance_id"] = runner
                    intent["process"] = values["open_process"]
                    launch_intents[participant_id] = intent
                    target_specs = operation.metadata.get("target_specs", {})
                    target_profile = operation.metadata.get("target_profile")
                    if (
                        not isinstance(target_specs, Mapping)
                        or not isinstance(target_specs.get(participant_id), Mapping)
                        or not isinstance(target_profile, Mapping)
                    ):
                        raise _error("invalid", "open recovery target identity is incomplete")
                    current_participant = self._participants.get(participant_id)
                    if current_participant is None:
                        raise _error("unknown", "open recovery participant is no longer enrolled")
                    self._adopt_target_runner(
                        current_participant,
                        target_specs[participant_id],
                        target_profile,
                        runner_instance_id=runner,
                        process=values["open_process"],
                    )
                    operation.readiness[participant_id] = {
                        "session_id": current_participant.session_id,
                        "runner_instance_id": runner,
                        "spec": _json_value(target_specs[participant_id]),
                        "evidence": values["open"],
                    }
            active_ids = [item.participant_id for item in self._participants.values()
                          if item.participant_id in operation.sealed_participants
                          and item.state.casefold() not in {"completed", "stopped"}]
            shutdown_done = all(item in maps["shutdown"] for item in active_ids)
            open_done = shutdown_done and all(item in maps["open"] for item in active_ids)
            release_done = all(item in maps["release"] for item in active_ids)
            if operation.metadata.get("release_intent", {}).get("state") == "in-progress":
                if release_done:
                    operation.release_count = 1
                    operation.phase = "released"
                    operation.metadata["release_intent"]["state"] = "complete"
                    operation.metadata["release_intent"]["completed_at"] = self.clock()
                else:
                    operation.phase = "indeterminate"
            elif open_done:
                operation.phase = "ready-held"
                operation.metadata["ready_generation"] = generation
            elif shutdown_done:
                operation.phase = "starting"
            elif operation.phase == "indeterminate":
                # Proving status/interrupt progress is safe, but it does not
                # authorize an open or a release.  Leave the operation fenced
                # until the next explicit swap continuation performs the
                # missing shutdown/open stages.
                if all(item in maps["status"] for item in active_ids):
                    operation.phase = "paused"
            self._persist({"event": "recover-operation", "operation_id": operation_id,
                           "phase": operation.phase})
            return operation

    # ---- completion and status ---------------------------------------

    @staticmethod
    def _runtime_terminal_status(
        value: Any,
        participant: Participant,
        operation: Operation,
        expected_runner_instance_id: str,
    ) -> Tuple[bool, str]:
        """Require an adapter-owned terminal turn before worker completion.

        The pinned runner evidence intentionally has no caller-controlled
        ``completed`` flag.  The exact adapter's status is authoritative when
        it reports a drained terminal turn with quiescent tools and no
        uncertain effects; explicit ``completed``/``stopped`` markers, when
        present, are accepted only in addition to those canonical facts.
        """
        valid, reason = ManagedController._runtime_quiescent(
            value,
            participant,
            operation,
            expected_runner_instance_id=expected_runner_instance_id,
        )
        if not valid:
            return False, reason
        evidence = ManagedController._runtime_evidence(value, "completion status")
        explicit_terminal = (
            evidence.get("completed") is True
            or evidence.get("stopped") is True
            or str(evidence.get("state", "")).casefold() in {"completed", "stopped", "complete"}
            or str(evidence.get("status", "")).casefold() in {"completed", "stopped", "complete"}
        )
        # ``turn_terminal`` + ``drained`` is the canonical SDK completion
        # proof (0.2.153 does not add a second status string).  Do not accept a
        # merely idle-looking result: _runtime_quiescent has already checked
        # every participant/tool/effect field and this exact terminal flag.
        if not explicit_terminal and evidence.get("turn_terminal") is not True:
            return False, "runtime status lacks authoritative completed/stopped evidence"
        try:
            ManagedController._runtime_process(value, "completion status")
        except ControllerError as exc:
            return False, exc.message
        return True, ""

    @staticmethod
    def _runtime_safe_evidence(value: Any, label: str) -> Dict[str, Any]:
        """Project bounded canonical evidence without retaining event bodies."""
        response = ManagedController._runtime_object(value, label)
        evidence = ManagedController._runtime_evidence(value, label)
        safe: Dict[str, Any] = {}
        for key in (
            "participant_id",
            "session_id",
            "runner_instance_id",
            "message_id",
            "accepted",
            "ack_kind",
        ):
            if key in response:
                safe[key] = _json_value(response[key])
        for key in (
            "ready",
            "released",
            "interrupt_receipt",
            "active_turn",
            "turn_terminal",
            "drained",
            "participant_quiescent",
            "tools_quiescent",
            "quiescent",
        ):
            if key in evidence:
                safe[key] = evidence[key]
        process = evidence.get("process")
        if isinstance(process, Mapping):
            safe["process"] = {
                key: _json_value(process[key])
                for key in (
                    "pid",
                    "process_group_id",
                    "process_start_token",
                    "process_group_owned",
                    "exited",
                    "group_excluded",
                )
                if key in process
            }
        initialization = evidence.get("initialization")
        if isinstance(initialization, Mapping):
            init: Dict[str, Any] = {}
            for key in ("account_email", "permission_mode", "model"):
                if key in initialization:
                    init[key] = _json_value(initialization[key])
            if isinstance(initialization.get("fingerprint"), Mapping):
                init["fingerprint"] = _safe_json_projection(
                    initialization["fingerprint"], "%s initialization fingerprint" % label
                )
            safe["initialization"] = init
        tools = evidence.get("tools")
        if isinstance(tools, list):
            # Tool details are diagnostic only.  Keep bounded identity/state
            # facts and never journal arbitrary SDK event or prompt content.
            projected_tools: list[Dict[str, Any]] = []
            for item in tools[:64]:
                if not isinstance(item, Mapping):
                    continue
                projected: Dict[str, Any] = {}
                for key in (
                    "tool_id",
                    "id",
                    "name",
                    "state",
                    "status",
                    "terminal",
                    "completed",
                    "participant_id",
                    "generation",
                ):
                    if key in item and isinstance(item[key], (str, int, float, bool)):
                        projected[key] = item[key]
                projected_tools.append(projected)
            safe["tools"] = projected_tools
        uncertain = evidence.get("uncertain_effects")
        safe["uncertain_effects"] = [] if uncertain == [] else {
            "count": len(uncertain) if isinstance(uncertain, list) else None,
        }
        _digest(safe)
        return safe

    @staticmethod
    def _stored_quiescence_proof(value: Any) -> bool:
        """Validate the bounded status projection kept across a crash.

        Lifecycle methods retain only canonical identity, turn/tool flags, and
        process facts in the durable snapshot.  That projection deliberately
        has no nested runtime envelope, so recovery validates it separately
        instead of treating the projection as a fresh adapter response.
        """
        if not isinstance(value, Mapping):
            return False
        if any(
            not isinstance(value.get(name), bool) or value.get(name) is not expected
            for name, expected in (
                ("active_turn", False),
                ("turn_terminal", True),
                ("drained", True),
                ("participant_quiescent", True),
                ("tools_quiescent", True),
                ("quiescent", True),
            )
        ):
            return False
        if not isinstance(value.get("tools"), list):
            return False
        if value.get("uncertain_effects") not in ([], {"count": 0}):
            return False
        process = value.get("process")
        if not isinstance(process, Mapping):
            return False
        required = (
            "pid",
            "process_group_id",
            "process_start_token",
            "process_group_owned",
            "exited",
            "group_excluded",
        )
        if any(key not in process for key in required):
            return False
        return (
            isinstance(process.get("pid"), int)
            and not isinstance(process.get("pid"), bool)
            and process.get("pid") > 0
            and isinstance(process.get("process_group_id"), (str, int))
            and isinstance(process.get("process_start_token"), str)
            and bool(process.get("process_start_token"))
            and process.get("process_group_owned") is True
            and process.get("exited") is False
            and process.get("group_excluded") is False
        )

    @staticmethod
    def _stored_shutdown_proof(value: Any) -> bool:
        """Validate the bounded shutdown projection used after a crash."""
        if not isinstance(value, Mapping):
            return False
        process = value.get("process")
        if not isinstance(process, Mapping):
            return False
        if (
            process.get("process_group_owned") is not True
            or process.get("exited") is not True
            or process.get("group_excluded") is not True
        ):
            return False
        if value.get("uncertain_effects") not in ([], {"count": 0}):
            return False
        tools = value.get("tools")
        if not isinstance(tools, list):
            return False
        return value.get("tools_quiescent") is True or value.get("quiescent") is True

    def _runtime_binding(
        self,
        participant: Participant,
        operation: Optional[Operation] = None,
    ) -> str:
        """Return one durable runner incarnation, refusing ambiguity."""
        from_operation: Any = None
        if operation is not None:
            runner_map = operation.metadata.get("runner_instances", {})
            if isinstance(runner_map, Mapping):
                from_operation = runner_map.get(participant.participant_id)
        from_participant = participant.metadata.get("runner_instance_id")
        candidates = [value for value in (from_operation, from_participant) if value is not None]
        if not candidates or any(not isinstance(value, str) or not value for value in candidates):
            raise _error(
                "uncertain-effect",
                "participant has no durable runner instance identity",
            )
        if len(set(candidates)) != 1:
            raise _error(
                "stale-generation",
                "participant runner identity copies disagree",
            )
        return candidates[0]

    def _mark_completion_uncertain(
        self,
        participant_id: str,
        generation: Any,
        runner_instance_id: str,
        code: str,
        detail: str,
    ) -> None:
        """Persist a failed completion attempt while retaining its claim."""
        try:
            with self._transaction():
                self._check_generation(generation)
                participant = self._participants.get(participant_id)
                if participant is None:
                    return
                intent = participant.metadata.get("completion_intent", {})
                if not isinstance(intent, Mapping):
                    intent = {}
                participant.metadata["completion_intent"] = {
                    **dict(intent),
                    "state": "indeterminate",
                    "generation": generation,
                    "runner_instance_id": runner_instance_id,
                    "last_error": {"code": code, "message": detail},
                }
                self._persist({
                    "event": "complete-worker-runtime-uncertain",
                    "participant_id": participant_id,
                    "code": code,
                })
        except ControllerError:
            # Preserve the original runtime refusal.  A stale concurrent
            # operation is itself proof that the claim cannot be released.
            return

    async def complete_worker_runtime(
        self,
        participant_id: str,
        generation: Any,
    ) -> Participant:
        """Complete one worker only after fresh adapter quiescence/stop proof.

        Runtime evidence is collected through the exact status and shutdown
        methods.  No caller-supplied evidence is accepted, and the writer
        claim remains active until the final identity-checked shutdown receipt
        has been durably recorded.  An active unfinished turn is refused;
        explicit lane shutdown owns interruption.
        """
        participant_id = _id(participant_id, "participant_id") or ""
        generation = self._generation_valid(generation)
        status_call = getattr(self.runtime, "status", None) if self.runtime is not None else None
        shutdown = getattr(self.runtime, "shutdown", None) if self.runtime is not None else None
        if not all(callable(method) for method in (status_call, shutdown)):
            raise _error("unsupported", "managed runtime completion lifecycle is unavailable")

        with self._transaction():
            self._check_generation(generation)
            participant = self._participants.get(participant_id)
            if participant is None:
                raise _error("unknown", "participant %s is unknown" % participant_id)
            if participant.role.casefold() != "worker":
                raise _error("invalid", "only workers may be completed")
            if participant.state.casefold() in {"completed", "stopped"}:
                return participant
            operation = self._operations.get(self._active_operation_id or "")
            if operation is None or operation.generation != generation:
                raise _error("uncertain-effect", "worker completion has no current operation binding")
            if participant_id not in operation.sealed_participants:
                raise _error("stale-generation", "worker is not part of the current operation")
            operation_id = operation.operation_id
            runner_instance_id = self._runtime_binding(participant, operation)
            prior_intent = participant.metadata.get("completion_intent")
            if isinstance(prior_intent, Mapping):
                prior_state = prior_intent.get("state")
                if prior_state == "shutdown-recorded":
                    if (
                        prior_intent.get("generation") != generation
                        or prior_intent.get("runner_instance_id") != runner_instance_id
                    ):
                        raise _error("stale-generation", "durable completion identity changed")
                    stored_shutdown = prior_intent.get("shutdown")
                    if not self._stored_shutdown_proof(stored_shutdown):
                        raise _error("uncertain-effect", "durable completion shutdown proof is malformed")
                    completion_record = {
                        "generation": generation,
                        "runner_instance_id": runner_instance_id,
                        "status": prior_intent.get("status"),
                        "shutdown": stored_shutdown,
                    }
                    participant.metadata["completion_evidence"] = completion_record
                    self._release_claim(participant)
                    participant.state = "completed"
                    participant.metadata["completion_intent"] = {
                        **dict(prior_intent),
                        "state": "complete",
                    }
                    self._persist({
                        "event": "complete-worker-runtime-reconcile",
                        "participant_id": participant_id,
                    })
                    return participant
                if prior_state not in (None, "complete"):
                    raise _error(
                        "uncertain-effect",
                        "worker completion has an in-progress runtime effect; reconcile explicitly",
                    )
            participant.metadata["completion_intent"] = {
                "state": "status-in-progress",
                "generation": generation,
                "runner_instance_id": runner_instance_id,
                "operation_id": operation_id,
            }
            self._persist({
                "event": "complete-worker-runtime-intent",
                "participant_id": participant_id,
                "generation": generation,
            })

        status_evidence: Any = None
        shutdown_evidence: Any = None
        try:
            status_evidence = status_call(participant_id)
            if not inspect.isawaitable(status_evidence):
                raise TypeError("managed runtime status must be awaitable")
            status_evidence = await status_evidence
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                current = self._participants.get(participant_id)
                if current is None:
                    raise _error("unknown", "worker disappeared during completion")
                runner_instance_id = self._runtime_binding(current, operation)
                identity_valid, reason = self._runtime_identity_matches(
                    status_evidence,
                    current,
                    operation,
                    expected_runner_instance_id=runner_instance_id,
                )
                if not identity_valid:
                    raise _error("uncertain-effect", "completion status identity is invalid: %s" % reason)
                evidence = self._runtime_evidence(status_evidence, "completion status")
                if not isinstance(evidence.get("tools"), list) or not isinstance(
                    evidence.get("uncertain_effects"), list
                ):
                    raise _error("uncertain-effect", "completion status quiescence evidence is incomplete")
                if any(
                    key not in evidence
                    for key in (
                        "active_turn",
                        "turn_terminal",
                        "drained",
                        "participant_quiescent",
                        "tools_quiescent",
                        "quiescent",
                    )
                ):
                    raise _error("uncertain-effect", "completion status quiescence evidence is incomplete")
                valid, reason = self._runtime_terminal_status(
                    status_evidence, current, operation, runner_instance_id
                )
                if not valid:
                    # Completion never turns an active/unfinished turn into a
                    # completed task by interrupting it.  The completion
                    # fence remains durable and the caller must reconcile a
                    # later natural terminal status explicitly.
                    raise _error(
                        "uncertain-effect",
                        "worker turn/tools are not authoritatively complete: %s" % reason,
                    )
                intent = current.metadata.get("completion_intent", {})
                if not isinstance(intent, Mapping):
                    intent = {}
                current.metadata["completion_intent"] = {
                    **dict(intent),
                    "state": "status-recorded",
                    "operation_id": operation_id,
                    "status": self._runtime_safe_evidence(status_evidence, "completion status"),
                }
                self._persist({
                    "event": "complete-worker-runtime-status",
                    "participant_id": participant_id,
                    "quiescent": True,
                })
                participant = current

            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                current = self._participants.get(participant_id)
                if current is None:
                    raise _error("unknown", "worker disappeared before shutdown")
                runner_instance_id = self._runtime_binding(current, operation)
                intent = current.metadata.get("completion_intent", {})
                if not isinstance(intent, Mapping) or intent.get("state") != "status-recorded":
                    raise _error("uncertain-effect", "worker shutdown intent is not ready")
                current.metadata["completion_intent"] = {
                    **dict(intent),
                    "state": "shutdown-in-progress",
                    "operation_id": operation_id,
                }
                self._persist({
                    "event": "complete-worker-runtime-shutdown-intent",
                    "participant_id": participant_id,
                })
            shutdown_evidence = shutdown(participant_id)
            if not inspect.isawaitable(shutdown_evidence):
                raise TypeError("managed runtime shutdown must be awaitable")
            shutdown_evidence = await shutdown_evidence
            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                current = self._participants.get(participant_id)
                if current is None:
                    raise _error("unknown", "worker disappeared during shutdown")
                runner_instance_id = self._runtime_binding(current, operation)
                valid, reason = self._runtime_shutdown(
                    shutdown_evidence, current, operation, runner_instance_id
                )
                if not valid:
                    raise _error(
                        "uncertain-effect",
                        "worker shutdown is not authoritative: %s" % reason,
                    )
                safe_shutdown = self._runtime_safe_evidence(
                    shutdown_evidence, "completion shutdown"
                )
                intent = current.metadata.get("completion_intent", {})
                if not isinstance(intent, Mapping):
                    intent = {}
                current.metadata["completion_intent"] = {
                    **dict(intent),
                    "state": "shutdown-recorded",
                    "operation_id": operation_id,
                    "shutdown": safe_shutdown,
                }
                self._persist({
                    "event": "complete-worker-runtime-shutdown",
                    "participant_id": participant_id,
                })
                participant = current

            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                current = self._participants.get(participant_id)
                if current is None:
                    raise _error("unknown", "worker disappeared before completion")
                runner_instance_id = self._runtime_binding(current, operation)
                intent = current.metadata.get("completion_intent", {})
                if not isinstance(intent, Mapping) or intent.get("state") != "shutdown-recorded":
                    raise _error("uncertain-effect", "worker completion shutdown proof is not durable")
                pending_dispatch = [
                    entry.message_id
                    for entry in self._mailboxes.values()
                    if entry.recipient_id == participant_id
                    and entry.state in {"dispatch-intent", "uncertain"}
                ]
                if pending_dispatch:
                    raise _error(
                        "uncertain-effect",
                        "worker has an unresolved dispatch effect: %s" % pending_dispatch[0],
                    )
                completion_record = {
                    "generation": generation,
                    "runner_instance_id": runner_instance_id,
                    "status": intent.get("status"),
                    "shutdown": intent.get("shutdown"),
                }
                current.metadata["completion_evidence"] = completion_record
                self._release_claim(current)
                current.state = "completed"
                current.metadata["completion_intent"] = {
                    **dict(intent),
                    "state": "complete",
                }
                self._persist({
                    "event": "complete-worker-runtime",
                    "participant_id": participant_id,
                })
                return current
        except BaseException as exc:
            self._mark_completion_uncertain(
                participant_id,
                generation,
                locals().get("runner_instance_id", "unknown-runner"),
                getattr(exc, "code", "uncertain-effect"),
                str(exc),
            )
            if isinstance(exc, asyncio.CancelledError):
                raise
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "worker completion outcome is uncertain")

    @staticmethod
    def _lifecycle_result(operation: Operation, *, owner_retained: bool) -> Dict[str, Any]:
        """Return bounded lifecycle evidence for the daemon/state owner."""
        receipts = operation.metadata.get("shutdown_receipts", {})
        if not isinstance(receipts, Mapping):
            receipts = {}
        return {
            "operation_id": operation.operation_id,
            "generation": operation.generation,
            "phase": operation.phase,
            "participants": _json_value(dict(receipts)),
            "quiescent": operation.phase == "complete",
            "process_groups_excluded": operation.phase == "complete",
            "owner_retained": owner_retained,
            "claims_retained": owner_retained,
        }

    async def shutdown(self, generation: Any) -> Dict[str, Any]:
        """Stop every enrolled runner while retaining owner and writer claims.

        Shutdown is a durable, bounded transition.  Each runtime status,
        interrupt receipt, and shutdown exclusion proof is recorded before the
        next participant is touched.  No release or unenrollment is implied;
        an uncertain participant leaves the operation and all remaining
        claims held for explicit reconciliation.
        """
        generation = self._generation_valid(generation)
        status_call = getattr(self.runtime, "status", None) if self.runtime is not None else None
        interrupt = getattr(self.runtime, "interrupt", None) if self.runtime is not None else None
        shutdown_call = getattr(self.runtime, "shutdown", None) if self.runtime is not None else None

        operation_id: Optional[str] = None
        participant_ids: list[str] = []
        with self._transaction():
            self._check_generation(generation)
            current = self._operations.get(self._active_operation_id or "")
            if current is not None and current.mode == "shutdown":
                if current.phase == "complete":
                    return self._lifecycle_result(current, owner_retained=True)
                raise _error("uncertain-effect", "shutdown is already in progress")
            if current is not None and current.phase in {"failed", "indeterminate"}:
                raise _error("uncertain-effect", "shutdown is blocked by unresolved operation effects")
            if current is not None and current.phase not in {"ready-held", "released"}:
                raise _error("busy", "shutdown requires a ready-held or released operation")
            scoped = [
                item for item in self._participants.values()
                if item.state.casefold() not in {"completed", "stopped"}
            ]
            participant_ids = [item.participant_id for item in scoped]
            if scoped and not all(callable(method) for method in (status_call, interrupt, shutdown_call)):
                raise _error("unsupported", "managed runtime shutdown lifecycle is unavailable")
            bindings: Dict[str, str] = {}
            for item in scoped:
                bindings[item.participant_id] = self._runtime_binding(item, current)
            if current is not None:
                current.phase = "complete"
                current.metadata["superseded_by"] = "shutdown-pending"
            operation = Operation(
                operation_id="op-" + uuid.uuid4().hex,
                request_id="shutdown-" + uuid.uuid4().hex,
                mode="shutdown",
                generation=generation,
                phase="quiescing",
                sealed_participants=tuple(participant_ids),
                metadata={
                    "runner_instances": bindings,
                    "status_evidence": {},
                    "interrupt_receipts": {},
                    "shutdown_receipts": {},
                    "shutdown_intents": {
                        participant_id: {
                            "state": "pending",
                            "participant_id": participant_id,
                            "generation": generation,
                            "runner_instance_id": bindings[participant_id],
                        }
                        for participant_id in participant_ids
                    },
                },
            )
            self._operations[operation.operation_id] = operation
            self._active_operation_id = operation.operation_id
            operation_id = operation.operation_id
            self._persist({
                "event": "shutdown-intent",
                "operation_id": operation_id,
                "participants": participant_ids,
            })

        if operation_id is None:
            # An empty roster still has a durable transition, so this branch
            # should be unreachable; keep it fail-closed if storage changes.
            raise _error("invalid", "shutdown operation was not created")

        async def _call(method: Any, participant_id: str) -> Any:
            result = method(participant_id)
            if not inspect.isawaitable(result):
                raise TypeError("managed runtime lifecycle method must be awaitable")
            return await result

        try:
            for participant_id in participant_ids:
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    participant = self._participants.get(participant_id)
                    if participant is None:
                        raise _error("unknown", "shutdown participant disappeared")
                    runner_instance_id = self._runtime_binding(participant, operation)
                    intent = operation.metadata["shutdown_intents"].get(participant_id)
                    if not isinstance(intent, Mapping):
                        raise _error("invalid", "shutdown participant intent is malformed")
                    if intent.get("state") == "complete":
                        continue
                    operation.metadata["shutdown_intents"][participant_id] = {
                        **dict(intent),
                        "state": "status-in-progress",
                        "runner_instance_id": runner_instance_id,
                    }
                    self._persist({
                        "event": "shutdown-status-intent",
                        "operation_id": operation_id,
                        "participant_id": participant_id,
                    })

                status_evidence = await _call(status_call, participant_id)
                need_interrupt = False
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    participant = self._participants.get(participant_id)
                    if participant is None:
                        raise _error("unknown", "shutdown participant disappeared after status")
                    runner_instance_id = self._runtime_binding(participant, operation)
                    identity_valid, reason = self._runtime_identity_matches(
                        status_evidence,
                        participant,
                        operation,
                        expected_runner_instance_id=runner_instance_id,
                    )
                    if not identity_valid:
                        raise _error("uncertain-effect", "shutdown status identity is invalid: %s" % reason)
                    status_map = self._runtime_evidence(status_evidence, "shutdown status")
                    try:
                        self._runtime_process(status_evidence, "shutdown status")
                    except ControllerError as exc:
                        raise _error("uncertain-effect", exc.message)
                    if not isinstance(status_map.get("tools"), list) or not isinstance(
                        status_map.get("uncertain_effects"), list
                    ):
                        raise _error("uncertain-effect", "shutdown status quiescence evidence is incomplete")
                    valid, reason = self._runtime_quiescent(
                        status_evidence,
                        participant,
                        operation,
                        expected_runner_instance_id=runner_instance_id,
                    )
                    operation.metadata["status_evidence"][participant_id] = self._runtime_safe_evidence(
                        status_evidence, "shutdown status"
                    )
                    operation.metadata["shutdown_intents"][participant_id] = {
                        **dict(operation.metadata["shutdown_intents"][participant_id]),
                        "state": "shutdown-in-progress" if valid else "interrupt-in-progress",
                    }
                    self._persist({
                        "event": "shutdown-status",
                        "operation_id": operation_id,
                        "participant_id": participant_id,
                        "quiescent": valid,
                    })
                    if not valid:
                        need_interrupt = True

                if need_interrupt:
                    receipt = await _call(interrupt, participant_id)
                    with self._transaction():
                        operation = self._current_operation(operation_id, generation)
                        participant = self._participants.get(participant_id)
                        if participant is None:
                            raise _error("unknown", "shutdown participant disappeared after interrupt")
                        runner_instance_id = self._runtime_binding(participant, operation)
                        valid, reason = self._runtime_identity_matches(
                            receipt,
                            participant,
                            operation,
                            expected_runner_instance_id=runner_instance_id,
                        )
                        if not valid:
                            raise _error("uncertain-effect", "shutdown interrupt receipt is invalid: %s" % reason)
                        operation.metadata["interrupt_receipts"][participant_id] = self._runtime_safe_evidence(
                            receipt, "shutdown interrupt"
                        )
                        operation.metadata["shutdown_intents"][participant_id] = {
                            **dict(operation.metadata["shutdown_intents"][participant_id]),
                            "state": "status-after-interrupt",
                        }
                        self._persist({
                            "event": "shutdown-interrupt-receipt",
                            "operation_id": operation_id,
                            "participant_id": participant_id,
                        })

                    drained_status = await _call(status_call, participant_id)
                    with self._transaction():
                        operation = self._current_operation(operation_id, generation)
                        participant = self._participants.get(participant_id)
                        if participant is None:
                            raise _error("unknown", "shutdown participant disappeared after drain")
                        runner_instance_id = self._runtime_binding(participant, operation)
                        valid, reason = self._runtime_quiescent(
                            drained_status,
                            participant,
                            operation,
                            expected_runner_instance_id=runner_instance_id,
                        )
                        if not valid:
                            raise _error(
                                "uncertain-effect",
                                "shutdown turn/tools are not quiescent: %s" % reason,
                            )
                        operation.metadata["status_evidence"][participant_id] = self._runtime_safe_evidence(
                            drained_status, "shutdown drained status"
                        )
                        operation.metadata["shutdown_intents"][participant_id] = {
                            **dict(operation.metadata["shutdown_intents"][participant_id]),
                            "state": "shutdown-in-progress",
                        }
                        self._persist({
                            "event": "shutdown-drained",
                            "operation_id": operation_id,
                            "participant_id": participant_id,
                        })

                shutdown_evidence = await _call(shutdown_call, participant_id)
                with self._transaction():
                    operation = self._current_operation(operation_id, generation)
                    participant = self._participants.get(participant_id)
                    if participant is None:
                        raise _error("unknown", "shutdown participant disappeared after shutdown")
                    runner_instance_id = self._runtime_binding(participant, operation)
                    valid, reason = self._runtime_shutdown(
                        shutdown_evidence,
                        participant,
                        operation,
                        runner_instance_id,
                    )
                    if not valid:
                        raise _error(
                            "uncertain-effect",
                            "shutdown process exclusion is unproven: %s" % reason,
                        )
                    safe_shutdown = self._runtime_safe_evidence(
                        shutdown_evidence, "shutdown receipt"
                    )
                    operation.metadata["shutdown_receipts"][participant_id] = safe_shutdown
                    participant.metadata["shutdown_evidence"] = {
                        "generation": generation,
                        "runner_instance_id": runner_instance_id,
                        "evidence": safe_shutdown,
                    }
                    participant.state = "stopped"
                    operation.metadata["shutdown_intents"][participant_id] = {
                        **dict(operation.metadata["shutdown_intents"][participant_id]),
                        "state": "complete",
                    }
                    self._persist({
                        "event": "shutdown-excluded",
                        "operation_id": operation_id,
                        "participant_id": participant_id,
                    })

            with self._transaction():
                operation = self._current_operation(operation_id, generation)
                intents = operation.metadata.get("shutdown_intents", {})
                receipts = operation.metadata.get("shutdown_receipts", {})
                if (
                    not isinstance(intents, Mapping)
                    or not isinstance(receipts, Mapping)
                    or any(intents.get(item, {}).get("state") != "complete" for item in participant_ids)
                    or set(receipts) != set(participant_ids)
                ):
                    raise _error("uncertain-effect", "shutdown evidence is incomplete")
                operation.phase = "complete"
                operation.metadata["shutdown_complete"] = True
                self._active_operation_id = None
                self._persist({"event": "shutdown-complete", "operation_id": operation_id})
                return self._lifecycle_result(operation, owner_retained=True)
        except BaseException as exc:
            self._mark_operation_failure(
                operation_id,
                "shutdown",
                getattr(exc, "code", "uncertain-effect"),
                str(exc),
            )
            if isinstance(exc, asyncio.CancelledError):
                raise
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "shutdown outcome is uncertain")

    @_transactional
    def unenroll(self, generation: Any) -> Dict[str, Any]:
        """Clear the controller roster only after durable stop/exclusion proof.

        This method performs no runtime call.  It consumes the canonical
        shutdown/completion evidence persisted by trusted lifecycle methods,
        releases each remaining writer claim exactly once, and archives the
        identities so the durable owner can be cleared by the state owner.
        Any missing or contradictory proof refuses before the first claim is
        touched.
        """
        generation = self._generation_valid(generation)
        self._check_generation(generation)
        current = self._operations.get(self._active_operation_id or "")
        if current is not None:
            if current.phase in {"failed", "indeterminate"}:
                raise _error("uncertain-effect", "unenroll is blocked by unresolved operation effects")
            raise _error("busy", "unenroll requires a completed shutdown")
        participants = list(self._participants.values())
        archived = list(self._archived_participants.values())
        scoped = participants + archived
        for participant in scoped:
            if participant.state.casefold() not in {"completed", "stopped"}:
                raise _error(
                    "uncertain-effect",
                    "participant %s is not authoritatively stopped" % participant.participant_id,
                )
            evidence_record = participant.metadata.get("shutdown_evidence")
            if participant.state.casefold() == "completed":
                evidence_record = participant.metadata.get(
                    "completion_evidence", evidence_record
                )
            if not isinstance(evidence_record, Mapping):
                # A ctx-archived coordinator's exclusion is stored on the ctx
                # operation rather than copied into the archived participant.
                evidence_record = None
                for operation in reversed(list(self._operations.values())):
                    receipts = operation.metadata.get("shutdown_receipts", {})
                    if (
                        participant.participant_id in operation.sealed_participants
                        and isinstance(receipts, Mapping)
                        and isinstance(receipts.get(participant.participant_id), Mapping)
                    ):
                        evidence_record = {
                            "generation": generation,
                            "evidence": receipts[participant.participant_id],
                        }
                        break
            if not isinstance(evidence_record, Mapping):
                raise _error(
                    "uncertain-effect",
                    "participant %s has no durable shutdown evidence" % participant.participant_id,
                )
            if evidence_record.get("generation", generation) != generation:
                raise _error("stale-generation", "unenroll evidence has the wrong generation")
            evidence = evidence_record.get("evidence", evidence_record)
            if isinstance(evidence, Mapping) and "process" not in evidence:
                nested = evidence.get("evidence")
                if isinstance(nested, Mapping):
                    evidence = nested
            if isinstance(evidence, Mapping) and "process" not in evidence:
                nested_shutdown = evidence.get("shutdown")
                if isinstance(nested_shutdown, Mapping):
                    evidence = nested_shutdown
            if not isinstance(evidence, Mapping):
                raise _error("uncertain-effect", "unenroll evidence is malformed")
            process = evidence.get("process")
            if not isinstance(process, Mapping):
                raise _error("uncertain-effect", "unenroll process exclusion evidence is missing")
            if (
                process.get("process_group_owned") is not True
                or process.get("exited") is not True
                or process.get("group_excluded") is not True
            ):
                raise _error("uncertain-effect", "unenroll process group is still live or unknown")
            if evidence.get("uncertain_effects") not in ([], {"count": 0}):
                raise _error("uncertain-effect", "unenroll evidence reports unknown effects")
            tools = evidence.get("tools")
            if not isinstance(tools, list):
                raise _error("uncertain-effect", "unenroll tool quiescence evidence is missing")
            if evidence.get("tools_quiescent") is not True and evidence.get("quiescent") is not True:
                raise _error("uncertain-effect", "unenroll tools are not quiescent")

        operation = Operation(
            operation_id="op-" + uuid.uuid4().hex,
            request_id="unenroll-" + uuid.uuid4().hex,
            mode="unenroll",
            generation=generation,
            phase="quiescing",
            sealed_participants=tuple(item.participant_id for item in scoped),
            metadata={
                "unenroll_intents": {
                    item.participant_id: {
                        "state": "pending",
                        "participant_id": item.participant_id,
                        "generation": generation,
                    }
                    for item in scoped
                },
                "shutdown_proven": True,
            },
        )
        self._operations[operation.operation_id] = operation
        self._active_operation_id = operation.operation_id
        self._persist({
            "event": "unenroll-intent",
            "operation_id": operation.operation_id,
        })
        try:
            for participant in scoped:
                intent = operation.metadata["unenroll_intents"][participant.participant_id]
                if participant.writer_claim is not None and participant.writer_claim.state != "released":
                    intent["state"] = "release-in-progress"
                    self._persist({
                        "event": "unenroll-claim-intent",
                        "operation_id": operation.operation_id,
                        "participant_id": participant.participant_id,
                    })
                    self._release_claim(participant)
                intent["state"] = "complete"
                self._persist({
                    "event": "unenroll-participant",
                    "operation_id": operation.operation_id,
                    "participant_id": participant.participant_id,
                })
            operation.phase = "complete"
            operation.metadata["unenrolled"] = True
            for participant in participants:
                self._archived_participants[participant.participant_id] = participant
                self._participants.pop(participant.participant_id, None)
            self._coordinator_id = None
            self._active_operation_id = None
            self._persist({"event": "unenroll-complete", "operation_id": operation.operation_id})
            return {
                "operation_id": operation.operation_id,
                "generation": generation,
                "phase": "complete",
                "unenrolled": True,
                "participants": [item.participant_id for item in scoped],
                "claims_released": True,
                "owner_clear_ready": True,
            }
        except BaseException as exc:
            operation.phase = "indeterminate"
            operation.uncertainty.append("unenroll")
            operation.metadata["last_error"] = {
                "code": getattr(exc, "code", "uncertain-effect"),
                "message": str(exc),
            }
            self._persist({"event": "unenroll-uncertain", "operation_id": operation.operation_id})
            if isinstance(exc, ControllerError):
                raise
            raise _error("uncertain-effect", "unenroll outcome is uncertain")

    @staticmethod
    def _completion_is_authoritative(
        evidence: Any, participant_id: str, generation: Any
    ) -> Tuple[bool, str]:
        if (not isinstance(evidence, Mapping) and not dataclasses.is_dataclass(evidence)) or isinstance(evidence, type):
            return False, "completion evidence must be an object"
        evidence_id = _get(
            evidence,
            "participant_id",
            "participant",
            "owner_participant_id",
            default=None,
        )
        if isinstance(evidence_id, Mapping):
            evidence_id = _get(evidence_id, "participant_id", "id", "owner", default=None)
        if evidence_id != participant_id:
            return False, "completion evidence is not linked to this participant"
        evidence_generation = _get(
            evidence,
            "generation",
            "owner_generation",
            "participant_generation",
            default=None,
        )
        if evidence_generation != generation:
            return False, "completion evidence does not match the current generation"

        authority = _get(
            evidence,
            "authoritative",
            "authoritative_stop",
            "authoritative_completion",
            default=None,
        )
        if authority is not True:
            return False, "completion evidence is not authoritative"

        state = _get(evidence, "status", "state", "result", "completion", default=None)
        stopped = _get(evidence, "stopped", default=None)
        completed = _get(evidence, "completed", default=None)
        if isinstance(state, Mapping):
            stopped = _get(state, "stopped", default=stopped)
            completed = _get(state, "completed", default=completed)
            state = _get(state, "status", "state", default=None)
        terminal = isinstance(state, str) and state.casefold() in {
            "completed",
            "stopped",
            "complete",
        }
        if stopped is not True and completed is not True and not terminal:
            return False, "authoritative completed/stopped evidence is required"

        participant_proof = _get(evidence, "participant_evidence", "participant", default=evidence)
        if isinstance(participant_proof, Mapping):
            nested_id = _get(participant_proof, "participant_id", "id", "owner", default=participant_id)
            nested_generation = _get(
                participant_proof,
                "generation",
                "owner_generation",
                "participant_generation",
                default=generation,
            )
            if nested_id != participant_id or nested_generation != generation:
                return False, "participant completion evidence has the wrong identity or generation"
        # Requiring an explicit positive quiescence marker prevents a client
        # supplied status string from releasing a still-running writer.
        quiescent = _get(evidence, "quiescent", default=None)
        participant_quiescent = _get(evidence, "participant_quiescent", default=None)
        tools_quiescent = _get(evidence, "tools_quiescent", "no_live_tools", default=None)
        live_participant = _get(evidence, "live_participant", "participant_live", default=False)
        live_tool = _get(evidence, "live_tool", "tool_live", "live_tools", default=False)
        unknown = _get(
            evidence,
            "unknown_effects",
            "unresolved_effects",
            "unknown_descendants",
            "unknown_tools",
            default=(),
        )
        if live_participant or live_tool:
            return False, "participant or tool is still live"
        if unknown:
            return False, "participant has unknown effects or descendants"
        if participant_quiescent is not True or tools_quiescent is not True:
            return False, "participant and tools must be authoritatively quiescent"
        tool_proof = _get(evidence, "tool_evidence", "tools", default=None)
        if isinstance(tool_proof, Mapping):
            if not any(
                key in tool_proof
                for key in ("participant_id", "owner_participant_id", "owner")
            ) or not any(
                key in tool_proof
                for key in ("generation", "owner_generation", "participant_generation")
            ):
                return False, "tool completion evidence has no identity or generation"
            tool_id = _get(tool_proof, "participant_id", "owner_participant_id", "owner", default=participant_id)
            tool_generation = _get(
                tool_proof,
                "generation",
                "owner_generation",
                "participant_generation",
                default=generation,
            )
            if tool_id != participant_id or tool_generation != generation:
                return False, "tool completion evidence has the wrong identity or generation"
        elif isinstance(tool_proof, list) and tool_proof:
            for item in tool_proof:
                if not isinstance(item, Mapping):
                    return False, "tool completion evidence is malformed"
                if not any(
                    key in item
                    for key in ("participant_id", "owner_participant_id", "owner")
                ) or not any(
                    key in item
                    for key in ("generation", "owner_generation", "participant_generation")
                ):
                    return False, "tool completion evidence has no identity or generation"
                tool_id = _get(item, "participant_id", "owner_participant_id", "owner", default=participant_id)
                tool_generation = _get(
                    item,
                    "generation",
                    "owner_generation",
                    "participant_generation",
                    default=generation,
                )
                if tool_id != participant_id or tool_generation != generation:
                    return False, "tool completion evidence has the wrong identity or generation"
        else:
            return False, "identity-linked tool completion evidence is required"
        process_group = _get(evidence, "process_group", "process_group_id", "process_group_owned", default=None)
        if process_group in (None, False, ""):
            return False, "owned process-group completion evidence is required"
        if isinstance(process_group, Mapping):
            process_owner = _get(
                process_group,
                "participant_id",
                "owner_participant_id",
                "owner",
                default=participant_id,
            )
            process_generation = _get(
                process_group,
                "generation",
                "owner_generation",
                "participant_generation",
                default=generation,
            )
            if process_owner != participant_id or process_generation != generation:
                return False, "process-group evidence has the wrong identity or generation"
        return True, ""

    def _release_claim(self, participant: Participant) -> None:
        claim = participant.writer_claim
        if claim is None or claim.state == "released":
            return
        method = getattr(self.store, "release_writer", None) if self.store is not None else None
        if not callable(method):
            raise _error("unsupported", "managed writer claims require the global state store")
        try:
            method(participant.participant_id, claim.worktree)
        except ControllerError:
            raise
        except Exception as exc:
            code = getattr(exc, "code", "ownership-conflict")
            raise _error(str(code), "writer claim release refused: %s" % exc)
        claim.state = "released"

    @_transactional
    def complete_worker(self, participant_id: str, evidence: Any) -> Participant:
        participant_id = _id(participant_id, "participant_id") or ""
        participant = self._participants.get(participant_id)
        if participant is None:
            raise _error("unknown", "participant %s is unknown" % participant_id)
        if participant.role.casefold() != "worker":
            raise _error("invalid", "only workers may be completed")
        if participant.state.casefold() in {"completed", "stopped"}:
            return participant
        valid, reason = self._completion_is_authoritative(
            evidence, participant_id, self._generation
        )
        if not valid:
            raise _error("uncertain-effect", reason)
        self._release_claim(participant)
        participant.state = "completed"
        self._persist({"event": "complete-worker", "participant_id": participant_id,
                       "evidence": {"status": _get(evidence, "status", "state", default="completed")}})
        return participant

    @staticmethod
    def _coordinator_interrupt_summary(
            record: Mapping[str, Any]
    ) -> Dict[str, Any]:
        """Project one already-validated interrupt record into observations.

        This is intentionally a pure projection.  The controller transaction
        reloads and validates the durable record before calling it; this
        helper never consults a runtime, writes a record, or changes an
        operation, claim, or authorization.  The raw record remains the
        compatibility surface, while this result is an ephemeral aggregate.
        """

        frame = _mapping(record["frame"], "coordinator interrupt frame")
        interrupt = _mapping(frame["interrupt"], "coordinator interrupt intent")
        roster = _mapping(interrupt["roster"], "coordinator interrupt roster")
        evidence_records = _mapping(
            record["evidence"], "coordinator interrupt evidence ledger"
        )

        blockers: list[str] = []
        graph_blockers: list[str] = []

        def add_blocker(value: str, *, graph: bool = False) -> None:
            if value not in blockers:
                blockers.append(value)
            if graph and value not in graph_blockers:
                graph_blockers.append(value)

        member_facts: Dict[Tuple[str, str, str, Any], list[Dict[str, Any]]] = {}
        tool_facts: Dict[Tuple[str, Optional[str], Optional[Any]], list[Dict[str, Any]]] = {}
        effect_facts: Dict[str, list[Dict[str, Any]]] = {}
        admission_facts: Dict[str, list[Dict[str, Any]]] = {}
        parent_facts: list[Dict[str, Any]] = []
        process_facts: list[Dict[str, Any]] = []
        request_facts: list[Dict[str, Any]] = []

        # Evidence IDs are transport identities only.  The maps below use the
        # member/tool/effect identities so a semantic conflict cannot be
        # hidden behind two different evidence IDs.
        for evidence_id in sorted(evidence_records):
            evidence_record = _mapping(
                evidence_records[evidence_id],
                "coordinator interrupt evidence record",
            )
            evidence_frame = _mapping(
                evidence_record["frame"],
                "coordinator interrupt evidence frame",
            )
            fact = _mapping(
                evidence_frame["evidence"],
                "coordinator interrupt evidence",
            )
            item = {
                "evidence_id": evidence_id,
                "observed_watermark": fact["observed_watermark"],
                "data": _mapping(fact["data"], "coordinator interrupt evidence data"),
            }
            item["kind"] = fact["kind"]
            data = item["data"]
            kind = item["kind"]
            if kind == "member-terminal":
                key = (
                    data["agent_id"], data["task_id"], data["tool_use_id"],
                    data["lineage_incarnation"],
                )
                member_facts.setdefault(key, []).append(item)
            elif kind == "tool-terminal":
                key = (
                    data["tool_use_id"], data["agent_id"],
                    data["lineage_incarnation"],
                )
                tool_facts.setdefault(key, []).append(item)
            elif kind == "effect-outcome":
                effect_facts.setdefault(data["effect_id"], []).append(item)
            elif kind == "admission-closed":
                admission_facts.setdefault(data["admission_id"], []).append(item)
            elif kind == "parent-drained":
                parent_facts.append(item)
            elif kind == "process-excluded":
                process_facts.append(item)
            elif kind == "request-observation":
                request_facts.append(item)

        child_rows = []
        child_admission_ids = set()
        for child in sorted(roster["children"], key=lambda value: value["admission_id"]):
            child_key = (
                child["agent_id"], child["task_id"], child["tool_use_id"],
                child["lineage_incarnation"],
            )
            child_admission_ids.add(child["admission_id"])

            facts = member_facts.get(child_key, [])
            statuses = {fact["data"]["status"] for fact in facts}
            child_blockers = []
            if len(statuses) > 1:
                conflict = "child-terminal-conflict:%s" % child["admission_id"]
                add_blocker(conflict, graph=True)
                child_blockers.append(conflict)

            observed_status = None
            observed_watermark = None
            observed_evidence_ids = [fact["evidence_id"] for fact in facts]
            if len(statuses) > 1:
                observed_status = "conflicted"
            elif len(statuses) == 1:
                observed_status = next(iter(statuses))
                latest = max(
                    facts,
                    key=lambda fact: (
                        fact["observed_watermark"], fact["evidence_id"]
                    ),
                )
                observed_watermark = latest["observed_watermark"]
            elif not facts and child["status"] in {"completed", "stopped"}:
                # The sealed terminal watermark is authoritative for a
                # natural completion already observed before the seal.  It is
                # not relabelled as an interrupt stop and does not require a
                # later receipt.
                observed_status = child["status"]
                observed_watermark = child["terminal_watermark"]

            if observed_status is None:
                missing = "child-terminal-missing:%s" % child["admission_id"]
                add_blocker(missing, graph=True)
                child_blockers.append(missing)

            child_rows.append({
                "admission_id": child["admission_id"],
                "tool_use_id": child["tool_use_id"],
                "agent_id": child["agent_id"],
                "task_id": child["task_id"],
                "parent_agent_id": child["parent_agent_id"],
                "invocation_id": child["invocation_id"],
                "lineage_incarnation": child["lineage_incarnation"],
                "sealed_status": child["status"],
                "sealed_terminal_watermark": child["terminal_watermark"],
                "status": observed_status,
                "observed_terminal_status": observed_status,
                "observed_terminal_watermark": observed_watermark,
                "terminal_evidence_ids": observed_evidence_ids,
                "blockers": child_blockers,
            })

        def tool_row(
                *, tool_id: str, agent_id: Optional[str],
                lineage_incarnation: Optional[Any], owner: str,
        ) -> None:
            key = (tool_id, agent_id, lineage_incarnation)
            facts = tool_facts.get(key, [])
            statuses = {fact["data"]["status"] for fact in facts}
            row_blockers = []
            if len(statuses) > 1:
                conflict = "tool-terminal-conflict:%s" % tool_id
                add_blocker(conflict, graph=True)
                row_blockers.append(conflict)
            status = "conflicted" if len(statuses) > 1 else None
            watermark = None
            evidence_ids = [fact["evidence_id"] for fact in facts]
            if len(statuses) == 1:
                status = next(iter(statuses))
                latest = max(
                    facts,
                    key=lambda fact: (
                        fact["observed_watermark"], fact["evidence_id"]
                    ),
                )
                watermark = latest["observed_watermark"]
            if status is None:
                missing = "tool-terminal-missing:%s" % tool_id
                add_blocker(missing, graph=True)
                row_blockers.append(missing)
            tool_rows.append({
                "tool_use_id": tool_id,
                "agent_id": agent_id,
                "lineage_incarnation": lineage_incarnation,
                "owner": owner,
                "status": status,
                "observed_terminal_status": status,
                "observed_terminal_watermark": watermark,
                "terminal_evidence_ids": evidence_ids,
                "blockers": row_blockers,
            })

        tool_rows = []
        for tool_id in sorted(
                set(roster["parent_active_tool_ids"]) |
                set(roster["parent_uncertain_tool_ids"])
        ):
            tool_row(tool_id=tool_id, agent_id=None,
                     lineage_incarnation=None, owner="parent")
        for child in sorted(roster["children"], key=lambda value: value["admission_id"]):
            for tool_id in sorted(
                    set(child["active_tool_ids"]) |
                    set(child["uncertain_tool_ids"])
            ):
                tool_row(
                    tool_id=tool_id,
                    agent_id=child["agent_id"],
                    lineage_incarnation=child["lineage_incarnation"],
                    owner="child",
                )

        effect_rows = []
        effect_inventory = []
        for effect_id in roster["parent_unresolved_effect_ids"]:
            effect_inventory.append((effect_id, "parent", None))
        for child in sorted(roster["children"], key=lambda value: value["admission_id"]):
            for effect_id in child["unresolved_effect_ids"]:
                effect_inventory.append((effect_id, "child", child["admission_id"]))
        for effect_id, owner, admission_id in sorted(effect_inventory):
            facts = effect_facts.get(effect_id, [])
            statuses = {fact["data"]["status"] for fact in facts}
            row_blockers = []
            if len(statuses) > 1:
                conflict = "effect-outcome-conflict:%s" % effect_id
                add_blocker(conflict, graph=True)
                row_blockers.append(conflict)
            status = "conflicted" if len(statuses) > 1 else (
                next(iter(statuses)) if statuses else None
            )
            evidence_ids = [fact["evidence_id"] for fact in facts]
            if status is None:
                missing = "effect-outcome-missing:%s" % effect_id
                add_blocker(missing, graph=True)
                row_blockers.append(missing)
            elif status == "unknown":
                unknown = "effect-outcome-unknown:%s" % effect_id
                add_blocker(unknown, graph=True)
                row_blockers.append(unknown)
            effect_rows.append({
                "effect_id": effect_id,
                "owner": owner,
                "admission_id": admission_id,
                "status": status,
                "observed_status": status,
                "outcome_evidence_ids": evidence_ids,
                "blockers": row_blockers,
            })

        admission_rows = []
        for admission_id in sorted(child_admission_ids):
            facts = admission_facts.get(admission_id, [])
            values = {fact["data"]["closed"] for fact in facts}
            row_blockers = []
            if len(values) > 1:
                conflict = "admission-closed-conflict:%s" % admission_id
                add_blocker(conflict, graph=True)
                row_blockers.append(conflict)
            closed = "conflicted" if len(values) > 1 else (
                next(iter(values)) if values else None
            )
            evidence_ids = [fact["evidence_id"] for fact in facts]
            if closed is None:
                missing = "admission-closed-missing:%s" % admission_id
                add_blocker(missing, graph=True)
                row_blockers.append(missing)
            admission_rows.append({
                "admission_id": admission_id,
                "closed": closed,
                "evidence_ids": evidence_ids,
                "blockers": row_blockers,
            })
        for pending_id in sorted(roster["pending_admission_ids"]):
            add_blocker("pending-admission:%s" % pending_id, graph=True)
        for pending_id in sorted(roster["pending_task_ids"]):
            add_blocker("pending-task:%s" % pending_id, graph=True)

        descendant_rows = []
        for descendant_id in sorted(roster["descendant_ids"]):
            # ``descendant_ids`` is intentionally opaque in the current
            # record schema.  There is no typed namespace or descendant
            # terminal evidence that could prove an association with a child,
            # admission, or process.  Even an equal-looking string and an
            # excluded process digest are therefore insufficient.
            unproven = "descendant-unproven:%s" % descendant_id
            add_blocker(unproven, graph=True)
            descendant_rows.append({
                "descendant_id": descendant_id,
                "mapped_admission_id": None,
                "resolved": False,
                "blockers": [unproven],
            })

        parent_blockers = []
        parent_evidence_ids = [fact["evidence_id"] for fact in parent_facts]
        parent_states = sorted({fact["data"]["state"] for fact in parent_facts})
        latest_parent = (
            max(
                parent_facts,
                key=lambda fact: (
                    fact["observed_watermark"], fact["evidence_id"]
                ),
            )
            if parent_facts else None
        )
        observed_parent_state = (
            latest_parent["data"]["state"] if latest_parent is not None else None
        )
        parent_idle_at_seal = roster["parent_state"] == "idle"
        parent_quiescent = parent_idle_at_seal or (
            any(state in {"idle", "drained"} for state in parent_states)
        )
        if not parent_quiescent:
            missing = "parent-drain-missing:%s" % interrupt["invocation_id"]
            add_blocker(missing, graph=True)
            parent_blockers.append(missing)

        process_status = "unknown"
        process_digest = None
        process_blockers = []
        process_statuses = {fact["data"]["status"] for fact in process_facts}
        process_digests = {
            fact["data"]["process_identity_digest"] for fact in process_facts
            if fact["data"]["process_identity_digest"] is not None
        }
        if len(process_statuses) > 1 or len(process_digests) > 1:
            conflict = "process-exclusion-conflict"
            add_blocker(conflict)
            process_blockers.append(conflict)
            process_status = "conflicted"
        elif len(process_statuses) == 1:
            process_status = next(iter(process_statuses))
            process_digest = next(iter(process_digests), None)
            if process_status == "unknown":
                unknown = "process-exclusion-unknown"
                add_blocker(unknown)
                process_blockers.append(unknown)
        else:
            missing = "process-exclusion-missing"
            add_blocker(missing)
            process_blockers.append(missing)
        process_evidence_ids = [fact["evidence_id"] for fact in process_facts]

        request_blockers = []
        request_epoch_id = interrupt["request_epoch_id"]
        request_entry_watermark = interrupt["request_entry_watermark"]
        request_through_watermark = None
        request_count = None
        request_observable = False
        request_positive = False
        request_unknown_count = False
        request_latest_observed_watermark = None
        request_latest_evidence_id = None
        request_coverage_gap = False
        if request_facts:
            ordered_requests = sorted(
                request_facts,
                key=lambda fact: (
                    fact["data"]["through_watermark"],
                    fact["observed_watermark"],
                    fact["evidence_id"],
                ),
            )
            request_through_watermark = max(
                fact["data"]["through_watermark"] for fact in request_facts
            )
            latest_request = ordered_requests[-1]
            request_latest_evidence_id = latest_request["evidence_id"]
            request_latest_observed_watermark = latest_request["observed_watermark"]
            request_unknown_count = any(
                fact["data"]["new_requests"] is None for fact in request_facts
            )
            counts = [
                fact["data"]["new_requests"] for fact in request_facts
                if fact["data"]["new_requests"] is not None
            ]
            request_count = max(counts) if counts else None
            request_positive = any(count > 0 for count in counts)
            request_observable = all(
                fact["data"]["observable"] for fact in request_facts
            )
            if request_positive:
                positive = "request-observation-positive"
                add_blocker(positive)
                request_blockers.append(positive)
            if not request_observable:
                unobservable = "request-observation-unobservable"
                add_blocker(unobservable)
                request_blockers.append(unobservable)
            if request_unknown_count:
                unknown_history = "request-observation-unknown-count-history"
                add_blocker(unknown_history)
                request_blockers.append(unknown_history)
            if request_through_watermark < record["progress_watermark"]:
                request_coverage_gap = True
                coverage_gap = "request-observation-coverage-gap"
                add_blocker(coverage_gap)
                request_blockers.append(coverage_gap)
        else:
            missing = "request-observation-missing"
            add_blocker(missing)
            request_blockers.append(missing)
        if request_count is None and not request_unknown_count:
            unknown = "request-observation-unknown-count"
            add_blocker(unknown)
            request_blockers.append(unknown)
        # The local watermark domain begins at the runner's reported entry
        # watermark; it cannot prove that observation covered the control
        # entry boundary before that fact existed.
        coverage = "request-observation-pre-entry-unproven"
        add_blocker(coverage)
        request_blockers.append(coverage)

        identity = {
            "participant_id": frame["participant_id"],
            "session_id": frame["session_id"],
            "runner_instance_id": frame["runner_instance_id"],
            "operation_id": interrupt["operation_id"],
            "owner_generation": interrupt["owner_generation"],
            "lineage_id": interrupt["lineage_id"],
            "lineage_generation": interrupt["lineage_generation"],
            "invocation_id": interrupt["invocation_id"],
            "fence_epoch": interrupt["fence_epoch"],
            "request_epoch_id": request_epoch_id,
            "capability_digest": interrupt["capability_digest"],
            "source_exclusion_key": record["source_exclusion_key"],
        }
        seal = {
            "roster_identity_digest": interrupt["roster_identity_digest"],
            "roster_seal_watermark": interrupt["roster_seal_watermark"],
            "admission_ids": sorted(child_admission_ids),
            "progress_watermark": record["progress_watermark"],
        }
        return {
            "interrupt_id": record["interrupt_id"],
            "operation_id": interrupt["operation_id"],
            "identity": identity,
            "seal": seal,
            "roster_identity_digest": interrupt["roster_identity_digest"],
            "roster_seal_watermark": interrupt["roster_seal_watermark"],
            "progress_watermark": record["progress_watermark"],
            "runtime_acknowledged": record["runtime_ack"] is not None,
            "graph_quiescent": not graph_blockers,
            "children": child_rows,
            "tools": tool_rows,
            "effects": effect_rows,
            "admissions": admission_rows,
            "descendants": descendant_rows,
            "parent": {
                "sealed_state": roster["parent_state"],
                "observed_state": observed_parent_state,
                "observed_states": parent_states,
                "idle_at_seal": parent_idle_at_seal,
                "drained_or_idle": parent_quiescent,
                "evidence_ids": parent_evidence_ids,
                "blockers": parent_blockers,
            },
            "process_exclusion": {
                "status": process_status,
                "process_identity_digest": process_digest,
                "evidence_ids": process_evidence_ids,
                "blockers": process_blockers,
            },
            "request_observation": {
                "epoch_id": request_epoch_id,
                "entry_watermark": request_entry_watermark,
                "through_watermark": request_through_watermark,
                "latest_observed_watermark": request_latest_observed_watermark,
                "new_requests": request_count,
                "positive_new_requests": request_positive,
                "unknown_count_history": request_unknown_count,
                "observable": request_observable,
                "coverage_proven": False,
                "external_entry_coverage_proven": False,
                "pre_entry_observation_proven": False,
                "coverage_gap": request_coverage_gap,
                "latest_evidence_id": request_latest_evidence_id,
                "blockers": request_blockers,
            },
            "blockers": blockers,
        }

    @_transactional
    def coordinator_interrupt_status(self, interrupt_id: str) -> Dict[str, Any]:
        """Return an observational aggregate for one durable interrupt.

        The transaction reloads the latest record and runs the existing strict
        durable validators.  This method deliberately has no persistence,
        runtime, operation, claim, or authorization side effect.
        """

        interrupt_id = _id(interrupt_id, "coordinator interrupt ID") or ""
        record = self._coordinator_interrupts.get(interrupt_id)
        if record is None:
            raise _error("unknown", "coordinator interrupt %s is unknown" % interrupt_id)
        return self._coordinator_interrupt_summary(record)

    def _native_children_status(self) -> List[Dict[str, Any]]:
        latest: Dict[str, Mapping[str, Any]] = {}
        for record in self._native_child_observations.values():
            run_id = record.get("child_run_id")
            observation = record.get("observation")
            if not isinstance(run_id, str) or not isinstance(observation, Mapping):
                raise _error("invalid", "native child status record is malformed")
            prior = latest.get(run_id)
            if (prior is None
                    or observation["observation_watermark"]
                    > prior["observation"]["observation_watermark"]):
                latest[run_id] = record
        result: List[Dict[str, Any]] = []
        for run_id, record in latest.items():
            observation = record["observation"]
            child = observation["child"]
            outcome = observation["terminal_outcome"]
            if child["status"] == "active":
                lifecycle = "active"
            elif (
                outcome == "completed"
                and child["status"] == "completed"
                and not any(
                    child[key]
                    for key in (
                        "active_tool_ids", "uncertain_tool_ids",
                        "unresolved_effect_ids",
                    )
                )
            ):
                lifecycle = "completed"
            elif outcome == "stopped" and child["status"] == "stopped":
                lifecycle = "stopped"
            else:
                lifecycle = "unresolved"
            result.append({
                "child_run_id": run_id,
                "source_identity": _json_value(observation["source_identity"]),
                "admission_id": child["admission_id"],
                "tool_use_id": child["tool_use_id"],
                "agent_id": child["agent_id"],
                "task_id": child["task_id"],
                "lineage_incarnation": child["lineage_incarnation"],
                "trusted_definition_digest": child["trusted_definition_digest"],
                "observation_id": observation["observation_id"],
                "observation_watermark": observation["observation_watermark"],
                "lifecycle_status": lifecycle,
                "terminal_outcome": outcome,
                "restoration": None,
            })
        result.sort(key=lambda item: item["child_run_id"])
        return result

    @_transactional
    def status(self) -> Dict[str, Any]:
        operation = self._operations.get(self._active_operation_id or "")
        roster = [item.to_dict() for item in self._participants.values()]
        archived = [item.to_dict() for item in self._archived_participants.values()]
        mailboxes = [item.to_dict() for item in self._mailboxes.values()]
        operation_data = operation.to_dict() if operation is not None else None
        coordinator_interrupt_summaries = {
            interrupt_id: self._coordinator_interrupt_summary(record)
            for interrupt_id, record in self._coordinator_interrupts.items()
        }
        native_source_archives = {
            archive_id: {
                key: _json_value(value)
                for key, value in archive.items()
                if key != "snapshot"
            }
            for archive_id, archive in self._native_source_archives.items()
        }
        return {
            **native_record_marker("controller-status"),
            "generation": _json_value(self._generation),
            "coordinator_id": self._coordinator_id,
            "participants": roster,
            "roster": roster,
            "archived_participants": archived,
            "session_history": sorted(self._session_history),
            "checkpoints": [_json_value(value) for value in self._checkpoints.values()],
            "mailboxes": mailboxes,
            "operation": operation_data,
            "active_operation": operation_data,
            "active_operation_id": operation.operation_id if operation is not None else None,
            "operation_id": operation.operation_id if operation is not None else None,
            "phase": operation.phase if operation is not None else None,
            "delivery_semantics": "at-most-once-automatic; cross-process exactly-once not claimed",
            "live_sdk": "UNVERIFIED",
            "runtime_capability": (
                next((_json_value(item.metadata["capability_gate"])
                      for item in reversed(list(self._operations.values()))
                      if "capability_gate" in item.metadata), None)
            ),
            "native_context": _json_value(self._native_context),
            "native_admissions": _json_value(self._native_admissions),
            "native_children": self._native_children_status(),
            "native_stops": _json_value(self._native_stops),
            "native_invocation_reservation": _json_value(
                next(
                    (
                        item.get("reservation_binding")
                        for item in reversed(list(self._native_invocation_rollovers.values()))
                        if item.get("reservation_binding") is not None
                    ),
                    None,
                )
            ),
            "native_invocation_history": _json_value(self._native_invocation_history),
            "native_invocation_rollovers": _json_value(self._native_invocation_rollovers),
            "native_source_archives": native_source_archives,
            "coordinator_interrupt_summaries": coordinator_interrupt_summaries,
            "coordinator_interrupts": _json_value(self._coordinator_interrupts),
        }


